# ── LAST SET OF DATA per report (owner 2026-07-29) ──────────────────────────────────────
# "show there for each report when the last set of data was uploaded". Reads the two ingest journals
# this module already writes — commcalc.upload_trace (mig 202: EVERY path, incl. the email/FTP sweeps and
# the feed→raw_sales promotion) and the older commcalc.upload_log (mig 007) — and folds them into ONE
# newest-per-report record. Nothing here writes.
_UPLOAD_SOURCE_LABEL = {
    'manual': 'manual upload',
    'email_sweep': 'email feed',
    'ftp_sweep': 'FTP feed',
    'promotion': 'auto-promotion',
    'portal': 'portal pull',
    'ledger-import': 'ledger import',
    'import-wizard': 'import wizard',
    'onboarding-import': 'onboarding import',
}
# Columns the "which ingest was newest" pass needs. Deliberately EXCLUDES the periods/date_counts JSONB
# so scanning a busy tenant's recent window stays small; the winners' detail is fetched by id after.
_UPLOAD_LAST_TRACE_COLS = 'id,created_at,upload_type,source,status,skipped,rows_saved,filename'
_UPLOAD_LAST_LOG_COLS = 'id,uploaded_at,file_type,period,rows_saved,filename'


def _upload_ts(v):
    """ISO timestamp → aware datetime for ORDERING two journals against each other. Never raises;
    an unparseable/absent stamp sorts oldest so it can never win a 'newest' comparison."""
    try:
        d = _datetime.fromisoformat(str(v).replace('Z', '+00:00'))
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
    except Exception:
        return _datetime.min.replace(tzinfo=timezone.utc)


def _upload_last_cand(row, origin):
    """Normalize one upload_trace ('trace') or upload_log ('log') row into the shared candidate shape."""
    if origin == 'trace':
        at, key = row.get('created_at'), row.get('upload_type')
        status, source, skipped, period_text = (row.get('status'), row.get('source'),
                                                row.get('skipped'), None)
    else:
        at, key = row.get('uploaded_at'), row.get('file_type')
        # upload_log has no source/status columns — report that honestly as unknown rather than
        # guessing 'manual' (the epay sweep writes upload_log rows too).
        status, source, skipped, period_text = None, None, None, row.get('period')
    if not at or not key:
        return None
    rs = row.get('rows_saved')
    return {'key': str(key), 'at': str(at), 'ts': _upload_ts(at),
            'rows_saved': (int(rs) if isinstance(rs, (int, float)) else None),
            'status': status, 'source': source, 'skipped': skipped, 'period_text': period_text,
            'filename': row.get('filename'), 'id': row.get('id'),
            'origin': ('upload_trace' if origin == 'trace' else 'upload_log')}


def _upload_last_public(c, extra=None):
    """Candidate → the wire shape (drops the internal sort key / row id)."""
    return {'at': c['at'], 'rows_saved': c['rows_saved'], 'status': c['status'],
            'source': c['source'], 'source_label': _UPLOAD_SOURCE_LABEL.get(c['source'] or '',
                                                                            (c['source'] or '').replace('_', ' ')),
            'skipped': c['skipped'], 'origin': c['origin'], 'filename': c['filename'],
            **(extra or {})}


@router.get("/upload/last")
def upload_last_by_report(types: str = "", limit: int = 1200, org_id: str = ORG_ID):
    """LAST SET OF DATA per report, for THIS org — powers the "Last upload: …" line on every Data
    Imports tile and on the manual MA upload page.

    Per report key it answers two different questions honestly:
      • `last_at` / `rows_saved` / `period` / `span`  — the newest ingest that actually LANDED rows
      • `latest_attempt`                              — present ONLY when a NEWER attempt saved nothing
        (a price-guard refusal, a parser that read no rows, an error), so a tile can never imply fresh
        data arrived when the last file was refused.

    `types` is an optional CSV of report keys the caller cares about: any of them absent from the recent
    window gets a targeted newest-row lookup (a monthly report can be older than the last `limit`
    ingests on a tenant that sweeps hourly), and any with no record at all is returned explicitly with
    `last_at: null` instead of being silently missing.

    Read-only + org-scoped (RULE ONE: org_id is a QUERY PARAM; every read is .eq('org_id', …)).
    Degrades gracefully — a missing upload_trace (mig 202 unrun) or upload_log (mig 007) is reported in
    `hint` and the other journal still answers; it never 500s."""
    require_org(org_id)
    client = sb()
    want = {t.strip() for t in (types or '').split(',') if t.strip()}
    win = max(1, min(int(limit or 1200), 5000))
    cands, sources_read, hints = [], [], []

    # 1. the recent window of each journal (newest first), light columns only
    for tbl, cols, order_col, origin in (
            ('upload_trace', _UPLOAD_LAST_TRACE_COLS, 'created_at', 'trace'),
            ('upload_log', _UPLOAD_LAST_LOG_COLS, 'uploaded_at', 'log')):
        try:
            rows = (client.schema('commcalc').table(tbl).select(cols)
                    .eq('org_id', org_id).order(order_col, desc=True).limit(win).execute().data) or []
            sources_read.append(tbl)
            for r in rows:
                c = _upload_last_cand(r, origin)
                if c:
                    cands.append(c)
        except Exception as e:
            mig = 'migration 202' if tbl == 'upload_trace' else '007_upload_log.sql'
            hints.append(f'{tbl} unavailable (run {mig}): {str(e)[:160]}')

    # 2. targeted lookup for asked-about keys the window didn't reach. Two queries at most per key:
    #    the newest row, then — only if that one saved nothing — the newest row that DID land rows.
    seen = {c['key'] for c in cands}
    for t in sorted(want - seen)[:40]:
        for tbl, cols, order_col, key_col, origin in (
                ('upload_trace', _UPLOAD_LAST_TRACE_COLS, 'created_at', 'upload_type', 'trace'),
                ('upload_log', _UPLOAD_LAST_LOG_COLS, 'uploaded_at', 'file_type', 'log')):
            if tbl not in sources_read:
                continue
            try:
                rows = (client.schema('commcalc').table(tbl).select(cols)
                        .eq('org_id', org_id).eq(key_col, t)
                        .order(order_col, desc=True).limit(1).execute().data) or []
                c = _upload_last_cand(rows[0], origin) if rows else None
                if c:
                    cands.append(c)
                    if not (c['rows_saved'] or 0) > 0:
                        landed = (client.schema('commcalc').table(tbl).select(cols)
                                  .eq('org_id', org_id).eq(key_col, t).gt('rows_saved', 0)
                                  .order(order_col, desc=True).limit(1).execute().data) or []
                        c2 = _upload_last_cand(landed[0], origin) if landed else None
                        if c2:
                            cands.append(c2)
            except Exception as e:
                print(f'WARN upload/last targeted lookup for {t} in {tbl} skipped: {e}')

    # 3. fold → newest-that-landed + newest-overall, per key
    landed_by, newest_by = {}, {}
    for c in cands:
        k = c['key']
        if k not in newest_by or c['ts'] > newest_by[k]['ts']:
            newest_by[k] = c
        if (c['rows_saved'] or 0) > 0 and (k not in landed_by or c['ts'] > landed_by[k]['ts']):
            landed_by[k] = c

    # 4. the winners' rich detail (per-period + per-day saved counts) — one extra query, by id
    detail = {}
    ids = [c['id'] for c in landed_by.values() if c['origin'] == 'upload_trace' and c.get('id')]
    if ids:
        try:
            for r in ((client.schema('commcalc').table('upload_trace')
                       .select('id,periods,date_counts,note,rows_in,target_table')
                       .eq('org_id', org_id).in_('id', ids).limit(len(ids)).execute().data) or []):
                detail[str(r.get('id'))] = r
        except Exception as e:
            print(f'WARN upload/last detail fetch skipped: {e}')

    reports = {}
    for k in sorted(set(landed_by) | set(newest_by) | want):
        landed, newest = landed_by.get(k), newest_by.get(k)
        d = detail.get(str((landed or {}).get('id'))) or {}
        periods = d.get('periods') if isinstance(d.get('periods'), dict) else None
        dcounts = d.get('date_counts') if isinstance(d.get('date_counts'), dict) else None
        days = sorted(str(x) for x in dcounts) if dcounts else []
        period = None
        if periods and len(periods) == 1:
            period = str(next(iter(periods)))
        elif landed and landed.get('period_text'):
            period = str(landed['period_text'])
        rec = {'key': k, 'last_at': (landed or {}).get('at'),
               'rows_saved': (landed or {}).get('rows_saved'),
               'rows_in': d.get('rows_in'), 'target_table': d.get('target_table'),
               'status': (landed or {}).get('status'), 'origin': (landed or {}).get('origin'),
               'source': (landed or {}).get('source'),
               'source_label': (_UPLOAD_SOURCE_LABEL.get((landed or {}).get('source') or '',
                                                         ((landed or {}).get('source') or '').replace('_', ' '))
                                or None),
               'filename': (landed or {}).get('filename'),
               'period': period, 'periods': periods,
               'span': ([days[0], days[-1]] if days else None), 'days': (len(days) or None),
               'note': d.get('note'), 'latest_attempt': None}
        # A newer attempt that did NOT land rows is the whole point of the honesty line.
        if newest and (not landed or newest['ts'] > landed['ts']):
            rec['latest_attempt'] = _upload_last_public(newest)
        reports[k] = rec

    return {'ok': True, 'org_id': org_id, 'count': len(reports), 'reports': reports,
            'sources': sources_read, 'asked': sorted(want),
            'hint': ('; '.join(hints) or None)}


# ── VIP Wireless invoice import (scraped via tools/vip_scraper) ───────────────
def _vip_money(v):
    """'$1,234.50' / '(12.47)' / '199.5' / '' -> float or None."""
    import re as _re
    if v is None:
        return None
    s = str(v).strip()
    if not s or s.lower() in ('nan', 'nat', 'none'):
        return None
    neg = '(' in s and ')' in s
    s = _re.sub(r'[^0-9.\-]', '', s.replace(',', ''))
    if s in ('', '-', '.'):
        return None
    try:
        f = float(s)
    except ValueError:
        return None
    return -f if neg else f


def _vip_int(v):
    s = str(v or '').strip()
    if not s or s.lower() in ('nan', 'none'):
        return None
    try:
        return int(float(s))
    except ValueError:
        return None


def _vip_ts(v):
    """Pass an ISO timestamp string through; '' -> None."""
    s = str(v or '').strip()
    if not s or s.lower() in ('nan', 'nat', 'none'):
        return None
    return s[:19] if 'T' in s else (s[:10] or None)


def _vip_period(created_on):
    """'2026-06-12T02:25:37' -> ('June 2026', 6, 2026)."""
    s = str(created_on or '').strip()
    if len(s) < 7:
        return None, None, None
    try:
        y, m = int(s[0:4]), int(s[5:7])
        return f"{_calendar.month_name[m]} {y}", m, y
    except Exception:
        return None, None, None


@router.post("/vip/upload")
async def upload_vip_invoices(file: UploadFile = File(...), org_id: str = ORG_ID):
    """Import the VIP scraper workbook (Invoices / Lines / Devices sheets) from
    tools/vip_scraper. Full replace: the portal has no per-period upload, so we
    wipe all VIP rows for the org and re-insert the full history each time."""
    require_org(org_id)
    contents = await file.read()
    try:
        xls = pd.ExcelFile(io.BytesIO(contents))
    except Exception as e:
        raise HTTPException(400, f"Could not read Excel file: {e}")
    sheets = set(xls.sheet_names)
    if 'Invoices' not in sheets:
        raise HTTPException(400, f"Missing 'Invoices' sheet. Found: {sorted(sheets)}")

    def sheet(name):
        if name not in sheets:
            return []
        return pd.read_excel(xls, sheet_name=name, dtype=str).fillna('').to_dict('records')

    def numc(r, *names):
        for n in names:
            if str(r.get(n, '')).strip() not in ('', 'nan', 'None'):
                return _vip_money(r.get(n))
        return None

    invoices = []
    for r in sheet('Invoices'):
        period, pm, py = _vip_period(r.get('CreatedOn', ''))
        invoices.append({
            'org_id': org_id,
            'vip_id': _vip_int(r.get('Id')),
            'invoice_number': str(r.get('InvoiceNumber', '')).strip() or None,
            'order_number': str(r.get('OrderNumber', '')).strip() or None,
            'location': r.get('Location', '') or None,
            'company_id': _vip_int(r.get('CompanyId')),
            'email': r.get('Email', '') or None,
            'status': r.get('Status', '') or None,
            'sub_total': numc(r, 'SubTotalNum', 'SubTotal'),
            'shipping': numc(r, 'ShippingNum', 'Shipping'),
            'discount': numc(r, 'DiscountNum', 'Discount'),
            'other_cost': numc(r, 'OtherCostNum', 'OtherCost'),
            'other_deductions': numc(r, 'OtherDeductionsNum', 'OtherDeductions'),
            'tax': numc(r, 'TaxNum', 'Tax'),
            'grand_total': numc(r, 'GrandTotalNum', 'GrandTotal'),
            'note': r.get('Note', '') or None,
            'created_on': _vip_ts(r.get('CreatedOn')),
            'transaction_date': _vip_ts(r.get('TransactionDate')),
            'due_date': _vip_ts(r.get('DueDate')),
            'period': period, 'period_month': pm, 'period_year': py,
        })

    lines = []
    for r in sheet('Lines'):
        period, pm, py = _vip_period(r.get('CreatedOn', ''))
        lines.append({
            'org_id': org_id,
            'vip_invoice_id': _vip_int(r.get('InvoiceId')),
            'invoice_number': str(r.get('InvoiceNumber', '')).strip() or None,
            'location': r.get('Location', '') or None,
            'status': r.get('Status', '') or None,
            'created_on': _vip_ts(r.get('CreatedOn')),
            'name': r.get('Name', '') or None,
            'note': r.get('Note', '') or None,
            'sku': r.get('SKU', '') or None,
            'price': numc(r, 'PriceNum', 'Price'),
            'quantity': _vip_money(r.get('Quantity')),
            'total': numc(r, 'TotalNum', 'Total'),
            'period': period, 'period_month': pm, 'period_year': py,
        })

    devices = []
    for r in sheet('Devices'):
        period, pm, py = _vip_period(r.get('CreatedOn', ''))
        devices.append({
            'org_id': org_id,
            'vip_invoice_id': _vip_int(r.get('InvoiceId')),
            'invoice_number': str(r.get('InvoiceNumber', '')).strip() or None,
            'location': r.get('Location', '') or None,
            'created_on': _vip_ts(r.get('CreatedOn')),
            'serial': str(r.get('Serial', '')).strip() or None,
            'product_name': r.get('ProductName', '') or None,
            'imei': str(r.get('IMEI', '')).strip() or None,
            'sim': str(r.get('SIM', '')).strip() or None,
            'period': period, 'period_month': pm, 'period_year': py,
        })

    client = sb()
    SENTINEL = '00000000-0000-0000-0000-000000000000'
    for tbl in ('vip_invoices', 'vip_invoice_lines', 'vip_invoice_devices'):
        try:
            # scope the wipe to THIS tenant — a bare delete-all would nuke every tenant's VIP invoices
            client.schema('commcalc').table(tbl).delete().eq('org_id', org_id).neq('id', SENTINEL).execute()
        except Exception as e:
            raise HTTPException(500, f"Failed clearing {tbl}: {e}. Did you run 008_vip_invoices.sql?")

    def insert_all(tbl, rows):
        saved = 0
        for i in range(0, len(rows), 500):
            batch = rows[i:i + 500]
            try:
                client.schema('commcalc').table(tbl).insert(batch).execute()
            except Exception as e:
                raise HTTPException(500, f"Insert into {tbl} failed at row {i}: {e}")
            saved += len(batch)
        return saved

    n_inv = insert_all('vip_invoices', invoices)
    n_line = insert_all('vip_invoice_lines', lines)
    n_dev = insert_all('vip_invoice_devices', devices)

    try:
        client.schema('commcalc').table('upload_log').insert({
            'org_id': org_id, 'file_type': 'vip_invoices', 'period': None,
            'filename': getattr(file, 'filename', None),
            'rows_saved': n_inv + n_line + n_dev,
        }).execute()
    except Exception as e:
        print(f'WARN upload_log insert failed: {e}')

    # mig-202 upload_trace under the REPORT KEY the connector registry uses ('vip_workbook'), so import
    # health sees a hand-uploaded workbook as a real delivery instead of reporting the feed as never-run.
    _write_upload_trace(org_id, source="manual", filename=getattr(file, 'filename', None),
                        upload_type="vip_workbook", period="",
                        result={"saved": n_inv + n_line + n_dev,
                                "note": f"{n_inv} invoices, {n_line} lines, {n_dev} devices",
                                "_trace": {"rows_in": n_inv + n_line + n_dev,
                                           "target_table": "vip_invoices"}})
    return {"invoices": n_inv, "lines": n_line, "devices": n_dev}


# ── VIP invoice reports ──────────────────────────────────────────────────────
VIP_FEE_COLS = ['shipping', 'discount', 'other_cost', 'other_deductions', 'tax']


def _vip_fetch(client, org_id, period=None, location=None, status=None, cols="*"):
    """Paginated fetch of vip_invoices (Supabase caps at 1000 rows/request)."""
    PAGE, out, frm = 1000, [], 0
    while True:
        q = client.schema('commcalc').table('vip_invoices').select(cols).eq('org_id', org_id)
        if period:
            q = q.in_('period', _pvariants(period))
        if location:
            q = q.eq('location', location)
        if status:
            q = q.eq('status', status)
        batch = (q.range(frm, frm + PAGE - 1).execute().data) or []
        out.extend(batch)
        if len(batch) < PAGE:
            break
        frm += PAGE
    return out


@router.get("/vip/filter-options")
def vip_filter_options(org_id: str = ORG_ID):
    """Distinct stores / periods / statuses for the VIP page filter bar."""
    require_org(org_id)
    rows = _vip_fetch(sb(), org_id, cols="location,period,period_year,period_month,status")
    locations = sorted({r['location'] for r in rows if r.get('location')})
    statuses = sorted({r['status'] for r in rows if r.get('status')})
    pmap = {}
    for r in rows:
        if r.get('period'):
            pmap[r['period']] = (r.get('period_year') or 0, r.get('period_month') or 0)
    periods = sorted(pmap, key=lambda p: pmap[p], reverse=True)
    return {"locations": locations, "periods": periods, "statuses": statuses}


@router.get("/vip/summary")
async def vip_summary(org_id: str = ORG_ID, period: str = "", location: str = "", status: str = ""):
    """Totals, fees-by-type (invoice money buckets), and per-store breakdown."""
    require_org(org_id)
    cols = "location,sub_total,shipping,discount,other_cost,other_deductions,tax,grand_total"
    rows = _vip_fetch(sb(), org_id, period or None, location or None, status or None, cols=cols)

    def f(v):
        try:
            return float(v or 0)
        except (TypeError, ValueError):
            return 0.0

    totals = {"invoices": len(rows), "sub_total": 0.0, "grand_total": 0.0}
    for c in VIP_FEE_COLS:
        totals[c] = 0.0
    by_store: dict = {}
    for r in rows:
        loc = r.get('location') or '—'
        s = by_store.setdefault(loc, {"location": loc, "invoices": 0, "sub_total": 0.0,
                                      "grand_total": 0.0, **{c: 0.0 for c in VIP_FEE_COLS}})
        s["invoices"] += 1
        s["sub_total"] += f(r.get('sub_total'))
        s["grand_total"] += f(r.get('grand_total'))
        totals["sub_total"] += f(r.get('sub_total'))
        totals["grand_total"] += f(r.get('grand_total'))
        for c in VIP_FEE_COLS:
            v = f(r.get(c))
            s[c] += v
            totals[c] += v
    totals["fees_total"] = sum(totals[c] for c in VIP_FEE_COLS)
    by_store_list = sorted(by_store.values(), key=lambda x: x["grand_total"], reverse=True)
    return {"totals": totals,
            "fees_by_type": {c: totals[c] for c in VIP_FEE_COLS},
            "by_store": by_store_list}


@router.get("/vip/invoices")
async def vip_invoices_list(org_id: str = ORG_ID, period: str = "", location: str = "",
                            status: str = "", limit: int = 2000, offset: int = 0):
    """Invoice list for the table + Excel/PDF export (newest first)."""
    require_org(org_id)
    q = sb().schema('commcalc').table('vip_invoices').select(
        "vip_id,invoice_number,order_number,location,status,created_on,due_date,"
        "sub_total,shipping,discount,other_cost,other_deductions,tax,grand_total,period"
    ).eq('org_id', org_id)
    if period:
        q = q.in_('period', _pvariants(period))
    if location:
        q = q.eq('location', location)
    if status:
        q = q.eq('status', status)
    lim = min(max(limit, 1), 5000)
    return (q.order('created_on', desc=True).range(offset, offset + lim - 1).execute().data) or []


@router.get("/vip/invoice/{vip_id}")
def vip_invoice_detail(vip_id: int, org_id: str = ORG_ID):
    """One invoice's full contents for the click-through preview: header + line items + devices."""
    require_org(org_id)
    client = sb()
    hdr = client.schema('commcalc').table('vip_invoices').select(
        "vip_id,invoice_number,order_number,location,status,created_on,transaction_date,due_date,"
        "sub_total,shipping,discount,other_cost,other_deductions,tax,grand_total,note,period"
    ).eq('org_id', org_id).eq('vip_id', vip_id).limit(1).execute().data
    if not hdr:
        raise HTTPException(404, f"Invoice {vip_id} not found")
    lines = client.schema('commcalc').table('vip_invoice_lines').select(
        "name,note,sku,price,quantity,total"
    ).eq('org_id', org_id).eq('vip_invoice_id', vip_id).execute().data or []
    devices = client.schema('commcalc').table('vip_invoice_devices').select(
        "serial,product_name,imei,sim"
    ).eq('org_id', org_id).eq('vip_invoice_id', vip_id).execute().data or []
    return {"invoice": hdr[0], "lines": lines, "devices": devices}


# ── VIP portal auto-sweep (admin-configurable credentials + schedule) ─────────
# Runs the scraper INSIDE the backend on a schedule (pg_cron → /vip/sweep/run-due),
# instead of the manual Codespace run. Creds + schedule live in the backend-only table
# commcalc.vip_sweep_config; the password is never returned to the browser.
def _vip_cfg(client, org_id):
    rows = client.schema('commcalc').table('vip_sweep_config').select('*') \
        .eq('org_id', org_id).limit(1).execute().data
    return rows[0] if rows else None


def _vip_next_run(frequency, day_of_week, day_of_month, hour, tzname, minute=0):
    """Next run (UTC ISO) after now, in `tzname`. day_of_week 0=Mon..6=Sun.

    `minute` (added 2026-08-09, default 0 so every existing caller is unchanged) exists because a
    per-report slot needs a real time, not just an hour: Comprehensive Comp is pulled at 23:30
    because the carrier posts the day's compensation late in the evening."""
    from zoneinfo import ZoneInfo
    import calendar as _c
    try:
        tz = ZoneInfo(tzname or 'America/New_York')
    except Exception:
        tz = ZoneInfo('America/New_York')
    now = _datetime.now(tz)
    hour = int(hour if hour is not None else 6)
    minute = min(59, max(0, int(minute or 0)))
    if frequency == 'hourly':
        # Intra-day feed (e.g. the daily-transaction report pulled every hour for live targets).
        # `hour` is ignored; the next run is simply the top of the next hour.
        nxt = now.replace(minute=minute, second=0, microsecond=0) + _timedelta(hours=1)
    elif frequency == 'daily':
        nxt = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
        if nxt <= now:
            nxt += _timedelta(days=1)
    elif frequency == 'monthly':
        dom = int(day_of_month if day_of_month is not None else 1)

        def at(y, m):
            d = min(dom, _c.monthrange(y, m)[1])
            return now.replace(year=y, month=m, day=d, hour=hour, minute=minute, second=0, microsecond=0)
        nxt = at(now.year, now.month)
        if nxt <= now:
            ny, nm = (now.year + 1, 1) if now.month == 12 else (now.year, now.month + 1)
            nxt = at(ny, nm)
    else:  # weekly (default)
        target = int(day_of_week if day_of_week is not None else 0)
        nxt = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
        nxt += _timedelta(days=(target - nxt.weekday()) % 7)
        if nxt <= now:
            nxt += _timedelta(days=7)
    return nxt.astimezone(_timezone.utc).isoformat()


_VIP_CFG_DEFAULTS = {'enabled': False, 'frequency': 'weekly', 'day_of_week': 0,
                     'day_of_month': 1, 'hour': 6, 'timezone': 'America/New_York',
                     'lookback_days': 14, 'sweep_invoices': True, 'sweep_asset': False,
                     'sweep_creditmemo': False, 'sweep_asset_ledger': True, 'sweep_chargebacks': True}


def _vip_public_cfg(cfg):
    """Config WITHOUT the password — only whether credentials are set."""
    if not cfg:
        return {**_VIP_CFG_DEFAULTS, 'configured': False, 'has_credentials': False,
                'portal_user': None, 'next_run_at': None, 'last_run_at': None,
                'last_status': None, 'last_detail': None}
    out = {k: cfg.get(k) for k in (
        'enabled', 'frequency', 'day_of_week', 'day_of_month', 'hour', 'timezone',
        'lookback_days', 'sweep_invoices', 'sweep_asset', 'sweep_creditmemo', 'sweep_asset_ledger',
        'sweep_chargebacks', 'portal_user', 'next_run_at', 'last_run_at', 'last_status', 'last_detail',
        'last_attempt_at')}
    out['configured'] = True
    out['has_credentials'] = bool(cfg.get('portal_user') and cfg.get('portal_pass'))
    return out


# ── IMPORT-FRESHNESS TRAIL (owner directive 2026-07-26) ──────────────────────────────────────────
# core.import_evidence (mig 717) answers "when did this feed last DELIVER data?" for every portal feed
# from ONE column: commcalc.<x>_sweep_config.last_run_at / commcalc.data_source.last_run_at. So
# last_run_at MUST mean "the last run that actually imported something".
#
# It used to be bumped on FAILURE too (rejected credentials, "needs login", a sweep with every report
# switched off, even merely opening the portal login screen). Consequence: a connector that had imported
# nothing for weeks looked FRESH, so the admin attention popup stayed silent — the exact opposite of the
# directive. Every non-delivering attempt now records `last_attempt_at` (mig 241) instead, and the UI
# shows both ("Last success" vs "Last attempt").
#
# Degrades: if last_attempt_at doesn't exist yet the write is retried without it, so the freshness fix is
# live BEFORE the SQL runs. Scheduling is untouched — the /run-due sweeps key off next_run_at, never
# last_run_at — and nothing else in the codebase treats last_run_at as "attempted".
_OPTIONAL_STATUS_COLS = ('last_attempt_at',)
_MISSING_STATUS_COLS: set = set()     # (table, column) pairs this database doesn't have yet


def _status_update(client, table, upd, filt):
    """UPDATE commcalc.<table> SET <upd> WHERE <filt(...)>, tolerating a not-yet-migrated column.

    `filt` applies the row filter (org_id / id) so every caller keeps its RULE ONE scoping. A failure
    for any reason OTHER than an optional column is re-raised — a real DB error must still surface."""
    row = {k: v for k, v in upd.items() if (table, k) not in _MISSING_STATUS_COLS}
    try:
        filt(client.schema('commcalc').table(table).update(row)).execute()
        return
    except Exception:
        opt = [k for k in row if k in _OPTIONAL_STATUS_COLS]
        if not opt:
            raise
    for k in opt:
        _MISSING_STATUS_COLS.add((table, k))     # probe once per process, then stop paying for it
    filt(client.schema('commcalc').table(table).update(
        {k: v for k, v in row.items() if k not in opt})).execute()


def _import_admin_strict():
    """Break-glass for the 2026-08-06 FAIL-CLOSED import-admin gate (security finding H3).

    Default ON. IMPORT_ADMIN_STRICT=0 restores the pre-2026-08-06 degrade-open behaviour for one
    deploy if a real lock-out ever appears. Deliberately an ENV VAR, not a silent default — the same
    never-strand-the-operator posture as REQUIRE_AUTH / IDENTITY_BACKEND_503 / STRICT_MEMBERSHIP in
    the middleware, and the same shape the privesc package (cad0aa9) used for H2."""
    return _os.environ.get("IMPORT_ADMIN_STRICT", "1").strip().lower() not in ("0", "false", "no", "off")


def _require_import_admin(authorization, org_id):
    """Editing an IMPORT CHANNEL (portal credentials, mailbox rules, schedules) is a settings action.

    Gated on core's registered 'import_health' settings area, so an owner can grant it to one role in the
    Roles UI instead of it being open to everyone with the page.

    FAIL-CLOSED (finding H3, 2026-08-06). This used to `return` — i.e. ALLOW — whenever the caller
    could not be resolved, and its bare `except Exception: return` turned ANY error (an import
    failure, a membership-store outage, a bad JWT round trip) into an ALLOW as well. That made these
    ten endpoints — portal credentials, mailbox rules, FTP creds, schedules — effectively ungated for
    an unauthenticated request, which is exactly the credential set the C4 SSRF abuses: write a
    portal_url, then read the rendered result back. It now follows the posture the privesc package
    (cad0aa9) established for the identity/RBAC gates:

      no/invalid token          -> 401  (was: ALLOW)
      token valid, no membership-> 403  (was: ALLOW)
      membership store errored  -> 503  (was: ALLOW)   — honest "can't tell", never a silent yes
      resolved, lacks the right -> 403  (unchanged)

    Verified before flipping: none of the ten gated handlers is ever called IN-PROCESS (which would
    bind FastAPI's Header sentinel and look like "no token"), so no existing automation loses access;
    every caller is a real HTTP request from the settings UI carrying the operator's bearer token.
    Break-glass if that turns out to be wrong anywhere: IMPORT_ADMIN_STRICT=0."""
    try:
        from app.modules.core.router import _uid_from_token, _resolve_caller, _can_edit_setting
    except Exception:
        if not _import_admin_strict():
            return
        raise HTTPException(503, "Permissions are temporarily unavailable — try again in a moment.")
    uid = _uid_from_token(authorization)
    if not uid:
        if not _import_admin_strict():
            return
        raise HTTPException(401, "Sign in to change import connections.")
    try:
        caller = _resolve_caller(sb(), uid)
    except Exception:
        if not _import_admin_strict():
            return
        raise HTTPException(503, "Permissions are temporarily unavailable — try again in a moment.")
    if caller is None:
        if not _import_admin_strict():
            return
        raise HTTPException(403, "This login isn't attached to a tenant, so it can't change import "
                                 "connections. Ask an administrator to add you.")
    if caller.get("super_admin") or _can_edit_setting(caller, "import_health"):
        return caller
    raise HTTPException(403, "You don't have permission to change import connections. Ask an "
                             "administrator to grant your role the 'Import Health' setting.")


def _sweep_set_status(client, table, org_id, status, detail, mark_run=False, success=None):
    """Record ONE portal sweep's outcome on its own *_sweep_config row.

    mark_run — this call ends a run (not the 'running…' heartbeat, which must stamp no timestamp).
    success  — did the run actually IMPORT data? Defaults to status in ('ok','partial'); only a success
               advances last_run_at (the freshness trail core.import_evidence reads)."""
    upd = {'last_status': status, 'last_detail': (detail or '')[:600]}
    if mark_run:
        ok = (str(status or '').strip().lower() in ('ok', 'partial')) if success is None else bool(success)
        upd['last_run_at' if ok else 'last_attempt_at'] = _datetime.now(_timezone.utc).isoformat()
    _status_update(client, table, upd, lambda q: q.eq('org_id', org_id))


def _vip_set_status(client, org_id, status, detail, mark_run=False, success=None):
    _sweep_set_status(client, 'vip_sweep_config', org_id, status, detail, mark_run, success)


def _registry_auto_map(client, org_id):
    """report_definitions.auto by report_key — CARRIER-SCOPED. The registry (Connectors page) drives which reports a
    sweep pulls. A report with no registry row falls back to the connector's config toggle, so this is
    a zero-behavior-change cutover (the seeded auto flags already match the live toggles)."""
    try:
        rows = (client.schema('commcalc').table('report_definitions')
                .select('report_key,auto,carrier_id').eq('org_id', org_id).execute().data) or []
    except Exception:
        try:    # pre-291 database has no carrier_id — degrade to the un-scoped read, never to {}
            rows = (client.schema('commcalc').table('report_definitions')
                    .select('report_key,auto').eq('org_id', org_id).execute().data) or []
        except Exception:
            return {}
    # CARRIER SCOPE (mig 291): never auto-pull a report belonging to a carrier this tenant does not
    # run. A row with carrier_id NULL is carrier-agnostic and always considered.
    carriers = _tenant_carriers(client, org_id)
    return {r['report_key']: bool(r['auto']) for r in rows
            if r.get('report_key') and _carrier_visible(r, carriers)}


# Columns the sweep reads per report. Kept as a literal list so a pre-290 database (which lacks the
# schedule columns) can be detected and degraded gracefully rather than 400-ing the whole sweep.
_REGISTRY_SWEEP_COLS = ('report_key,auto,refresh_months,refresh_days,'
                        'sweep_hour,sweep_minute,sweep_timezone,sweep_next_run_at')


def _registry_report_cfg(client, org_id):
    """Per-report sweep configuration from commcalc.report_definitions, keyed by report_key.

    This is the SAP-configurable half of two live defects: `refresh_months` had been a column on
    this table (set to 3 for mi_report) that NOTHING READ — the multi-month refresh was a Python
    constant applied to the comp leg only, so MI never re-pulled a closed month and every one of
    them froze mid-accrual. `sweep_hour` (migration 290) is the same idea for time: the connector
    has ONE hour for all three reports, but Comprehensive Comp must run at 23:30 because the
    carrier posts the day's compensation late in the evening.

    Degrades to {} — i.e. the built-in defaults — if migration 290 has not been applied."""
    try:
        rows = (client.schema('commcalc').table('report_definitions')
                .select(_REGISTRY_SWEEP_COLS).eq('org_id', org_id).execute().data) or []
    except Exception as e:
        # pre-290: the schedule columns don't exist yet. Fall back to the columns that do.
        print(f'WARN report_definitions sweep columns unavailable (run migration 290?): {e}')
        try:
            rows = (client.schema('commcalc').table('report_definitions')
                    .select('report_key,auto,refresh_months').eq('org_id', org_id).execute().data) or []
        except Exception:
            return {}
    out = {r['report_key']: r for r in rows if r.get('report_key')}
    # Optional operator override: a pinned portal report id (e.g. the Daily Transaction Detail menu id)
    # so the sweep need not resolve it by label. Read in isolation so a database without the column
    # never disturbs the main select above.
    try:
        pin = (client.schema('commcalc').table('report_definitions')
               .select('report_key,portal_report_id').eq('org_id', org_id).execute().data) or []
        for p in pin:
            rk = p.get('report_key')
            if rk in out and p.get('portal_report_id'):
                out[rk]['portal_report_id'] = p['portal_report_id']
    except Exception:
        pass
    return out


def _epay_sub_schedule(client, org_id, now_iso):
    """Split the ePay reports into (due_on_their_own_slot, riding_the_connector_slot).

    Migration 290 lets a single report own a time: `report_definitions.sweep_hour/sweep_minute`.
    Comprehensive Comp needs 23:30 because the carrier posts the day's compensation late in the
    evening — pulling it on the connector's 06:00 slot returned an empty workbook every time and
    was logged as a failure for eight weeks. MI and payment detail stay on 06:00 untouched.

    Reports whose own slot has come round are returned in the first list AND have their
    `sweep_next_run_at` advanced here, so a caller that fires hourly does not re-run them. Reports
    with no slot of their own are returned in the second list for the caller to run when the
    CONNECTOR is due. Degrades to ([], all reports) if migration 290 is not applied, which is
    exactly today's behaviour."""
    all_keys = list(_EPAY_REGISTRY_KEYS)
    try:
        defs = (client.schema('commcalc').table('report_definitions')
                .select('id,report_key,auto,sweep_hour,sweep_minute,sweep_timezone,sweep_next_run_at')
                .eq('org_id', org_id).execute().data) or []
    except Exception as e:
        print(f'WARN per-report schedule unavailable (run migration 290?): {e}')
        return [], all_keys
    by_report = {d.get('report_key'): d for d in defs}
    tzname = None
    try:
        _c = _epay_cfg(client, org_id) or {}
        tzname = _c.get('timezone')
    except Exception:
        pass
    due, shared = [], []
    for key, rkey in _EPAY_REGISTRY_KEYS.items():
        d = by_report.get(rkey)
        # Daily Transaction Detail: idempotent upsert makes an hourly re-pull safe and cheap, and the
        # recon wants the freshest portal data EVERY tick — so it is due on every run-due (not just on
        # the connector's daily slot), unless the registry explicitly disables it (auto=False).
        if key == 'epay_daily_tx':
            if d is not None and d.get('auto') is False:
                continue
            due.append(key)
            continue
        if not d or d.get('sweep_hour') is None:
            shared.append(key)          # no slot of its own -> rides the connector
            continue
        if not d.get('auto'):
            continue                    # switched off in the registry
        nra = d.get('sweep_next_run_at')
        if nra and nra > now_iso:
            continue                    # its slot has not come round yet
        nxt = _vip_next_run('daily', None, None, d.get('sweep_hour'),
                            d.get('sweep_timezone') or tzname,
                            minute=int(d.get('sweep_minute') or 0))
        try:
            client.schema('commcalc').table('report_definitions').update(
                {'sweep_next_run_at': nxt, 'sweep_last_run_at': now_iso}).eq('id', d['id']).execute()
        except Exception as e:
            print(f'WARN could not advance {rkey} slot: {e}')
        due.append(key)
    return due, shared


def _do_vip_sweep(org_id):
    """Background worker: read creds from the config table, run the invoice sweep, record status."""
    client = sb()
    cfg = _vip_cfg(client, org_id)
    if not cfg or not cfg.get('portal_user') or not cfg.get('portal_pass'):
        _vip_set_status(client, org_id, 'error', 'No Distributor credentials set in the admin area', mark_run=True)
        return
    _vip_set_status(client, org_id, 'running', 'Sweep in progress…')
    # Default to the invoice sweep (back-compat: cfg may predate the toggles). sweep_asset
    # additionally pulls the PayGo / asset-lending weekly billing ledger (migration 014).
    amap = _registry_auto_map(client, org_id)
    def _en(key, fb):
        return amap[key] if key in amap else fb
    do_invoices = _en('vip_workbook', cfg.get('sweep_invoices') is not False)
    do_asset = bool(cfg.get('sweep_asset'))               # PayGo billing: no registry row → config
    do_creditmemo = bool(cfg.get('sweep_creditmemo'))     # credit memos: no registry row → config
    do_asset_ledger = _en('asset_ledger', cfg.get('sweep_asset_ledger') is not False)
    do_chargebacks = _en('vip_chargebacks', cfg.get('sweep_chargebacks') is not False)
    lookback = int(cfg.get('lookback_days') or 14)
    u, pw = cfg['portal_user'], cfg['portal_pass']
    helpers = (_vip_money, _vip_int, _vip_ts, _vip_period)
    parts, errs = [], []

    # Each step runs independently (its own login + session): a network timeout / portal hiccup on
    # one report no longer aborts the rest, so the asset-ledger + chargebacks still land even if an
    # earlier step flakes. A login failure surfaces per-step. Status = ok | partial | error.
    def _step(name, enabled, fn):
        if not enabled:
            return
        try:
            parts.append(fn())
        except vip_sweep.VipLoginError as e:
            errs.append(f"{name}: {e}")
        except Exception as e:
            errs.append(f"{name}: {str(e)[:140]}")

    def _invoices():
        res = vip_sweep.run_invoice_sweep(client, org_id, u, pw, lookback, helpers)
        return f"{res['invoices']} invoices, {res['lines']} lines, {res['devices']} devices ({res['window']})"

    def _paygo():
        ar = vip_sweep.run_paygo_sweep(client, org_id, u, pw, lookback)
        owed = f"${ar['current_owed']:,.2f}" if ar.get('current_owed') is not None else "n/a"
        return f"PayGo: {ar['payments']} batches (current owed {owed})"

    def _creditmemo():
        cr = vip_sweep.run_creditmemo_sweep(client, org_id, u, pw, helpers)
        return f"Credit memos: {cr['credit_memos']} ({cr['xfinity_excluded']} Xfinity excluded)"

    def _asset_ledger():
        al = vip_sweep.run_asset_ledger_sweep(client, org_id, u, pw)
        return f"Asset ledger: {al['rows']} rows"

    def _chargebacks():
        cb = vip_sweep.run_chargeback_sweep(client, org_id, u, pw)
        return f"Chargebacks: {cb['rows']} staged"

    _step('invoices', do_invoices, _invoices)
    _step('paygo', do_asset, _paygo)
    _step('creditmemo', do_creditmemo, _creditmemo)
    _step('asset_ledger', do_asset_ledger, _asset_ledger)
    _step('chargebacks', do_chargebacks, _chargebacks)

    if not parts and not errs:
        # NOT a delivery: every report toggle is off, so this sweep imported nothing. Recording it as
        # 'ok' + a fresh last_run_at made the feed look healthy forever while no data ever arrived.
        _vip_set_status(client, org_id, 'idle',
                        "Nothing enabled — tick at least one report on the Distributor Sweep page "
                        "(or turn the sweep off if this tenant doesn't use the distributor portal)",
                        mark_run=True, success=False)
        return
    status = 'ok' if not errs else ('partial' if parts else 'error')
    detail = (("OK — " if status == 'ok' else "") + " · ".join(parts)
              + ((" | FAILED: " if parts else "FAILED: ") + " · ".join(errs) if errs else ""))
    _vip_set_status(client, org_id, status, detail, mark_run=True)


@router.get("/vip/sweep/config")
def vip_sweep_get_config(org_id: str = ORG_ID):
    require_org(org_id)
    return _vip_public_cfg(_vip_cfg(sb(), org_id))


class VipSweepPutConfigIn(LaxModel):
    frequency: Any = None
    day_of_week: Any = None
    day_of_month: Any = None
    hour: Any = None
    timezone: Any = None
    lookback_days: Any = None
    sweep_invoices: Any = None
    sweep_asset: Any = None
    sweep_creditmemo: Any = None
    sweep_asset_ledger: Any = None
    sweep_chargebacks: Any = None
    enabled: Any = None
    portal_user: Any = None
    portal_pass: Any = None


@router.put("/vip/sweep/config")
async def vip_sweep_put_config(body: VipSweepPutConfigIn, org_id: str = ORG_ID,
                               authorization: str = Header(default="")):
    """Update creds + schedule. Password is WRITE-ONLY: send portal_pass to change it,
    omit/blank to keep the existing one. Never returns the password."""
    require_org(org_id)
    _require_import_admin(authorization, org_id)
    client = sb()
    cur = _vip_cfg(client, org_id) or {}
    row = {'org_id': org_id}
    for k in ('frequency', 'day_of_week', 'day_of_month', 'hour', 'timezone',
              'lookback_days', 'sweep_invoices', 'sweep_asset', 'sweep_creditmemo',
              'sweep_asset_ledger', 'sweep_chargebacks', 'enabled', 'portal_user'):
        if k in body.model_fields_set and getattr(body, k) is not None:
            row[k] = getattr(body, k)
    pw = (body.portal_pass or '').strip()
    if pw:
        row['portal_pass'] = pw
    row['updated_at'] = _datetime.now(_timezone.utc).isoformat()
    merged = {**_VIP_CFG_DEFAULTS, **cur, **row}
    row['next_run_at'] = _vip_next_run(
        merged.get('frequency') or 'weekly', merged.get('day_of_week'),
        merged.get('day_of_month'), merged.get('hour'), merged.get('timezone'))
    client.schema('commcalc').table('vip_sweep_config').upsert(row, on_conflict='org_id').execute()
    return _vip_public_cfg(_vip_cfg(client, org_id))


@router.post("/vip/sweep/run-now")
def vip_sweep_run_now(background_tasks: BackgroundTasks, org_id: str = ORG_ID):
    """Manual 'Run now' from the admin page (background task)."""
    require_org(org_id)
    cfg = _vip_cfg(sb(), org_id)
    if not cfg or not cfg.get('portal_user') or not cfg.get('portal_pass'):
        raise HTTPException(400, "Set the Distributor credentials first.")
    background_tasks.add_task(_do_vip_sweep, org_id)
    return {"status": "started"}


@router.post("/vip/sweep/run-due")
def vip_sweep_run_due(background_tasks: BackgroundTasks, x_notify_secret: str = Header(default="")):
    """pg_cron entrypoint: run every enabled config whose next_run_at has passed.
    Reuses NOTIFY_RUN_SECRET so no new env var is needed."""
    if not verify_notify_secret(x_notify_secret):
        raise HTTPException(403, "forbidden")
    client = sb()
    now_iso = _datetime.now(_timezone.utc).isoformat()
    due = client.schema('commcalc').table('vip_sweep_config').select('*') \
        .eq('enabled', True).lte('next_run_at', now_iso).execute().data or []
    for cfg in due:
        oid = cfg.get('org_id') or ORG_ID
        nxt = _vip_next_run(cfg.get('frequency') or 'weekly', cfg.get('day_of_week'),
                            cfg.get('day_of_month'), cfg.get('hour'), cfg.get('timezone'))
        client.schema('commcalc').table('vip_sweep_config').update(
            {'next_run_at': nxt}).eq('org_id', oid).execute()
        background_tasks.add_task(_do_vip_sweep, oid)
    return {"triggered": len(due)}


# ── Carrier category map (SaaS framework Phase 1: config-driven canonical components) ────────
def _period_variants(p):
    p = (p or "").strip()
    if not p:
        return []
    out = {p}
    try:
        from dateutil import parser as _dp
        d = _dp.parse(p if len(p) > 7 else p + "-01")
        out.add(d.strftime("%B %Y"))
        out.add(d.strftime("%Y-%m"))
    except Exception:
        pass
    return list(out)


@router.get("/carriers")
def list_carriers(org_id: str = ORG_ID):
    require_org(org_id)
    return (sb().schema("commcalc").table("carrier").select("*").eq("org_id", org_id).order("name").execute().data) or []


class CarrierIn(LaxModel):
    name: str = ""
    code: str = ""
    is_default: Any = None


@router.post("/carriers")
def create_carrier(body: CarrierIn, org_id: str = ORG_ID):
    require_org(org_id)
    name = (body.name or "").strip()
    if not name:
        raise HTTPException(400, "name required")
    is_default = bool(body.is_default)
    row = {"org_id": org_id, "name": name, "code": (body.code or "").strip() or None,
           "is_default": is_default}
    client = sb()
    if is_default:  # only one default carrier per org
        client.schema("commcalc").table("carrier").update({"is_default": False}).eq("org_id", org_id).execute()
    r = client.schema("commcalc").table("carrier").upsert(row, on_conflict="org_id,name").execute()
    return r.data[0] if r.data else row


@router.patch("/carriers/{cid}")
def update_carrier(cid: str, body: CarrierIn, org_id: str = ORG_ID):
    require_org(org_id)
    patch = {}
    if "name" in body.model_fields_set:
        nm = (body.name or "").strip()
        if not nm:
            raise HTTPException(400, "name cannot be empty")
        patch["name"] = nm
    if "code" in body.model_fields_set:
        patch["code"] = (body.code or "").strip() or None
    if "is_default" in body.model_fields_set:
        patch["is_default"] = bool(body.is_default)
    if not patch:
        raise HTTPException(400, "nothing to update")
    client = sb()
    if patch.get("is_default"):  # only one default carrier per org
        client.schema("commcalc").table("carrier").update({"is_default": False}).eq("org_id", org_id).neq("id", cid).execute()
    client.schema("commcalc").table("carrier").update(patch).eq("org_id", org_id).eq("id", cid).execute()
    return {"ok": True, "id": cid}


@router.delete("/carriers/{cid}")
def delete_carrier(cid: str, org_id: str = ORG_ID):
    require_org(org_id)
    sb().schema("commcalc").table("carrier").delete().eq("org_id", org_id).eq("id", cid).execute()
    return {"ok": True}


@router.get("/payout-plans/overview")
def payout_plans_overview(org_id: str = ORG_ID):
    """Per-carrier map of HOW each enabled carrier's reps get paid, and whether the calculator will
    actually pay them. Drives the unified 'Commission Payout Plans' hub. Uses the SAME carrier gate
    as the live calc, so what it shows is what /calculate will do."""
    require_org(org_id)
    client = sb()
    def _all(table, cols="*"):
        try:
            return (client.schema("commcalc").table(table).select(cols)
                    .eq("org_id", org_id).limit(10000).execute().data) or []
        except Exception:
            return []
    carriers = _all("carrier")
    plans    = _all("commission_plan", "id,carrier_id,is_active,name")
    assigns  = _all("commission_plan_assignment", "plan_id,scope,scope_value")
    scheds   = _all("payout_schedule", "id,carrier_id,is_active")
    mode     = _resolve_carrier_mode(carriers)
    default  = next((c for c in carriers if c.get("is_default")), None)
    assign_by_plan = {}
    for a in assigns:
        assign_by_plan[a.get("plan_id")] = assign_by_plan.get(a.get("plan_id"), 0) + 1
    def _is_boost(c):
        return 'boost' in ((c.get('code') or '') + ' ' + (c.get('name') or '')).lower()
    out = []
    for c in carriers:
        cid = c.get("id")
        boost = _is_boost(c)
        cplans  = [p for p in plans if p.get("carrier_id") in (cid, None) and p.get("is_active", True)]
        cassign = sum(assign_by_plan.get(p["id"], 0) for p in cplans)
        cscheds = [s for s in scheds if s.get("carrier_id") in (cid, None) and s.get("is_active", True)]
        if boost:
            pays_via, ready = "boost_rates", True
        elif cassign > 0 or len(cscheds) > 0:
            pays_via, ready = "commission_plans", True
        else:
            pays_via, ready = "unconfigured", False
        out.append({
            "id": cid, "name": c.get("name"), "code": c.get("code"),
            "is_default": bool(c.get("is_default")), "is_boost": boost,
            "pays_via": pays_via, "ready": ready,
            "plan_count": len(cplans), "assignment_count": cassign,
            "schedule_count": len(cscheds),
        })
    return {
        "org_carrier_mode": mode,
        "default_carrier": ({"id": default.get("id"), "name": default.get("name"),
                             "code": default.get("code")} if default else None),
        "carriers": out,
    }


@router.get("/payout-plans/diagnose")
def payout_plans_diagnose(period: str, org_id: str = ORG_ID):
    """WHY aren't reps showing in the commission report for this period? Read-only. Reports the rep-roster
    sources (raw_sales / raw_mi), configured plans + assignments, what the plan + installment engines WOULD
    produce, the current rep_commissions count, and a plain-language reason list. Drives the Overview
    'Why is my report empty?' panel."""
    require_org(org_id)
    client = sb()
    from app.modules.commcalc import commission_engine, installment_engine

    def _roster(table, col):
        rows, start, page, names = 0, 0, 1000, {}
        while True:
            try:
                chunk = (client.schema('commcalc').table(table).select(col)
                         .eq('org_id', org_id).in_('period', _pvariants(period))
                         .range(start, start + page - 1).execute().data) or []
            except Exception:
                break
            for r in chunk:
                v = str(r.get(col) or '').strip()
                if v:
                    names[v.upper()] = names.get(v.upper(), 0) + 1
            rows += len(chunk)
            if len(chunk) < page:
                break
            start += page
        return rows, sorted(names.keys())

    sales_n, sales_reps = _roster('raw_sales', 'salesperson')
    mi_n, mi_reps = _roster('raw_mi', 'epay_salesperson')
    carriers = (client.schema('commcalc').table('carrier').select('*').eq('org_id', org_id).execute().data) or []
    mode = _resolve_carrier_mode(carriers)

    plans, _ready = commission_engine._load_plans(client, org_id)
    plan_info = [{"name": p.get("name"), "carrier_id": p.get("carrier_id"),
                  "is_active": p.get("is_active", True), "rules": len(p.get("rules") or []),
                  "assignments": [{"scope": a.get("scope"), "value": a.get("scope_value")}
                                  for a in (p.get("assignments") or [])]} for p in plans]
    n_assign = sum(len(p.get("assignments") or []) for p in plans)
    scoped = [a for p in plans for a in (p.get('assignments') or []) if a.get('scope') in ('market', 'store')]
    role_assigns = [a for p in plans for a in (p.get('assignments') or []) if a.get('scope') == 'role']
    # SAME name->role map preview() uses, so this narration can never disagree with what pays.
    role_map = commission_engine._read_employee_roles(client, org_id)
    roster_roles = sorted({r for r in role_map.values() if r})
    name_collisions = commission_engine._role_name_collisions(client, org_id)

    try:
        prev = commission_engine.preview(client, org_id, period)
    except Exception as e:
        prev = {"by_rep": [], "note": f"preview error: {e}"}
    try:
        inst = installment_engine.compute_installments(client, org_id, period, persist=False)
    except Exception as e:
        inst = {"by_rep": {}, "totals": {"reps": 0}, "note": f"installment error: {e}"}
    scheds = (client.schema('commcalc').table('payout_schedule').select('id')
              .eq('org_id', org_id).eq('is_active', True).execute().data) or []
    rc = (client.schema('commcalc').table('rep_commissions').select('epay_salesperson')
          .eq('org_id', org_id).in_('period', _pvariants(period)).limit(5000).execute().data) or []

    prev_reps = [r.get("rep") for r in (prev.get("by_rep") or [])]
    inst_reps = list((inst.get("by_rep") or {}).keys())
    reasons = []
    if mode == 'boost':
        reasons.append("Carrier mode is BOOST for this org — it runs the Boost engine, not commission plans. If it should run plans (Total), set its DEFAULT carrier to a non-Boost carrier on tenant Carriers / Carrier Mapping.")
    if sales_n == 0:
        reasons.append("No raw_sales for this period. Commission-PLAN pay is computed from sale LINES, so plan reps come only from sales; with no sales, reps can come only from multi-month installments (raw_mi) or a carrier statement." + (" (In Boost mode this ABORTS the whole calc — now fixed for plan mode.)" if mode == 'boost' else ""))
    if not plans:
        reasons.append("No commission plans configured for this org.")
    elif n_assign == 0:
        reasons.append("Plans exist but have NO rep assignments — no rep is covered. Assign each plan to employees/stores/markets on Commission Plans.")
    if scheds and mi_n == 0:
        reasons.append("Payout schedules exist but there is no raw_mi for this period — multi-month installments have no subscriber/rep rows to pay on. Import the carrier MI/commission file for this period.")
    if scoped:
        reasons.append(f"{len(scoped)} assignment(s) use STORE/MARKET scope — those attach to a rep only if the rep's store (raw_sales.store) resolves to that store/market via Store Matching. An unmapped store → the plan won't attach. If unsure, use EMPLOYEE-scope assignments (rep name must match raw_sales.salesperson / raw_mi rep).")
    if role_assigns:
        bad_roles = sorted({(a.get('scope_value') or '').strip() for a in role_assigns
                            if (a.get('scope_value') or '').strip().lower() not in roster_roles})
        msg = (f"{len(role_assigns)} assignment(s) use ROLE scope — each attaches to EVERY rep whose storeops "
               f"roster role equals it (the rep's sales name is bridged to their roster row name-order-"
               f"insensitively, so 'Antunez, Diana' finds 'Diana Antunez'). A rep missing from the roster, or "
               f"with a blank role, can't match a role assignment — add them to storeops or use an EMPLOYEE "
               f"assignment (which OVERRIDES their role). Roster roles present: {roster_roles or 'none'}.")
        if bad_roles:
            msg += f" These role assignment values match NO roster role: {bad_roles}."
        reasons.append(msg)
    if name_collisions:
        parts = []
        for c in name_collisions:
            roles = [f"{r.get('name')}={r.get('role') or '(no role)'}" for r in c.get('rows', [])]
            tag = " ROLE CONFLICT" if c.get('role_conflict') else ""
            parts.append(f"'{c.get('canon')}' ({', '.join(roles)}) → uses '{c.get('winner_role') or '(no role)'}'{tag}")
        reasons.append(f"{len(name_collisions)} roster name collision(s) — multiple storeops employees share "
                       f"a canonical name, so employee/role resolution uses the LOWEST-id row deterministically: "
                       f"{'; '.join(parts)}. If a conflicting rep should pay differently, give them distinct "
                       f"roster names or an explicit EMPLOYEE assignment.")
    if not prev_reps and not inst_reps:
        reasons.append("Neither the plan engine nor the installment engine produced ANY rep for this period → nothing to write. Fix the data/assignment issues above.")
    elif len(rc) == 0:
        reasons.append("The engines WOULD produce reps but rep_commissions is EMPTY — the calc has not been re-run since setup. Click Run Calculation for this period (POST /calculate).")
    if not reasons:
        reasons.append("Engines produced reps and rep_commissions has rows — the report should be populated. If it isn't, check the report's period selector and any rep/store filters.")

    return {
        "period": period, "carrier_mode": mode,
        "sales": {"rows": sales_n, "reps": sales_reps},
        "raw_mi": {"rows": mi_n, "reps": mi_reps},
        "plans": plan_info, "assignments_total": n_assign, "schedules": len(scheds),
        "plan_engine": {"reps": prev_reps, "note": prev.get("note")},
        "installment_engine": {"reps": inst_reps, "totals": inst.get("totals"), "note": inst.get("note")},
        "rep_commissions_now": len(rc),
        "reasons": reasons,
    }


# ── Generic column mapping (A2) — config-driven, any-carrier ingestion ────────────────────────
@router.get("/column-mapping/targets")
def column_mapping_targets(report_key: str = "", org_id: str = ORG_ID):
    """Canonical target fields for a report_key (drives the mapping UI), plus the list of known
    report keys. New report keys (from report_definitions) have no registry → empty fields list,
    and the UI lets the user type target field names freely."""
