@router.get("/plan-installments/category-impact/{period}")
def category_impact(period: str, org_id: str = ORG_ID):
    """READ-ONLY BLAST RADIUS for a pay period: what the current include/exclude set + the device-price
    MRC guard change, per rep, WITHOUT recomputing anything.

    Runs the installment engine THREE times in memory, so the two moving parts can be told apart:
      B = every category included AND the device-price guard off  (the pre-2026-07-27 behaviour),
      C = every category included, guard ON                        (B + only the MRC corrections),
      A = the settings exactly as they stand                       (what the next Run Calculation pays).
    Per rep: before (B) → mrc_corrected (C) → now (A), with both deltas. Plus the per-category
    breakdown, the excluded chains with examples, and every activation whose MRC moved off a device
    price. Writes nothing; never triggers a calculate."""
    require_org(org_id)
    from app.modules.commcalc import installment_category as icat
    client = sb()
    try:
        _all = {k: True for k in icat.CATEGORY_KEYS}
        cur = sale_installment_engine.compute_sale_installments(client, org_id, period, persist=False)
        base = sale_installment_engine.compute_sale_installments(
            client, org_id, period, persist=False,
            _config_override={"hardware_guard": False, "qualification": _all})
        mrconly = sale_installment_engine.compute_sale_installments(
            client, org_id, period, persist=False,
            _config_override={"hardware_guard": True, "qualification": _all})
    except Exception as e:
        raise HTTPException(500, f"category impact failed: {type(e).__name__}: {e}")
    reps = sorted(set(cur.get("by_rep") or {}) | set(base.get("by_rep") or {})
                  | set(mrconly.get("by_rep") or {}))
    rows = []
    for r in reps:
        a = safe_float((cur.get("by_rep") or {}).get(r))
        b = safe_float((base.get("by_rep") or {}).get(r))
        c = safe_float((mrconly.get("by_rep") or {}).get(r))
        rows.append({"rep": r, "now": round(a, 2), "before": round(b, 2),
                     "mrc_corrected": round(c, 2),
                     "delta_mrc": round(c - b, 2), "delta_category": round(a - c, 2),
                     "delta": round(a - b, 2)})
    rows.sort(key=lambda x: x["delta"])

    def _key(x):
        return (str(x.get("trans_id") or ""), str(x.get("mdn") or ""), int(x.get("month_index") or 0))

    base_by = {_key(x): x for x in (base.get("ledger") or [])}
    mrc_moves = []
    # the MRC comparison uses run C (all categories included), so a correction is still REPORTED for an
    # activation that the category switches then exclude — otherwise the tablet fix would be invisible.
    for x in (mrconly.get("ledger") or []):
        y = base_by.get(_key(x))
        if not y:
            continue
        if round(safe_float(x.get("mrc_at_pay")), 2) != round(safe_float(y.get("mrc_at_pay")), 2):
            mrc_moves.append({"rep": x.get("epay_salesperson"), "trans_id": x.get("trans_id"),
                              "imei": x.get("serial_1"), "month_index": x.get("month_index"),
                              "label": x.get("display_label"),
                              "mrc_now": round(safe_float(x.get("mrc_at_pay")), 2),
                              "mrc_before": round(safe_float(y.get("mrc_at_pay")), 2),
                              "amount_now": round(safe_float(x.get("amount")), 2),
                              "amount_before": round(safe_float(y.get("amount")), 2),
                              "category": x.get("device_category"),
                              "still_paid": bool(next((True for z in (cur.get("ledger") or [])
                                                       if _key(z) == _key(x)), False))})
    mrc_moves.sort(key=lambda m: (m["amount_now"] - m["amount_before"]))
    return {"period": period, "org_id": org_id,
            "totals": {"now": round(safe_float((cur.get("totals") or {}).get("amount")), 2),
                       "before": round(safe_float((base.get("totals") or {}).get("amount")), 2),
                       "mrc_corrected": round(safe_float((mrconly.get("totals") or {}).get("amount")), 2),
                       "delta": round(safe_float((cur.get("totals") or {}).get("amount"))
                                      - safe_float((base.get("totals") or {}).get("amount")), 2)},
            "by_rep": rows, "category_guard": cur.get("category_guard"),
            "warnings": cur.get("warnings"), "chain_guard": cur.get("chain_guard"),
            "mrc_moves": mrc_moves[:200], "mrc_moves_count": len(mrc_moves)}


# ════════════════════════════════════════════════════════════════════════════════════════════════════
# FLAT (ONE-TIME) PAYOUT BY DEVICE CATEGORY  (mig 256; engine: commcalc/installment_category_payout.py)
# ════════════════════════════════════════════════════════════════════════════════════════════════════
# OWNER DIRECTIVE 2026-08-01: "fwa is paid on flat rate should not be in monthly payments - fix but
# dont hard code". A tenant can take a DEVICE CATEGORY out of the M1..M6 monthly chain and pay it once,
# as a flat dollar amount THEY type. Nothing here is branched on a carrier, tenant or product name —
# the category comes from the tenant's own installment_category rules (mig 245).
#
# MONEY: the GET + the impact endpoint are read-only and recompute nothing. The PUT is the owner's own
# entry point (admin-gated) and still moves nothing until the next Run Calculation. A category set to
# flat with NO amount is NOT active — the chain keeps paying monthly and the engine warns.


@router.get("/plan-installments/category-payout")
def get_category_payout(org_id: str = ORG_ID):
    """The tenant's per-category payout MODE (monthly installments vs a one-time flat amount).

    Returns the ORG-level config (falling back to the code default — every category on monthly
    installments, i.e. today's behaviour), each schedule's own override, the category vocabulary and
    the mode vocabulary for pick-don't-type editing (§3b). Read-only; writes nothing.

    NO AMOUNT IS EVER INVENTED HERE: an unconfigured category reports `amount: null`, and the UI shows
    an empty box for the owner to type into."""
    require_org(org_id)
    from app.modules.commcalc import installment_category as icat
    from app.modules.commcalc import installment_category_payout as icpay
    client = sb()
    stored, ready = None, True
    try:
        rows = (client.schema('commcalc').table('commission_org_config')
                .select('installment_category_payout')
                .eq('org_id', org_id).limit(1).execute().data) or []
        if rows:
            stored = rows[0].get('installment_category_payout')
    except Exception:
        ready = False          # migration 256 not applied — the engine still uses the code defaults
    payout = icpay.normalize_payout(stored)
    scheds, sched_ready = [], True
    try:
        scheds = (client.schema('commcalc').table('plan_installment_schedule')
                  .select('*').eq('org_id', org_id).execute().data) or []
    except Exception:
        sched_ready = False
    out_scheds = []
    for s in scheds:
        try:
            own = s.get('category_payout')
        except Exception:
            own = None
        out_scheds.append({"id": s.get("id"), "name": s.get("name"), "plan_id": s.get("plan_id"),
                           "num_months": s.get("num_months"), "is_active": s.get("is_active"),
                           "category_payout": own if isinstance(own, dict) else None})
    return {
        "payout": {k: dict(payout.get(k) or {}) for k in icpay.CATEGORY_KEYS},
        "is_default": not (isinstance(stored, dict) and bool(stored)),
        "defaults": {k: dict(v) for k, v in icpay.DEFAULT_PAYOUT.items()},
        "categories": [{"key": k, "label": icat.CATEGORY_LABELS[k]} for k in icpay.CATEGORY_KEYS],
        "modes": [{"key": m, "label": icpay.MODE_LABELS[m]} for m in icpay.PAYOUT_MODES],
        "max_pay_month": icpay.MAX_PAY_MONTH,
        "flat_categories": icpay.configured_categories(payout),
        "schedules": out_scheds, "schedules_ready": sched_ready,
        "ready": ready,
        "migration": None if ready else "256_commission_installment_category_flat_payout.sql",
    }


@router.put("/plan-installments/category-payout")
def put_category_payout(body: dict, authorization: str = Header(default=""),
                              org_id: str = ORG_ID):
    """Admin-only. Save the tenant's per-category payout mode + flat amount (mig 256).
    body: {payout: {home_internet: {mode:'flat_once', amount: 25, pay_month: 1}, ...}}
          OR {reset: true} to revert every category to monthly installments (stored NULL).

    MONEY. Switching a category to a one-time flat amount changes what those activations pay on the
    NEXT Run Calculation (nothing moves now): the configured month pays the flat amount and the other
    installment months of that chain stop paying. Both effects are reported in the Calculate/preview
    warnings with per-rep dollars — never a silent zero.

    THE AMOUNT IS YOURS. There is no default and no seed. Saving mode='flat_once' with a blank amount
    is accepted and stored, but it does NOT take effect: the chains keep paying monthly and the engine
    raises a `flat_amount_unconfigured` warning until an amount is entered."""
    require_org(org_id)
    _require_commission_admin(authorization, org_id)
    from app.modules.commcalc import installment_category_payout as icpay
    payout = None
    if not body.get("reset"):
        raw = body.get("payout") if isinstance(body.get("payout"), dict) else body
        norm = icpay.normalize_payout(raw)
        bad = []
        for k, v in (raw or {}).items():
            if k in icpay.CATEGORY_KEYS or k.startswith("_"):
                continue
            bad.append(k)
        if bad:
            raise HTTPException(400, f"unknown category key(s) {bad} — allowed: {list(icpay.CATEGORY_KEYS)}")
        for k, v in ((raw or {}).items() if isinstance(raw, dict) else []):
            if isinstance(v, dict) and str(v.get("mode") or "").strip().lower() not in ("", *icpay.PAYOUT_MODES):
                raise HTTPException(400, f"mode for '{k}' must be one of {list(icpay.PAYOUT_MODES)}")
        payout = {k: dict(norm[k]) for k in icpay.CATEGORY_KEYS}
    row = {"org_id": org_id, "installment_category_payout": payout,
           "updated_by": _caller_uid(authorization), "updated_at": _datetime.now(_timezone.utc).isoformat()}
    try:
        sb().schema('commcalc').table('commission_org_config').upsert(row, on_conflict='org_id').execute()
    except Exception as e:
        raise HTTPException(400, "could not save the flat payout config — run migration "
                                 f"256_commission_installment_category_flat_payout.sql first. [{e}]")
    unconfigured = sorted(k for k, v in (payout or {}).items()
                          if v.get("mode") == "flat_once" and v.get("amount") is None)
    return {"saved": True, "is_default": payout is None,
            "payout": payout or {k: dict(v) for k, v in icpay.DEFAULT_PAYOUT.items()},
            "flat_categories": icpay.configured_categories(payout or {}),
            "unconfigured_amount": unconfigured,
            "note": (None if not unconfigured else
                     "Saved, but these categories have no amount yet, so they are STILL paying monthly "
                     "installments (nothing was zeroed): " + ", ".join(unconfigured))}


@router.get("/plan-installments/category-payout-impact/{period}")
def category_payout_impact(period: str, category: str = "", amount: str = "",
                                 pay_month: int = 1, org_id: str = ORG_ID):
    """READ-ONLY per-rep delta for the flat-payout switch. Writes nothing; recomputes nothing.

    Runs the installment engine TWICE in memory:
      A = the settings exactly as they stand now (what the next Run Calculation would pay),
      B = the same settings PLUS the hypothetical the caller asked about
          (`?category=home_internet&amount=25`).

    `amount` has NO DEFAULT. Called without one, B is the saved config only — so the endpoint can
    never quote a dollar figure nobody entered. The response echoes the exact amount used in
    `hypothesis`, which is what makes the Gate-2 table honest ("at $X per activation").
    """
    require_org(org_id)
    from app.modules.commcalc import installment_category_payout as icpay
    client = sb()
    amt = icpay._num(amount)
    cat = str(category or "").strip().lower()
    if cat and cat not in icpay.CATEGORY_KEYS:
        raise HTTPException(400, f"category must be one of {list(icpay.CATEGORY_KEYS)}")
    override = None
    if cat and amt is not None:
        saved = icpay.load_org_payout(client, org_id)
        override = {k: dict(saved.get(k) or {}) for k in icpay.CATEGORY_KEYS}
        override[cat] = {"mode": "flat_once", "amount": amt,
                         "pay_month": max(1, min(icpay.MAX_PAY_MONTH, int(pay_month or 1)))}
    try:
        cur = sale_installment_engine.compute_sale_installments(client, org_id, period, persist=False)
        alt = (cur if override is None else
               sale_installment_engine.compute_sale_installments(
                   client, org_id, period, persist=False,
                   _config_override={"category_payout": override}))
    except Exception as e:
        raise HTTPException(500, f"flat payout impact failed: {type(e).__name__}: {e}")
    reps = sorted(set(cur.get("by_rep") or {}) | set(alt.get("by_rep") or {}))
    rows = []
    for r in reps:
        a = safe_float((cur.get("by_rep") or {}).get(r))
        b = safe_float((alt.get("by_rep") or {}).get(r))
        rows.append({"rep": r, "now": round(a, 2), "with_flat": round(b, 2), "delta": round(b - a, 2)})
    rows.sort(key=lambda x: x["delta"])
    return {"period": period, "org_id": org_id,
            "hypothesis": ({"category": cat, "amount": amt, "pay_month": pay_month} if override
                           else None),
            "hypothesis_note": (None if override else
                                "No hypothesis was supplied (pass ?category=<key>&amount=<dollars>), so "
                                "both columns are the SAVED configuration — the delta is 0 by "
                                "construction. This endpoint never invents an amount."),
            "totals": {"now": round(safe_float((cur.get("totals") or {}).get("amount")), 2),
                       "with_flat": round(safe_float((alt.get("totals") or {}).get("amount")), 2),
                       "delta": round(safe_float((alt.get("totals") or {}).get("amount"))
                                      - safe_float((cur.get("totals") or {}).get("amount")), 2)},
            "by_rep": rows,
            "flat_guard_now": cur.get("flat_guard"), "flat_guard_with": alt.get("flat_guard"),
            "category_guard": cur.get("category_guard"),
            "warnings": [w for w in (alt.get("warnings") or [])
                         if str(w.get("type") or "").startswith("flat_")
                         or w.get("type") == "mrc_unresolved"][:100]}


# ════════════════════════════════════════════════════════════════════════════════════════════════════
# EXPECTED vs EARNED + the permission-gated manual promote  (mig 258; engine: expected_commission.py)
# ════════════════════════════════════════════════════════════════════════════════════════════════════
# OWNER 2026-08-01: "let the system calculate the expected commission as a separate column but not use
# that to pay out, if the company gets paid the employee commission auto fills from there, there should
# be an option to move the expected commission to the earned column if the system malfunctions or the
# report is not updated on time, this will be done as an edit function gated per permission."
#
# EXPECTED pays nobody — it is the pre-gate amount, surfaced as a column and summed into nothing.
# EARNED is the EXISTING paid gate, untouched. The PROMOTE is the only new money path: permission-
# gated, fully audited, and it SURVIVES RECOMPUTE (its own table; the calc never deletes it).
#
# ROUTE ORDER MATTERS: every literal /expected-commission/<word> route below is declared BEFORE
# /expected-commission/{period}, or FastAPI would bind 'config' and 'promotes' as a period.


def _xc_can_promote(authorization, org_id):
    """(allowed, reason, caller) — may this caller move an EXPECTED amount into EARNED?

    Gated on the `commission_promote` settings area via core's `_can_edit_setting` (the established
    per-setting pattern — `roles.permissions.settings['commission_promote']`). Until that area is
    registered in core.SETTING_AREAS + the Roles UI (filed NEEDS CORE), `_can_edit_setting` DEGRADES to
    admin-only (scope='all' / role='admin') — a SAFE default that never OPENS a money write to a
    non-admin.

    DELIBERATELY STRICTER THAN THE REST OF THIS MODULE on one point: an UNIDENTIFIABLE caller is
    REFUSED by default, where `_require_commission_admin` and `_can_edit_classification` degrade open.
    This is a money write whose whole purpose is an audit trail, and "promoted by: unknown" is not one.
    A genuinely RBAC-off deployment can set `expected_commission_config.promote_allow_unidentified`."""
    cfg = expected_commission.load_config(sb(), org_id)
    try:
        from app.modules.core.router import _uid_from_token, _resolve_caller, _can_edit_setting
    except Exception:
        return (bool(cfg.get("promote_allow_unidentified")), "core_rbac_unavailable", None)
    try:
        uid = _uid_from_token(authorization)
        caller = _resolve_caller(sb(), uid, org_id) if uid else None
    except Exception:
        caller = None
    if caller is None:
        if cfg.get("promote_allow_unidentified"):
            return (True, "unidentified_allowed_by_config", None)
        return (False, "unidentified_caller", None)
    return (bool(_can_edit_setting(caller, "commission_promote")), "setting_area", caller)


def _xc_who(authorization):
    try:
        from app.modules.core.router import _uid_from_token
        return _uid_from_token(authorization) or None
    except Exception:
        return None


def _xc_rows(client, org_id, period):
    """(engine result, error). ONE read-only installment computation for the period. Never persists."""
    try:
        return sale_installment_engine.compute_sale_installments(
            client, org_id, period, persist=False), None
    except Exception as e:
        return None, f"{type(e).__name__}: {e}"


@router.get("/expected-commission/config")
def get_expected_commission_config(org_id: str = ORG_ID, authorization: str = Header(default="")):
    """The tenant's expected-commission window + posture, and whether THIS caller may promote.
    Read-only. Degrades to the code defaults (months 2..6) with migration 258 unapplied."""
    require_org(org_id)
    cfg = expected_commission.load_config(sb(), org_id)
    allowed, why, _caller = _xc_can_promote(authorization, org_id)
    ready = True
    try:
        (sb().schema("commcalc").table(expected_commission.TABLE).select("id")
         .eq("org_id", org_id).limit(1).execute())
    except Exception:
        ready = False
    return {"config": {k: v for k, v in cfg.items() if not k.startswith("_")},
            "is_default": not cfg.get("_stored"),
            "defaults": dict(expected_commission.DEFAULT_CONFIG),
            "on_change_modes": list(expected_commission.ON_CHANGE_MODES),
            "can_promote": allowed, "can_promote_reason": why,
            "setting_area": "commission_promote",
            "ready": ready,
            "migration": None if ready else "258_commission_expected_earned_promote.sql"}


@router.put("/expected-commission/config")
def put_expected_commission_config(body: dict, authorization: str = Header(default=""),
                                         org_id: str = ORG_ID):
    """Admin-only. Save the expected-commission window + posture (mig 258).
    body: {config:{enabled,from_month,to_month,on_expected_change,promote_allow_unidentified}}
          or {reset:true}.

    MONEY-ADJACENT, NOT MONEY: narrowing the window stops months being PROMOTABLE and removes their
    EXPECTED column; it never changes what the paid gate pays. Widening it does not pay anything
    either — only a promote does."""
    require_org(org_id)
    _require_commission_admin(authorization, org_id)
    cfg = None
    if not body.get("reset"):
        raw = body.get("config") if isinstance(body.get("config"), dict) else body
        mode = str((raw or {}).get("on_expected_change") or "").strip().lower()
        if mode and mode not in expected_commission.ON_CHANGE_MODES:
            raise HTTPException(400, "on_expected_change must be one of "
                                     f"{list(expected_commission.ON_CHANGE_MODES)}")
        cfg = {k: v for k, v in expected_commission.normalize_config(raw).items()
               if not k.startswith("_")}
    row = {"org_id": org_id, "expected_commission_config": cfg,
           "updated_by": _caller_uid(authorization),
           "updated_at": _datetime.now(_timezone.utc).isoformat()}
    try:
        sb().schema("commcalc").table("commission_org_config").upsert(row, on_conflict="org_id").execute()
    except Exception as e:
        raise HTTPException(400, "could not save — run migration "
                                 f"258_commission_expected_earned_promote.sql first. [{e}]")
    return {"saved": True, "is_default": cfg is None,
            "config": cfg or dict(expected_commission.DEFAULT_CONFIG)}


@router.get("/expected-commission/promotes")
def list_expected_commission_promotes(period: str = "", status: str = "",
                                            org_id: str = ORG_ID):
    """The AUDIT LIST: every promote for the tenant (optionally one period / one status), newest first.
    Revoked rows are KEPT and returned — the audit trail is the point. Read-only."""
    require_org(org_id)
    try:
        q = (sb().schema("commcalc").table(expected_commission.TABLE).select("*")
             .eq("org_id", org_id))
        if period:
            q = q.in_("pay_period", _pvariants(period))
        if status:
            q = q.eq("status", status)
        rows = (q.limit(100000).execute().data) or []
    except Exception:
        return {"promotes": [], "count": 0, "ready": False,
                "migration": "258_commission_expected_earned_promote.sql"}
    rows.sort(key=lambda r: str(r.get("promoted_at") or ""), reverse=True)
    return {"promotes": rows, "count": len(rows),
            "active": len([r for r in rows if str(r.get("status") or "active") == "active"]),
            "revoked": len([r for r in rows if str(r.get("status") or "") == "revoked"]),
            "ready": True, "migration": None}


class PromoteExpectedCommissionIn(LaxModel):
    period: str = ""
    trans_id: str = ""
    mdn: str = ""
    reason: str = ""
    month_index: Any = None


@router.post("/expected-commission/promote")
def promote_expected_commission(body: PromoteExpectedCommissionIn, authorization: str = Header(default=""),
                                      org_id: str = ORG_ID):
    """💰 MONEY WRITE — move ONE chain-month's EXPECTED amount into EARNED.
    body: {period, trans_id, mdn, month_index, reason} (`reason` is REQUIRED — this is an audit row).

    The owner's use case: "if the system malfunctions or the report is not updated on time". It does
    NOT change the gate; it records an approval that `compute_sale_installments` re-applies on every
    run, so the payment survives recompute.

    REFUSALS, all explicit: no permission (403) · unidentifiable caller (403, unless the tenant allows
    it) · no reason (400) · the month is outside the tenant's expected window (400) · the chain-month
    does not exist in that period (404) · the month is already earned through the normal gate (400 —
    promoting it would be a no-op, and pretending otherwise would imply a second payment) · migration
    258 not applied (400).

    The APPROVED amount is stored. If a later recompute expects something different the month is HELD
    (or paid at the CURRENT figure, per the tenant's posture) and shouted about — never paid at the
    stored number."""
    require_org(org_id)
    allowed, why, caller = _xc_can_promote(authorization, org_id)
    if not allowed:
        raise HTTPException(403, (
            "You do not have permission to move expected commission into earned. This is a money "
            "action gated by the 'commission_promote' settings permission."
            if why == "setting_area" else
            "This action must be performed by an identified, signed-in user — it writes a money "
            "record naming who approved it."))
    period = str(body.period or "").strip()
    trans_id = str(body.trans_id or "").strip()
    mdn = str(body.mdn or "").strip()
    reason = str(body.reason or "").strip()
    try:
        month_index = int(body.month_index)
    except (TypeError, ValueError):
        raise HTTPException(400, "month_index is required")
    if not period or not trans_id:
        raise HTTPException(400, "period and trans_id are required")
    if not reason:
        raise HTTPException(400, "A reason is required — this writes a money audit record.")
    client = sb()
    cfg = expected_commission.load_config(client, org_id)
    if not cfg.get("enabled"):
        raise HTTPException(400, "Expected-to-earned promotion is switched off for this tenant.")
    if not expected_commission.in_window(month_index, cfg):
        raise HTTPException(400, f"Month {month_index} is outside this tenant's expected-commission "
                                 f"window (months {cfg['from_month']}–{cfg['to_month']}).")
    res, err = _xc_rows(client, org_id, period)
    if err:
        raise HTTPException(500, f"could not compute installments: {err}")
    key = expected_commission.promote_key(period, trans_id, mdn, month_index)
    row = next((r for r in (res.get("ledger") or [])
                if expected_commission.row_key(r) == key), None)
    if row is None:
        raise HTTPException(404, "No installment for that transaction / mobile number / month exists "
                                 "in this pay period. (If the category is paid as a one-time flat "
                                 "amount it has no monthly installments at all.)")
    if row.get("paid_gate_met") and str(row.get("status") or "") == "paid":
        raise HTTPException(400, "That month is already EARNED through the normal paid gate — there is "
                                 "nothing to promote.")
    who, now = _xc_who(authorization), _datetime.now(_timezone.utc).isoformat()
    prow = expected_commission.promote_row(org_id, row, reason, who, now)
    try:
        r = (client.schema("commcalc").table(expected_commission.TABLE)
             .upsert(prow, on_conflict="org_id,pay_period,trans_id,mdn,month_index").execute())
    except Exception as e:
        raise HTTPException(400, "Could not save — run migration "
                                 f"258_commission_expected_earned_promote.sql first. [{e}]")
    return {"ok": True, "promoted": (r.data[0] if r.data else prow),
            "expected_amount": prow["expected_at_promote"],
            "note": ("Recorded. This month pays its expected amount from the next calculation onward, "
                     "and the approval survives every recompute. If a later run expects a DIFFERENT "
                     "amount it will be held for your re-approval rather than paid at a figure nobody "
                     "approved.")}


class RevokeExpectedCommissionIn(LaxModel):
    id: str = ""
    reason: Any = None


@router.post("/expected-commission/revoke")
def revoke_expected_commission(body: RevokeExpectedCommissionIn, authorization: str = Header(default=""),
                                     org_id: str = ORG_ID):
    """💰 MONEY WRITE — revoke a promote. body: {id, reason?}. The row is KEPT with status='revoked'
    (an audit trail you can delete is not an audit trail); the month reverts to the normal gate on the
    next calculation."""
    require_org(org_id)
    allowed, why, _caller = _xc_can_promote(authorization, org_id)
    if not allowed:
        raise HTTPException(403, "You do not have permission to change expected-to-earned promotions.")
    rid = str(body.id or "").strip()
    if not rid:
        raise HTTPException(400, "id is required")
    try:
        (sb().schema("commcalc").table(expected_commission.TABLE)
         .update({"status": "revoked", "revoked_by": _xc_who(authorization),
                  "revoked_at": _datetime.now(_timezone.utc).isoformat(),
                  "revoke_reason": (body.reason or None),
                  "updated_at": _datetime.now(_timezone.utc).isoformat()})
         .eq("org_id", org_id).eq("id", rid).execute())
    except Exception as e:
        raise HTTPException(400, f"Could not revoke — [{e}]")
    return {"ok": True, "id": rid, "status": "revoked",
            "note": "The month reverts to the normal paid gate from the next calculation."}


@router.get("/expected-commission/{period}")
def expected_commission_report(period: str, rep: str = "", store: str = "",
                                     org_id: str = ORG_ID, authorization: str = Header(default="")):
    """READ-ONLY: EXPECTED vs EARNED per chain-month for one pay period. Writes nothing, recomputes
    nothing, persists nothing.

    Every row carries what the month WOULD pay (`expected`), what it DID pay (`earned`), why, and
    whether a human promoted it. The two are deliberately separate columns and `expected` is never
    added into any total — the tiles say so."""
    require_org(org_id)
    client = sb()
    res, err = _xc_rows(client, org_id, period)
    if err:
        raise HTTPException(500, f"could not compute installments: {err}")
    cfg = expected_commission.load_config(client, org_id)
    allowed, why, _caller = _xc_can_promote(authorization, org_id)
    rows, by_rep = [], {}
    for r in (res.get("ledger") or []):
        if rep and str(r.get("epay_salesperson") or "").strip().lower() != rep.strip().lower():
            continue
        if store and str(r.get("store") or "").strip().lower() != store.strip().lower():
            continue
        earned = safe_float(r.get("amount"))
        exp = safe_float(r.get("expected_amount"))
        in_win = bool(r.get("expected_in_window"))
        promoted = str(r.get("status") or "") == "paid_manual_promote"
        rows.append({
            "rep": r.get("epay_salesperson"), "store": r.get("store"),
            "label": r.get("display_label"), "device_category": r.get("device_category"),
            "trans_id": r.get("trans_id"), "mdn": r.get("mdn"), "imei": r.get("serial_1"),
            "sale_period": r.get("sale_period"), "pay_period": r.get("pay_period"),
            "month_index": r.get("month_index"), "payout_kind": r.get("payout_kind"),
            "expected": exp, "earned": earned,
            "expected_in_window": in_win,
            "unearned": round(exp - earned, 2) if in_win else 0.0,
            "status": r.get("status"), "gate_met": bool(r.get("paid_gate_met")),
            "gate_mode": r.get("gate_mode"), "gate_kind": r.get("gate_kind"),
            "promoted": promoted, "promoted_by": r.get("promoted_by"),
            "promoted_at": r.get("promoted_at"), "promote_reason": r.get("promote_reason"),
            "promote_id": r.get("promote_id"), "promote_stale": bool(r.get("promote_stale")),
            "promotable": bool(in_win and not r.get("paid_gate_met")),
        })
        k = str(r.get("epay_salesperson") or "")
        b = by_rep.setdefault(k, {"rep": k, "store": r.get("store"), "expected": 0.0, "earned": 0.0,
                                  "unearned": 0.0, "months": 0, "promoted_months": 0})
        b["months"] += 1
        b["earned"] = round(b["earned"] + earned, 2)
        if in_win:
            b["expected"] = round(b["expected"] + exp, 2)
            b["unearned"] = round(b["unearned"] + max(0.0, exp - earned), 2)
        if promoted:
            b["promoted_months"] += 1
    rows.sort(key=lambda x: (-(x["unearned"] or 0), str(x["rep"] or ""), x["month_index"] or 0))
    xg = res.get("expected_guard") or {}
    return {
        "period": period, "org_id": org_id,
        "config": {k: v for k, v in cfg.items() if not k.startswith("_")},
        "can_promote": allowed, "can_promote_reason": why,
        "rows": rows, "by_rep": sorted(by_rep.values(), key=lambda x: -x["unearned"]),
        "totals": {
            # EARNED is the only figure that is money. EXPECTED is reported beside it and summed into
            # nothing anywhere in the system — that is the whole point of the directive.
            "earned": round(safe_float((res.get("totals") or {}).get("amount")), 2),
            "expected_in_window": safe_float(xg.get("expected_total")),
            "expected_not_yet_earned": safe_float(xg.get("expected_unearned_total")),
            "promoted_amount": safe_float(xg.get("promoted_amount")),
            "promotes_applied": xg.get("promotes_applied", 0),
        },
        "expected_guard": xg,
        "warnings": [w for w in (res.get("warnings") or [])
                     if str(w.get("type") or "").startswith("promote_")][:100],
        "money_note": ("EXPECTED is what a month would pay once the carrier pays us. It is a column, "
                       "not a payment: it is never added to anyone's commission, to rep_commissions or "
                       "to the P&L. EARNED is what actually paid — automatically when the dealer is "
                       "shown paid, or because someone with permission promoted it and said why."),
        "ready": res.get("schedules", 0) > 0,
        "note": res.get("note"),
    }


# ── PARAMETRIZED schedule EDIT/DELETE — REGISTERED LAST ON PURPOSE (routing bug fixed 2026-07-27).
# FastAPI matches routes in REGISTRATION ORDER, so `PUT /plan-installments/{sid}` declared before the
# literal `/plan-installments/activation-matcher` and `/plan-installments/plan-line-matcher` SWALLOWED
# them: a save of either matcher bound sid="activation-matcher" / "plan-line-matcher" and 400'd with
# "plan_id is required" — i.e. the mig-210 and mig-233 matcher editors could never be saved from the
# UI. Every literal /plan-installments/... route must stay ABOVE this block.
@router.put("/plan-installments/{sid}")
def update_plan_installment(sid: str, body: dict, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """EDIT an existing sale-triggered schedule + its month lines (money config → admin-only). Same body
    shape as POST (minus id). RECOMPUTE SEMANTICS: the edit takes effect from the NEXT POST /calculate
    onward — it does NOT retroactively rewrite pay. sale_installment_ledger rows already written for PAST
    pay periods are IMMUTABLE unless the operator explicitly re-runs POST /calculate for that period (and
    even then, a paid month only re-derives from the edited schedule if that period is recomputed). Every
    edit is captured in commcalc.plan_installment_schedule_audit (before/after + who/when)."""
    require_org(org_id)
    _require_commission_admin(authorization, org_id)
    if not body.get("plan_id"):
        raise HTTPException(400, "plan_id is required.")
    client = sb()
    exists = _installment_snapshot(client, org_id, sid)
    if exists is None:
        raise HTTPException(404, "installment schedule not found for this tenant (or migration 201 not applied).")
    try:
        _write_installment_schedule(client, org_id, body, sid, _caller_uid(authorization))
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"could not update installment schedule: {e}")
    return {"id": sid, "saved": True, "updated": True}


@router.delete("/plan-installments/{sid}")
def delete_plan_installment(sid: str, authorization: str = Header(default=""), org_id: str = ORG_ID):
    require_org(org_id)
    _require_commission_admin(authorization, org_id)
    client = sb()
    before = _installment_snapshot(client, org_id, sid)
    try:
        client.schema('commcalc').table('plan_installment_schedule').delete().eq('id', sid).eq('org_id', org_id).execute()
    except Exception as e:
        raise HTTPException(500, f"delete failed: {e}")
    _installment_audit(client, org_id, sid, "delete", before, None, _caller_uid(authorization))
    return {"deleted": True}


# ── Classification-first MRC MAPPING (§7b decision 1): classify imported plan lines + prefill $ MRC ──
@router.get("/mrc-mapping/candidates")
def mrc_mapping_candidates(period: str, org_id: str = ORG_ID):
    """Scan a period's sale lines for distinct PLAN/product descriptions, AUTO-CLASSIFY each (reusing the
    existing accessory/carrier-category config), AUTO-PREFILL the $ MRC from the description text, and
    cross-reference the product_mrc catalog to show which are already CONFIRMED. Read-only — the user
    confirms/overwrites via POST /mrc-mapping/confirm. This is the classification-first flow."""
    require_org(org_id)
    client = sb()
    acc = sale_installment_engine._acc_sets(client, org_id)
    ccmap = sale_installment_engine._load_ccmap(client, org_id)
    catalog = installment_engine._load_product_mrc(client, org_id)
    # existing confirmed mappings keyed by lowered plan pattern
    confirmed = {}
    for r in catalog:
        confirmed[str(r.get('plan_pattern') or '').strip().lower()] = {
            "mrc": safe_float(r.get('mrc')), "confirmed": bool(r.get('confirmed')),
            "classification": r.get('classification')}
    sales = commission_engine._read_sales(client, org_id, period)
    seen = {}
    for row in sales:
        if str(row.get('voided', '') or '').upper().strip() == 'YES':
            continue
        key = str(row.get('customer_plan') or row.get('product_desc') or '').strip()
        if not key:
            continue
        lk = key.lower()
        e = seen.get(lk)
        if not e:
            e = seen[lk] = {"plan": key, "count": 0,
                            "classification": sale_installment_engine.classify_line(row, acc, ccmap),
                            "prefill_mrc": sale_installment_engine.extract_mrc_from_desc(
                                row.get('product_desc') or row.get('customer_plan')),
                            "confirmed": False, "confirmed_mrc": None}
        e["count"] += 1
        c = confirmed.get(lk)
        if c:
            e["confirmed"] = c["confirmed"]
            e["confirmed_mrc"] = c["mrc"]
            if c.get("classification"):
                e["classification"] = c["classification"]
    out = sorted(seen.values(), key=lambda x: (x["confirmed"], -x["count"]))
    return {"period": period, "candidates": out, "count": len(out)}


class MrcMappingConfirmIn(LaxModel):
    carrier_id: Any = None
    match_op: str = ""
    items: Any = None


@router.post("/mrc-mapping/confirm")
def mrc_mapping_confirm(body: MrcMappingConfirmIn, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Upsert user-confirmed product_mrc rows (money config → admin-only). Body: {carrier_id?, match_op?,
    items:[{plan, mrc, classification?}]}. Marks each row confirmed=true. Reuses the existing product_mrc
    table (mig 074) — never a new mapping table."""
    require_org(org_id)
    _require_commission_admin(authorization, org_id)
    client = sb()
    carrier_id = body.carrier_id or None
    match_op = (body.match_op or "equals").strip() or "equals"
    saved = 0
    for it in (body.items or []):
        plan = str(it.get("plan") or "").strip()
        if not plan:
            continue
        row = {"org_id": org_id, "carrier_id": carrier_id, "plan_pattern": plan, "match_op": match_op,
               "mrc": safe_float(it.get("mrc")), "is_active": True, "confirmed": True,
               "classification": it.get("classification"), "source_desc": it.get("source_desc"),
               "prefill_mrc": (safe_float(it.get("prefill_mrc")) if it.get("prefill_mrc") is not None else None)}
        try:
            client.schema('commcalc').table('product_mrc').upsert(
                row, on_conflict='org_id,carrier_id,plan_pattern,match_op').execute()
            saved += 1
        except Exception:
            # pre-mig-201 (no confirmed/classification cols): retry without them so the MRC still saves
            for k in ("confirmed", "classification", "source_desc", "prefill_mrc"):
                row.pop(k, None)
            try:
                client.schema('commcalc').table('product_mrc').upsert(
                    row, on_conflict='org_id,carrier_id,plan_pattern,match_op').execute()
                saved += 1
            except Exception:
                pass
    return {"saved": saved}


# ── BULK classify + write-in filter + cross-menu conflict guard (owner directive 2026-07-18) ─────────
# Assign ONE classification (category) to MANY plan/product MRC mappings in a single call — the bulk
# companion to /mrc-mapping/confirm, driven by the write-in filter on the plan-installments MRC card
# ("type 'rtr' → all RTR plans come up → assign one category to all"). Two design facts make this safe:
#   1. product_mrc.classification is DISPLAY/config only — the installment PAY engine classifies each line
#      LIVE via classify_line() and reads the catalog only for the $ MRC (mrc), so bulk-setting the
#      classification never changes a payout number. Nothing recalculates until Run Calculation.
#   2. product_mrc.classification and item_mapping.sales_category share the SAME mig-210 sales vocabulary,
#      so the cross-menu guard compares them DIRECTLY (no lossy crosswalk). The guard is READ-ONLY: it
#      never writes item_mapping (which WOULD move money — item_mapping.sales_category feeds the month-1
#      activation-payment pay gate + KPI/sales reporting), so two-way AUTO-sync is deferred to the owner.
_MRC_SHARED_VOCAB = {"accessory", "activation", "upgrade", "swap", "bill_payment", "rebate", "misc_other"}


def _mrc_norm(s):
    """Normalize a product/category string for matching: lowercased, single-spaced, trimmed."""
    return re.sub(r"\s+", " ", str(s or "").strip().lower())


def _mrc_crossmenu_conflicts(item_rows, plans, classification):
    """READ-ONLY cross-menu guard. For each requested plan, find item_mapping rows for the SAME product
    (normalized equality on item_key OR item_desc) whose sales_category is a DIFFERENT, CONFIDENT value in
    the shared sales vocabulary. Never writes anything, never moves a money number. Returns a list of
    {plan, assigning, other_menu, other_key, other_category}. Conservative by design: exact normalized
    match only (no substring) and both sides must be confident (in-vocab and not 'misc_other') to flag —
    so a spurious block is unlikely, and any block is user-overridable by fixing the other menu."""
    want = _mrc_norm(classification)
    if want not in _MRC_SHARED_VOCAB or want == "misc_other":
        return []  # assigning an unknown/"other" category is non-committal — never conflicts
    idx = {}  # normalized item_key/item_desc -> [(row, sales_category)]
    for r in (item_rows or []):
        sc = _mrc_norm(r.get("sales_category"))
        if sc not in _MRC_SHARED_VOCAB or sc == "misc_other":
            continue
        for k in (r.get("item_key"), r.get("item_desc")):
            nk = _mrc_norm(k)
            if nk:
                idx.setdefault(nk, []).append((r, sc))
    conflicts, seen = [], set()
    for it in (plans or []):
        raw_plan = (it.get("plan") if isinstance(it, dict) else it)
        np = _mrc_norm(raw_plan)
        if not np:
            continue
        for r, sc in idx.get(np, []):
            if sc != want:
                sig = (np, r.get("id") or r.get("item_key"))
                if sig in seen:
                    continue
                seen.add(sig)
                conflicts.append({
                    "plan": str(raw_plan).strip(),
                    "assigning": classification,
                    "other_menu": "Item / Model Mapping",
                    "other_key": r.get("item_desc") or r.get("item_key"),
                    "other_category": sc,
                })
    return conflicts


class MrcMappingBulkClassifyIn(LaxModel):
    classification: str = ""
    carrier_id: Any = None
    match_op: str = ""
    dry_run: Any = None
    items: Any = None


@router.post("/mrc-mapping/bulk-classify")
def mrc_mapping_bulk_classify(body: MrcMappingBulkClassifyIn, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Assign ONE classification to MANY product_mrc mappings in a single round trip (bulk companion to
    /mrc-mapping/confirm). Body: {items:[{plan, mrc?, source_desc?, prefill_mrc?} | str], classification,
    carrier_id?, match_op?, dry_run?}. CROSS-MENU GUARD: every plan is checked against the Item / Model
    Mapping (item_mapping.sales_category, shared vocab); if ANY same product already carries a DIFFERENT
    category there the WHOLE batch is blocked (409, writes nothing) with the conflict list — the user
    resolves the divergence on the other menu (two-way auto-sync is an owner decision: writing item_mapping
    moves the activation-payment pay gate + KPI numbers). dry_run=true returns the guard result + a
    would-apply count without writing. Update-or-insert by id so an existing MRC dollar is NEVER clobbered.
    Money-safe: classification is display/config, not a pay input; nothing recalculates until Run
    Calculation. Admin-gated (money config surface)."""
    require_org(org_id)
    _require_commission_admin(authorization, org_id)
    classification = (body.classification or "").strip()
    if not classification:
        raise HTTPException(400, "classification is required")
    carrier_id = body.carrier_id or None
    match_op = (body.match_op or "equals").strip() or "equals"
    dry_run = bool(body.dry_run)
    # de-dupe the requested plans (case-insensitive), preserving any per-plan mrc/prefill payload
    items, seen = [], set()
    for it in (body.items or []):
        plan = str((it.get("plan") if isinstance(it, dict) else it) or "").strip()
        if not plan or plan.lower() in seen:
            continue
        seen.add(plan.lower())
        items.append(it if isinstance(it, dict) else {"plan": plan})
    if not items:
        raise HTTPException(400, "no plans selected")
    client = sb()
    # cross-menu conflict guard (READ-ONLY — never writes item_mapping, never moves money)
    item_rows = list(_load_item_map(client, org_id).values())
    conflicts = _mrc_crossmenu_conflicts(item_rows, items, classification)
    if dry_run:
        return {"ok": True, "count": len(items), "conflicts": conflicts,
                "would_apply": 0 if conflicts else len(items)}
    if conflicts:
        raise HTTPException(status_code=409, detail={
            "error": "cross_menu_conflict",
            "message": (f"{len(conflicts)} selected product(s) already carry a different category on the "
                        "Item / Model Mapping menu. Resolve the divergence there first, or change your "
                        "selection — nothing was saved."),
            "conflicts": conflicts, "applied": 0})
    # preload existing rows so we UPDATE by id (never clobber an existing mrc $) or INSERT fresh
    try:
        existing_rows = (client.schema('commcalc').table('product_mrc')
                         .select('id,carrier_id,plan_pattern,match_op,mrc').eq('org_id', org_id).execute().data) or []
    except Exception:
        raise HTTPException(400, "Run migration 074_product_mrc.sql first.")
    existing = {((e.get('carrier_id') or ''), _mrc_norm(e.get('plan_pattern')), (e.get('match_op') or 'equals')): e
                for e in existing_rows}
    applied = 0
    results = []
    for it in items:
        plan = str(it.get('plan') or '').strip()
        ex = existing.get(((carrier_id or ''), _mrc_norm(plan), match_op))
        try:
            if ex:
                patch = {"classification": classification, "confirmed": True, "is_active": True}
                if it.get("mrc") is not None:
                    patch["mrc"] = safe_float(it.get("mrc"))
                client.schema('commcalc').table('product_mrc').update(patch)                     .eq('id', ex['id']).eq('org_id', org_id).execute()
                applied += 1
                results.append({"plan": plan, "saved": True, "action": "updated"})
            else:
                row = {"org_id": org_id, "carrier_id": carrier_id, "plan_pattern": plan, "match_op": match_op,
                       "mrc": safe_float(it.get("mrc")) if it.get("mrc") is not None else 0.0,
                       "priority": 100, "is_active": True, "confirmed": True, "classification": classification}
                if it.get("source_desc") is not None:
                    row["source_desc"] = it.get("source_desc")
                if it.get("prefill_mrc") is not None:
                    row["prefill_mrc"] = safe_float(it.get("prefill_mrc"))
                client.schema('commcalc').table('product_mrc').insert(row).execute()
                applied += 1
                results.append({"plan": plan, "saved": True, "action": "inserted"})
        except Exception as e:
            # graceful degrade (pre-mig-201: classification/confirmed cols absent) — retry money-only so
            # the mapping still lands; report per-row so a bad row never aborts the batch.
            try:
                if ex and it.get("mrc") is not None:
                    client.schema('commcalc').table('product_mrc').update({"mrc": safe_float(it.get("mrc")), "is_active": True})                         .eq('id', ex['id']).eq('org_id', org_id).execute()
                    applied += 1
                    results.append({"plan": plan, "saved": True, "action": "updated", "note": "without classification (pre-mig-201)"})
                elif not ex:
                    client.schema('commcalc').table('product_mrc').insert({
                        "org_id": org_id, "carrier_id": carrier_id, "plan_pattern": plan, "match_op": match_op,
                        "mrc": safe_float(it.get("mrc")) if it.get("mrc") is not None else 0.0,
                        "priority": 100, "is_active": True}).execute()
                    applied += 1
                    results.append({"plan": plan, "saved": True, "action": "inserted", "note": "without classification (pre-mig-201)"})
                else:
                    results.append({"plan": plan, "saved": False, "error": str(e)})
            except Exception as e2:
                results.append({"plan": plan, "saved": False, "error": str(e2)})
    return {"ok": True, "applied": applied, "classification": classification, "results": results, "conflicts": []}


# ── Multi-month payout SCHEDULES (migration 057) — generic per-carrier installment payouts ────────
# A schedule spreads one activation's commission over N months (flat or %MRC), with months 2..N gated
# on the bill being paid + residual received that month. With no schedule, payouts are single-month
# (unchanged). The engine is READ-ONLY/PREVIEW here — not yet summed into the live calc (see HANDOFF).

@router.get("/payout-schedule")
def list_payout_schedules(org_id: str = ORG_ID):
    """All schedules + their installment lines. [] (not 500) if migration 057 isn't applied yet."""
    client = sb()
    try:
        scheds = client.schema('commcalc').table('payout_schedule').select('*').eq('org_id', org_id).execute().data or []
        lines = client.schema('commcalc').table('payout_schedule_line').select('*').eq('org_id', org_id).execute().data or []
    except Exception:
        return {"schedules": [], "ready": False, "note": "Run migration 057_multi_month_payout.sql to enable."}
    by_sched = {}
    for ln in lines:
        by_sched.setdefault(ln.get('schedule_id'), []).append(ln)
    for s in scheds:
        s['lines'] = sorted(by_sched.get(s['id'], []), key=lambda x: x.get('month_index') or 0)
    return {"schedules": scheds, "ready": True}


class SavePayoutScheduleIn(LaxModel):
    id: Any = None
    company_id: Any = None
    carrier_id: Any = None
    activation_type: str = ""
    num_months: Any = None
    gate_signal: Any = None
    bypass_tier: Any = True
    is_active: Any = True
    lines: Any = None


@router.post("/payout-schedule")
def save_payout_schedule(body: SavePayoutScheduleIn, org_id: str = ORG_ID):
    """Create/replace a schedule + its lines. Body: {id?, company_id?, carrier_id?, activation_type?,
    num_months, gate_signal?, bypass_tier?, is_active?, lines:[{month_index, payout_kind, flat_amount?,
    mrc_pct?, mrc_basis?, requires_paid}]}. Replaces the lines for the schedule (delete-then-insert)."""
    client = sb()
    head = {
        "org_id": org_id,
        "company_id": body.company_id or None,
        "carrier_id": body.carrier_id or None,
        "activation_type": (body.activation_type or "*").strip() or "*",
        "num_months": int(body.num_months or 1),
        "gate_signal": body.gate_signal or "paid_residual",
        "bypass_tier": bool(body.bypass_tier),
        "is_active": bool(body.is_active),
    }
    try:
        if body.id:
            client.schema('commcalc').table('payout_schedule').update(head).eq('id', body.id).eq('org_id', org_id).execute()
            sid = body.id
        else:
            r = client.schema('commcalc').table('payout_schedule').upsert(
                head, on_conflict='org_id,company_id,carrier_id,activation_type').execute()
            sid = (r.data or [{}])[0].get('id')
        if not sid:
            raise HTTPException(500, "could not save schedule header")
        client.schema('commcalc').table('payout_schedule_line').delete().eq('org_id', org_id).eq('schedule_id', sid).execute()
        lines = []
        for ln in (body.lines or []):
            lines.append({
                "org_id": org_id, "schedule_id": sid,
                "month_index": int(ln.get("month_index") or 1),
                "payout_kind": ln.get("payout_kind") or "flat",
                "flat_amount": safe_float(ln.get("flat_amount")),
                "mrc_pct": safe_float(ln.get("mrc_pct")),
                "mrc_basis": ln.get("mrc_basis") or "commissionable_mrc",
                "requires_paid": bool(ln.get("requires_paid")),
            })
        if lines:
            client.schema('commcalc').table('payout_schedule_line').insert(lines).execute()
        return {"id": sid, "lines": len(lines)}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"save payout-schedule failed (is migration 057 applied?): {e}")


@router.delete("/payout-schedule/{schedule_id}")
def delete_payout_schedule(schedule_id: str, org_id: str = ORG_ID):
    client = sb()
    client.schema('commcalc').table('payout_schedule_line').delete().eq('org_id', org_id).eq('schedule_id', schedule_id).execute()
    client.schema('commcalc').table('payout_schedule').delete().eq('org_id', org_id).eq('id', schedule_id).execute()
    return {"deleted": schedule_id}


