# ── COMMISSION FROM EXECUTIVE MTD (owner directive 2026-08-30) ─────────────────────────────────────
# "A simple $10 and 10% should be easily calculated from the Executive MTD ... the data source should be
# the SAME for all sales reports, commission and Exec MTD ... if the accessory numbers show in Exec MTD why
# are they not in the incentive payout." Root cause: the line-by-line commission engine classifies
# accessories with its OWN classifier, which drifts from the shared Sales-Report classifier that Exec MTD
# (and the Sales Report, Daily Targets) use — so an accessory counted on Exec MTD can be invisible to the
# payout. This computes the two headline commission components DIRECTLY from the Exec MTD per-employee
# aggregates, so the commission basis is byte-identical to what the owner already sees on that report:
#     activation_pay = Total Activation (excl. Upgrade on the Activation-Details basis) × the plan's flat rate
#     accessory_pay  = Acc. Sales                                                       × the plan's accessory %
# READ-ONLY: it calls _exec_mtd and writes nothing. ONE trustworthy data source for report AND commission.
# The DISJOINT Exec MTD activation categories (they sum to Total Activation): each is its OWN payout
# option so a plan can pay, say, BYOD and Tablet and Home Internet at different rates and Upgrade at $0.
# TENANT-AGNOSTIC: every tenant's contract types already normalize into these SAME columns via the shared
# classifier — Boost / Cricket just relabel; the product (and therefore the architecture) is the same, so
# one rate map per category serves all tenants. `activation` here is the PURE New count (Tablet / Home
# Internet / Edge are broken out on their own, matching the Exec MTD row).
_MTD_ACT_CATEGORIES = ("activation", "port", "byod", "tablet", "home_internet", "edge", "upgrade")
_MTD_CATEGORY_LABELS = {
    "activation": "New Activation", "port": "Port", "byod": "BYOD", "tablet": "Tablet",
    "home_internet": "Home Internet", "edge": "Edge", "upgrade": "Upgrade",
}


def _plan_mtd_rates(plan):
    """(activation flat $/unit, accessory fraction) for the MTD-basis commission, read from a plan's rules:
    the amount of the first qualifying flat_per_unit rule keyed on activation_bucket|department, and the pct
    of the first qualifying pct_* rule keyed on accessory. 0 when a component is absent (it then pays $0).
    This is the SIMPLE default; a caller can override with an explicit per-category rate map."""
    act_rate, acc_pct = 0.0, 0.0
    for r in (plan.get("rules") or []):
        if r.get("qualifies") is False:
            continue
        mf = str(r.get("match_field") or "").strip().lower()
        pk = str(r.get("payout_kind") or "").strip().lower()
        if not act_rate and pk == "flat_per_unit" and mf in ("activation_bucket", "department"):
            act_rate = safe_float(r.get("amount"))
        elif not acc_pct and mf == "accessory" and pk.startswith("pct"):
            acc_pct = safe_float(r.get("pct"))
    return act_rate, acc_pct


def _default_mtd_rate_map(act_rate):
    """Per-category default: the plan's flat activation rate on EVERY activation category EXCEPT Upgrade
    (0 — the standing 'upgrades don't pay' rule), so with no override the total reproduces
    Total-Activation-excluding-Upgrade × rate."""
    return {c: (0.0 if c == "upgrade" else float(act_rate or 0.0)) for c in _MTD_ACT_CATEGORIES}


def _parse_mtd_rate_map(rates_str, fallback):
    """Parse a compact 'activation:10,byod:12,upgrade:0' string into a category->rate map layered over the
    fallback. Unknown keys ignored; malformed values skipped; None/'' -> the fallback unchanged. This is
    how the wizard sends the owner's per-category rates without a schema change."""
    out = dict(fallback)
    for part in str(rates_str or "").split(","):
        if ":" not in part:
            continue
        k, v = part.split(":", 1)
        k = k.strip().lower()
        if k in _MTD_ACT_CATEGORIES:
            try:
                out[k] = float(str(v).strip())
            except Exception:
                pass
    return out


def _commission_from_mtd_rows(emp_rows, rate_map, acc_pct):
    """Per-rep commission from Exec MTD by_employee rows, with a PER-CATEGORY rate map. PURE (no I/O), so
    it is unit-testable: activation_pay = Σ_category round(count × rate); accessory_pay = round(acc × pct).
    Each rep row carries a `by_category` breakdown so the wizard can show where the money came from."""
    out = []
    for r in emp_rows or []:
        by_cat, ap = {}, 0.0
        for c in _MTD_ACT_CATEGORIES:
            cnt = int(round(safe_float(r.get(c))))
            rate = float((rate_map or {}).get(c, 0.0) or 0.0)
            pay = round(cnt * rate, 2)
            by_cat[c] = {"count": cnt, "rate": rate, "pay": pay}
            ap += pay
        ap = round(ap, 2)
        acc = round(safe_float(r.get("acc_sales")), 2)
        cp = round(acc * acc_pct, 2)
        out.append({"employee": r.get("employee"),
                    "activations": int(round(safe_float(r.get("total_activation")))),
                    "acc_sales": acc, "activation_pay": ap, "accessory_pay": cp,
                    "commission": round(ap + cp, 2), "by_category": by_cat})
    out.sort(key=lambda x: -x["commission"])
    return out


def _commission_mtd_result(client, org_id, period, plan, rates="", acc_pct="", today=""):
    """Compute the Exec-MTD commission for ONE plan + period. PURE-ish (reads Exec MTD; writes nothing).
    Shared by GET /commission-mtd and the Save endpoint so the saved record and the preview can never
    disagree. Returns the same dict the endpoint returns."""
    plan_act_rate, plan_acc_pct = _plan_mtd_rates(plan)
    # Fallback rate map, in order: the plan's SAVED per-category rates (mig 298 mtd_rates), else the plan's
    # flat activation rate on every category except Upgrade. An explicit `rates` override still wins.
    _stored = plan.get("mtd_rates") if isinstance(plan.get("mtd_rates"), dict) else {}
    _base_map = _default_mtd_rate_map(plan_act_rate)
    for _c in _MTD_ACT_CATEGORIES:
        if _c in _stored:
            try:
                _base_map[_c] = float(_stored[_c])
            except Exception:
                pass
    rate_map = _parse_mtd_rate_map(rates, _base_map)
    try:
        if str(acc_pct).strip() != "":
            eff_acc_pct = float(acc_pct)
        elif "accessory_pct" in _stored:
            eff_acc_pct = float(_stored.get("accessory_pct") or 0.0)
        else:
            eff_acc_pct = plan_acc_pct
    except Exception:
        eff_acc_pct = plan_acc_pct
    stores, markets, emps_scope = [], [], []
    for a in (plan.get("assignments") or []):
        sc = str(a.get("scope") or "").strip().lower()
        sv = a.get("scope_value")
        if not sv:
            continue
        if sc == "store":
            stores.append(sv)
        elif sc == "market":
            markets.append(sv)
        elif sc == "employee":
            emps_scope.append(sv)
    _t = None
    if today:
        try:
            _t = _date.fromisoformat(str(today)[:10])
        except Exception:
            _t = None
    data = _exec_mtd(client, org_id, period, stores=stores or None, markets=markets or None,
                     reps=emps_scope or None, today=_t)
    emp_rows = ((data.get("by_employee") or {}).get("rows")) or []
    rows = _commission_from_mtd_rows(emp_rows, rate_map, eff_acc_pct)
    cat_totals = {c: {"count": sum(r["by_category"][c]["count"] for r in rows),
                      "pay": round(sum(r["by_category"][c]["pay"] for r in rows), 2),
                      "rate": rate_map.get(c, 0.0), "label": _MTD_CATEGORY_LABELS[c]}
                  for c in _MTD_ACT_CATEGORIES}
    totals = {
        "activations": sum(r["activations"] for r in rows),
        "acc_sales": round(sum(r["acc_sales"] for r in rows), 2),
        "activation_pay": round(sum(r["activation_pay"] for r in rows), 2),
        "accessory_pay": round(sum(r["accessory_pay"] for r in rows), 2),
        "commission": round(sum(r["commission"] for r in rows), 2),
        "by_category": cat_totals,
    }
    return {
        "period": period, "plan_id": plan.get("id"), "plan_name": plan.get("name"),
        "categories": [{"key": c, "label": _MTD_CATEGORY_LABELS[c]} for c in _MTD_ACT_CATEGORIES],
        "rate_map": rate_map, "accessory_pct": eff_acc_pct,
        "scope": {"stores": stores, "markets": markets, "employees": emps_scope},
        "activation_source": data.get("activation_source"),
        "by_rep": rows, "totals": totals,
    }


def _load_plan_or_404(client, org_id, plan_id):
    plans, ready = commission_engine._load_plans(client, org_id)
    if not ready:
        raise HTTPException(400, "Commission plans are not set up (migration 059).")
    plan = next((p for p in plans if str(p.get("id")) == str(plan_id)), None)
    if not plan:
        raise HTTPException(404, "plan_id not found")
    return plan


@router.get("/commission-mtd/{period}")
def commission_mtd(period: str, plan_id: str = "", org_id: str = ORG_ID, today: str = "",
                   rates: str = "", acc_pct: str = ""):
    """READ-ONLY commission computed from the Executive MTD per-employee numbers (see the block header).
    Applies ONE plan's rates to the reps in that plan's scope. Moves no pay — Save it or run the calc.

    `rates` (optional) is the owner's PER-CATEGORY override, 'activation:10,byod:10,tablet:10,upgrade:0,…';
    omitted -> the plan's saved rates / flat rate. `acc_pct` (optional) overrides the accessory %. `today`
    (YYYY-MM-DD) is the caller's local date for the MTD cut."""
    require_org(org_id)
    if not period:
        raise HTTPException(400, "period required")
    if not plan_id:
        raise HTTPException(400, "plan_id required")
    client = sb()
    plan = _load_plan_or_404(client, org_id, plan_id)
    out = _commission_mtd_result(client, org_id, period, plan, rates=rates, acc_pct=acc_pct, today=today)
    out["note"] = ("Commission computed from Executive MTD per-employee numbers (per-category activation "
                   "rate + Acc. Sales × %). READ-ONLY — press Save to record it for this period.")
    # attach any existing saved record so the UI can show 'saved / stale'
    out["saved"] = _mtd_saved_summary(client, org_id, period, plan_id)
    return out


def _mtd_saved_summary(client, org_id, period, plan_id):
    """The saved Exec-MTD commission record for (org, period, plan), or None. Never raises (pre-299 DB)."""
    try:
        rows = (client.schema('commcalc').table('mtd_commission_payout')
                .select('rep,commission,saved_at')
                .eq('org_id', org_id).in_('period', _pvariants(period))
                .eq('plan_id', plan_id).execute().data) or []
    except Exception:
        return None
    if not rows:
        return None
    return {"reps": len(rows), "commission": round(sum(safe_float(r.get("commission")) for r in rows), 2),
            "saved_at": max((str(r.get("saved_at") or "") for r in rows), default=None)}


@router.post("/commission-mtd/{period}/save")
def save_commission_mtd(period: str, plan_id: str = "", org_id: str = ORG_ID, today: str = "",
                        rates: str = "", acc_pct: str = ""):
    """SAVE the Exec-MTD-derived commission for a plan + period into commcalc.mtd_commission_payout (mig
    299). ADDITIVE and standalone: it does NOT touch rep_commissions or the /calculate path, so nothing
    else changes and a recalculation never disturbs this record. Recomputes from the SAME helper the
    preview uses, then delete-then-inserts this (org, period, plan)'s rows so a re-save is idempotent."""
    require_org(org_id)
    if not period:
        raise HTTPException(400, "period required")
    if not plan_id:
        raise HTTPException(400, "plan_id required")
    client = sb()
    plan = _load_plan_or_404(client, org_id, plan_id)
    res = _commission_mtd_result(client, org_id, period, plan, rates=rates, acc_pct=acc_pct, today=today)
    rows = res.get("by_rep") or []
    _now = datetime.now(timezone.utc).isoformat()
    payload = [{
        "org_id": org_id, "period": period, "plan_id": plan_id,
        "rep": r.get("employee") or "", "activations": int(r.get("activations") or 0),
        "acc_sales": safe_float(r.get("acc_sales")), "activation_pay": safe_float(r.get("activation_pay")),
        "accessory_pay": safe_float(r.get("accessory_pay")), "commission": safe_float(r.get("commission")),
        "by_category": r.get("by_category"), "rate_map": res.get("rate_map"),
        "accessory_pct": safe_float(res.get("accessory_pct")), "saved_at": _now,
    } for r in rows if (r.get("employee") or "").strip()]
    try:
        (client.schema('commcalc').table('mtd_commission_payout')
         .delete().eq('org_id', org_id).in_('period', _pvariants(period)).eq('plan_id', plan_id).execute())
        if payload:
            client.schema('commcalc').table('mtd_commission_payout').insert(payload).execute()
    except Exception as e:
        raise HTTPException(500, f"save failed (is migration 299 applied?): {e}")
    return {"saved": True, "period": period, "plan_id": plan_id, "plan_name": plan.get("name"),
            "reps": len(payload), "totals": res.get("totals"),
            "note": ("Saved the Executive-MTD commission for this plan + period. Standalone record — it does "
                     "not change rep_commissions or any other payout.")}


@router.get("/commission-mtd/{period}/saved")
def get_saved_commission_mtd(period: str, plan_id: str = "", org_id: str = ORG_ID):
    """Read back the saved Exec-MTD commission record (mig 299) for a plan + period."""
    require_org(org_id)
    client = sb()
    try:
        q = (client.schema('commcalc').table('mtd_commission_payout').select('*')
             .eq('org_id', org_id).in_('period', _pvariants(period)))
        if plan_id:
            q = q.eq('plan_id', plan_id)
        rows = q.execute().data or []
    except Exception:
        rows = []
    rows.sort(key=lambda r: -safe_float(r.get("commission")))
    return {"period": period, "plan_id": plan_id, "rows": rows,
            "totals": {"reps": len(rows),
                       "commission": round(sum(safe_float(r.get("commission")) for r in rows), 2)}}


# ── Commission-plan ASSIGNMENT roster + BULK assign (owner directive 2026-07-23) ──────────────────
# The plan editor assigns ONE person at a time and shows only a name. These two endpoints back the
# people-centric bulk surface: a filterable roster (role + market next to each name — RULE FIVE
# filters, RULE THREE pick-don't-type) and a one-action bulk assign of a single plan to many checked
# people. NO payout math changes here — an assignment only decides WHICH plan a rep's existing sales
# pay under; the next POST /calculate applies it. Bulk writes the SAME employee-scope rows single-
# assign writes (see save_commission_plan): {org_id, plan_id, scope:'employee', scope_value, priority}.
def _norm_assign(v):
    """Case/space-insensitive key for comparing an employee-scope scope_value to a roster person's
    value — matches how commission_engine._resolve_plan_for compares employee scope (.strip().lower())
    so 'already has this plan' agrees with what the engine will actually pay."""
    return (v or "").strip().lower()


@router.get("/commission-plans/roster")
def commission_plan_roster(org_id: str = ORG_ID, include_inactive: bool = True):
    """People roster for the bulk plan-assignment surface. Returns every org employee with the fields
    the UI needs: display name, ROLE + MARKET (for role-next-to-name + the role/market filter facets),
    the disambiguation email, and the assignment VALUE (epay_salesperson || name) that IS the
    employee-scope scope_value written by BOTH single- and bulk-assign (identical rows). Each person
    also carries their CURRENT direct (employee-scope) plan assignments so the owner can see who
    already has what before overwriting. Read-only; org-scoped on every query. Degrades to whatever it
    can read (empty roster / no plans) rather than erroring, so the page never hard-fails."""
    client = sb()
    # 1. roster from storeops.employees (org-scoped). Include inactive by default: a mid-month
    #    terminated rep still has period sale lines that pay under their plan (the engine matches
    #    inactive reps too), so hiding them here would silently make them un-assignable.
    try:
        q = (client.schema("storeops").table("employees")
             .select("id,name,role,email,home_store,epay_salesperson,is_active").eq("org_id", org_id))
        if not include_inactive:
            q = q.eq("is_active", True)
        emps = q.order("name").execute().data or []
    except Exception:
        emps = []
    # 2. home_store -> market via storeops.stores (keyed by BOTH store_code and address — home_store
    #    may hold either form).
    mkt_by_store = {}
    try:
        stores = (client.schema("storeops").table("stores")
                  .select("store_code,address,market").eq("org_id", org_id).execute().data) or []
        for s in stores:
            mk = (s.get("market") or "").strip()
            for k in (s.get("store_code"), s.get("address")):
                if k:
                    mkt_by_store[str(k).strip()] = mk
    except Exception:
        pass
    # 3. current EMPLOYEE-scope assignments -> plan names (org-scoped). ready=False lets the UI show
    #    the "run migration 059" hint instead of a broken page.
    plan_name, assigns_by_val, ready = {}, {}, True
    try:
        plans = (client.schema("commcalc").table("commission_plan")
                 .select("id,name").eq("org_id", org_id).execute().data) or []
        plan_name = {p["id"]: p.get("name") for p in plans}
        arows = (client.schema("commcalc").table("commission_plan_assignment")
                 .select("plan_id,scope_value").eq("org_id", org_id).eq("scope", "employee")
                 .execute().data) or []
        for a in arows:
            assigns_by_val.setdefault(_norm_assign(a.get("scope_value")), []).append(a.get("plan_id"))
    except Exception:
        ready = False
    people, roles_set, markets_set = [], set(), set()
    for e in emps:
        val = (e.get("epay_salesperson") or e.get("name") or "").strip()
        if not val:
            continue
        name = (e.get("name") or "").strip() or val
        role = (e.get("role") or "").strip()
        market = mkt_by_store.get((e.get("home_store") or "").strip(), "")
        cur_ids = assigns_by_val.get(_norm_assign(val), [])
        cur = [{"plan_id": pid, "plan_name": plan_name.get(pid, "(unknown plan)")} for pid in cur_ids]
        if role:
            roles_set.add(role)
        if market:
            markets_set.add(market)
        people.append({
            "id": e.get("id"), "name": name, "value": val, "role": role, "market": market,
            "email": (e.get("email") or "").strip(),
            "home_store": (e.get("home_store") or "").strip(),
            "epay_salesperson": (e.get("epay_salesperson") or "").strip(),
            "is_active": bool(e.get("is_active", True)),
            "current_plans": cur,
        })
    return {"ready": ready, "people": people,
            "roles": sorted(roles_set), "markets": sorted(markets_set)}


@router.get("/commission-plans/assignment-audit")
def commission_plan_assignment_audit(org_id: str = ORG_ID, include_inactive: bool = True):
    """READ-ONLY audit: for EVERY roster employee, which commission plan they resolve to and WHY —
    flagging the dangerous by-name pin that silently overrides a rep's store/market plan.

    THE PROBLEM IT SOLVES (real production case, "Silvia Nava"): a rep pinned to a plan by NAME
    (employee-scope assignment, rank 4) outranks their store (rank 2) and market (rank 1). So a rep in
    Chicago who has a by-name pin on the "…NY" plan keeps getting paid the NY plan even after their
    store/market is corrected — the pin has to be removed. This endpoint finds ALL such cases at once.

    SINGLE SOURCE OF TRUTH: every "which plan / via which assignment" answer comes straight from
    `commission_engine._resolve_plan_for(..., explain=True)` — the SAME matcher the live /calculate path
    pays from — and the flags come from the pure `commission_engine.audit_flags(winner, considered, …)`.
    Nothing here re-implements matching, so the audit cannot disagree with what actually pays.

    ENUMERATION mirrors the employee picker (`/commission-plans/roster`): reps come from the storeops
    roster, each with their home_store. MARKET is resolved through `_read_store_market`
    (commcalc.store_mapping) with the EXACT expression the live calc uses
    (`store_market.get(low) or store_market.get(first_token, "")`), and ROLE through the SAME
    `_read_employee_roles` name bridge the pay path uses — so the inputs fed to the resolver match the
    live calc for the store the rep is on. (Caveat: the live calc keys market off each SALES ROW'S POS
    store string; here we substitute the roster home_store, since a per-employee audit has no sale row.
    For a rep whose sales land on a different store than their home_store, the resolved market can
    differ — the by-name pin itself is store/market-independent, so the by_name_override finding stands
    regardless.)

    Org-scoped, read-only, never writes. Degrades to {ready:false} when migration 059 is unapplied."""
    require_org(org_id)
    client = sb()
    plans, ready = commission_engine._load_plans(client, org_id)
    if not ready:
        return {"ready": False,
                "note": "Run migration 059_commission_plans.sql to enable the assignment audit.",
                "employees": [], "counts": {}}
    # roster (same source the picker / _read_employee_roles uses), with home_store per person
    try:
        q = (client.schema("storeops").table("employees")
             .select("id,name,role,email,home_store,epay_salesperson,is_active").eq("org_id", org_id))
        if not include_inactive:
            q = q.eq("is_active", True)
        emps = q.order("name").execute().data or []
    except Exception:
        emps = []
    store_market = commission_engine._read_store_market(client, org_id)   # commcalc.store_mapping
    role_by_rep = commission_engine._read_employee_roles(client, org_id)  # {_canon(name) -> role}
    known_markets = sorted({(m or "").strip() for m in store_market.values() if (m or "").strip()})

    employees, counts = [], {"total": 0, "by_name_override": 0, "no_plan": 0, "location_mismatch": 0}
    for e in emps:
        name = (e.get("name") or "").strip()
        if not name:
            continue
        store = (e.get("home_store") or "").strip()
        low = store.lower()
        first = low.split(" ")[0] if low else ""
        # EXACT expression preview() uses to map a store string to a market.
        market = (store_market.get(low) or store_market.get(first, "")) if low else ""
        rep_role = role_by_rep.get(commission_engine._canon_person(name))
        resolution = commission_engine._resolve_plan_for(
            name, store, market, plans, rep_role=rep_role, explain=True)
        winner = resolution.get("winner")
        considered = resolution.get("considered") or []
        flags = commission_engine.audit_flags(winner, considered, rep_market=market,
                                              known_markets=known_markets)
        flag_names = {f["flag"] for f in flags}
        counts["total"] += 1
        for fn in ("by_name_override", "no_plan", "location_mismatch"):
            if fn in flag_names:
                counts[fn] += 1
        employees.append({
            "employee": name,
            "store": store,
            "market": market,
            "role": rep_role or None,
            "is_active": bool(e.get("is_active", True)),
            "resolved_plan": (winner or {}).get("plan_name"),
            "winner_scope": (winner or {}).get("scope"),
            "winner_value": (winner or {}).get("scope_value"),
            "winner_priority": (winner or {}).get("rank"),          # precedence 4>3>2>1>0
            "winner_assignment_priority": (winner or {}).get("priority"),  # in-scope tie-break
            "flags": flags,
            "flag_names": sorted(flag_names),
        })
    # flagged rows first (by_name_override at the very top), then the rest, name-stable within a group.
    def _rank(row):
        fn = set(row.get("flag_names") or [])
        if "by_name_override" in fn:
            return 0
        if "no_plan" in fn:
            return 1
        if "location_mismatch" in fn:
            return 2
        return 3
    employees.sort(key=lambda r: (_rank(r), str(r.get("employee") or "").lower()))
    return {"ready": True, "employees": employees, "counts": counts,
            "markets": known_markets}


class BulkAssignCommissionPlanIn(LaxModel):
    plan_id: str = ""
    people: Any = None
    replace_existing: Any = None


@router.post("/commission-plans/bulk-assign")
async def bulk_assign_commission_plan(body: BulkAssignCommissionPlanIn, org_id: str = ORG_ID):
    """Assign ONE commission plan to MANY employees in a single action (owner directive 2026-07-23).

    Body: {plan_id, people:[<scope_value> | {value}...], replace_existing?:bool}. Additive to single-
    assign; writes the SAME row shape ({org_id, plan_id, scope:'employee', scope_value, priority:0}).
    NO payout-math change — assignments only decide which plan a rep's sales pay under; the next
    POST /calculate applies it. org_id stamped on every inserted row; org-scoped on every read/delete.

    Per-person status:
      • already_assigned  — an employee-scope row for this person→this plan already exists (no-op)
      • assigned          — person had NO direct plan; new row inserted
      • replaced          — person had a DIFFERENT direct plan; replace_existing=true → old direct
                            rows deleted + new row inserted ('replaced' = # rows removed for them)
      • skipped_has_other — person had a different direct plan and replace_existing=false (needs confirm)
    """
    plan_id = (body.plan_id or "").strip()
    if not plan_id:
        raise HTTPException(400, "plan_id required")
    # normalize + dedupe the selection (accept plain strings or {value} objects), first-seen order
    seen, values = set(), []
    for p in (body.people or []):
        v = str((p.get("value") if isinstance(p, dict) else p) or "").strip()
        k = _norm_assign(v)
        if not v or k in seen:
            continue
        seen.add(k)
        values.append(v)
    if not values:
        raise HTTPException(400, "no people selected")
    replace_existing = bool(body.replace_existing)
    client = sb()
    # plan must exist for THIS org (guards a stale / cross-tenant plan_id)
    try:
        prow = (client.schema("commcalc").table("commission_plan").select("id,name")
                .eq("org_id", org_id).eq("id", plan_id).limit(1).execute().data) or []
    except Exception as ex:
        raise HTTPException(500, f"bulk-assign failed (is migration 059 applied?): {ex}")
    if not prow:
        raise HTTPException(404, "plan not found for this org")
    plan_nm = prow[0].get("name")
    # existing employee-scope assignments for the org → {norm(scope_value): [{id, plan_id}]}
    existing = {}
    arows = (client.schema("commcalc").table("commission_plan_assignment")
             .select("id,plan_id,scope_value").eq("org_id", org_id).eq("scope", "employee")
             .execute().data) or []
    for a in arows:
        existing.setdefault(_norm_assign(a.get("scope_value")), []).append(a)
    results, to_insert, to_delete_ids = [], [], []
    for v in values:
        cur = existing.get(_norm_assign(v), [])
        same = [a for a in cur if a.get("plan_id") == plan_id]
        other = [a for a in cur if a.get("plan_id") != plan_id]
        if same:
            results.append({"value": v, "status": "already_assigned"})
        elif other and not replace_existing:
            results.append({"value": v, "status": "skipped_has_other",
                            "existing_plan_ids": [a.get("plan_id") for a in other]})
        elif other:  # replace_existing
            to_delete_ids.extend([a["id"] for a in other if a.get("id")])
            to_insert.append({"org_id": org_id, "plan_id": plan_id, "scope": "employee",
                              "scope_value": v, "priority": 0})
            results.append({"value": v, "status": "replaced", "replaced": len(other)})
        else:
            to_insert.append({"org_id": org_id, "plan_id": plan_id, "scope": "employee",
                              "scope_value": v, "priority": 0})
            results.append({"value": v, "status": "assigned"})
    # WRITE order = INSERT then DELETE. An extra, soon-deleted config row is harmless; a LOST
    # assignment is money-adjacent — so the replacement always lands before the old row is removed.
    # Both are single batched calls (delete-then-insert is the plan-children convention; inverted
    # here only to protect against a mid-op failure dropping pay).
    inserted = deleted = 0
    if to_insert:
        client.schema("commcalc").table("commission_plan_assignment").insert(to_insert).execute()
        inserted = len(to_insert)
    if to_delete_ids:
        (client.schema("commcalc").table("commission_plan_assignment").delete()
         .eq("org_id", org_id).in_("id", to_delete_ids).execute())
        deleted = len(to_delete_ids)
    summary = {
        "assigned": sum(1 for r in results if r["status"] == "assigned"),
        "already": sum(1 for r in results if r["status"] == "already_assigned"),
        "replaced": sum(1 for r in results if r["status"] == "replaced"),
        "skipped": sum(1 for r in results if r["status"] == "skipped_has_other"),
        "rows_inserted": inserted, "rows_deleted": deleted,
    }
    return {"ok": True, "plan_id": plan_id, "plan_name": plan_nm,
            "replace_existing": replace_existing, "results": results, "summary": summary}


# ── SINGLE-REP RECOMPUTE (owner directive 2026-08-22, luxelink) ────────────────────────────────────
# After an incentive plan is attached to ONE rep (Incentive Explain page), recompute JUST that rep's
# rep_commissions row so the page can show the new number immediately — WITHOUT a full-company Run
# Calculation. It drives the SAME engines and the SAME per-row write helper (_apply_engine_components_
# to_row) the full run uses, so this rep's row is byte-identical to what the next full run would write
# for them. It NEVER touches any other rep's row (no period-wide delete; a single scoped update/insert).
class RecomputeRepIn(LaxModel):
    period: Any = None
    rep: Any = None


@router.post("/recompute-rep")
def recompute_rep(body: RecomputeRepIn, org_id: str = ORG_ID):
    """Recompute + UPSERT ONE rep's rep_commissions row (plan_comm / plan_name / total_payout) after a
    plan attach, using commission_engine.preview(only_rep=rep) + that rep's installment amounts and the
    SHARED write helper the full run uses. Org/period scoped; never rewrites other reps."""
    require_org(org_id)
    period = str(body.period or "").strip()
    rep = str(body.rep or "").strip()
    if not period or not rep:
        raise HTTPException(400, "period and rep are required")
    client = sb()

    # SAME deterministic POS->roster identity map + plan resolver the full run (_apply_new_engines) uses,
    # restricted to this ONE rep. only_rep filters the rep grouping AFTER the (org-wide) sales read and
    # store/financing context are built, so this rep's plan amount is identical to the full-run slice.
    _id_map = _rep_canon_map(client, org_id)
    plan_by_rep = {}
    try:
        pr = commission_engine.preview(client, org_id, period, only_rep=rep, identity_map=_id_map)
        for r in (pr.get("by_rep") or []):
            rn = str(r.get("rep") or "").strip().upper()
            if rn:
                plan_by_rep[rn] = {"amount": safe_float(r.get("total_payout")),
                                   "plan_name": r.get("plan_name"),
                                   "setup_fee_comm": safe_float(r.get("setup_fee_comm"))}
    except Exception as e:
        raise HTTPException(500, f"recompute-rep preview failed: {e}")

    # this rep's installment / statement components — computed exactly as _apply_new_engines does (the
    # engines are org-wide; we only WRITE this rep's row, so we just index by this rep's keys below).
    inst_by_rep, sale_inst_by_rep, stmt_by_rep = {}, {}, {}
    try:
        ir = installment_engine.compute_installments(client, org_id, period, persist=True)
        for r, amt in (ir.get("by_rep") or {}).items():
            if r:
                inst_by_rep[str(r).strip().upper()] = safe_float(amt)
    except Exception:
        inst_by_rep = {}
    try:
        sr = sale_installment_engine.compute_sale_installments(client, org_id, period, persist=True)
        for r, amt in (sr.get("by_rep") or {}).items():
            if r:
                sale_inst_by_rep[str(r).strip().upper()] = safe_float(amt)
    except Exception:
        sale_inst_by_rep = {}
    try:
        srows, _s, _pg = [], 0, 1000
        while True:
            chunk = (client.schema('commcalc').table('carrier_commission')
                     .select('rep_name,total_commission').eq('org_id', org_id)
                     .in_('period', _pvariants(period)).range(_s, _s + _pg - 1).execute().data) or []
            srows.extend(chunk)
            if len(chunk) < _pg:
                break
            _s += _pg
        for r in srows:
            rn = str(r.get('rep_name') or '').strip().upper()
            if rn:
                stmt_by_rep[rn] = round(stmt_by_rep.get(rn, 0.0) + safe_float(r.get('total_commission')), 2)
    except Exception:
        stmt_by_rep = {}

    cols = _probe_rep_comm_engine_cols(client, org_id)

    # find this rep's existing stored row (org+period scoped). Match on either name key AND the roster
    # bridge, so a POS/roster spelling difference still finds the row to update in place.
    rep_up = rep.upper()
    keyset = {rep_up}
    _bridged = _id_map.get(rep_up)
    if _bridged:
        keyset.add(_bridged.strip().upper())
    try:
        stored = (client.schema('commcalc').table('rep_commissions').select('*')
                  .eq('org_id', org_id).in_('period', _pvariants(period)).execute().data) or []
    except Exception:
        stored = []
    row, existing_id = None, None
    for s in stored:
        if _rep_comm_row_keys(s) & keyset:
            row, existing_id = dict(s), s.get('id')
            break

    pm = parse_period(period)
    if row is None:
        # no standard row yet → build one exactly as the full run's plan-only branch does.
        row = {"org_id": org_id, "period": period,
               "period_month": pm.get("month"), "period_year": pm.get("year"),
               "storeops_name": rep, "epay_salesperson": rep,
               "subtotal": 0.0, "tier": 1, "total_payout": 0.0}
    else:
        # recover the standard-calc base (strip the previously-folded installment components) so the
        # shared helper recomputes total_payout the same way the full run does from a FRESH calc row.
        # For a plan-covered rep the helper overwrites `base` with the plan amount, so this only affects
        # the (non-plan) fallback branch — keeping it consistent with the full run's non-plan formula.
        row["total_payout"] = round(
            safe_float(row.get("total_payout"))
            - safe_float(row.get("residual_installment_comm"))
            - safe_float(row.get("installment_comm_sale")), 2)

    ks = _rep_comm_row_keys(row) or keyset
    _apply_engine_components_to_row(
        row, ks, inst_by_rep, sale_inst_by_rep, stmt_by_rep, plan_by_rep, cols)

    # UPSERT ONLY this rep's row: update in place when it existed, else insert. No period-wide delete,
    # so no other rep's row is ever touched.
    row["org_id"] = org_id
    try:
        if existing_id is not None:
            payload = {k: v for k, v in row.items() if k != "id"}
            (client.schema('commcalc').table('rep_commissions').update(payload)
             .eq('org_id', org_id).eq('id', existing_id).execute())
        else:
            client.schema('commcalc').table('rep_commissions').insert(row).execute()
    except Exception as e:
        raise HTTPException(500, f"recompute-rep write failed: {e}")

    pv = next((plan_by_rep[k] for k in ks if k in plan_by_rep), None)
    return {"ok": True, "rep": rep, "period": period,
            "matched_plan": pv is not None,
            "plan_name": (pv or {}).get("plan_name"),
            "plan_comm": safe_float((pv or {}).get("amount")) if pv else 0.0,
            "total_payout": safe_float(row.get("total_payout"))}


# ── MARKETS (pick-don't-type options for the Store Markets editor — AGENT_CONTRACT §3b/RULE THREE) ──
# A market is a free-form label the org invents once and then reuses; typing it per store is how "LI",
# "li" and "L I" become three different markets and a store silently drops out of its market filter.
# These helpers are the single definition of "the markets this org already uses" + "what a submitted
# market normalizes to", shared by the options read and the store write below.

def _market_key(name: str) -> str:
    """Case/whitespace-insensitive identity of a market label — the ONLY thing that decides whether two
    spellings are the SAME market (' li ' == 'LI'). Not stored; used for matching/dedupe."""
    return " ".join((name or "").split()).casefold()


def _org_markets(client, org_id: str) -> list:
    """The org's existing market labels: distinct, non-blank, sorted (case-insensitive).
    Source = commcalc.store_mapping (the canon this settings page edits) UNIONed with storeops.stores
    (a tenant may keep its roster only there; storeops writes propagate into store_mapping anyway).
    Both reads are org-scoped (RULE ONE). Spellings that differ only by case/whitespace collapse to ONE
    canonical option — the spelling the most rows use, ties broken alphabetically — so the dropdown can
    never offer both "LI" and "li". Never raises: an unreadable table just contributes nothing."""
    variants = {}
    for schema, table in (("commcalc", "store_mapping"), ("storeops", "stores")):
        try:
            rows = (client.schema(schema).table(table).select("market")
                    .eq("org_id", org_id).execute().data) or []
        except Exception as e:
            print(f"WARN _org_markets: {schema}.{table}.market unreadable ({e})")
            rows = []
        for r in rows:
            name = " ".join((r.get("market") or "").split())
            if not name:                      # blank/NULL market = "unassigned", never an option
                continue
            bucket = variants.setdefault(_market_key(name), {})
            bucket[name] = bucket.get(name, 0) + 1
    canon = [sorted(b.items(), key=lambda kv: (-kv[1], kv[0]))[0][0] for b in variants.values()]
    return sorted(canon, key=lambda s: (s.casefold(), s))


def _canonical_market(client, org_id: str, value) -> str:
    """Normalize a submitted market label before it is stored: trim (and collapse inner runs of
    whitespace), then snap to the CANONICAL casing of an existing market when it matches one
    case-insensitively — picking/typing "li" where "LI" already exists stores "LI", so the two can never
    become separate market buckets. A value matching nothing is kept verbatim (that IS how a genuinely
    new market is created — the UI makes that an explicit choice). Blank stays blank: no market is a
    legitimate, explicit state.

    HTML/angle-bracket junk (e.g. a pasted "<li>") is stripped FIRST (scope.sanitize_market_label) so
    this verbatim create-new path can never persist markup as a market — the defect that put "<li>"
    into commcalc.store_mapping.market (migration 740). An all-markup value collapses to "" =
    unassigned."""
    from app.core.scope import sanitize_market_label
    name = sanitize_market_label(value)
    if not name:
        return ""
    key = _market_key(name)
    for existing in _org_markets(client, org_id):
        if _market_key(existing) == key:
            return existing
    return name


@router.get("/markets")
def list_markets(org_id: str = ORG_ID):
    """Options list for the market dropdown: the org's existing markets, distinct + sorted, blanks
    excluded. Read-only, org-scoped; degrades to [] rather than erroring so the editor still renders."""
    require_org(org_id)
    return {"markets": _org_markets(sb(), org_id)}


@router.get("/stores")
def get_stores(org_id: str = "00000000-0000-0000-0000-000000000001"):
    client = sb()
    r = client.schema('commcalc').table('store_mapping').select('*').eq('org_id', org_id).order('store_address').execute()
    return r.data or []

class UpdateStoreIn(LaxModel):
    market: Any = None
    store_code: Any = None
    store_address: Any = None
    is_active: Any = None
    salesforce_id: Any = None


@router.put("/stores/{store_id}")
async def update_store(store_id: str, body: UpdateStoreIn, org_id: str = "00000000-0000-0000-0000-000000000001"):
    client = sb()
    allowed = {k: getattr(body, k) for k in ('market', 'store_code', 'store_address', 'is_active', 'salesforce_id')
               if k in body.model_fields_set}
    if not allowed:
        raise HTTPException(400, "No valid fields to update")
    # market is normalized for EVERY caller, not just the settings dropdown: trimmed, and snapped to the
    # canonical casing of an existing market when it matches one case-insensitively (see
    # _canonical_market). Blank is preserved as blank = explicitly unassigned.
    if 'market' in allowed:
        allowed['market'] = _canonical_market(client, org_id, allowed['market'])
    r = client.schema('commcalc').table('store_mapping').update(allowed).eq('org_id', org_id).eq('id', store_id).execute()
    return r.data[0] if r.data else {}


# ── store-name aliases (migration 023): map alternate spellings of a store in the B2B sales
# file to a canonical store_code, so Daily Targets actuals attach correctly. Additive — does
# NOT touch store_mapping (which the asset market join depends on). Mirrors rep name aliases.
@router.get("/store-aliases")
def list_store_aliases(org_id: str = ORG_ID):
    require_org(org_id)
    client = sb()
    try:
        aliases = (client.schema('commcalc').table('store_aliases').select('*')
                   .eq('org_id', org_id).order('store_code').execute().data) or []
    except Exception as e:
        print(f'WARN store_aliases query failed (run 023_store_aliases.sql?): {e}')
        aliases = []
    # pick-don't-type source = the org's REAL stores: commcalc.store_mapping (house canon) UNIONed with the
    # org's storeops.stores roster, so a tenant with NO store_mapping (luxelink) still has options to pick.
    stores = [{'store_code': s['store_code'], 'store_address': s['address'], 'market': s.get('market', '')}
              for s in _store_maps(client, org_id)['stores']]
    stores.sort(key=lambda s: (s.get('store_address') or s.get('store_code') or '').lower())
    return {"aliases": aliases, "stores": stores}


@router.get("/store-resolution")
def store_resolution(period: str = "", org_id: str = ORG_ID):
    """Store-Matching UI data: every observed POS/sales store string × its current resolution status
    (explicit / store_mapping / exact-fallback / unresolved) + ranked smart suggestions. Optional `period`
    narrows the observed strings to that month; empty = all of the org's sales/feed data."""
    require_org(org_id)
    return _store_resolution_report(sb(), org_id, period=(period or None))


class AddStoreAliasIn(LaxModel):
    alias: str = ""
    store_code: str = ""


@router.post("/store-aliases")
def add_store_alias(body: AddStoreAliasIn, org_id: str = ORG_ID):
    require_org(org_id)
    alias = (body.alias or '').strip()
    code = (body.store_code or '').strip()
    if not alias or not code:
        raise HTTPException(400, "alias and store_code required")
    client = sb()
    # pick-don't-type (§3b): the code MUST be one of the org's real stores (store_mapping OR storeops) —
    # a confirm/suggestion can only ever materialize a mapping to a store that actually exists.
    M = _store_maps(client, org_id)
    valid = {s['store_code'].upper() for s in M['stores']}
    if valid and code.upper() not in valid:
        raise HTTPException(400, f"'{code}' is not one of your stores — pick from the store list.")
    # replace any existing alias with the same text (case-insensitive) to keep it unique
    existing = (client.schema('commcalc').table('store_aliases').select('id,alias')
                .eq('org_id', org_id).execute().data) or []
    for r in existing:
        if (r.get('alias') or '').strip().lower() == alias.lower():
            client.schema('commcalc').table('store_aliases').delete().eq('id', r['id']).execute()
    row = {'org_id': org_id, 'alias': alias, 'store_code': code,
           'note': (body.get('note') or '').strip() or None}
    # provenance (mig 219) — how the mapping was made (manual / suggested / fallback-confirmed) + the
    # suggestion confidence, for the audit trail. Included only if the columns exist → pre-mig-219 graceful.
    extra = {'source': (body.get('source') or 'manual').strip() or 'manual',
             'confidence': (body.get('confidence') or '').strip() or None}
    present = _known_columns(client, 'store_aliases', ['source', 'confidence'])
    for k, v in extra.items():
        if k in present:
            row[k] = v
    res = client.schema('commcalc').table('store_aliases').insert(row).execute()
    return {"alias": (res.data or [row])[0]}


@router.delete("/store-aliases/{alias_id}")
def delete_store_alias(alias_id: str, org_id: str = ORG_ID):
    require_org(org_id)
    sb().schema('commcalc').table('store_aliases').delete() \
        .eq('org_id', org_id).eq('id', alias_id).execute()
    return {"ok": True}


# Tables this diagnostic scans, and the column each one spells a store string in. `daily_sales_feed`
# was MISSING (2026-08-06): the hourly B2B feed is where a store string FIRST enters a tenant, and
# `_promote_feed_to_raw_sales` then copies it into raw_sales — so the one source that could show an
# unknown store the moment it arrives was the one source not looked at.
_UNMATCHED_SRCS = [('raw_sales', 'store'), ('daily_sales_feed', 'store'), ('asset_ledger', 'store'),
                   ('rep_commissions', 'store'), ('raw_comp_report', 'business_address'),
                   ('vip_paygo', 'dealer'), ('vip_invoices', 'location')]
# Rows read per source in ONE request. The scan stays single-shot per source (this endpoint fans out
# over seven tables; paginating each one would turn a diagnostic into a gateway timeout), but a scan
# that hits the cap now SAYS SO — see `truncated` below.
_UNMATCHED_SCAN_LIMIT = 60000


# ═══════════════════════════════════════════════════════════════════════════════════════════
# CROSS-TENANT INGEST GUARD — admin API (owner-approved 2026-08-06; migration 280)
# Config + review queue for the guard in `ingest_store_guard.py`. Everything is org-scoped and
# every handler degrades gracefully when migration 280 has not been run yet.
# ═══════════════════════════════════════════════════════════════════════════════════════════
def _require_guard_edit(authorization: str, org_id: str):
    """Editing the guard is gated on the EXISTING 'classification' settings area (the same area
    that already gates the accessory/contract-type config this sits beside). Degrades to
    admin-only if core has not registered it, and to open if RBAC is off — the module-wide
    posture, so the house org can never lock itself out."""
    if not _can_edit_classification(authorization, org_id):
        raise HTTPException(403, "You need the 'Classification' settings permission to change the "
                                 "cross-tenant ingest guard. Ask an administrator to grant it.")


@router.get("/ingest-guard/config")
def get_ingest_guard_config(org_id: str = ORG_ID):
    """This tenant's cross-tenant ingest guard: enforcement mode + how many stores it knows about.
    `ready:false` = migration 280 has not been run (the guard is inert, ingests are unaffected)."""
    require_org(org_id)
    client = sb()
    cfg = _isg.get_config(client, org_id)
    try:
        _known, n = _isg.known_store_matcher(client, org_id)
        cfg["known_store_keys"] = n
    except Exception:
        cfg["known_store_keys"] = 0
    cfg["modes"] = [
        {"value": "off", "label": "Off",
         "help": "Don't check anything. Exactly how the system behaved before this feature."},
        {"value": "warn", "label": "Warn (recommended)",
         "help": "Import everything as normal, but list any store we've never heard of so you can "
                 "check it. Nothing is held back."},
        {"value": "block", "label": "Block",
         "help": "Hold back rows for a store we've never heard of instead of importing them. "
                 "They're kept safe here and you can release them with one click."},
    ]
    cfg["guarded_tables"] = sorted(_isg.GUARDED_TABLES)
    return cfg


class PutIngestGuardConfigIn(LaxModel):
    mode: str = ""
    block_min_rows: Any = None
    allow_creates_alias: Any = True
    notify_on_flag: Any = True
    updated_by: Any = None


@router.put("/ingest-guard/config")
def put_ingest_guard_config(body: PutIngestGuardConfigIn, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Set the enforcement mode / thresholds. Permission-gated; org-scoped (org_id is the query
    param the tenant middleware rewrites from the caller's JWT — never a body field)."""
    require_org(org_id)
    _require_guard_edit(authorization, org_id)
    mode = str(body.mode or "warn").strip().lower()
    if mode not in _isg.MODES:
        raise HTTPException(400, f"mode must be one of {', '.join(_isg.MODES)}")
    row = {
        "org_id": org_id, "mode": mode,
        "block_min_rows": max(0, int(safe_float(body.block_min_rows) or 0)),
        "allow_creates_alias": bool(body.allow_creates_alias),
        "notify_on_flag": bool(body.notify_on_flag),
        "updated_by": (body.updated_by or "web"),
    }
    try:
        sb().schema("commcalc").table("ingest_store_guard").upsert(row, on_conflict="org_id").execute()
    except Exception as e:
        raise HTTPException(500, f"Could not save — run migration 280 first ({e}).")
    return _isg.get_config(sb(), org_id)


@router.get("/ingest-guard/queue")
def get_ingest_guard_queue(status: str = "pending", limit: int = 200, org_id: str = ORG_ID):
    """The review queue: store strings the guard did not recognise, newest first, with row counts
    and dollar totals so a flag can be sized at a glance. `withheld_rows` is deliberately NOT
    returned (it can be thousands of rows) — only whether any exist."""
    require_org(org_id)
    try:
        q = (sb().schema("commcalc").table("ingest_store_quarantine")
             .select("id,created_at,store_raw,source,upload_type,target_table,period,filename,"
                     "rows_seen,rows_withheld,amount_seen,sample,status,mode_at_flag,"
                     "decided_at,decided_by,decision_note")
             .eq("org_id", org_id).order("created_at", desc=True)
             .limit(max(1, min(limit, 1000))))
        if status and status != "all":
            q = q.eq("status", status)
        rows = q.execute().data or []
    except Exception as e:
        return {"ok": False, "items": [], "count": 0,
                "hint": f"ingest_store_quarantine unavailable — run migration 280 ({e})."}
    return {"ok": True, "count": len(rows), "items": rows, "status": status}


class DecideIngestGuardItemIn(LaxModel):
    decision: str = ""
    store_code: str = ""
    decided_by: Any = None
    note: Any = None


@router.post("/ingest-guard/queue/{item_id}/decide")
def decide_ingest_guard_item(item_id: str, body: Optional[DecideIngestGuardItemIn] = None,
                             authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Rule on one flagged store.

      decision='allow'  — this store IS ours. When `allow_creates_alias` is on (default) and a
                          `store_code` is supplied, a normal commcalc.store_aliases row is created
                          so the guard (and every report) knows it permanently — the existing
                          pick-don't-type machinery, not a parallel allowlist. Any rows that were
                          WITHHELD are then written to their target table.
      decision='reject' — this store belongs to another tenant. Withheld rows stay parked; nothing
                          is written and nothing is destroyed.

    Writing withheld rows back is the only write here and it is idempotent per item (status flips
    to 'released', so a second call is a no-op)."""
    require_org(org_id)
    _require_guard_edit(authorization, org_id)
    body = body or DecideIngestGuardItemIn()
    decision = str(body.decision or "").strip().lower()
    if decision not in ("allow", "reject"):
        raise HTTPException(400, "decision must be 'allow' or 'reject'")
    client = sb()
    try:
        rows = (client.schema("commcalc").table("ingest_store_quarantine").select("*")
                .eq("org_id", org_id).eq("id", item_id).limit(1).execute().data) or []
    except Exception as e:
        raise HTTPException(500, f"Queue unavailable — run migration 280 ({e}).")
    if not rows:
        raise HTTPException(404, "That flagged store is not in this tenant's review queue.")
    item = rows[0]
    if str(item.get("status")) != "pending":
        return {"ok": True, "already": item.get("status"), "item_id": item_id}

    released, alias = 0, None
    if decision == "allow":
        cfg = _isg.get_config(client, org_id)
        code = str(body.store_code or "").strip()
        if code and cfg.get("allow_creates_alias"):
            # pick-don't-type: the code MUST be one of the org's real stores.
            M = _store_maps(client, org_id)
            valid = {s["store_code"].upper() for s in M["stores"]}
            if valid and code.upper() not in valid:
                raise HTTPException(400, f"'{code}' is not one of your stores — pick from the list.")
            try:
                client.schema("commcalc").table("store_aliases").insert({
                    "org_id": org_id, "alias": item["store_raw"], "store_code": code,
                    "note": "allowed from the cross-tenant ingest guard",
                }).execute()
                alias = {"alias": item["store_raw"], "store_code": code}
            except Exception as e:
                print(f"WARN guard alias create failed: {e}")
        held = item.get("withheld_rows") or []
        if held:
            tbl = str(item.get("target_table") or "")
            if tbl in _isg.GUARDED_TABLES:
                for i in range(0, len(held), 500):
                    client.schema("commcalc").table(tbl).insert(held[i:i + 500]).execute()
                released = len(held)

    try:
        client.schema("commcalc").table("ingest_store_quarantine").update({
            "status": ("released" if released else ("allowed" if decision == "allow" else "rejected")),
            "decided_at": _datetime.now(timezone.utc).isoformat(),
            "decided_by": (body.decided_by or "web"),
            "decision_note": (body.note or None),
        }).eq("org_id", org_id).eq("id", item_id).execute()
    except Exception as e:
        print(f"WARN guard decision not recorded: {e}")
    # Intimation-only mirror: reflect the guard decision into the inbox request (allow->approve,
    # reject->deny). The board owns the effect (alias pick + row release); never affects it.
    try:
        from app.modules.approvals import engine as _approvals
        _approvals.sync_source_decision(org_id, type="ingest_guard",
                                        source_table="ingest_store_quarantine", source_id=item_id,
                                        decision=("approve" if decision == "allow" else "deny"),
                                        actor=(body.decided_by or None), note=(body.note or None))
    except Exception:
        pass
    return {"ok": True, "item_id": item_id, "decision": decision,
            "rows_released": released, "alias_created": alias}


@router.get("/store-unmatched")
def store_unmatched(period: str = "", org_id: str = ORG_ID):
    """Diagnose store mismatches for the Store-Matching UI: distinct raw store strings across the
    data sources that do NOT resolve to a canonical commcalc.store_mapping address (after the
    alias / store_code / leading-number chain). These are the stores to map (add an alias) so the
    P&L, Daily Targets and recon all attribute to one canonical store instead of splitting it.

    It is also the first place a CROSS-TENANT mis-file shows up: another tenant's store string filed
    under this org resolves to nothing here, because this org's store_mapping has never heard of it.

    ★ HONEST SCAN (2026-08-06). Two defects made this endpoint quietly under-report, and they cost a
    real investigation:
      • the per-source read was `.limit(60000)` with NO ordering. The house org holds well over 60k
        `raw_sales` rows across its history, so the raw_sales scan was TRUNCATED at an arbitrary,
        non-repeatable 60k rows — and a leaked store whose rows fell outside that window was reported
        as coming from `rep_commissions` ONLY, hiding the fact that the SALES BASIS was contaminated
        too. The read is now ORDERED (repeatable) and every source reports `rows_scanned` +
        `truncated`, so a partial answer can never again be mistaken for a complete one.
      • `daily_sales_feed` was not scanned at all (see `_UNMATCHED_SRCS`).

    `period` (optional, either spelling) narrows every period-bearing source to one month. That is the
    way to get an EXACT, untruncated answer on a big tenant — and the way to ask "which month did this
    foreign store arrive in". Sources with no `period` column are still scanned whole.

    Read-only and org-scoped. Response keys that existed before are unchanged; `counts`, `per_source`
    and `scan` are additive."""
    require_org(org_id)
    client = sb()
    from app.modules.account import coa
    canon = {}
    for m in (client.schema('commcalc').table('store_mapping')
              .select('store_code,store_address,market').eq('org_id', org_id).execute().data or []):
        a = (m.get('store_address') or '').strip()
        if a:
            canon[a.lower()] = m
    resolve = coa.store_resolver(client, org_id)
    pv = _pvariants(period) if str(period or '').strip() else None
    seen, scan = {}, {}
    for table, col in _UNMATCHED_SRCS:
        rows, narrowed = None, False
        if pv:
            # Try the narrowed read first; a source with no `period` column raises -> scan it whole
            # rather than dropping it (dropping it would understate the answer, which is the exact
            # class of defect this docstring is about).
            try:
                rows = (client.schema('commcalc').table(table).select(col)
                        .eq('org_id', org_id).in_('period', pv)
                        .order('id').limit(_UNMATCHED_SCAN_LIMIT).execute().data) or []
                narrowed = True
            except Exception:
                rows = None
        if rows is None:
            try:
                rows = (client.schema('commcalc').table(table).select(col)
                        .eq('org_id', org_id).order('id')
                        .limit(_UNMATCHED_SCAN_LIMIT).execute().data) or []
            except Exception:
                try:                      # no `id` column to order by -> unordered, still counted
                    rows = (client.schema('commcalc').table(table).select(col)
                            .eq('org_id', org_id).limit(_UNMATCHED_SCAN_LIMIT).execute().data) or []
                except Exception as e:
                    scan[table] = {'rows_scanned': 0, 'truncated': False, 'period_narrowed': False,
                                   'error': str(e)[:200]}
                    continue              # table missing org_id / not present -> skip that source
        scan[table] = {'rows_scanned': len(rows),
                       'truncated': len(rows) >= _UNMATCHED_SCAN_LIMIT,
                       'period_narrowed': narrowed}
        for r in rows:
            v = (r.get(col) or '').strip()
            if not v:
                continue
            e = seen.setdefault(v.lower(), {'raw': v, 'sources': set(), 'per_source': {}})
            e['sources'].add(table)
            e['per_source'][table] = e['per_source'].get(table, 0) + 1
    unmatched = []
    for e in seen.values():
        res = resolve(e['raw'])
        if not res or res.lower() not in canon:
            # `counts`/`per_source` turn "this store is unmapped" into "this store is unmapped and it
            # is 6 rows in raw_sales" — the difference between a spelling to alias and a mis-filed
            # tenant to escalate.
            unmatched.append({'raw': e['raw'], 'sources': sorted(e['sources']), 'guess': res,
                              'counts': sum(e['per_source'].values()),
                              'per_source': dict(sorted(e['per_source'].items()))})
    unmatched.sort(key=lambda x: x['raw'].lower())
    return {'unmatched': unmatched, 'unmatched_count': len(unmatched),
            'matched_distinct': len(seen) - len(unmatched),
            'sources_scanned': [s[0] for s in _UNMATCHED_SRCS],
            'period': (period or None), 'scan': scan,
            'scan_truncated': sorted(t for t, d in scan.items() if d.get('truncated'))}


def _compute_gp(client, org_id, period, market=""):
    """The Gross-Profit engine call, factored out so BOTH GET /gp/{period} and the Trends gp-trend can
    use it. Returns the full result; pass `market` to filter store_rows. Same narrowed selects as before."""
    pv = _pvariants(period)
    sc = client.schema('commcalc')
    # `voided` + `trans_type` are selected ONLY so the GP bucket-composition transparency map can apply the
    # canonical skip rules (Gate-1 follow-up ⑦). The money columns (acc_gp / phone_sales / plan_gp / other_gp
    # / net_profit) do NOT read them and are byte-identical. Defensive fallback to the pre-⑦ select so a
    # tenant/table without those columns can never break the GP page (composition then counts every line,
    # exactly as it did before).
    _sales_cols = 'store,department,category,gp,product_desc,ext_price,salesperson,product_id,sku,voided,trans_type'
    try:
        sales  = sc.table('raw_sales').select(_sales_cols).eq('org_id', org_id).in_('period', pv).limit(50000).execute().data or []
    except Exception as _sce:
        print(f'WARN gp sales select fell back (no voided/trans_type columns?): {_sce}')
        sales  = sc.table('raw_sales').select('store,department,category,gp,product_desc,ext_price,salesperson,product_id,sku').eq('org_id', org_id).in_('period', pv).limit(50000).execute().data or []
    pay_detail = sc.table('raw_payment_detail').select('business_address,amount,payment_type').eq('org_id', org_id).in_('period', pv).limit(50000).execute().data or []
    # VidaPay/MA fallback for the carrier-income columns (owner 2026-07-29: "the commission received
    # should be in commission column"). ePay-less orgs (Total/luxelink — raw_payment_detail EMPTY for the
    # period) fall through to the MA sources, mirroring the P&L's owner-approved fallback (account/coa.py):
    # commission received = raw_ma_commission (sign-flipped Σ _MA_COMPONENTS; positive = dealer receives)
    # → the COMMISSION column; airtime margin = raw_ma_daily_tx.merchant_discount → the ATU column. MA rows
    # carry no store address, so calc_gp_report books the money on ONE company-wide row (same posture as
    # the P&L). House/Boost: pay_detail non-empty → never fires; both MA tables empty → None → identical.
    ma_income = None
    if not pay_detail:
        _ma_comm = _ma_atu = 0.0
        try:
            from app.modules.account.residual_subs import _MA_COMPONENTS as _MACOMP
            _mrows = sc.table('raw_ma_commission').select(','.join(_MACOMP)).eq('org_id', org_id) \
                .in_('period', pv).limit(100000).execute().data or []
            _ma_comm = -sum(sum(safe_float(x.get(c)) for c in _MACOMP) for x in _mrows)
        except Exception:
            _ma_comm = 0.0
        try:
            _drows = sc.table('raw_ma_daily_tx').select('merchant_discount').eq('org_id', org_id) \
                .in_('period', pv).limit(100000).execute().data or []
            _ma_atu = sum(safe_float(x.get('merchant_discount')) for x in _drows)
        except Exception:
            _ma_atu = 0.0
        if _ma_comm or _ma_atu:
            ma_income = {'comm': round(_ma_comm, 2), 'atu': round(_ma_atu, 2)}
            # Commission-LEG split (owner 2026-08-04): the leg is the COLUMN NAME on the MA feed
            # (spiff_m1 = 1st month, spiff_m2..m6 = trailing). Hand the GP engine the PER-COMPONENT
            # sums plus the exact component list `_ma_comm` was built from, so the split re-sums to
            # `comm` by construction instead of being re-derived from a second query.
            try:
                ma_income['components'] = {c: sum(safe_float(x.get(c)) for x in _mrows)
                                           for c in _MACOMP}
                ma_income['component_list'] = list(_MACOMP)
            except Exception:
                pass
    # `mi_activation_date` is selected ONLY so the commission-LEG split can tell 1st-month residual
    # (subscriber activated THIS month) from M2–M12 residual. The mi/atu money columns do not read it
    # and are byte-identical. Falls back to the pre-split select if the column is absent (pre-mig-021
    # raw_mi), in which case every residual dollar is honestly reported as 'unsplit'.
    try:
        mi_rows = sc.table('raw_mi').select('salesforce_id,actual_mi_payout,actual_atu_payout,mi_activation_date').eq('org_id', org_id).in_('period', pv).execute().data or []
    except Exception as _mie:
        print(f'WARN gp raw_mi select fell back (no mi_activation_date column?): {_mie}')
        mi_rows = sc.table('raw_mi').select('salesforce_id,actual_mi_payout,actual_atu_payout').eq('org_id', org_id).in_('period', pv).execute().data or []
    rep_comms  = sc.table('rep_commissions').select('store,total_payout,epay_salesperson,storeops_name').eq('org_id', org_id).in_('period', pv).execute().data or []
    expenses   = sc.table('store_expenses').select('store_code,amount').eq('org_id', org_id).in_('period', pv).execute().data or []
    # Wide select so the cost map can key on the TOTAL variant's UPC/SKU/desc (migs 230/231); high limit so
    # a multi-thousand-row catalog isn't truncated at the PostgREST default. Falls back to the legacy
    # product_id,cost select when the TOTAL columns don't exist yet (pre-230) → house byte-identical.
    try:
        catalog    = sc.table('raw_catalog').select('product_id,cost,upc,sku,product_desc').eq('org_id', org_id).limit(100000).execute().data or []
    except Exception:
        catalog    = sc.table('raw_catalog').select('product_id,cost').eq('org_id', org_id).limit(100000).execute().data or []
    store_map  = sc.table('store_mapping').select('store_address,salesforce_id,market,store_code,is_active').eq('org_id', org_id).execute().data or []
    pay_cats   = sc.table('payment_categories').select('description,category').eq('org_id', org_id).execute().data or []
    comp_rows  = sc.table('raw_comp_report').select('business_address,compensation_type,payment_amount').eq('org_id', org_id).in_('period', pv).limit(50000).execute().data or []
    cat_map    = {r['description'].strip(): r['category'] for r in pay_cats if r.get('description')}
    for r in pay_detail:
        pt = str(r.get('payment_type', '') or '').strip()
        r['category'] = cat_map.get(pt, 'Unknown')
    try:   # per-tenant department→GP-category overrides (mig 069); empty/missing = built-in Boost buckets
        gp_cat_map = sc.table('gp_category_map').select('department,category').eq('org_id', org_id).execute().data or []
    except Exception:
        gp_cat_map = []
    # Config-driven GP bucket classification (mig 250 apply_to_gp; owner 2026-07-29: "accessory sales
    # should be in accessory column"). OPT-IN per org: when the tenant ticked "use these rules for the
    # GP report" (Classification settings), accessory lines classify via the SAME rule the Sales Report
    # uses (_is_accessory — feeds like luxelink's are ambiguous by department alone; Category is the
    # discriminator) and device lines via the org's BOX departments. Default false / pre-mig-250 →
    # config_classify None → the legacy department-only classifier, byte-identical.
    config_classify = None
    try:
        _acfg = _accessory_config(client, org_id)
        if _acfg.get('apply_to_gp'):
            config_classify = {
                'is_accessory': (lambda r, _a=_acfg: _is_accessory(
                    r.get('department'), r.get('category'), r.get('product_desc'), _a)),
                'box_departments': _acfg.get('box_departments') or set(),
            }
    except Exception:
        config_classify = None
    # Universal store-code resolution (store_mapping → storeops roster → explicit store_aliases) so a
    # tenant with NO commcalc.store_mapping (e.g. luxelink) still attaches its configured store_expenses,
    # which are keyed by the org's storeops store_code. House byte-identical (store_mapping populated →
    # calc_gp_report's own street-number join yields the code and the fallback never fires).
    _resolve_code = _store_code_resolver(client, org_id)
    # Commission-LEG attribution (owner 2026-08-04) — 1st month vs M2–M12. Config-resolved per (org,
    # carrier mode) exactly like every other carrier-shaped rule here; NEVER raises, so a tenant whose
    # mig-274 tables are absent simply gets the seeded code defaults and the report is unchanged apart
    # from the new split columns.
    try:
        _legcls = _commission_legs.for_org(
            client, org_id,
            carrier_mode=_resolve_carrier_mode(
                sc.table('carrier').select('*').eq('org_id', org_id).execute().data or []))
    except Exception as _lge:
        print(f'WARN gp commission-leg config fell back to code defaults: {_lge}')
        _legcls = _commission_legs.default_classifier()
    result = calc_gp_report(sales, pay_detail, mi_rows, rep_comms, expenses, catalog, store_map, period,
                            comp_rows=comp_rows, gp_category_map=gp_cat_map, resolve_store_code=_resolve_code,
                            config_classify=config_classify, ma_income=ma_income, leg_classify=_legcls)
    if market:
        result['store_rows'] = [r for r in result['store_rows'] if r.get('market', '').upper() == market.upper()]
    return result


def _gp_snapshot_rows(result):
    return [{'store': r.get('store'), 'store_code': r.get('store_code'), 'market': r.get('market'),
             'total_rev': r.get('total_rev'), 'net_profit': r.get('net_profit')}
            for r in (result.get('store_rows') or [])]


def _write_gp_snapshot(client, org_id, period, result):
    """Cache per-period GP totals for the Trends hub (best-effort; never breaks the report)."""
    try:
        client.schema('commcalc').table('gp_snapshot').upsert(
            {'org_id': org_id, 'period': period, 'store_rows': _gp_snapshot_rows(result),
             'computed_at': _datetime.now(_timezone.utc).isoformat()},
            on_conflict='org_id,period').execute()
    except Exception as e:
        print(f"WARN gp_snapshot upsert failed (run migration 102?): {e}")


@router.get("/gp/{period}")
async def get_gp_report(period: str, view: str = "store", market: str = "", authorization: str = Header(default=""), org_id: str = "00000000-0000-0000-0000-000000000001"):
    client = sb()
    result = _compute_gp(client, org_id, period, market="")   # full (unfiltered) so the snapshot is complete
    _write_gp_snapshot(client, org_id, period, result)   # snapshot stays company-complete
    # Per-store NET PROFIT target (default $10,000) + attainment (mig 855). Defaults to 10000 when the
    # column isn't applied yet, so the goal + attainment show immediately.
    try:
        _st = (client.schema("storeops").table("stores").select("store_code,net_profit_target")
               .eq("org_id", org_id).limit(50000).execute().data) or []
        _tgt = {str(s.get("store_code")): s.get("net_profit_target") for s in _st}
    except Exception:
        _tgt = {}
    for r in (result.get("store_rows") or []):
        try:
            t = float(_tgt.get(str(r.get("store_code"))))
        except (TypeError, ValueError):
            t = 10000.0
        r["net_profit_target"] = t
        r["net_profit_attainment"] = (round((r.get("net_profit") or 0) / t, 3) if t else None)
    from app.modules.storeops.router import scope_keyset, in_keyset
    ks = scope_keyset(authorization, org_id)   # None = unrestricted (admin / rbac off)
    if ks is not None:
        result = {**result, 'store_rows': [r for r in result['store_rows'] if in_keyset(ks, r.get('store'), r.get('store_code'), r.get('address'))]}
    if market:
        result = {**result, 'store_rows': [r for r in result['store_rows'] if r.get('market', '').upper() == market.upper()]}
    return result


# ═══ TRENDS (month-over-month) — power the Trends hub + per-report charts ═════════════════════════
def _tperiods(periods_present, months):
    """Sort present 'Month YYYY' periods chronologically; keep the most recent `months`."""
    kept = sorted({(p or '').strip() for p in periods_present if p},
                  key=lambda p: (parse_period(p)['year'], parse_period(p)['month']))
    return kept[-months:] if months and months > 0 else kept


def _trend_shape(kept, by_store, comp, mkt, value_keys):
    """Assemble the common trend response from per-(store,period) values."""
    stores = []
    for code, per in by_store.items():
        series = [{'period': p, **{k: round((per.get(p) or {}).get(k, 0.0), 2) for k in value_keys}} for p in kept]
        stores.append({'store': code, 'store_code': code, 'market': mkt.get(code, ''), 'series': series})
    sort_key = value_keys[0]
    stores.sort(key=lambda x: -sum(s[sort_key] for s in x['series']))
    company = [{'period': p, **{k: round(comp[p].get(k, 0.0), 2) for k in value_keys}} for p in kept]
    return stores, company


@router.get("/expenses-trend")
def expenses_trend(months: int = 6, org_id: str = ORG_ID):
    """Total store expenses per month, per store (+ company total). Cheap (store_expenses only)."""
    require_org(org_id)
    sc = sb().schema('commcalc')
    rows = sc.table('store_expenses').select('period,store_code,amount').eq('org_id', org_id).limit(200000).execute().data or []
    sm = sc.table('store_mapping').select('store_code,market').eq('org_id', org_id).execute().data or []
    mkt = {str(s.get('store_code') or '').strip(): (s.get('market') or '') for s in sm}
    kept = _tperiods({r.get('period') for r in rows}, months); ks = set(kept)
    by, comp = {}, {p: {'total': 0.0} for p in kept}
    for r in rows:
        p = (r.get('period') or '').strip()
        if p not in ks:
            continue
        code = str(r.get('store_code') or '').strip()
        amt = safe_float(r.get('amount'))
        by.setdefault(code, {}).setdefault(p, {'total': 0.0})
        by[code][p]['total'] += amt
        comp[p]['total'] += amt
    stores, company = _trend_shape(kept, by, comp, mkt, ['total'])
    return {'months': kept, 'company': company, 'stores': stores,
            'markets': sorted({s['market'] for s in stores if s['market']}), 'money': True}


@router.get("/commission-trend")
def commission_trend(months: int = 6, org_id: str = ORG_ID):
    """Commission WE PAY (Σ rep_commissions.total_payout) per month, per store (+ company total)."""
    require_org(org_id)
    import re as _re
    sc = sb().schema('commcalc')
    comms = sc.table('rep_commissions').select('period,store,total_payout').eq('org_id', org_id).limit(200000).execute().data or []
    sm = sc.table('store_mapping').select('store_code,store_address,market').eq('org_id', org_id).execute().data or []

    def _num(a):
        m = _re.match(r'\s*(\d+)', str(a or ''))
        return m.group(1) if m else ''

    code_by_num, mkt, codes = {}, {}, set()
    for s in sm:
        code = str(s.get('store_code') or '').strip()
        if code:
            codes.add(code); mkt[code] = s.get('market') or ''
        n = _num(s.get('store_address'))
        if n and code:
            code_by_num.setdefault(n, code)
    kept = _tperiods({r.get('period') for r in comms}, months); ks = set(kept)
    by, comp = {}, {p: {'total': 0.0} for p in kept}
    for r in comms:
        p = (r.get('period') or '').strip()
        if p not in ks:
            continue
        pay = safe_float(r.get('total_payout'))
        comp[p]['total'] += pay
        st = str(r.get('store') or '').strip()
        code = st if st in codes else code_by_num.get(_num(st))
        if code:
            by.setdefault(code, {}).setdefault(p, {'total': 0.0})
            by[code][p]['total'] += pay
    stores, company = _trend_shape(kept, by, comp, mkt, ['total'])
    return {'months': kept, 'company': company, 'stores': stores,
            'markets': sorted({s['market'] for s in stores if s['market']}), 'money': True}


@router.get("/gp-trend")
def gp_trend(months: int = 6, compute_missing: int = 3, org_id: str = ORG_ID):
    """Revenue + Net Profit per month, per store (+ company total), from the gp_snapshot cache. Computes
    up to `compute_missing` newest un-cached months inline (then caches them) so the hub fills in over a
    few loads without recomputing 40k rows every time; older un-cached months are reported in pending_months."""
    require_org(org_id)
    client = sb(); sc = client.schema('commcalc')
    try:
        snaps = {r['period']: (r.get('store_rows') or []) for r in
                 (sc.table('gp_snapshot').select('period,store_rows').eq('org_id', org_id).execute().data or [])}
    except Exception:
        snaps = {}   # migration 102 not run yet
    cand = set(snaps.keys())
    for t in ('store_expenses', 'rep_commissions'):
        for r in (sc.table(t).select('period').eq('org_id', org_id).limit(200000).execute().data or []):
            if r.get('period'):
                cand.add(r['period'].strip())
    kept = _tperiods(cand, months)
    missing = [p for p in kept if p not in snaps]
    for p in list(reversed(missing))[:max(0, compute_missing)]:
        try:
            res = _compute_gp(client, org_id, p, market="")
            _write_gp_snapshot(client, org_id, p, res)
            snaps[p] = _gp_snapshot_rows(res)
        except Exception as e:
            print(f"WARN gp-trend compute {p} failed: {e}")
    mkt, by, comp = {}, {}, {p: {'total_rev': 0.0, 'net_profit': 0.0} for p in kept}
    for p in kept:
        for r in snaps.get(p, []):
            code = str(r.get('store_code') or r.get('store') or '').strip()
            if not code:
                continue
            mkt.setdefault(code, r.get('market') or '')
            by.setdefault(code, {})[p] = {'total_rev': safe_float(r.get('total_rev')),
                                          'net_profit': safe_float(r.get('net_profit'))}
            comp[p]['total_rev'] += safe_float(r.get('total_rev'))
            comp[p]['net_profit'] += safe_float(r.get('net_profit'))
    stores, company = _trend_shape(kept, by, comp, mkt, ['net_profit', 'total_rev'])
    pending = [p for p in kept if p not in snaps]
    return {'months': kept, 'company': company, 'stores': stores,
            'markets': sorted({s['market'] for s in stores if s['market']}), 'money': True,
            'pending_months': pending,
            'note': (f"{len(pending)} month(s) not yet computed — open the Gross Profit report for them, or reload to compute a few more." if pending else None)}


# ═══ GP / P&L department → category map (de-hardcode Gross Profit, mig 069) ══════════════════════
@router.get("/gp-category-map")
def get_gp_category_map(org_id: str = ORG_ID):
    """The tenant's POS department → GP-category overrides. Empty/un-migrated = built-in Boost buckets
    (device = Android/IPHONE/TABLET-XP at ext_price, accessory = Ondigo, blank = plan, else = other)."""
    from app.modules.commcalc.gp_report import DEVICE_DEPTS, ONDIGO_DEPT, GP_CATEGORIES
    try:
        rows = sb().schema('commcalc').table('gp_category_map').select('*').eq('org_id', org_id).order('department').execute().data or []
        ready = True
    except Exception:
        rows, ready = [], False
    return {"rows": rows, "ready": ready, "categories": sorted(GP_CATEGORIES),
            "defaults": {"device": sorted(DEVICE_DEPTS), "accessory": [ONDIGO_DEPT]}}


class SetGpCategoryMapIn(LaxModel):
    department: Any = None
    category: str = ""


@router.post("/gp-category-map")
def set_gp_category_map(body: SetGpCategoryMapIn, org_id: str = ORG_ID):
    """Upsert ONE department→category override. body: {department, category}. An empty category REMOVES
    the override (reverts to the built-in default). 400 (not 500) if migration 069 isn't applied."""
    if 'department' not in body.model_fields_set:
        raise HTTPException(400, "department required")
    dept = str(body.department or '').strip()
    cat = str(body.category or '').strip().lower()
    try:
        if not cat:
            sb().schema('commcalc').table('gp_category_map').delete() \
                .eq('org_id', org_id).eq('department', dept).execute()
            # The map feeds _accessory_config's accessory DEPARTMENTS — drop the memoized config AFTER the
            # write; the generation bump inside invalidate() also makes a read that raced us discard its
            # own cache_put instead of resurrecting the pre-write answer (Gate-1 ② + rework finding 2).
            _invalidate_accessory_config(org_id)
            return {"ok": True, "removed": dept}
        sb().schema('commcalc').table('gp_category_map').upsert(
            {"org_id": org_id, "department": dept, "category": cat,
             "updated_at": _datetime.now(_timezone.utc).isoformat()},
            on_conflict="org_id,department").execute()
        _invalidate_accessory_config(org_id)
    except Exception as e:
        raise HTTPException(400, f"Could not save — run migration 069_gp_category_map.sql first. [{e}]")
    return {"ok": True, "department": dept, "category": cat}


@router.get("/gp-departments")
def get_gp_departments(period: str = "", org_id: str = ORG_ID):
    """Distinct POS department labels in raw_sales (optionally for a period) with their line count and
    CURRENT GP category — so the tenant can see + map every real label. Drives the GP Category Map UI."""
    from collections import Counter
    from app.modules.commcalc.gp_report import _dept_classifier
    sc = sb().schema('commcalc')
    q = sc.table('raw_sales').select('department').eq('org_id', org_id)
    if period:
        q = q.in_('period', _pvariants(period))
    rows = q.limit(50000).execute().data or []
    cnt = Counter(str(r.get('department') or '').strip() for r in rows)
    try:
        omap = (sc.table('gp_category_map').select('department,category').eq('org_id', org_id).execute().data) or []
    except Exception:
        omap = []
    mapped_keys = {str(r.get('department') or '').strip() for r in omap}
    classify = _dept_classifier(omap)
    out = [{"department": d, "count": n, "category": classify(d), "mapped": d in mapped_keys}
           for d, n in sorted(cnt.items(), key=lambda kv: -kv[1])]
    return {"departments": out}


# ═══ COMMISSION LEGS — 1st month vs M2–M12 (owner directive 2026-08-04) ══════════════════════════
# READ-ONLY. These endpoints DECOMPOSE commission money already received; none of them writes a payout,
# a rate, a tier or a calc input. `commcalc/commission_legs.py` holds the (pure) attribution rules and
# `commcalc.commission_leg_config` / `commission_leg_label_map` (mig 274) hold the per-org config.

def _ma_summary_legs(client, org_id, comps):
    """1st-month / M2–M12 split of a master-agent commission roll-up, from the SAME component sums the
    roll-up's own `total_payable` is built from — so the two can never disagree. Never raises."""
    try:
        res = _org_leg_classifier(client, org_id).ma(comps, _MA_LEG_COMPONENTS)
        total = round(-sum(safe_float(comps.get(c)) for c in _MA_LEG_COMPONENTS), 2)
        return {"m1": res["buckets"]["m1"], "m2_12": res["buckets"]["trailing"],
                "unsplit": res["buckets"]["unsplit"], "total": total,
                "ladder": res["leg_ladder"],
                "identity_ok": abs(round(sum(res["buckets"].values()), 2) - total) < 0.01,
                "unsplit_fields": res.get("unsplit_fields") or [],
                "basis": ("1st Month = spiff_m1; M2–M12 = spiff_m2…m6 — the leg is the column name on "
                          "the MA Commission Details export. The activation-order margins "
                          "(rebate / device / consumer / financing / wallet funding / fees) are NOT "
                          "commission legs (owner 2026-08-04) — they are in the total but sit in "
                          "Unsplit, which is why 1st Month here equals the portal's Commissions Paid.")}
    except Exception as e:
        return {"m1": 0.0, "m2_12": 0.0, "unsplit": 0.0, "total": 0.0, "ladder": {},
                "identity_ok": False, "basis": f"leg split unavailable ({e})"}


def _org_leg_classifier(client, org_id):
    """The org's ONE commission-leg classifier (1st month vs M2–M12), resolved per carrier mode.
    NEVER raises — a tenant without migration 274 gets the seeded code defaults."""
    try:
        return _commission_legs.for_org(
            client, org_id,
            carrier_mode=_resolve_carrier_mode(
                client.schema('commcalc').table('carrier').select('*')
                .eq('org_id', org_id).execute().data or []))
    except Exception:
        return _commission_legs.default_classifier()


# The raw_ma_commission money components the org's MA commission total is built from. Imported from
# the finance module's ONE definition so the leg split can never iterate a different column set than
# the total it is decomposing (a mismatch there is exactly how a "split" stops adding up); the literal
# is only a last-resort fallback if that import ever moves.
try:
    from app.modules.account.residual_subs import _MA_COMPONENTS as _MA_LEG_COMPONENTS
except Exception:                                                          # pragma: no cover
    _MA_LEG_COMPONENTS = ["device_margin", "consumer_margin", "consumer_financing", "rebate",
                          "wallet_funding", "fees_margin",
                          "spiff_m1", "spiff_m2", "spiff_m3", "spiff_m4", "spiff_m5", "spiff_m6"]


def _leg_window(period, months):
    """The last `months` month-labels ending at `period`, oldest first. The window is anchored on the
    page's OWN period (RULE FIVE: the period filter drives everything) instead of on 'the latest row in
    the table', so the trend is deterministic and needs no distinct-period scan of a 360k-row table."""
    try:
        months = max(1, min(int(months or 12), 36))
    except (TypeError, ValueError):
        months = 12
    try:                       # parse_period raises on an empty/short string — never 500 the page
        pm = parse_period(period or "")
    except Exception:
        pm = {}
    y, m = pm.get("year") or 0, pm.get("month") or 0
    if not (y and m):
        n = _datetime.now(_timezone.utc)
        y, m = n.year, n.month
    idx = y * 12 + (m - 1)
    out = []
    for k in range(months - 1, -1, -1):
        i = idx - k
        out.append(f"{_calendar.month_name[i % 12 + 1]} {i // 12}")
    return out


def _leg_period_key(labels):
    """{any spelling of a month in `labels`: its canonical 'Month YYYY' label}."""
    key = {}
    for lab in labels:
        for v in _pvariants(lab):
            key[v] = lab
    return key


def _leg_comp_is_commission(label):
    """The Comprehensive Comp bucketing rule, IDENTICAL to gp_report's (reimbursement/rebate -> Re-imb,
    mdf -> MDF, everything else -> Comm) so the trend explains the same money the GP column shows."""
    ct = str(label or "").lower()
    return not ("reimbursement" in ct or "rebate" in ct or "mdf" in ct)


def _leg_store_index(client, org_id):
    """{street number: {'store','store_code','market'}} for attributing carrier money to a store — the
    SAME street-number join gp_report.calc_gp_report uses, so the trend's store/market filter selects
    exactly the rows the GP table would."""
    idx = {}
    try:
        rows = (client.schema('commcalc').table('store_mapping')
                .select('store_address,store_code,market,salesforce_id')
                .eq('org_id', org_id).execute().data) or []
    except Exception:
        rows = []
    by_sfid = {}
    for s in rows:
        addr = str(s.get('store_address') or '').strip()
        num = addr.split(' ')[0] if addr else ''
        ent = {'store': addr, 'store_code': str(s.get('store_code') or '').strip(),
               'market': str(s.get('market') or '').strip()}
        if num:
            idx.setdefault(num, ent)
        sf = str(s.get('salesforce_id') or '').strip()
        if sf:
            by_sfid.setdefault(sf, ent)
    return idx, by_sfid


def _leg_passes(ent, markets, stores):
    """RULE FIVE filter test. No filters = everything passes. An UNMAPPED carrier row (no store match)
    passes only when no store/market filter is active — it cannot be claimed for a specific store."""
    if not markets and not stores:
        return True
    if not ent:
        return False
    if markets and (ent.get('market') or '').upper() not in markets:
        return False
    if stores and not any(s and (s in (ent.get('store') or '') or s == ent.get('store_code'))
                          for s in stores):
        return False
    return True


def _leg_blank_period(label):
    return {'period': label, 'm1': 0.0, 'm2_12': 0.0, 'unsplit': 0.0, 'total': 0.0,
            'ladder': {}, 'sources': {}}


@router.get("/commission-leg-trend")
def commission_leg_trend(period: str = "", months: int = 12, market: str = "", store: str = "",
                               org_id: str = ORG_ID):
    """Month-over-month decomposition of RECEIVED commission into the 1st-month leg vs the M2–M12
    trailing legs, plus the per-month-of-life LADDER that makes the owner's 3MR/6MR question answerable.

    WHAT THIS SHOWS (stated verbatim on the page so nobody has to guess):
      • "1st Month" = commission received in the SAME month the number activated.
      • "M2–M12"    = commission received for a number that activated in an EARLIER month.
      • The ladder  = the same money split by the leg's month-of-life (M1, M2, M3 …). Boost's bounties
        pay a Month-1..Month-6 ladder and a leg only lands if the subscriber survived that month, so
        legs 2–3 ARE the money 3-month retention produced and legs 4–6 the 6-month tail. That is the
        alignment the owner asked for; the DLAR 3MR KPI is overlaid when the org has it.

    Money source = exactly the GP report's Commission column: raw_payment_detail rows whose payment
    type maps to the 'Commission' payment category, plus (for ePay-less orgs, on the same emptiness
    gate _compute_gp uses) the VidaPay/MA commission components. Comprehensive Comp is returned
    alongside as its own series, never added in — the GP report keeps them as separate columns.
    """
    require_org(org_id)
    client = sb(); sc = client.schema('commcalc')
    labels = _leg_window(period, months)
    pkey = _leg_period_key(labels)
    variants = sorted(pkey.keys())
    markets = {m.strip().upper() for m in (market or '').split(',') if m.strip()}
    stores = [s.strip() for s in (store or '').split(',') if s.strip()]

    try:
        legcls = _commission_legs.for_org(
            client, org_id,
            carrier_mode=_resolve_carrier_mode(
                sc.table('carrier').select('*').eq('org_id', org_id).execute().data or []))
    except Exception:
        legcls = _commission_legs.default_classifier()
    store_idx, sfid_idx = _leg_store_index(client, org_id)

    out = {lab: _leg_blank_period(lab) for lab in labels}
    comp_series = {lab: _leg_blank_period(lab) for lab in labels}
    notes, degraded = [], False

    # ── 1. label rollup (payment detail + comp report) — one aggregate round trip ────────────────
    rows, used_rpc = [], True
    try:
        rows = (client.schema('commcalc')
                .rpc('commission_leg_label_rollup', {'p_org_id': org_id, 'p_periods': variants})
                .execute().data) or []
    except Exception as e:
        used_rpc = False
        degraded = True
        print(f'WARN commission_leg_label_rollup RPC unavailable ({e}) — per-month fallback')
        cap = min(len(labels), 3)
        notes.append(f'Migration 274 not applied yet — the aggregate is being computed month by month, '
                     f'so only the most recent {cap} month(s) are shown. Run 274 for the full window.')
        try:
            cat_map = {str(r['description']).strip(): r['category']
                       for r in (sc.table('payment_categories').select('description,category')
                                 .eq('org_id', org_id).execute().data or []) if r.get('description')}
        except Exception:
            cat_map = {}
        for lab in labels[-cap:]:
            try:
                pd = (sc.table('raw_payment_detail').select('business_address,payment_type,amount')
                      .eq('org_id', org_id).in_('period', _pvariants(lab)).limit(60000).execute().data) or []
            except Exception:
                pd = []
            for r in pd:
                rows.append({'source': 'payment_detail', 'period': lab,
                             'store_num': str(r.get('business_address') or '').strip().split(' ')[0],
                             'label': str(r.get('payment_type') or '').strip(),
                             'category': cat_map.get(str(r.get('payment_type') or '').strip(), 'Unknown'),
                             'amount': safe_float(r.get('amount')), 'n': 1})

    for r in rows:
        lab = pkey.get(str(r.get('period') or '').strip())
        if not lab:
            continue
        src = str(r.get('source') or '').strip()
        ent = store_idx.get(str(r.get('store_num') or '').strip())
        if not _leg_passes(ent, markets, stores):
            continue
        amt = safe_float(r.get('amount'))
        label = r.get('label')
        if src == 'payment_detail':
            if str(r.get('category') or '').strip() != 'Commission':
                continue
            target = out[lab]
        elif src == 'comp_report':
            if not _leg_comp_is_commission(label):
                continue
            target = comp_series[lab]
        else:
            continue
        bucket, leg, _why = legcls.label(label)
        k = {'m1': 'm1', 'trailing': 'm2_12', 'unsplit': 'unsplit'}[bucket]
        target[k] = round(target[k] + amt, 2)
        target['total'] = round(target['total'] + amt, 2)
        lk = 'unknown' if leg is None else str(int(leg))
        target['ladder'][lk] = round(target['ladder'].get(lk, 0.0) + amt, 2)
        sname = 'ePay Payment Detail' if src == 'payment_detail' else 'Comprehensive Comp'
        target['sources'][sname] = round(target['sources'].get(sname, 0.0) + amt, 2)

    # ── 2. VidaPay / master-agent commission — only for months with NO payment detail, exactly the
    #      emptiness gate _compute_gp uses, so the two surfaces can never double-count the same month.
    ma_rows = []
    try:
        ma_rows = (client.schema('commcalc')
                   .rpc('commission_leg_ma_rollup', {'p_org_id': org_id, 'p_periods': variants})
                   .execute().data) or []
    except Exception:
        if used_rpc:
            for lab in labels:
                try:
                    mr = (sc.table('raw_ma_commission').select('*').eq('org_id', org_id)
                          .in_('period', _pvariants(lab)).limit(100000).execute().data) or []
                except Exception:
                    mr = []
                if mr:
                    agg = {'period': lab}
                    for c in _MA_LEG_COMPONENTS:
                        agg[c] = sum(safe_float(x.get(c)) for x in mr)
                    ma_rows.append(agg)
    if ma_rows and (markets or stores):
        notes.append('VidaPay/master-agent commission carries no store address, so it is company-wide '
                     'and is EXCLUDED while a store or market filter is active.')
    for r in ma_rows:
        lab = pkey.get(str(r.get('period') or '').strip())
        if not lab or (markets or stores):
            continue
        if out[lab]['sources'].get('ePay Payment Detail'):
            continue                      # this month is an ePay month — MA is the ePay-less fallback
        res = legcls.ma(r, _MA_LEG_COMPONENTS)
        b = res['buckets']
        out[lab]['m1'] = round(out[lab]['m1'] + b['m1'], 2)
        out[lab]['m2_12'] = round(out[lab]['m2_12'] + b['trailing'], 2)
        out[lab]['unsplit'] = round(out[lab]['unsplit'] + b['unsplit'], 2)
        out[lab]['total'] = round(out[lab]['total'] + res['total'], 2)
        for lk, lv in (res.get('leg_ladder') or {}).items():
            k = 'unknown' if lk == 'unknown' else str(int(lk))
            out[lab]['ladder'][k] = round(out[lab]['ladder'].get(k, 0.0) + lv, 2)
        out[lab]['sources']['VidaPay/MA'] = round(
            out[lab]['sources'].get('VidaPay/MA', 0.0) + res['total'], 2)

    # ── 3. DLAR 3MR overlay (optional) — the ONE retention KPI this codebase actually has ────────
    tmr3 = {}
    try:
        dl = (sc.table('raw_dlar_rep').select('period,tmr3').eq('org_id', org_id)
              .limit(200000).execute().data) or []
        acc = {}
        for r in dl:
            lab = pkey.get(str(r.get('period') or '').strip())
            v = safe_float(r.get('tmr3'))
            if lab and v:
                a = acc.setdefault(lab, [0.0, 0])
                a[0] += v; a[1] += 1
        tmr3 = {k: round(v[0] / v[1], 1) for k, v in acc.items() if v[1]}
    except Exception:
        tmr3 = {}

    series = []
    for lab in labels:
        d = out[lab]
        tot = d['total']
        series.append({**d,
                       'm2_12_pct': round(d['m2_12'] / tot * 100, 1) if tot else 0.0,
                       'tmr3': tmr3.get(lab)})
    ladder_months = sorted({int(k) for d in series for k in d['ladder'] if k != 'unknown'})

    return {
        'months': labels,
        'company': series,
        'comp_series': [comp_series[l] for l in labels],
        'ladder_months': ladder_months,
        'has_unknown_leg': any('unknown' in d['ladder'] for d in series),
        'config': legcls.describe(),
        'notes': notes,
        'degraded': degraded,
        'money': True,
        'basis': ('Commission RECEIVED, same money as the Gross Profit report\'s Commission column. '
                  '1st Month = received in the month the number activated; M2–M12 = received later for '
                  'an already-activated number. The ladder splits the same money by the leg\'s '
                  'month-of-life (M1, M2, M3 …) — legs 2–3 are what 3-month retention pays, legs 4–6 '
                  'the 6-month tail.'),
        'retention_note': ('3MR here is the DLAR rep-average 3-month-retention KPI (raw_dlar_rep.tmr3) — '
                           'the only retention KPI this system stores. There is no stored 6MR KPI; the '
                           'M4–M6 rungs of the ladder are the payout-side view of 6-month retention.'),
    }


@router.get("/commission-leg-labels")
def commission_leg_labels(period: str = "", months: int = 6, org_id: str = ORG_ID):
    """Every carrier payment/compensation label the org's data actually contains, with the $ behind it,
    how it is CURRENTLY attributed and why — the pick-don't-type source for the Commission Legs admin
    page (§3b: you map a label that exists, you never type one)."""
    require_org(org_id)
    client = sb(); sc = client.schema('commcalc')
    labels = _leg_window(period, months)
    pkey = _leg_period_key(labels)
    variants = sorted(pkey.keys())
    try:
        legcls = _commission_legs.for_org(
            client, org_id,
            carrier_mode=_resolve_carrier_mode(
                sc.table('carrier').select('*').eq('org_id', org_id).execute().data or []))
    except Exception:
        legcls = _commission_legs.default_classifier()

    agg, ready = {}, True
    try:
        rows = (client.schema('commcalc')
                .rpc('commission_leg_label_rollup', {'p_org_id': org_id, 'p_periods': variants})
                .execute().data) or []
    except Exception:
        ready = False
        rows = []
        for lab in labels[-1:]:
            try:
                for r in (sc.table('raw_payment_detail').select('payment_type,amount')
                          .eq('org_id', org_id).in_('period', _pvariants(lab))
                          .limit(60000).execute().data) or []:
                    rows.append({'source': 'payment_detail', 'label': str(r.get('payment_type') or '').strip(),
                                 'category': '', 'amount': safe_float(r.get('amount')), 'n': 1})
            except Exception:
                pass
    for r in rows:
        lbl = str(r.get('label') or '').strip()
        if not lbl:
            continue
        e = agg.setdefault(lbl, {'label': lbl, 'amount': 0.0, 'lines': 0, 'sources': set(),
                                 'categories': set()})
        e['amount'] = round(e['amount'] + safe_float(r.get('amount')), 2)
        e['lines'] += int(r.get('n') or 0)
        e['sources'].add(str(r.get('source') or ''))
        if r.get('category'):
            e['categories'].add(str(r.get('category')))

    try:
        overrides = {str(r.get('label') or '').strip().lower(): r
                     for r in (sc.table('commission_leg_label_map').select('*')
                               .eq('org_id', org_id).execute().data or [])}
        map_ready = True
    except Exception:
        overrides, map_ready = {}, False

    out = []
    for e in agg.values():
        bucket, leg, why = legcls.label(e['label'])
        ov = overrides.get(e['label'].lower())
        out.append({'label': e['label'], 'amount': e['amount'], 'lines': e['lines'],
                    'sources': sorted(x for x in e['sources'] if x),
                    'categories': sorted(e['categories']),
                    'bucket': bucket, 'leg_month': leg, 'why': why,
                    'overridden': bool(ov),
                    'override_note': (ov or {}).get('note') or ''})
    out.sort(key=lambda x: (x['bucket'] != 'unsplit', -abs(x['amount']), x['label'].lower()))
    return {'labels': out, 'months': labels, 'rollup_ready': ready, 'map_ready': map_ready,
            'config': legcls.describe(),
            'unsplit_total': round(sum(x['amount'] for x in out if x['bucket'] == 'unsplit'), 2)}


class SetCommissionLegLabelIn(LaxModel):
    label: str = ""
    bucket: str = ""
    leg_month: Any = None
    note: Any = None


@router.post("/commission-leg-labels")
def set_commission_leg_label(body: SetCommissionLegLabelIn, org_id: str = ORG_ID):
    """Map ONE exact carrier label to a leg bucket. bucket '' REMOVES the override (back to the regex).
    Reporting only — this moves a dollar between two REPORT columns, never between two people."""
    require_org(org_id)
    label = str(body.label or '').strip()
    if not label:
        raise HTTPException(400, 'label required')
    bucket = str(body.bucket or '').strip().lower()
    sc = sb().schema('commcalc')
    try:
        if not bucket:
            sc.table('commission_leg_label_map').delete()               .eq('org_id', org_id).eq('label', label).execute()
            return {'ok': True, 'removed': label}
        if bucket not in _commission_legs.BUCKETS:
            raise HTTPException(400, f"bucket must be one of {', '.join(_commission_legs.BUCKETS)}")
        lm = body.leg_month
        row = {'org_id': org_id, 'label': label, 'bucket': bucket,
               'leg_month': int(lm) if str(lm or '').strip().isdigit() else None,
               'note': str(body.note or '').strip() or None,
               'updated_at': _datetime.now(_timezone.utc).isoformat()}
        sc.table('commission_leg_label_map').upsert(row, on_conflict='org_id,label').execute()
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(400, f'Could not save — run migration 274_commission_leg_split.sql first. [{e}]')
    return {'ok': True, 'label': label, 'bucket': bucket}


@router.get("/commission-leg-config")
def get_commission_leg_config(org_id: str = ORG_ID):
    """The org's resolved leg-attribution rules + the raw config rows behind them."""
    require_org(org_id)
    client = sb(); sc = client.schema('commcalc')
    try:
        rows = (sc.table('commission_leg_config').select('*')
                .in_('org_id', [org_id, _commission_legs.ORG_ID]).execute().data) or []
        ready = True
    except Exception:
        rows, ready = [], False
    try:
        mode = _resolve_carrier_mode(sc.table('carrier').select('*').eq('org_id', org_id)
                                     .execute().data or [])
    except Exception:
        mode = 'boost'
    legcls = _commission_legs.for_org(client, org_id, carrier_mode=mode)
    return {'ready': ready, 'rows': rows, 'carrier_mode': mode,
            'resolved': legcls.describe(), 'buckets': list(_commission_legs.BUCKETS)}


class SetCommissionLegConfigIn(LaxModel):
    carrier_mode: Any = None
    label_month_regex: Any = None
    unlabeled_bucket: Any = None
    ma_month_field_prefix: Any = None
    notes: Any = None
    m1_month: Any = None
    max_leg_month: Any = None
    ma_max_month: Any = None
    mi_split_by_activation: Any = None
    ma_m1_fields: Any = None


@router.post("/commission-leg-config")
def set_commission_leg_config(body: SetCommissionLegConfigIn, org_id: str = ORG_ID):
    """Upsert THIS org's mode-default leg-attribution row (carrier_id = nil). Reporting config only."""
    require_org(org_id)
    sc = sb().schema('commcalc')
    mode = str(body.carrier_mode or 'boost').strip().lower() or 'boost'
    row = {'org_id': org_id, 'carrier_id': '00000000-0000-0000-0000-000000000000',
           'carrier_mode': mode, 'is_active': True,
           'updated_at': _datetime.now(_timezone.utc).isoformat()}
    for k in ('label_month_regex', 'unlabeled_bucket', 'ma_month_field_prefix', 'notes'):
        if k in body.model_fields_set and str(getattr(body, k) or '').strip():
            row[k] = str(getattr(body, k)).strip()
    for k in ('m1_month', 'max_leg_month', 'ma_max_month'):
        if k in body.model_fields_set and str(getattr(body, k) or '').strip().isdigit():
            row[k] = int(getattr(body, k))
    if 'mi_split_by_activation' in body.model_fields_set:
        row['mi_split_by_activation'] = bool(body.mi_split_by_activation)
    if isinstance(body.ma_m1_fields, list):
        row['ma_m1_fields'] = [str(x).strip() for x in body.ma_m1_fields if str(x).strip()]
    if row.get('unlabeled_bucket') and row['unlabeled_bucket'] not in _commission_legs.BUCKETS:
        raise HTTPException(400, f"unlabeled_bucket must be one of {', '.join(_commission_legs.BUCKETS)}")
    if row.get('label_month_regex'):
        import re as _re_check
        try:
            _re_check.compile(row['label_month_regex'])
        except _re_check.error as e:
            raise HTTPException(400, f'label_month_regex is not a valid regular expression: {e}')
    try:
        sc.table('commission_leg_config').upsert(row, on_conflict='org_id,carrier_id,carrier_mode').execute()
    except Exception as e:
        raise HTTPException(400, f'Could not save — run migration 274_commission_leg_split.sql first. [{e}]')
    return {'ok': True, 'carrier_mode': mode}


# ═══ COMMISSION RECEIVED — the FULL breakout (owner directive 2026-08-05) ════════════════════════
#   "we need to see what we made in M1 and other months and how much is on ATU and how much is on
#    residual."
# READ-ONLY, and it MOVES NOTHING. Every figure here is a finer split of a figure the Gross Profit
# report already shows: the commission rows re-sum to its Commission column, the MI/ATU rows to its
# MI and ATU columns, and the VidaPay airtime row to its ATU column for an MA-fed org. The pure
# decomposition lives in `commcalc/commission_received.py`; this endpoint only fetches and filters.


def _breakout_tx_rows(client, sc, org_id, variants, labels, pattern, sign, out_notes):
    """Per-period VidaPay daily-tx figures (airtime margin + postpaid residual orders). Migration 278
    RPC first; a BOUNDED per-period read of the most recent 3 months if it has not been run yet, so
    the page degrades to less history instead of to a wrong number. Never raises."""
    try:
        rows = (sc.rpc('commission_received_tx_rollup',
                       {'p_org_id': org_id, 'p_periods': variants,
                        'p_residual_pattern': pattern}).execute().data) or []
        return [{'period': r.get('period'),
                 'airtime_all': safe_float(r.get('airtime_all')),
                 'airtime_residual_orders': safe_float(r.get('airtime_residual_orders')),
                 'residual_orders': safe_float(r.get('residual_orders')) * sign,
                 'n': r.get('n'), 'n_residual': r.get('n_residual')} for r in rows], False
    except Exception as e:
        print(f'WARN commission_received_tx_rollup RPC unavailable ({e}) — bounded fallback')
    pat = str(pattern or '').strip().lower()
    out, cap = [], min(len(labels), 3)
    for lab in labels[-cap:]:
        try:
            tx = (sc.table('raw_ma_daily_tx').select('order_type,merchant_discount,retail_cost')
                  .eq('org_id', org_id).in_('period', _pvariants(lab)).limit(100000).execute().data) or []
        except Exception:
            tx = []
        if not tx:
            continue
        a_all = a_res = r_res = 0.0
        n_res = 0
        for r in tx:
            d = safe_float(r.get('merchant_discount'))
            a_all += d
            if pat and pat in str(r.get('order_type') or '').strip().lower():
                a_res += d
                r_res += safe_float(r.get('retail_cost'))
                n_res += 1
        out.append({'period': lab, 'airtime_all': a_all, 'airtime_residual_orders': a_res,
                    'residual_orders': r_res * sign, 'n': len(tx), 'n_residual': n_res})
    if out:
        out_notes.append(f'Migration 278 not applied yet — the VidaPay airtime / residual-order rows '
                         f'are being summed month by month, so only the most recent {cap} month(s) '
                         f'carry them. Run 278 for the full window.')
    return out, True


@router.get("/commission-received-breakout")
def commission_received_breakout(period: str = "", months: int = 12, market: str = "",
                                       store: str = "", org_id: str = ORG_ID):
    """WHAT DID WE MAKE — 1st Month, M2…M6 individually, ATU, MI/residual, and the unsplit margin
    block — per money stream, per month, over the last `months` months ending at `period`.

    WHAT EACH ROW IS (stated on the page too, so nobody has to guess):
      • Commission received (ePay)      — raw_payment_detail rows in the Commission payment category;
                                          the leg is the month written into the payment type.
      • Commission received (VidaPay)   — raw_ma_commission; the leg is the COLUMN (1st…6th Month
                                          Spiff). The activation-order margins carry no month-of-life
                                          and sit in Unsplit (owner ruling 2026-08-05) — which is why
                                          the M1 figure here equals the portal's Commissions Paid.
      • Comprehensive Comp              — its own column on the GP report; reported beside, never
                                          added into, the Commission total.
      • MI residual / ATU residual      — raw_mi, split by the subscriber's activation date vs the
                                          month the money arrived (migration 274's mi rollup, wired
                                          here for the first time).
      • Airtime margin (VidaPay)        — raw_ma_daily_tx merchant discount; the SAME figure the GP
                                          report's ATU column shows for an MA-fed org.
      • Postpaid Residual Orders        — the /ma-overview-recon + What-If residual basis. A
                                          CROSS-CHECK row, in NO total: see `divergence_note`.

    RULE FIVE: period + store + market drive every figure and therefore every export. Carrier money
    that carries no store address (VidaPay commission, airtime, residual orders) is company-wide and
    is EXCLUDED while a store or market filter is active, which the payload says out loud.

    MONEY-SAFE: no write, no recompute, no rep_commissions read. Nothing here can change a payout.
    """
    require_org(org_id)
    client = sb(); sc = client.schema('commcalc')
    labels = _leg_window(period, months)
    pkey = _leg_period_key(labels)
    variants = sorted(pkey.keys())
    markets = {m.strip().upper() for m in (market or '').split(',') if m.strip()}
    stores = [s.strip() for s in (store or '').split(',') if s.strip()]
    filtered = bool(markets or stores)

    try:
        mode = _resolve_carrier_mode(sc.table('carrier').select('*').eq('org_id', org_id)
                                     .execute().data or [])
    except Exception:
        mode = 'boost'
    try:
        legcls = _commission_legs.for_org(client, org_id, carrier_mode=mode)
    except Exception:
        legcls = _commission_legs.default_classifier()
    store_idx, sfid_idx = _leg_store_index(client, org_id)
    notes, gaps, degraded = [], [], False

    # ── 1. ePay Payment Detail + Comprehensive Comp (mig 274 rollup, bounded fallback) ───────────
    label_rows = []
    try:
        label_rows = (sc.rpc('commission_leg_label_rollup',
                             {'p_org_id': org_id, 'p_periods': variants}).execute().data) or []
    except Exception as e:
        degraded = True
        print(f'WARN commission_leg_label_rollup RPC unavailable ({e}) — bounded fallback')
        cap = min(len(labels), 3)
        notes.append(f'Migration 274 not applied yet — the ePay rows are being summed month by month, '
                     f'so only the most recent {cap} month(s) carry them. Run 274 for the full window.')
        try:
            cat_map = {str(r['description']).strip(): r['category']
                       for r in (sc.table('payment_categories').select('description,category')
                                 .eq('org_id', org_id).execute().data or []) if r.get('description')}
        except Exception:
            cat_map = {}
        for lab in labels[-cap:]:
            try:
                pd = (sc.table('raw_payment_detail').select('business_address,payment_type,amount')
                      .eq('org_id', org_id).in_('period', _pvariants(lab))
                      .limit(60000).execute().data) or []
            except Exception:
                pd = []
            for r in pd:
                pt = str(r.get('payment_type') or '').strip()
                label_rows.append({'source': 'payment_detail', 'period': lab,
                                   'store_num': str(r.get('business_address') or '').strip().split(' ')[0],
                                   'label': pt, 'category': cat_map.get(pt, 'Unknown'),
                                   'amount': safe_float(r.get('amount')), 'n': 1})

    # Months that HAVE ePay payment detail are ePay months: VidaPay commission is the ePay-LESS
    # fallback (the same emptiness gate _compute_gp and /commission-leg-trend use), so adding both
    # for one month would double-count that month's commission across two feeds.
    skip_periods = set()
    for r in label_rows:
        if str(r.get('source') or '') == 'payment_detail' and safe_float(r.get('amount')):
            lab = pkey.get(str(r.get('period') or '').strip())
            if lab:
                skip_periods.add(lab)

    # ── 2. VidaPay / master-agent commission (mig 274 rollup, bounded fallback) ──────────────────
    ma_rows = []
    if not filtered:
        try:
            ma_rows = (sc.rpc('commission_leg_ma_rollup',
                              {'p_org_id': org_id, 'p_periods': variants}).execute().data) or []
        except Exception:
            for lab in labels[-min(len(labels), 3):]:
                try:
                    mr = (sc.table('raw_ma_commission').select('*').eq('org_id', org_id)
                          .in_('period', _pvariants(lab)).limit(100000).execute().data) or []
                except Exception:
                    mr = []
                if mr:
                    agg = {'period': lab, 'n': len(mr)}
                    for c in _MA_LEG_COMPONENTS:
                        agg[c] = sum(safe_float(x.get(c)) for x in mr)
                    ma_rows.append(agg)

    # ── 3. ePay MI/ATU residual — migration 274's rollup, wired here for the FIRST time ──────────
    mi_rows = []
    try:
        mi_rows = (sc.rpc('commission_leg_mi_rollup',
                          {'p_org_id': org_id, 'p_periods': variants}).execute().data) or []
    except Exception as e:
        print(f'WARN commission_leg_mi_rollup RPC unavailable ({e}) — bounded fallback')
        cap = min(len(labels), 3)
        for lab in labels[-cap:]:
            try:
                mr = (sc.table('raw_mi')
                      .select('salesforce_id,actual_mi_payout,actual_atu_payout,mi_activation_date')
                      .eq('org_id', org_id).in_('period', _pvariants(lab))
                      .limit(60000).execute().data) or []
            except Exception:
                mr = []
            for r in mr:
                _b, _leg, _why = legcls.activation(lab, r.get('mi_activation_date'))
                mi_rows.append({'period': lab, 'salesforce_id': str(r.get('salesforce_id') or ''),
                                'leg_month': _leg, 'mi': safe_float(r.get('actual_mi_payout')),
                                'atu': safe_float(r.get('actual_atu_payout')), 'n': 1})
            if mr:
                degraded = True

    # ── 4. VidaPay daily transactions — airtime margin + postpaid residual orders (mig 278) ──────
    tx_rows = []
    if not filtered:
        try:
            _wcfg = whatif._whatif_source_config(client, org_id, None, mode)
        except Exception:
            _wcfg = {}
        _pattern = str(_wcfg.get('residual_order_type') or 'Postpaid Residual Order').strip() \
            or 'Postpaid Residual Order'
        _sign = -1.0 if str(_wcfg.get('residual_sign') or 'negate').strip().lower() == 'negate' else 1.0
        tx_rows, _tx_degraded = _breakout_tx_rows(client, sc, org_id, variants, labels,
                                                  _pattern, _sign, notes)
        degraded = degraded or _tx_degraded

    if filtered:
        notes.append('VidaPay/master-agent money (commission, airtime margin, residual orders) carries '
                     'no store address, so it is company-wide and is EXCLUDED while a store or market '
                     'filter is active.')

    out = _commission_received.build_breakout(
        labels, legcls,
        label_rows=label_rows, ma_rows=ma_rows, mi_rows=mi_rows, tx_rows=tx_rows,
        components=_MA_LEG_COMPONENTS, period_key=pkey,
        passes=lambda num: _leg_passes(store_idx.get(num), markets, stores),
        passes_sfid=lambda sf: _leg_passes(sfid_idx.get(sf), markets, stores),
        comp_is_commission=_leg_comp_is_commission,
        skip_periods=skip_periods, notes=notes, gaps=gaps, degraded=degraded)

    # WHAT IS MISSING, NAMED. An empty row is either "this tenant does not use that feed" (correct
    # isolation) or "that report was never ingested" (a real gap) — the page must not leave the owner
    # guessing which. Only report a gap for a feed this tenant's CARRIER MODE actually expects.
    present = {s['key'] for s in out['streams']}
    expect = ({'comm_ma': ('MA Commission Details (VidaPay) — Commission by month',
                           'Data Imports → ma_commission, or the ⬆ on /commcalc/ma-upload'),
               'ma_airtime': ('MA Daily Transactions (VidaPay) — airtime margin / ATU',
                              'Data Imports → ma_daily_tx, or the ⬆ on /commcalc/ma-upload')}
              if mode != 'boost' else
              {'comm_epay': ('ePay Commission Payment Detail (#50273) — Commission by month',
                             'the ePay sweep, or Data Imports → payment_detail'),
               'mi': ('ePay MI/ATU residual — Monthly Incentive report',
                      'the ePay sweep, or Data Imports → mi')})
    for k, (what, how) in expect.items():
        if k not in present and not filtered:
            gaps.append({'stream': k, 'what': what, 'how': how,
                         'why': f'No rows for {labels[0]} – {labels[-1]}. Either this feed has never '
                                f'been ingested for these months, or this tenant does not use it.'})
    out['gaps'] = gaps
    out['carrier_mode'] = mode
    out['filtered'] = filtered
    out['window'] = {'period': labels[-1] if labels else period, 'months': len(labels)}
    return out


@router.get("/chargebacks/{period}")
def get_chargebacks(period: str, authorization: str = Header(default=""), org_id: str = "00000000-0000-0000-0000-000000000001"):
    client = sb()
    r = client.schema('commcalc').table('chargeback_items').select('*').eq('org_id', org_id).in_('period', _pvariants(period)).order('epay_salesperson').execute()
    rows = r.data or []
    from app.modules.storeops.router import scope_keyset, in_keyset
    ks = scope_keyset(authorization, org_id)   # None = unrestricted (admin / rbac off)
    # chargeback_items' store column is `store` — it has NEITHER store_code NOR store_address.
    # Filtering on those two meant in_keyset() saw None/None on every row and returned False for
    # every scoped caller, so the whole page read "$0" to every DM and store manager while
    # super-admins (ks is None) saw all of it. Match `store`, which holds the POS store string.
    return [c for c in rows if in_keyset(ks, c.get('store'))]

class UpdateChargebackIn(LaxModel):
    deduct: Any = False
    decided_by: Any = None


@router.put("/chargebacks/{item_id}")
async def update_chargeback(item_id: str, body: UpdateChargebackIn, org_id: str = "00000000-0000-0000-0000-000000000001"):
    client = sb()
    update = {'deduct': bool(body.deduct), 'decided_at': 'now()'}
    if body.decided_by:
        update['decided_by'] = body.decided_by
    r = client.schema('commcalc').table('chargeback_items').update(update).eq('id', item_id).execute()
    return r.data[0] if r.data else {}

@router.get("/calc-status/{period}")
def get_calc_status(period: str, org_id: str = "00000000-0000-0000-0000-000000000001"):
    client = sb()
    r = client.schema('commcalc').table('calc_status').select('*').eq('org_id', org_id).in_('period', _pvariants(period)).limit(1).execute()
    return r.data[0] if r.data else {'calc_status': 'not_run'}


