class PutCatalogOverrideIn(LaxModel):
    match_type: str = ""
    match_value: Any = None
    category: str = ""


@router.put("/catalog/override")
def put_catalog_override(body: PutCatalogOverrideIn, org_id: str = ORG_ID, authorization: str = Header(default="")):
    """Set (or CLEAR) a category override for one catalog product — the user-editable, NON-destructive layer
    on top of the loaded catalog file (deliverable 3). Body:
      {match_type:'upc'|'sku'|'product_id'|'product_desc', match_value:str, category:str}
    An empty/absent `category` CLEARS the override (the file's category is restored). match_value is
    normalized (lowercased/trimmed; product_desc whitespace-collapsed) so it matches the classifier's keys.
    GATED on the 'classification' settings permission (per-setting pattern); org-scoped; stamps org_id on
    the insert. Degrades with a clear 500 hint until mig 230 runs."""
    require_org(org_id)
    if not _can_edit_classification(authorization, org_id):
        raise HTTPException(403, "You don't have permission to edit Classification settings.")
    from app.modules.commcalc import accessory_catalog as _accat
    mt = str(body.match_type or "").strip().lower()
    if mt not in ("upc", "sku", "product_id", "product_desc"):
        raise HTTPException(400, "match_type must be one of upc / sku / product_id / product_desc.")
    raw_val = body.match_value
    if mt == "product_desc":
        mv = _accat.norm_desc(raw_val)
    elif mt == "product_id":
        mv = _accat.pid_key(raw_val)
    else:
        mv = _accat.clean_key(raw_val)
    if not mv:
        raise HTTPException(400, "match_value is required.")
    cat = str(body.category or "").strip()
    client = sb()
    try:
        if not cat:
            # CLEAR — restore the file default for this product.
            client.schema("commcalc").table("catalog_category_override").delete()\
                .eq("org_id", org_id).eq("match_type", mt).eq("match_value", mv).execute()
        else:
            client.schema("commcalc").table("catalog_category_override").upsert(
                {"org_id": org_id, "match_type": mt, "match_value": mv, "category": cat,
                 "updated_at": _cb_now()}, on_conflict="org_id,match_type,match_value").execute()
    except Exception as e:
        raise HTTPException(500, f"save failed — run migration 230_commission_catalog_total_variant.sql first: {e}")
    # The override layer feeds the cached catalog sets + the catalog page's category list — drop them now
    # so the edit is visible on the very next read instead of up to a TTL later (②).
    _invalidate_accessory_config(org_id)
    return {"ok": True, "org_id": org_id, "match_type": mt, "match_value": mv, "category": cat or None}


@router.get("/commission-drill")
def commission_drill(period: str, rep: str = "", org_id: str = ORG_ID):
    """The exact transactions behind each paid-out commission component for one rep + period, so every
    number on the Rep Commission Report can be verified. Replays the SAME classification the calculator
    uses (shared contract-type classifier + configurable accessory + setup-fee + ACIMA-tender), over the
    rep's raw_sales rows (the calc's source; falls back to the daily feed for visibility). Premium/BYOD/
    upgrade/ACIMA are DISTINCT transactions (matching the pay counts); accessories/setup are line items."""
    import re as _re
    client = sb()
    acfg = _accessory_config(client, org_id)
    _acima_tender_set = {t.strip().lower() for t in acfg["acima_tenders_list"] if t.strip()} or {"acima"}
    cols = ("trans_id,trans_date,store,salesperson,department,category,product_desc,contract_type,"
            "tender_type,ext_price,gp,voided,trans_type,mdn,serial_1")   # no 'sku' — feed lacks that column

    def _q(table):
        return (client.schema("commcalc").table(table).select(cols)
                .eq("org_id", org_id).in_("period", _pvariants(period)).limit(200000).execute().data) or []
    rows = _q("raw_sales")
    source = "raw_sales"
    if not rows:
        try:
            rows = _q("daily_sales_feed"); source = "daily_sales_feed"
        except Exception:
            rows = []

    def _norm(s):
        return _re.sub(r"[^a-z0-9]+", " ", str(s or "").lower()).strip()
    rnorm = _norm(rep)
    rtok = set(rnorm.split())

    def _match(sp):
        s = _norm(sp)
        if not (s and rnorm):
            return False
        if s == rnorm:
            return True
        st = set(s.split())
        return bool(st) and (st <= rtok or rtok <= st)
    if rep:
        rows = [r for r in rows if _match(r.get("salesperson"))]

    def _line(r):
        return {"trans_id": r.get("trans_id"), "date": str(r.get("trans_date") or "")[:10],
                "product": r.get("product_desc"), "contract_type": r.get("contract_type"),
                "ext_price": round(safe_float(r.get("ext_price")), 2), "gp": round(safe_float(r.get("gp")), 2),
                "tender_type": r.get("tender_type"), "mdn": r.get("mdn"), "serial": r.get("serial_1")}
    prem, byod, upg, acima = {}, {}, {}, {}
    acc, setup = [], []
    for r in rows:
        # SHARED voided token set (owner 2026-07-25) — this endpoint exists to REPLAY what the calculator
        # counted, so its skip rule must be the calculator's skip rule exactly.
        if _gp_is_voided(r.get("voided")):
            continue
        if str(r.get("trans_type") or "").strip() == "Return":
            continue
        tid = str(r.get("trans_id") or "").strip()
        cls = classify_contract_type(r.get("contract_type"))
        if tid and cls == "premium":
            prem.setdefault(tid, _line(r))
        elif tid and cls == "byod":
            byod.setdefault(tid, _line(r))
        elif tid and cls == "upgrade":
            upg.setdefault(tid, _line(r))
        if _is_accessory(r.get("department"), r.get("category"), r.get("product_desc"), acfg):
            acc.append(_line(r))
        if "Device Setup Charge" in str(r.get("product_desc") or ""):
            setup.append(_line(r))
        _tl = str(r.get("tender_type") or "").lower()
        if tid and any(at in _tl for at in _acima_tender_set):
            acima.setdefault(tid, _line(r))

    def _bucket(d):
        items = list(d.values()) if isinstance(d, dict) else d
        items.sort(key=lambda x: (x["date"], str(x["trans_id"])))
        return {"count": len(items), "sales": round(sum(x["ext_price"] for x in items), 2),
                "gp": round(sum(x["gp"] for x in items), 2), "items": items[:2000]}
    return {"rep": rep, "period": period, "source": source,
            "premium": _bucket(prem), "byod": _bucket(byod), "upgrade": _bucket(upg),
            "accessories": _bucket(acc), "setup": _bucket(setup), "acima": _bucket(acima)}


@router.get("/commission-explain")
def commission_explain(period: str, rep: str = "", org_id: str = ORG_ID):
    """READ-ONLY 'how was this commission calculated' for ONE rep + period. Returns the PLAN component
    (which plan attached, VIA WHICH assignment — reused from _resolve_plan_for(explain=True), the same
    matcher the live calc uses — plus per-rule matched sale lines), the MULTI-MONTH component (per-device
    M1–M6 installment rows with gate status/held-reason + the MA-file cross-reference), a $0 explanation,
    and a reconciliation against the last calc's rep_commissions row. Writes nothing; changes no payout
    number; never touches the live /calculate path. See commission_drilldown."""
    require_org(org_id)
