@router.post("/discrepancy/run")
def run_discrepancy_check(payload: dict, org_id: str = ORG_ID):
    """Trigger discrepancy detection. Send: { "period": "2026-04" }"""
    period = payload.get("period")
    if not period or len(period) != 7:
        raise HTTPException(status_code=400, detail="period must be YYYY-MM")
    try:
        result = run_discrepancy(period, org_id)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    return result


@router.get("/discrepancy/{period}")
async def get_discrepancy_results(period: str, org_id: str = ORG_ID):
    """Get all discrepancy results for a period, grouped by store."""
    client = sb()
    resp = client.schema("commcalc").table("discrepancy_results")        .select("*")        .eq("org_id", org_id)        .in_("period", _pvariants(period))        .order("store")        .order("gap", desc=True)        .execute()
    rows = resp.data or []

    # Group by store
    stores = {}
    for r in rows:
        store = r["store"] or "Unknown"
        if store not in stores:
            stores[store] = {"store": store, "total_gap": 0.0, "flagged_count": 0, "rows": []}
        stores[store]["rows"].append(r)
        if r.get("status") == "open" and r["gap"] > 0.50:
            stores[store]["total_gap"] = round(stores[store]["total_gap"] + r["gap"], 2)
            stores[store]["flagged_count"] += 1

    return {
        "period": period,
        "summary": sorted(stores.values(), key=lambda x: x["total_gap"], reverse=True),
        "total_gap_usd": round(sum(s["total_gap"] for s in stores.values()), 2),
        "total_flagged": sum(s["flagged_count"] for s in stores.values()),
    }


@router.patch("/discrepancy/{discrepancy_id}")
def update_discrepancy_status(discrepancy_id: int, payload: dict, org_id: str = ORG_ID):
    """Update status of a discrepancy row: open, resolved, disputed"""
    client = sb()
    client.schema("commcalc").table("discrepancy_results")        .update({"status": payload.get("status"), "notes": payload.get("notes")})        .eq("org_id", org_id)        .eq("id", discrepancy_id)        .execute()
    return {"status": "ok"}


def _period_ym(period: str) -> tuple[int, int]:
    """(year, month) from a period label, accepting both 'June 2026' and '2026-06'.

    Both forms are used across the app; these endpoints originally parsed only the
    numeric form and 500'd (ValueError) on the month-name form that every sibling
    endpoint accepts. Raises 400 with a clear message on anything unrecognized
    instead of leaking a ValueError as a 500. (_MONTH_TOKENS is a module global
    defined below; resolved at call time.)
    """
    p = (period or "").strip()
    if len(p) >= 7 and p[:4].isdigit() and p[4] == "-" and p[5:7].isdigit():
        year, month = int(p[:4]), int(p[5:7])
    elif p and p.lower().split()[0] in _MONTH_TOKENS:
        pm = parse_period(p)
        year, month = pm["year"], pm["month"]
    else:
        raise HTTPException(400, f"Unrecognized period '{period}' (expected 'Month YYYY' or 'YYYY-MM')")
    if not 1 <= month <= 12:
        raise HTTPException(400, f"Invalid month in period '{period}'")
    return year, month

@router.get("/discrepancy/{period}/phantom")
async def get_phantom_payments(period: str, org_id: str = ORG_ID):
    """Payments received in the period with no matching commissionable sale (by MDN or IMEI)."""
    from datetime import date as _date
    client = sb()
    year, month = _period_ym(period)
    plabel = _date(year, month, 1).strftime("%B %Y")

    # Build sets of MDNs and IMEIs from ALL sales (any period) AND all MI lines.
    # True phantom = payment matches NO sale anywhere AND no subscriber record.
    sales = (client.schema("commcalc").table("raw_sales")
             .select("serial_1,mdn").eq("org_id", org_id).execute().data) or []
    sale_mdns = {(s.get("mdn") or "").strip() for s in sales if s.get("mdn")}
    sale_imeis = {(s.get("serial_1") or "").strip() for s in sales if s.get("serial_1")}

    mi = (client.schema("commcalc").table("raw_mi")
          .select("device_serial,phone_number").eq("org_id", org_id).execute().data) or []
    mi_mdns = {(m.get("phone_number") or "").strip() for m in mi if m.get("phone_number")}
    mi_imeis = {(m.get("device_serial") or "").strip() for m in mi if m.get("device_serial")}
    known_mdns = sale_mdns | mi_mdns
    known_imeis = sale_imeis | mi_imeis

    # All payments in the period
    pays = (client.schema("commcalc").table("raw_payment_detail")
            .select("imei,mdn,payment_type,amount,business_address,payment_date")
            .eq("org_id", org_id).eq("period_month", month)
            .eq("period_year", year).execute().data) or []

    phantom = []
    matched_total = 0.0
    phantom_total = 0.0
    for p in pays:
        mdn = (p.get("mdn") or "").strip()
        imei = (p.get("imei") or "").strip()
        amt = float(p.get("amount") or 0)
        is_matched = (mdn and mdn in known_mdns) or (imei and imei in known_imeis)
        if is_matched:
            matched_total += amt
        else:
            phantom_total += amt
            phantom.append({
                "mdn": mdn, "imei": imei,
                "payment_type": p.get("payment_type"),
                "amount": round(amt, 2),
                "business_address": p.get("business_address"),
                "payment_date": str(p.get("payment_date"))[:10] if p.get("payment_date") else None,
            })

    # Group phantom by business_address
    by_store = {}
    for ph in phantom:
        addr = ph["business_address"] or "Unknown"
        if addr not in by_store:
            by_store[addr] = {"business_address": addr, "total": 0.0, "count": 0, "rows": []}
        by_store[addr]["total"] = round(by_store[addr]["total"] + ph["amount"], 2)
        by_store[addr]["count"] += 1
        by_store[addr]["rows"].append(ph)

    return {
        "period": period,
        "phantom_total": round(phantom_total, 2),
        "phantom_count": len(phantom),
        "matched_total": round(matched_total, 2),
        "by_store": sorted(by_store.values(), key=lambda x: x["total"], reverse=True),
    }


@router.get("/top-sellers/{period}")
async def get_top_sellers(period: str, limit: int = 10, org_id: str = ORG_ID):
    """Top-selling device models for the period (by activation volume) to prioritize hotsheet updates."""
    from datetime import date as _date
    client = sb()
    year, month = _period_ym(period)
    plabel = _date(year, month, 1).strftime("%B %Y")

    sales = (client.schema("commcalc").table("raw_sales")
             .select("product_desc,contract_type,ext_price")
             .eq("org_id", org_id).eq("period", plabel)
             .neq("contract_type", "").execute().data) or []

    # Aggregate by device model (strip promo suffix after " - " for cleaner grouping)
    models = {}
    for s in sales:
        desc = (s.get("product_desc") or "").strip()
        if not desc:
            continue
        # Only count rows that look like a device (has a category-ish device name, not a plan)
        # Heuristic: device rows usually contain a model + " - " promo, or brand keywords
        base = desc.split(" - ")[0].strip()
        low = base.lower()
        if not any(k in low for k in ["iphone","samsung","galaxy","moto","pixel","celero","tcl","summit","apple","motorola","ipad","watch","tab"]):
            continue
        if base not in models:
            models[base] = {"model": base, "units": 0, "sample_desc": desc}
        models[base]["units"] += 1

    ranked = sorted(models.values(), key=lambda x: x["units"], reverse=True)[:limit]
    return {"period": period, "top_sellers": ranked}


@router.get("/device-history")
def get_device_history(q: str = "", authorization: str = Header(default=""), org_id: str = ORG_ID):
    """DEVICE HISTORY LOOKUP (commission-16) — employee-portal widget backend. Enter an IMEI OR a phone
    number (one box; the shape is auto-detected but BOTH keys are searched). Returns, org-scoped and
    carrier-agnostic:
      • device + sale from the B2B sales data (raw_sales -> daily_sales_feed fallback): model, sold
        date, sale price. Match IMEI->serial_1, phone->mdn.
      • activation + tenure from the tenant's RESIDUAL data (raw_mi): first residual period =
        activation; months active = COUNT of DISTINCT residual periods (residual-months, NOT calendar).
      • a salesperson-facing prompt: NOT sold by us -> sell a NEW phone; sold by us -> offer an UPGRADE.
      • (admin-only, gated by the 'device_commission' DATA_GRANT) a per-period MONEY table with
        COMMISSION (raw_mi residual MI+ATU) and REBATE (raw_payment_detail reimbursement classes) as
        SEPARATE categories, each with a subtotal + a grand total.
    READ-ONLY: DISPLAY of already-recorded data, no pay-path change."""
    require_org(org_id)
    q = (q or "").strip()
    if not q:
        raise HTTPException(400, "Enter an IMEI or phone number.")
    client = sb()
    cands = device_history.query_candidates(q)
    shape = device_history.detect_shape(q)

    # CARRIER MODE (config-driven, RULE TWO): 'boost' → the tenure + money section reads raw_mi /
    # raw_payment_detail (byte-identical to before); any explicitly non-Boost carrier ('plan', e.g.
    # Total / VidaPay / luxelink) is MA-fed → the tenure + money section reads the raw_ma_* tables. No
    # hard-coded org/carrier names — resolved from the org's own carrier config via the single-source
    # _resolve_carrier_mode (same resolver the calc path uses).
    try:
        _carriers = (client.schema("commcalc").table("carrier").select("id,name,code,is_default")
                     .eq("org_id", org_id).execute().data) or []
    except Exception:
        _carriers = []
    carrier_mode = _resolve_carrier_mode(_carriers)
    # The org's OWN carrier name(s) for the MA money heading (config-driven — no carrier name in code;
    # neutral fallback lives in the UI). Prefer the default carrier, else the distinct active names.
    _def_carrier = next((c for c in _carriers if c.get("is_default")), None)
    if _def_carrier and (_def_carrier.get("name") or "").strip():
        carrier_label = _def_carrier["name"].strip()
    else:
        _names = [n for n in ((c.get("name") or "").strip() for c in _carriers) if n]
        carrier_label = ", ".join(dict.fromkeys(_names)) or None

    def _rows(table, cols, key_cols):
        out = []
        for kc in key_cols:
            try:
                out += (client.schema("commcalc").table(table).select(cols)
                        .eq("org_id", org_id).in_(kc, cands).limit(2000).execute().data) or []
            except Exception as e:
                print(f"WARN device-history {table}.{kc} read failed: {e}")
        return out

    # ── B2B SALE (raw_sales authoritative, daily_sales_feed fallback) ──────────────────────────────
    # gp is selected so the at-sale POS cost can be derived (ext_price − GP) — there is no explicit
    # cost column on raw_sales / daily_sales_feed; the 78-col export carries GP + Ext Price.
    sale_cols = "trans_id,trans_date,store,salesperson,product_desc,contract_type,ext_price,gp,mdn,serial_1"
    sale_rows = [r for r in _rows("raw_sales", sale_cols, ("serial_1", "mdn"))
                 if device_history.keys_match(cands, r.get("serial_1"), r.get("mdn"))]
    sale_source = "raw_sales" if sale_rows else None
    if not sale_rows:
        feed = [r for r in _rows("daily_sales_feed", sale_cols, ("serial_1", "mdn"))
                if device_history.keys_match(cands, r.get("serial_1"), r.get("mdn"))]
        if feed:
            sale_rows, sale_source = feed, "daily_sales_feed"

    sold_by_us = bool(sale_rows)
    device = None
    if sale_rows:
        # the DEVICE line: prefer a row carrying a serial (the handset line), else the biggest-ticket line.
        dev = max(sale_rows, key=lambda r: (1 if str(r.get("serial_1") or "").strip() else 0,
                                            safe_float(r.get("ext_price"))))
        dates = sorted(str(r.get("trans_date"))[:10] for r in sale_rows if r.get("trans_date"))
        device = {
            "phone_model": (dev.get("product_desc") or "").strip() or None,
            "sold_by_us": True,
            "sold_date": dates[0] if dates else (str(dev.get("trans_date"))[:10] if dev.get("trans_date") else None),
            "sale_price": round(safe_float(dev.get("ext_price")), 2),
            "gp": (round(safe_float(dev.get("gp")), 2) if dev.get("gp") is not None else None),
            "store": (dev.get("store") or "").strip() or None,
            "salesperson": (dev.get("salesperson") or "").strip() or None,
            "contract_type": (dev.get("contract_type") or "").strip() or None,
            "sale_source": sale_source,
            "mdn": (dev.get("mdn") or "").strip() or None,
            "imei": (dev.get("serial_1") or "").strip() or None,
        }

    # ── RESIDUAL / MI (raw_mi across ALL periods → activation + tenure + commission rows) ──────────
    mi_cols = "period,device_serial,phone_number,actual_mi_payout,actual_atu_payout,customer_plan,subscriber_status"
    mi_rows = [r for r in _rows("raw_mi", mi_cols, ("device_serial", "phone_number"))
               if device_history.keys_match(cands, r.get("device_serial"), r.get("phone_number"))]
    tenure = device_history.tenure_from_periods([r.get("period") for r in mi_rows])
    mi_matches = [{"period": r.get("period"),
                   "amount": safe_float(r.get("actual_mi_payout")) + safe_float(r.get("actual_atu_payout"))}
                  for r in mi_rows]

    # ── REBATES (raw_payment_detail across ALL periods) ───────────────────────────────────────────
    pay_cols = "imei,mdn,payment_type,amount,period_month,period_year,payment_date"
    pay_rows = [r for r in _rows("raw_payment_detail", pay_cols, ("imei", "mdn"))
                if device_history.keys_match(cands, r.get("imei"), r.get("mdn"))]

    def _pay_period(r):
        try:
            mo, yr = int(r.get("period_month") or 0), int(r.get("period_year") or 0)
            if 1 <= mo <= 12 and yr:
                return device_history.canon_display_period(f"{yr}-{mo:02d}")
        except Exception:
            pass
        return str(r.get("payment_date"))[:7] if r.get("payment_date") else ""
    payment_matches = [{"period": _pay_period(r), "amount": safe_float(r.get("amount")),
                        "payment_type": r.get("payment_type")} for r in pay_rows]

    # ── AGING + OUR PURCHASE PRICE (UNGATED — reps may see cost per owner directive 2026-07-17) ─────
    # v2: the purchase price is UNIVERSAL / POS-SKU based — owed_to_vip is NOT universal (VIP/house
    # only) so it is DEMOTED to last resort. Source priority (first real number wins), all org-scoped:
    #   ① per-IMEI inventory-aging cost   commcalc.inventory_aging_device.unit_cost   (POS/SKU, universal)
    #   ② at-sale POS cost                raw_sales/daily_sales_feed  ext_price − GP   (universal, b2bsoft)
    #   ③ MA marketplace order price      raw_ma_commission.imei → .activation_order →
    #                                     raw_ma_fulfillment.order_number → .price     (Total/MA)
    #   ④ asset_ledger.raw_row explicit device-cost column                             (VIP/house)
    #   ⑤ asset_ledger.owed_to_vip — LAST RESORT, VIP billing basis (house only)
    # A tenant with none of these gets an HONEST 'no cost on file' line (never a fabricated 0).
    from datetime import date as _dh_date
    today_iso = _dh_date.today().isoformat()
    sale_sold_date = device.get("sold_date") if device else None

    # asset_ledger (VIP / asset-lending — house aging path + sources ④⑤). Org-scoped via `_rows`.
    asset_cols = ("id,esn_imei,phone_number,store,market,device_model,category,status,acquired_date,"
                  "due_date,payg_date,reimbursement_date,trigger_date,billing_friday,bill_path,"
                  "date_sold,owed_to_vip,reimbursement,selling_price,raw_row")
    asset_rows = [r for r in _rows("asset_ledger", asset_cols, ("esn_imei", "phone_number"))
                  if device_history.keys_match(cands, r.get("esn_imei"), r.get("phone_number"))]
    asset_row = None
    if asset_rows:
        asset_row = max(asset_rows, key=lambda r: (
            1 if device_history.keys_match(cands, r.get("esn_imei")) else 0,
            str(r.get("acquired_date") or "")))

    # per-IMEI inventory-aging device row (source ① + non-VIP aging path). Latest snapshot wins.
    inv_cols = "id,imei,serial,sku,item,store,unit_cost,received_date,days_in_stock,as_of_date"
    inv_rows = [r for r in _rows("inventory_aging_device", inv_cols, ("imei", "serial"))
                if device_history.keys_match(cands, r.get("imei"), r.get("serial"))]
    inv_row = max(inv_rows, key=lambda r: str(r.get("as_of_date") or "")) if inv_rows else None

    # MA marketplace linkage (source ③): imei → raw_ma_commission.activation_order → fulfillment price.
    # The SAME imei-matched fetch also feeds the carrier-aware MA money table + tenure below, so the money
    # columns (device/consumer margin, rebate, mrc_net_discount, spiff_m1..m6, line_status) + the daily-tx
    # link keys (activation_order / merchant_account_id) ride along on this one query.
    ma_comm_cols = ("imei,activation_order,merchant_account_id,ban,sku,tx_date,period,period_month,"
                    "period_year,activation_type,activation_type2,device_margin,consumer_margin,rebate,"
                    "mrc_net_discount,spiff_m1,spiff_m2,spiff_m3,spiff_m4,spiff_m5,spiff_m6,line_status,"
                    "status_change_date")
    ma_comm_rows = [r for r in _rows("raw_ma_commission", ma_comm_cols, ("imei",))
                    if device_history.keys_match(cands, r.get("imei"))]
    ma_fulfil_rows = []
    ord_cands = device_history.order_candidates(
        [r.get("activation_order") for r in ma_comm_rows])
    if ord_cands:
        try:
            ma_fulfil_rows = (client.schema("commcalc").table("raw_ma_fulfillment")
                              .select("order_number,price,product_name,date_ordered")
                              .eq("org_id", org_id).in_("order_number", ord_cands)
                              .limit(2000).execute().data) or []
        except Exception as e:
            print(f"WARN device-history raw_ma_fulfillment read failed: {e}")
    ma_price = device_history.pick_ma_marketplace_price(ma_comm_rows, ma_fulfil_rows)

    # ── CARRIER-AWARE tenure (config-driven) — MA-fed tenants read raw_ma_* for "residual history" ──
    # Backbone = the imei-matched raw_ma_commission periods (the 1st–6th-month schedule) — always correct
    # because raw_ma_commission is imei-keyed. AUGMENTED by raw_ma_daily_tx rows linked to THIS device's
    # activation order(s): every order-linked tx month evidences the line was active that month (we take
    # ALL order_types deliberately — any activity, not only 'residual', counts as an active recurring
    # month). GUARD: raw_ma_daily_tx has no imei and no uniqueness on order_number, so if an activation
    # order maps to MORE THAN ONE imei in raw_ma_commission (a shared/multi-line order), its daily-tx
    # months belong partly to a sibling line — we SKIP those orders (backbone alone stays correct) and
    # note the omission. Boost tenants keep the raw_mi tenure computed above, untouched.
    def _ma_row_period(r):
        p = (r.get("period") or "").strip()
        if p:
            return p
        try:
            mo, yr = int(r.get("period_month") or 0), int(r.get("period_year") or 0)
            if 1 <= mo <= 12 and yr:
                return device_history.canon_display_period(f"{yr}-{mo:02d}")
        except Exception:
            pass
        return str(r.get("tx_date"))[:7] if r.get("tx_date") else ""

    ma_daily_rows = []
    if carrier_mode != "boost":
        # resolve which activation orders are UNAMBIGUOUS (map to exactly one imei org-wide).
        shared_order = False
        safe_orders = list(ord_cands)
        if ord_cands:
            try:
                omap = (client.schema("commcalc").table("raw_ma_commission").select("activation_order,imei")
                        .eq("org_id", org_id).in_("activation_order", ord_cands)
                        .limit(20000).execute().data) or []
            except Exception as e:
                omap = []
                print(f"WARN device-history raw_ma_commission order-map read failed: {e}")
            imeis_by_order = {}
            for r in omap:
                o = device_history.norm_order(r.get("activation_order"))
                im = device_history.norm_digits(r.get("imei"))
                if o and im:
                    imeis_by_order.setdefault(o, set()).add(im)
            safe_orders = []
            for oc in ord_cands:
                ims = imeis_by_order.get(device_history.norm_order(oc))
                if ims is not None and len(ims) > 1:
                    shared_order = True
                else:
                    safe_orders.append(oc)
        if safe_orders:
            try:
                ma_daily_rows = (client.schema("commcalc").table("raw_ma_daily_tx")
                                 .select("period,period_month,period_year,order_number,order_type,tx_date")
                                 .eq("org_id", org_id).in_("order_number", safe_orders)
                                 .limit(5000).execute().data) or []
            except Exception as e:
                print(f"WARN device-history raw_ma_daily_tx read failed: {e}")
        ma_periods = ([_ma_row_period(r) for r in ma_comm_rows]
                      + [_ma_row_period(r) for r in ma_daily_rows])
        tenure = device_history.ma_tenure_from_periods(ma_periods)
        if shared_order and tenure.get("note"):
            tenure["note"] += (" (A shared activation order was detected — order-level recurring months "
                               "were omitted for it; tenure reflects the IMEI-keyed commission periods.)")

    # aging: house/VIP asset_ledger when present, else the non-VIP inventory-aging device row.
    if asset_row:
        aging = device_history.build_aging(asset_row, sale_sold_date, today_iso)
    elif inv_row:
        aging = device_history.build_aging_inventory(inv_row, sale_sold_date, today_iso)
    else:
        aging = device_history.build_aging(None, sale_sold_date, today_iso)

    # our purchase price — source-priority pick (①→⑤) with provenance (UNGATED).
    price_candidates = []
    # ① per-IMEI inventory-aging cost (POS/SKU — universal)
    if inv_row:
        inv_amt, inv_sku = device_history.inv_device_cost(inv_row)
        if inv_amt is not None:
            price_candidates.append({
                "amount": inv_amt, "source": "inventory_aging_device.unit_cost",
                "label": ("POS inventory cost" + (f" — SKU {inv_sku}" if inv_sku else " (SKU-based)"))})
    # ② at-sale POS cost = ext_price − GP (universal for every b2bsoft tenant incl. house)
    if device:
        pos_cost = device_history.pos_cost_from_sale(device.get("sale_price"), device.get("gp"))
        if pos_cost is not None:
            price_candidates.append({
                "amount": pos_cost, "source": f"{sale_source or 'raw_sales'} (ext − GP)",
                "label": "POS sale line (ext − GP)"})
    # ③ MA marketplace order price (Total/MA tenants)
    if ma_price.get("found"):
        price_candidates.append({
            "amount": ma_price["amount"], "source": "raw_ma_fulfillment.price",
            "label": ("MA marketplace order" + (f" {ma_price['order_number']}" if ma_price.get("order_number") else ""))})
    # ④ asset_ledger.raw_row explicit device-cost column (VIP/house)
    if asset_row:
        rr_amt, rr_hdr = device_history.scan_raw_row_price((asset_row.get("raw_row") or {}))
        if rr_amt is not None:
            price_candidates.append({"amount": rr_amt,
                                     "source": f"asset_ledger.raw_row[{rr_hdr}]",
                                     "label": f"VIP asset ledger — {rr_hdr}"})
        # ⑤ asset_ledger.owed_to_vip — LAST RESORT, VIP billing basis (house only)
        owed = safe_float(asset_row.get("owed_to_vip"))
        price_candidates.append({"amount": (round(owed, 2) if owed > 0 else None),
                                 "source": "asset_ledger.owed_to_vip",
                                 "label": "VIP billing basis (house — Owed to VIP)"})
    purchase_price = device_history.pick_purchase_price(price_candidates)

    # ── MONEY TABLE (gated: admin-only by default via the 'device_commission' grant) ───────────────
    # CARRIER-AWARE (config-driven): Boost → raw_mi residual + raw_payment_detail rebate (byte-identical
    # to before); MA-fed → the raw_ma_commission per-IMEI section (M1–M6 spiffs / rebate / margins / plan
    # MRC / line status), paid-to-dealer normalized. Degrades to an explicit "no MA data" note (never a
    # silent $0, never a crash) when the raw_ma_* tables are absent/empty for the org.
    from app.modules.commcalc.discrepancy_engine import parse_payment_type
    can_money = _can_view_device_commission(authorization, org_id)
    money, money_locked = None, None
    if can_money:
        if carrier_mode != "boost":
            money = device_history.build_ma_money_table(ma_comm_rows, carrier_label=carrier_label)
        else:
            money = device_history.build_money_table(
                mi_matches, payment_matches, lambda pt: parse_payment_type(pt)[0])
    else:
        money_locked = {"note": "Commission details are restricted — this requires the "
                                "'device_commission' data grant (admin-only by default)."}

    return {
        "query": q, "detected": shape, "org_id": org_id,
        # carrier_mode is added ONLY for non-Boost modes → the Boost payload key-set stays byte-identical
        # to the pre-carrier-aware shape (device_history.carrier_response_fields, proved in the harness).
        **device_history.carrier_response_fields(carrier_mode),
        "found": bool(sale_rows or mi_rows or pay_rows or asset_rows or inv_rows or ma_comm_rows),
        "device": device,
        "sold_by_us": sold_by_us,
        "prompt": device_history.prompt_for(sold_by_us, device.get("sold_date") if device else None),
        "tenure": tenure,
        "residual_periods": tenure["months_active"],
        "aging": aging,
        "purchase_price": purchase_price,
        "commission_visible": can_money,
        "money": money,
        "money_locked": money_locked,
    }


@router.get("/sales-analyzer/{period}")
def get_sales_analyzer(period: str, window_days: int = 90, rep: str = "",
                            authorization: str = Header(default=""), org_id: str = ORG_ID):
    """3-Month Retention (3MR) behavior per rep: each rep's activations from 3 months before
    `period` and which churned (cancelled/ported/suspended/deactivated) before their 3rd bill
    (within window_days). Returns per-rep summary + churned line items (model, MRC, sold-for,
    dates, store). RBAC-scoped: a non-admin manager only sees subscribers in their stores."""
    require_org(org_id)
    from app.modules.storeops.router import scope_keyset
    ks = scope_keyset(authorization, org_id)
    try:
        return sales_analyzer.analyze(sb(), org_id, period, window_days=window_days, rep=rep, store_keys=ks)
    except Exception as e:
        raise HTTPException(500, f"sales-analyzer failed: {type(e).__name__}: {e}")


@router.get("/comp/residual-trend")
def get_comp_residual_trend(months: int = 6, store: str = "", market: str = "",
                                  min_drop_pct: float = 20.0, min_drop_amt: float = 1.0,
                                  authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Month-over-month carrier residual (Comprehensive Comp) trend. Returns total residual per
    month with deltas, plus per-account DIPS (residual fell or the account vanished from the
    report = likely cancellation) labeled by the month each dip occurred — so you can see which
    month a residual dropped and why."""
    require_org(org_id)
    _require_carrier_residual(authorization, org_id)   # carrier-residual visibility gate (mig 201)
    try:
        return comp_trend.compute_residual_trend(
            sb(), org_id, months=months, store=store, market=market,
            min_drop_pct=min_drop_pct, min_drop_amt=min_drop_amt)
    except Exception as e:
        raise HTTPException(500, f"comp-residual-trend failed: {type(e).__name__}: {e}")


@router.get("/comp/rep-pay-trend")
def get_comp_rep_pay_trend(months: int = 6, store: str = "", org_id: str = ORG_ID):
    """Per-REP commission trend — the commission WE ACTUALLY PAY each rep (rep_commissions.total_payout)
    month over month. This is the per-rep number the Total Compensation page was missing (its other
    view is account-level carrier comp). One row per rep with each kept month's payout + a total."""
    require_org(org_id)
    try:
        client = sb()
        result = comp_trend.compute_rep_pay_trend(client, org_id, months=months, store=store)
        # RULE FIVE (§3d): stamp each rep row with its `market` (store_mapping resolver) so the Total
        # Compensation page can market-filter the per-rep view client-side. Additive + org-scoped.
        _resolve_market, _ = _store_market_resolver(client, org_id)
        for rr in (result.get('reps') or []):
            rr['market'] = _resolve_market(rr.get('store'))          # legacy top-level (backward compat)
            for pt in (rr.get('points') or []):                      # FIX 4: per-MONTH market so a store/
                pt['market'] = _resolve_market(pt.get('store'))      # market filter narrows the right months
        return result
    except Exception as e:
        raise HTTPException(500, f"comp-rep-pay-trend failed: {type(e).__name__}: {e}")


# ── Daily Sales Targets ──────────────────────────────────────
_MONTH_TOKENS = {
    'january', 'february', 'march', 'april', 'may', 'june', 'july',
    'august', 'september', 'october', 'november', 'december',
}


def _period_bounds(period: str, today_override: str = ""):
    """Return (month_start, next_month_start, resolved_today) for a period label.

    `today_override` (YYYY-MM-DD) lets the client pass its *local* date so "today"
    isn't computed in the server's UTC clock — critical for an evening sales floor
    where UTC has already rolled to tomorrow. Falls back to the server date.
    """
    # parse_period silently falls back to January on an unknown month; guard here
    # so a malformed period fails loudly instead of returning wrong bounds.
    if not period or period.lower().split()[0] not in _MONTH_TOKENS:
        raise HTTPException(400, f"Unrecognized period '{period}' (expected 'Month YYYY')")
    pm = parse_period(period)
    year, month = pm['year'], pm['month']
    start = _date(year, month, 1)
    last_day = _calendar.monthrange(year, month)[1]
    end = _date(year, month, last_day) + _timedelta(days=1)
    real = _date.today()
    if today_override:
        try:
            real = _date.fromisoformat(today_override[:10])
        except ValueError:
            pass  # ignore a malformed override, keep server date
    if real < start:
        today = start                       # future period — nothing is "past" yet
    elif real >= end:
        today = _date(year, month, last_day)  # past period — whole month is realized
    else:
        today = real
    return start, end, today


def _rep_canon_map(client, org_id=ORG_ID):
    """alias(UPPER) -> canonical rep name. From commcalc.name_map (epay_salesperson ->
    storeops_name) + commcalc.rep_aliases (user merges, override). Degrades to {} if absent."""
    m = {}
    try:
        for n in (client.schema('commcalc').table('name_map')
                  .select('epay_salesperson,storeops_name').eq('org_id', org_id).execute().data or []):
            a = (n.get('epay_salesperson') or '').strip().upper()
            c = (n.get('storeops_name') or '').strip()
            if a and c:
                m[a] = c
    except Exception:
        pass
    try:
        for r in (client.schema('commcalc').table('rep_aliases')
                  .select('alias,canonical').eq('org_id', org_id).execute().data or []):
            a = (r.get('alias') or '').strip().upper()
            c = (r.get('canonical') or '').strip()
            if a and c:
                m[a] = c
    except Exception:
        pass
    return m


def _canon(name, cmap):
    if not name:
        return name
    return cmap.get(name.strip().upper(), name)


def _fetch_shifts(client, start, end, org_id=ORG_ID):
    rows = (client.schema('storeops').table('shifts')
            .select('employee_name,store_code,shift_date,scheduled_hours,is_deleted')
            .eq('org_id', org_id)
            .gte('shift_date', start.isoformat())
            .lt('shift_date', end.isoformat())
            .limit(50000).execute().data) or []
    cmap = _rep_canon_map(client, org_id)
    for r in rows:
        r['employee_name'] = _canon(r.get('employee_name'), cmap)
    return rows


def _is_open_month(period):
    """True if `period` is the current in-progress calendar month. Handles BOTH 'June 2026' and the
    '2026-07' shape (parse_period only understands the month-name form → it silently mapped '2026-07'
    to January, so July read as a CLOSED month — the source-selection bug)."""
    try:
        p = str(period).strip()
        if len(p) >= 7 and p[:4].isdigit() and p[4] == '-' and p[5:7].isdigit():
            yr, mo = int(p[:4]), int(p[5:7])
        else:
            pm = parse_period(period)
            yr, mo = pm['year'], pm['month']
        t = _date.today()
        return mo == t.month and yr == t.year
    except Exception:
        return False


_BOX_DEPTS = {'Android - XP', 'IPHONE - XP', 'TABLET - XP'}


def _open_month_source(client, org_id, period):
    """(primary, other) sales tables for a period. Closed month → the authoritative raw_sales first.
    Open month → the daily feed first, EXCEPT when the feed has NO Category-bearing rows for the period
    but raw_sales does — then raw_sales (the richer custom data) leads. Keeps a Legacy (Category-blank)
    feed from masking a better raw_sales for the open month. No-op in the healthy state where the feed
    already carries Category. Best-effort — any error falls back to the plain feed-first rule."""
    if not _is_open_month(period):
        return 'raw_sales', 'daily_sales_feed'
    primary, other = 'daily_sales_feed', 'raw_sales'
    try:
        def _cat(tbl):
            return (client.schema('commcalc').table(tbl).select('id', count='exact')
                    .eq('org_id', org_id).in_('period', _pvariants(period))
                    .neq('category', '').limit(1).execute().count) or 0
        if _cat('daily_sales_feed') == 0 and _cat('raw_sales') > 0:
            primary, other = 'raw_sales', 'daily_sales_feed'
    except Exception:
        pass
    return primary, other


# Default column projection for the display sales resolver — the exact set every reader agrees on and
# that exists in BOTH raw_sales and daily_sales_feed (selecting a feed-absent column like `sku` throws;
# see the sales-report/detail note). Callers may pass their own `cols`.
_SALES_DISPLAY_COLS = ("trans_id,trans_date,store,salesperson,department,category,product_desc,"
                       "contract_type,ext_price,gp,voided,trans_type")


# ── Feed↔raw_sales merge / dedupe / promotion-mutex primitives (all pure + unit-testable) ──────────
# Extracted so the promotion-dedup + display day-pick logic can be tested without a live DB
# (backend/scratchpad/promotion_dedup_proof.py). Introduced 2026-07-16 for the luxelink July 2026
# feed-less-day compounding-duplication incident.

# Day-grain "richer source wins" thresholds — a deliberate MIRROR of the ingest price-guard
# (_SHRINK_* / router.py upload_file: protect a day at existing >= 50 priced rows, refuse it at
# incoming < 0.5 x existing). Same 50-row floor + 50% ratio, applied to READS so the display never
# shows a degraded copy of a day when the other table holds a materially fuller copy of that same day.
_RICHER_DAY_MIN_ROWS = 50
_RICHER_DAY_RATIO = 0.5


def _merge_days_richer(prows, orows, day_fn, min_rows=_RICHER_DAY_MIN_ROWS, ratio=_RICHER_DAY_RATIO):
    """Per-DAY merge of a PRIMARY and OTHER row set. The primary keeps every day it has EXCEPT a day
    whose primary copy is DEGRADED versus the other's — i.e. the other holds >= `min_rows` rows for that
    day AND the primary holds < `ratio` x the other's count for it (the price-guard 50%/50-row rule). On
    such a day the other's richer copy is used and the day is reported as SWAPPED. Days the primary lacks
    entirely are FILLED from the other (the prior behaviour). Blank-day rows (day_fn falsy) on the primary
    are always kept; blank-day rows on the other are dropped (can't be day-compared). Primary order is
    preserved for kept rows; other-source rows are appended.

    Returns (merged_rows, swapped_days_sorted, filled_days_sorted). Pure — no I/O, never raises."""
    if not prows:
        odays = sorted({day_fn(r) for r in orows if day_fn(r)})
        return list(orows), [], odays
    p_cnt, o_cnt = {}, {}
    for r in prows:
        d = day_fn(r)
        if d:
            p_cnt[d] = p_cnt.get(d, 0) + 1
    for r in orows:
        d = day_fn(r)
        if d:
            o_cnt[d] = o_cnt.get(d, 0) + 1
    pdays = set(p_cnt)
    swapped = sorted(d for d, oc in o_cnt.items()
                     if oc >= min_rows and p_cnt.get(d, 0) > 0 and p_cnt.get(d, 0) < ratio * oc)
    swap_set = set(swapped)
    filled = sorted(d for d in o_cnt if d not in pdays)
    kept_primary = [r for r in prows if day_fn(r) not in swap_set]
    add_from_other = [r for r in orows
                      if day_fn(r) and (day_fn(r) in swap_set or day_fn(r) not in pdays)]
    return kept_primary + add_from_other, swapped, filled


# Cell-grain (day × store) "richer source wins" thresholds — the store-aware successor to the day-grain
# rule above. The day-grain merge masked EVERY store on a day the primary led: the luxelink July 2026
# incident — the daily b2bsoft feed carries only ~6 NY stores, so on a feed-led day the freshly
# re-uploaded raw_sales rows for the other ~13 stores (Chicago / NJ) were hidden, and only the feed-less
# days showed all stores. Merging at (day × store) grain lets the primary win only the CELLS it actually
# holds; every other store's cell fills from the other source. The row FLOOR is scaled DOWN from the
# day-level 50 to 10 (a single store-day is far fewer rows than a whole day); the 50% ratio is unchanged.
_RICHER_CELL_MIN_ROWS = 10
_RICHER_CELL_RATIO = 0.5


def _cell_store_key(store):
    """Cheap canonicalization for the store half of a (day, store) cell key: strip, collapse internal
    whitespace, casefold. NO store_mapping / resolver lookup (deliberately out of scope) — just enough
    that a feed copy and a raw_sales copy of the SAME store don't split into two cells over case /
    whitespace drift (which would double-count that store-day). The row's ORIGINAL store string is
    preserved in the merged output; this key only decides which source wins a cell."""
    return ' '.join(str(store or '').split()).casefold()


def _norm_sale_tid(v):
    """Normalize a trans_id for the completeness dedup, MIRRORING the ingest normalization
    (upload_file / _daily_feed_map: `str(Trans ID).replace('.0','').strip()`), so a float-formatted
    '1624.0' and a plain '1624' — which a feed export and a monthly export can spell differently —
    can't split into two 'distinct' transactions and double-count. Also collapses leading-zero padding
    for an all-digit id ('01624' == '1624'). The row's ORIGINAL trans_id is preserved in the output;
    this only normalizes the DEDUP KEY. Pure; never raises."""
    t = str(v or '').strip()
    if t.endswith('.0'):
        t = t[:-2]
    if t.isdigit():
        t = t.lstrip('0') or '0'
    return t


def _merge_cells_richer(prows, orows, cell_fn, min_rows=_RICHER_CELL_MIN_ROWS, ratio=_RICHER_CELL_RATIO):
    """Per-(day × store)-CELL merge of a PRIMARY and OTHER row set — the store-aware successor to
    `_merge_days_richer`. The primary keeps every cell it has EXCEPT a cell whose primary copy is
    DEGRADED versus the other's — the other holds >= `min_rows` rows for that cell AND the primary holds
    < `ratio` x the other's count (the ingest price-guard rule, scaled to store-day cells). On such a
    cell the other's richer copy is used and the cell is reported as RICHER (swapped). Cells the primary
    lacks entirely are FILLED from the other. Rows whose `cell_fn` is falsy (blank day) on the primary
    are always kept; such rows on the other are dropped (can't be cell-compared). Primary order preserved
    for kept rows; other-source rows appended.

    Returns (merged_rows, richer_cells_sorted, filled_cells_sorted), each cell a (day, store_key) tuple.
    Pure — no I/O, never raises."""
    if not prows:
        ocells = sorted({c for c in (cell_fn(r) for r in orows) if c})
        return list(orows), [], ocells
    p_cnt, o_cnt = {}, {}
    for r in prows:
        c = cell_fn(r)
        if c:
            p_cnt[c] = p_cnt.get(c, 0) + 1
    for r in orows:
        c = cell_fn(r)
        if c:
            o_cnt[c] = o_cnt.get(c, 0) + 1
    pcells = set(p_cnt)
    richer = sorted(c for c, oc in o_cnt.items()
                    if oc >= min_rows and p_cnt.get(c, 0) > 0 and p_cnt.get(c, 0) < ratio * oc)
    richer_set = set(richer)
    filled = sorted(c for c in o_cnt if c not in pcells)
    kept_primary = [r for r in prows if cell_fn(r) not in richer_set]
    add_from_other = [r for r in orows
                      if cell_fn(r) and (cell_fn(r) in richer_set or cell_fn(r) not in pcells)]
    return kept_primary + add_from_other, richer, filled


def _row_content_sig(row, drop_keys=('id', 'created_at')):
    """A stable, order-independent full-content signature of a row: every column except `drop_keys`,
    values normalized to str (None → '') so ('5' vs 5) and (None vs '') can't split a true duplicate.
    Used to collapse read-skew / compounded duplicate rows. NOTE: two genuinely-identical line items on
    one real ticket produce the same signature and WILL collapse to one — accepted, because the
    authoritative monthly re-upload restores exact per-line truth; the feed merge is a self-heal, not the
    system of record."""
    drop = set(drop_keys)
    return tuple(sorted((k, '' if v is None else str(v)) for k, v in row.items() if k not in drop))


def _dedupe_rows(rows, drop_keys=('id', 'created_at')):
    """Dedupe rows on their full-content signature (`_row_content_sig`), keeping the FIRST occurrence of
    each signature. Returns (deduped_rows, dropped_count). Pure — no I/O."""
    seen, out, dropped = set(), [], 0
    for r in rows:
        sig = _row_content_sig(r, drop_keys)
        if sig in seen:
            dropped += 1
            continue
        seen.add(sig)
        out.append(r)
    return out, dropped


# In-process, per-(org_id, period) promotion mutex. Railway runs a SINGLE process, so a module-level
# lock table is sufficient to serialize the hourly email-sweep promotion side-effect against the
# scheduled _promote_all_due (and any manual promote-feed): two overlapping delete-then-insert cycles
# for the same org+period would otherwise interleave into a double-count. Non-blocking by design — a
# second concurrent caller SKIPS rather than queueing.
_PROMO_LOCKS = {}
_PROMO_LOCKS_GUARD = threading.Lock()


def _promo_lock_for(org_id, period_key):
    """Return the shared threading.Lock for one (org_id, period_key), creating it under the guard lock
    on first use (so two threads racing to create it get the SAME lock object)."""
    key = (org_id, period_key)
    with _PROMO_LOCKS_GUARD:
        lk = _PROMO_LOCKS.get(key)
        if lk is None:
            lk = threading.Lock()
            _PROMO_LOCKS[key] = lk
        return lk


def _sales_rows_union(client, org_id, period, cols=_SALES_DISPLAY_COLS):
    """THE canonical DISPLAY sales source: a per-DAY UNION of daily_sales_feed and raw_sales.

    The open-month PRIMARY source (per `_open_month_source`) wins every day it has rows for; the OTHER
    source fills only the days the primary lacks. This is promotion's feed-wins merge (see
    `_promote_feed_to_raw_sales`) applied at day grain to READS, so a manually-uploaded raw_sales month
    can NEVER be invisible behind a partial feed (the luxelink July 2026 incident: feed days 1-8 + a
    hand-uploaded raw_sales 1-13 → the union shows 1-13, not a truncated 1-8), and a promoted raw_sales
    month is never masked by a stale feed. Closed month → raw_sales leads, feed fills gaps.

    Per-(day × store)-CELL pick WITH a degradation guard (2026-07-16): the primary leads each store-day
    CELL it has UNLESS its copy of that cell is degraded versus the other source's — the other holds
    >= 10 rows for the cell AND the primary holds < 50% of that (a MIRROR of the ingest price-guard,
    scaled to store-day grain) — in which case the other's richer copy of that cell is shown and it is
    counted in meta['richer_cells']. Cells the primary lacks are filled from the other. STORE-grain (not
    the old day-grain) is what stops a partial feed from MASKING other stores: the luxelink July 2026
    incident — the daily feed carries only ~6 NY stores, so on a feed-led day the re-uploaded raw_sales
    rows for the other ~13 stores (Chicago / NJ) were dropped; now only the feed's own store cells win
    and every other store fills from raw_sales, so all stores show on every day. meta reports store
    coverage (`stores_shown` / `primary_stores` / `stores_from_other`) so the page can show which source
    covered what.

    NEVER raises: a failed read on either table degrades to whatever the other returned (so a column
    drift on one side can't 500 the page). Returns `(rows, meta)`; `meta` carries the per-source counts,
    which source led, which days were filled from the other, and which days were swapped to the richer
    source (`richer_days`) — for the report's transparency line.

    DISPLAY ONLY. The commission CALC path (`_run_calculation`/`_fetch_sales_unified`,
    `commission_engine._read_sales`) is deliberately NOT wired to this — that is money and gets its own
    gate; this function must not be called from a payout path."""
    primary, other = _open_month_source(client, org_id, period)

    def _q(table):
        try:
            return (client.schema('commcalc').table(table).select(cols)
                    .eq('org_id', org_id).in_('period', _pvariants(period))
                    .limit(200000).execute().data) or []
        except Exception as e:
            print(f"WARN _sales_rows_union read of {table} failed: {e}")
            return []

    # The two source reads are INDEPENDENT and are each the heaviest cost of this call (a full period of
    # raw_sales / daily_sales_feed lines, up to the 200k cap). They were issued back-to-back, so the page
    # paid their latency SERIALLY. Run them CONCURRENTLY on the process-wide singleton client — the exact
    # concurrency FastAPI already serves across simultaneous requests against this one connection pool
    # (get_supabase() singleton + db_resilience pool; httpx.Client is documented thread-safe for
    # concurrent requests, and harness_db_singleton proves concurrent .schema() usage keeps headers
    # isolated). `_q` swallows its own errors and returns [], so a worker thread can never raise; any
    # unexpected executor failure falls back to the original sequential reads. Byte-identical output —
    # the SAME rows for each source, only fetched in parallel (prows/orows are assigned by source, not by
    # completion order). DISPLAY path only (see the docstring: the money calc never calls this).
    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=2) as _ex:
            _fp = _ex.submit(_q, primary)
            _fo = _ex.submit(_q, other)
            prows, orows = _fp.result(), _fo.result()
    except Exception as _pe:
        print(f"WARN _sales_rows_union parallel read fell back to sequential: {_pe}")
        prows = _q(primary)
        orows = _q(other)

    def _day(r):
        return str(r.get('trans_date') or '')[:10]

    def _cell(r):
        d = _day(r)
        return (d, _cell_store_key(r.get('store'))) if d else None

    # Primary leads each (day × store) CELL it has; a cell where the other source is materially richer
    # (>= 10 rows AND the primary < 50% of it) is SWAPPED to the other; cells the primary lacks are
    # FILLED from the other. Store-grain (not day-grain) so a feed carrying only some stores can no longer
    # mask the other stores' rows on a day it leads (the luxelink July 2026 incident).
    merged, richer_cells, filled_cells = _merge_cells_richer(prows, orows, _cell)

    # ── COMPLETENESS backfill (2026-07-18; luxelink '957 Pennsylvania Ave' undercount) ──────────
    # `_merge_cells_richer` is winner-take-all PER (day x store) CELL: on a cell the feed leads, every
    # raw_sales transaction whose trans_id the feed lacked for that cell is DROPPED — the documented
    # 'narrow completeness edge' (see _fetch_actuals). For a tenant whose hourly feed is chronically
    # INCOMPLETE (luxelink) that hides real raw_sales transactions on a store-day the feed also sold.
    # The cell-grain merge above still decides source COVERAGE + the degradation guard; here we UNION
    # back any raw_sales row whose (store-cell, trans_id) isn't already in the merged set.
    #   • M2 (raw-only source): the backfill runs ONLY when the OTHER source is raw_sales — i.e. an
    #     open month the FEED leads. On a raw_sales-led month (closed month, or the feed-has-no-Category
    #     open-month case) we NEVER resurrect a feed-only trans_id into the authoritative raw-led view
    #     (a transaction deleted from the POS must stay gone).
    #   • M1 (store-scoped key): the dedup key is (canonical store cell, normalized trans_id), NOT a
    #     bare tenant-wide trans_id — otherwise feed '1624' @ Store A would suppress a REAL raw-only
    #     '1624' @ Store B and the bug would persist cross-store.
    #   • m2 (id format): `_norm_sale_tid` mirrors ingest ('1624.0'/'01624' == '1624') so a format
    #     skew between the feed and the monthly export can't double-count.
    # A transaction present in BOTH sources keeps the FEED copy (feed leads) — never double-counted
    # (same philosophy as _sales_rows_union_txn). In the healthy feed-only / fully-promoted state
    # (raw_sales (store,tid) subset of the feed) NOTHING is added -> byte-identical (Boost unchanged).
    # Blank trans_ids can't be deduped and are left to the cell-grain decision.
    # LINE-SET LIMITATION (n2): dedup is per TRANSACTION — for a trans_id present in BOTH sources the
    # feed's line set wins, so if raw_sales holds MORE line items for that same transaction the extra
    # lines are NOT merged in (the materially-degraded-cell case is handled separately by the richer
    # guard). The fix targets whole raw-ONLY transactions, which is the reported bug. Pure; never raises.
    completeness = []
    if other == 'raw_sales':
        def _bk_key(r):
            return (_cell_store_key(r.get('store')), _norm_sale_tid(r.get('trans_id')))
        _merged_keys = {_bk_key(r) for r in merged if _norm_sale_tid(r.get('trans_id'))}
        completeness = [r for r in orows
                        if _norm_sale_tid(r.get('trans_id')) and _bk_key(r) not in _merged_keys]
        if completeness:
            merged = merged + completeness
    # n1: the transparency count reflects real recovered SALES — exclude voided / Return lines (they
    # never count as sales in _sales_cell_agg anyway). The rows are still in `merged` (the agg drops
    # them), only the surfaced number is sales-only.
    completeness_sales = sum(
        1 for r in completeness
        if str(r.get('voided') or '').strip().lower() not in _VOID_TOKENS
        and str(r.get('trans_type') or '').strip() != 'Return')

    feed_rows = len(prows) if primary == 'daily_sales_feed' else len(orows)
    raw_rows = len(prows) if primary == 'raw_sales' else len(orows)
    filled_set, richer_set = set(filled_cells), set(richer_cells)
    fill_rows = sum(1 for r in orows if _cell(r) in filled_set)
    richer_rows = sum(1 for r in orows if _cell(r) in richer_set)
    # Day-level rollups of the cell picks — kept so the existing sales-report transparency line
    # (`filled_days` / `richer_days`) still reads; now "days on which >= 1 store cell was filled / swapped".
    filled_days = sorted({c[0] for c in filled_cells})
    richer_days = sorted({c[0] for c in richer_cells})

    # Store coverage — the transparency the page needs to SEE that all stores are present (not just the
    # feed's ~6): how many distinct stores each side holds, how many the merged view shows, and how many
    # only appear because of the other source.
    def _stores_of(rs):
        return {_cell_store_key(r.get('store')) for r in rs if str(r.get('store') or '').strip()}
    p_stores, o_stores, shown_stores = _stores_of(prows), _stores_of(orows), _stores_of(merged)
    stores_from_other = sorted(s for s in shown_stores if s and s not in p_stores)

    meta = {
        'primary': primary, 'other': other,
        'primary_rows': len(prows), 'other_rows': len(orows),
        'feed_rows': feed_rows, 'raw_rows': raw_rows,
        'filled_rows': fill_rows, 'filled_days': filled_days, 'filled_cells': len(filled_cells),
        'richer_rows': richer_rows, 'richer_days': richer_days, 'richer_cells': len(richer_cells),
        'shown_rows': len(merged),
        'completeness_rows': completeness_sales,
        'stores_shown': len(shown_stores), 'primary_stores': len(p_stores),
        'other_stores': len(o_stores), 'stores_from_other': len(stores_from_other),
    }
    return merged, meta


def _sales_rows_union_txn(client, org_id, period, cols=_SALES_DISPLAY_COLS):
    """TRANSACTION-grain union of daily_sales_feed and raw_sales, deduped by trans_id — the READ-side
    mirror of `_promote_feed_to_raw_sales`'s merge. The open-month PRIMARY source (`_open_month_source`;
    the feed for the open month) wins a WHOLE trans_id; the OTHER source contributes only transactions the
    primary lacks (`monthly_only` in promotion). Every LINE ITEM of a kept transaction is preserved
    (raw_sales/feed are line-item grain), so accessory / tax ext_price sums stay correct, and a trans_id
    present in BOTH tables is counted ONCE — never double-counted across sources.

    Differs from `_sales_rows_union` (per-DAY): this keeps a raw_sales transaction the feed doesn't have
    even on a day the feed also sold — the completeness the Daily-Targets actuals + Tax drill-down need.
    In the healthy feed-only state (raw_sales empty or fully promoted from the feed) the result is the feed
    verbatim → byte-identical to reading the feed alone. NEVER raises. Returns (rows, meta)."""
    primary, other = _open_month_source(client, org_id, period)

    def _q(table):
        try:
            return (client.schema('commcalc').table(table).select(cols)
                    .eq('org_id', org_id).in_('period', _pvariants(period))
                    .limit(200000).execute().data) or []
        except Exception as e:
            print(f"WARN _sales_rows_union_txn read of {table} failed: {e}")
            return []

    prows = _q(primary)
    orows = _q(other)
    ptids = {str(r.get('trans_id')).strip() for r in prows if str(r.get('trans_id') or '').strip()}
    # `monthly_only`: other-source transactions whose trans_id isn't in the primary (blank trans_id → ''
    # → not in ptids → kept, exactly as promotion keeps a blank-trans_id monthly row).
    extra = [r for r in orows if str(r.get('trans_id') or '').strip() not in ptids]
    merged = list(prows) + extra
    feed_rows = len(prows) if primary == 'daily_sales_feed' else len(orows)
    raw_rows = len(prows) if primary == 'raw_sales' else len(orows)
    meta = {
        'primary': primary, 'other': other,
        'primary_rows': len(prows), 'other_rows': len(orows),
        'feed_rows': feed_rows, 'raw_rows': raw_rows,
        'other_only_rows': len(extra), 'shown_rows': len(merged),
        'primary_trans': len(ptids),
    }
    return merged, meta


_ACTUALS_COLS = ("trans_id,trans_date,store,salesperson,user_login,contract_type,department,category,"
                 "product_desc,gp,ext_price,voided,trans_type")


# ── THE ONE shared per-(store, rep, day) sales aggregation ─────────────────────────────────────────
# The Sales Report, Executive MTD and Daily Targets ALL consume this single row-level pass so they can
# never disagree again (owner directive 2026-07-16: "the Sales Report is CORRECT — Exec MTD should take
# its cumulative numbers from there, and Daily Targets should flow from the Sales Report too"). Before
# this, each of the three had its OWN loop with slightly different rules — which is exactly how Exec MTD
# "kept taking data from somewhere" the Sales Report dropped (see the divergence table in the handoff):
#   • Exec counted activations PER LINE; the Sales Report counts DISTINCT trans_id (a 4-device AAL under
#     one trans_id was 4 in Exec, 1 in the Sales Report — the dominant inflation).
#   • Exec did NOT skip Return rows or the blank/'admin' rep; the Sales Report + Targets do.
#   • Exec classified activations from exec_metric_config tokens ("any non-blank contract_type = an
#     activation"); the Sales Report uses the shared classify_contract_type (recognized labels only).
#   • Exec measured accessory$ from its OWN exec_metric_config['accessory'] token match; the Sales
#     Report + Targets use the shared _is_accessory (the Classification-settings config).
# This function applies ONE canonical skip set + ONE classification (the shared classify_contract_type +
# _is_accessory, DISTINCT-trans_id counting) and returns per-cell bucket SETS + sums. Consumers roll it up
# their own way (Sales Report → the cell rows as-is; Exec MTD → by store / employee + an MTD date-cut +
# trending; Targets → by canonical store_code). Extension-only line metrics a single consumer needs (Exec
# phones / bill-payment / activation-fee / protect — b2bsoft per-line columns the Sales Report doesn't
# show; Targets box / bill-payment) are computed in the SAME pass so there is never a divergent second
# scan. Pure — no I/O, never raises. DISPLAY ONLY: the commission CALC path is deliberately NOT wired here.
# The Sales Report's set, now SHARED with the pay path (owner 2026-07-25) — gp_report.VOID_TOKENS
# HOLDS the single source of truth; _VOID_TOKENS is aliased (not re-declared) from the top-of-module
# import so the display aggregation below, the GP report's transparency map, and the pay path can
# never drift apart (Gate-1 follow-up ⑦, 2026-07-25). Value unchanged:
#   ('true', 'yes', '1', 'voided', 'void')
_VOID_TOKENS = _GP_VOID_TOKENS
# Default bill-payment product tokens (the historical hard-coded Boost/Xfinity walk-in-recharge tokens),
# matched by lower-cased CONTAINMENT on product_desc. Used ONLY when the org has no billpay_products config
# (mig 214) — an empty per-org list falls back to these so the house/Boost conversion stays byte-identical.
_BILLPAY_DEFAULT_TOKENS = ('boost rtr', 'xfinity prepaid refill')

# DISPLAY-ONLY auto-recognition of NON-PHONE ACTIVATION categories whose Contract Type labels the phone
# classifier (calculator.classify_contract_type, tuned to Boost handset labels) does not recognize (owner
# 2026-08-13, "luxelink activations don't match b2bsoft" — Diversey read 30 vs 49 because Home Internet /
# FiOS / Tablet activations resolved to None and dropped out of Total Activation). A Total-carrier B2B
# Month-To-Date report counts these as activations, so the store total has to as well. Substring, lower-cased
# — deliberately keyword-shaped (never "any non-blank label") so a stray non-activation type can't be swept
# in. See _resolve_ct_bucket for the strict gating that keeps the house/Boost org byte-identical.
# 'edge' = a carrier early-upgrade / device-lease activation (e.g. Verizon Edge); the b2bsoft MTD report
# counts it in Total Activation, so it belongs here (owner's Diversey breakdown 2026-08-13: 7 new act + 18
# port + 6 byod + 12 tablet + 5 home internet + 1 edge = 49).
_AUTO_ACT_CATEGORY_KEYS = ('home internet', 'home-internet', 'fixed wireless', 'fwa', 'fios', 'tablet', 'edge')


def _resolve_ct_bucket(ct, ct_map=None):
    """DISPLAY-path contract-type classification with a per-org override (mig 213). Returns
    'byod' | 'upgrade' | 'premium' | None — the SAME vocabulary as calculator.classify_contract_type.

    `ct_map` = the org's {stripped-lowercased contract_type : bucket} map from
    accessory_config['contract_type_map'] (bucket in 'premium'|'upgrade'|'byod'|'none'). A MAPPED value wins
    ('none' -> None, i.e. force-excluded); an UNMAPPED value falls back to the hard-coded classifier — so an
    empty map (the house/Boost default) is BYTE-IDENTICAL to calling classify_contract_type directly, and a
    tenant only needs to map the labels the hard-coded set misses. Pure; never raises.

    NON-PHONE ACTIVATION AUTO-COUNT (owner 2026-08-13). After an explicit map miss AND a phone-classifier
    miss, a CONFIG-DRIVEN tenant (one that maintains a non-empty contract_type_map) also gets the well-known
    non-phone activation categories in _AUTO_ACT_CATEGORY_KEYS (Home Internet / FiOS / Tablet / FWA)
    recognized as 'premium', so those activations count toward Total Activation the way the b2bsoft MTD report
    counts them. Three guards keep this safe:
      • The house/Boost org has an EMPTY map -> this branch is skipped -> BYTE-IDENTICAL (no house number
        moves). Only a tenant that has already opted into config-driven classification is affected.
      • It fires ONLY for a label the tenant did NOT explicitly map — so mapping a label to 'none' (or to any
        bucket) still wins and is the escape hatch to exclude a category on purpose.
      • It fires ONLY when the phone classifier found no signal, so 'Tablet Upgrade' stays 'upgrade' and
        'BYOD Home Internet' stays 'byod' (byod/upgrade are decided first in classify_contract_type).

    DISPLAY ONLY: used by _sales_cell_agg (Sales Report / Executive MTD / Daily Targets). The Boost payout
    path (calculator.classify_contract_type) and plan-mode payout (commission_engine) do NOT call this, so
    neither the map nor the auto-count ever moves a commission/payout number."""
    if ct_map:
        b = ct_map.get(str(ct or "").strip().lower())
        if b:
            return None if b == "none" else b
    base = classify_contract_type(ct)
    if base:
        return base
    # Config-driven tenants only (non-empty map): auto-count the non-phone activation categories the phone
    # classifier misses. Empty map (house/Boost) -> skipped -> byte-identical.
    if ct_map:
        cl = str(ct or "").strip().lower()
        if cl and any(k in cl for k in _AUTO_ACT_CATEGORY_KEYS):
            return 'premium'
    return None


def _line_cond_hit(cond, lines):
    """True if >=1 line satisfies `cond`: the line's <field> (case-insensitively) CONTAINS any of
    `contains_any` OR EQUALS any of `equals_any`. `field` is any row column (department / category /
    product_desc / trans_type / …), default product_desc. Pure; never raises."""
    if not isinstance(cond, dict):
        return False
    field = str(cond.get('field') or 'product_desc')
    # m1 (Gate-1): a STRING value (e.g. a SQL-seeded/hand-edited `contains_any:"Rtr"` that bypassed the
    # PUT sanitizer) must NOT be iterated per-CHARACTER (which would match 'r'/'t' substrings). Coerce a
    # bare string to a one-element list; a list/tuple to its string items; anything else -> [] (skip).
    def _as_pats(v):
        if isinstance(v, str):
            v = [v]
        if not isinstance(v, (list, tuple)):
            return []
        return [str(p).strip().lower() for p in v if str(p).strip()]
    pats = _as_pats(cond.get('contains_any'))
    eqs = _as_pats(cond.get('equals_any'))
    if not pats and not eqs:
        return False
    for l in lines:
        v = str(l.get(field) or '').strip().lower()
        if not v:
            continue
        if eqs and v in eqs:
            return True
        if pats and any(p in v for p in pats):
            return True
    return False


def _classify_blank_ct_txn(lines, rules):
    """Config-driven activation classification for a transaction whose Contract Type is BLANK, from OTHER
    line fields. `rules` = the org's accessory_config.activation_rules (mig 224); EMPTY => None (no-op =>
    Boost byte-identical). Each rule: {bucket:'premium'|'upgrade'|'byod', all_of:[cond,...],
    none_of:[cond,...]} where a cond = {field, contains_any:[...], equals_any:[...]} matched against ANY
    line. A rule FIRES when EVERY all_of cond is met by >=1 line AND NO none_of cond is met by any line.
    Rules are tried IN ORDER; the first that fires wins (config controls precedence — e.g. a BYOD
    'SIM without branded device' rule before the PREMIUM 'branded device + plan' rule). Returns the
    bucket or None. Pure; never raises."""
    if not rules:
        return None
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        bucket = str(rule.get('bucket') or '').strip().lower()
        if bucket not in ('premium', 'upgrade', 'byod'):
            continue
        alls = rule.get('all_of') or []
        if not alls or not all(_line_cond_hit(c, lines) for c in alls):
            continue
        if any(_line_cond_hit(c, lines) for c in (rule.get('none_of') or [])):
            continue
        return bucket
    return None


def _blank_ct_bucket_map(rows, ct_map, rules):
    """trans_id -> activation bucket for transactions with NO contract_type-based classification, via the
    per-org activation_rules (mig 224). Only fires for a tid where NO line resolves to premium/upgrade/byod
    through contract_type (so it NEVER overrides a labeled classification). EMPTY rules => {} => no-op =>
    Boost byte-identical. Pure; never raises."""
    if not rules:
        return {}
    txn, classed = {}, set()
    for r in rows:
        # m2 (Gate-1): a voided / Return line must not serve as activation EVIDENCE, and a voided
        # ct-labeled line must not mark its tid 'classed' (which would block the rescue). Same skip
        # rules as _sales_cell_agg / _classification_gaps.
        if str(r.get('voided') or '').strip().lower() in _VOID_TOKENS:
            continue
        if str(r.get('trans_type') or '').strip() == 'Return':
            continue
        t = str(r.get('trans_id') or '').strip()
        if not t:
            continue
        txn.setdefault(t, []).append(r)
        if _resolve_ct_bucket(str(r.get('contract_type') or ''), ct_map):
            classed.add(t)
    out = {}
    for t, lns in txn.items():
        if t in classed:
            continue
        b = _classify_blank_ct_txn(lns, rules)
        if b:
            out[t] = b
    return out


def _txn_activation_candidate(lines, acfg, is_excluded=None):
    """Could this blank-contract-type transaction PLAUSIBLY have been an activation? True when >=1 of its
    lines is neither EXCLUDED nor an ACCESSORY — i.e. something was sold that a contract type could have
    described. Pure; never raises.

    WHY THIS EXISTS (2026-08-09). A blank Contract Type is the NORMAL state for a transaction that was
    never an activation: a bill payment / airtime refill, or an accessory-only receipt. Counting those as
    "unclassified activations" told the Total Wireless tenant that 1009 of its 1303 August transactions
    needed mapping "so they count as activations" — when 930 of them were RTR bill payments, which the
    owner has ruled NEVER pay (2026-08-01, the payout_exclusion_map seed), and 78 more were accessory-only
    receipts. Acting on that note would have invented an activation rule that swept every bill payment
    into the activation count. The note has to earn its alarm, or it trains the owner to ignore it.

    NOTHING IS HARD-CODED HERE. All three tests are the tenant's own config, already curated elsewhere in
    this same page: `is_excluded` is the payout_exclusion_map predicate (the RTR rule is a seeded, editable,
    WORD-anchored config row — not a branch), the bill-payment list is `billpay_products`, and the accessory
    test is `_is_accessory`, the very classifier the report aggregates accessory revenue with. A tenant with
    none of them configured gets `is_excluded=None` + an empty accessory config, every line reads
    activation-capable, and the count is byte-identical to the old behaviour.

    An exclusion rule keyed on a column the DISPLAY projection does not carry (sku / tender_type) simply
    never hits — `exclusion_hit` skips a blank value — so this can only ever UNDER-suppress, never
    wrongly hide a real gap."""
    bp = (acfg or {}).get('billpay_products') or set()
    for l in lines or ():
        try:
            if is_excluded is not None and is_excluded(l):
                continue
            # The tenant's BILL-PAYMENT list, matched exactly as _sales_cell_agg matches it (explicit
            # picked products when configured, else the default tokens) so the note and the report's own
            # conversion metric can never disagree about what a walk-in recharge is.
            _p = str(l.get('product_desc') or '').strip().lower()
            if _p and (_p in bp if bp else any(_t in _p for _t in _BILLPAY_DEFAULT_TOKENS)):
                continue
            if _is_accessory(l.get('department'), l.get('category'), l.get('product_desc'), acfg):
                continue
        except Exception:
            return True   # a classifier error must SHOW the gap, never silently swallow it
        return True
    return False


def _classification_gaps(rows, acfg, is_excluded=None, want_samples=False, sample_cap=300):
    """Report-level VISIBILITY into activation-classification gaps so a tenant's activations never silently
    read 0 again. Over the (voided/Return-skipped) rows already in memory, returns:
      unrecognized_contract_types : [{contract_type, lines, transactions}] for NON-blank ct values that
        resolve to None (not activation/upgrade/byod, not a swap) -> map them in the ct-map.
      blank_ct_transactions : distinct tids with a blank-ct line and NO ct-based activation on any line.
      blank_ct_non_activation : of those, how many could not have been an activation at all — every line
        is either tenant-EXCLUDED (the RTR / bill-payment map) or an ACCESSORY. Reported, never alarmed
        on: mapping these would count bill payments as activations. See _txn_activation_candidate.
      blank_ct_unrecovered  : of those, how many are activation-CAPABLE, were not rescued by the per-org
        activation_rules, and therefore really are unclassified (still 0).
      rescued_by_rules      : how many blank-ct tids the activation_rules DID classify.
      note                  : a human sentence (or None) telling the owner exactly where to map them.
    DISPLAY ONLY. Pure; never raises. Empty everything (house/Boost, no blank/unknown labels) -> note None.

    want_samples (2026-08-14): the counts alone tell the owner "7 unclassified" but not WHICH 7 or their
    line shape, so they cannot author the activation rule the note asks for (the "see the unmatched
    transactions" blind spot). When True this ALSO returns the ACTUAL unrecovered transactions — built from
    the SAME `unrecovered` tid set this function already derives (single source of truth; the classifier is
    never re-run or re-implemented for the listing):
      blank_ct_unrecovered_by_line : [{store, department, category, product_desc, lines, transactions}]
        grouped over every line of the unrecovered transactions, most-frequent first — the field/value
        vocabulary the owner ticks into an activation rule (dept 'BrandedHandset' + dept 'Rtr' -> premium).
      blank_ct_unrecovered_txns : [{trans_id, store, trans_date, lines:[{department,category,product_desc}]}]
        (capped at sample_cap) so the owner can eyeball intact transaction shapes.
    NOTE: the Sales-Report DISPLAY projection (_SALES_DISPLAY_COLS) carries no tender_type, so tender is not
    surfaced here — the blank-ct activation rules match on department/category/product_desc/trans_type, which
    are exactly the fields returned."""
    from collections import Counter
    ct_map = (acfg or {}).get('contract_type_map')
    rules = (acfg or {}).get('activation_rules') or []
    blank_bucket = _blank_ct_bucket_map(rows, ct_map, rules)
    unrec_lines, unrec_txn = Counter(), {}
    txn_blank, txn_classed = set(), set()
    lines_by_tid = {}
    for r in rows:
        if str(r.get('voided') or '').strip().lower() in _VOID_TOKENS:
            continue
        if str(r.get('trans_type') or '').strip() == 'Return':
            continue
        tid = str(r.get('trans_id') or '').strip()
        ct = str(r.get('contract_type') or '').strip()
        if tid:
            lines_by_tid.setdefault(tid, []).append(r)
        cls = _resolve_ct_bucket(ct, ct_map)
        if cls:
            if tid:
                txn_classed.add(tid)
        elif ct:
            # A label the tenant EXPLICITLY mapped to 'none' is a DELIBERATE exclusion, not a gap — don't
            # nag them to "map it so it counts" (it resolves to None on purpose). Swaps are likewise not an
            # activation gap. Everything else that resolves to None with a non-blank label is unrecognized.
            _explicit_none = bool(ct_map) and ct_map.get(ct.lower()) == 'none'
            if 'swap' not in ct.lower() and not _explicit_none:
                unrec_lines[ct] += 1
                if tid:
                    unrec_txn.setdefault(ct, set()).add(tid)
        elif tid:
            txn_blank.add(tid)
    txn_blank -= txn_classed
    # A transaction that could never have BEEN an activation (bill-payment / accessory-only) is not a
    # mapping gap — see _txn_activation_candidate. Counted and returned, but never alarmed on.
    non_act = {t for t in txn_blank
               if not _txn_activation_candidate(lines_by_tid.get(t), acfg, is_excluded)}
    unrecovered = sorted(t for t in txn_blank if t not in blank_bucket and t not in non_act)
    unrecognized = sorted(
        [{'contract_type': ct, 'lines': n, 'transactions': len(unrec_txn.get(ct, set()))}
         for ct, n in unrec_lines.items()], key=lambda x: -x['lines'])
    parts = []
    if unrecovered:
        parts.append(f"{len(unrecovered)} transaction(s) have no contract type and no activation rule matched")
    if unrecognized:
        _top = ', '.join(f"{u['contract_type']}×{u['transactions']}" for u in unrecognized[:5])
        parts.append(f"{len(unrecognized)} contract-type value(s) are unrecognized ({_top})")
    note = None
    if parts:
        note = ('; '.join(parts) + ' — map them in Sales Report ⚙ Classification (contract-type map / '
                'blank-contract-type activation rules) so they count as activations.')
    out = {'unrecognized_contract_types': unrecognized,
           'blank_ct_transactions': len(txn_blank),
           'blank_ct_non_activation': len(non_act),
           'blank_ct_unrecovered': len(unrecovered),
           'rescued_by_rules': len(blank_bucket),
           'note': note}
    if want_samples:
        # The ACTUAL unrecovered transactions, built from the SAME `unrecovered` tid set above — never a
        # second classifier pass. `unrecovered` is already sorted (deterministic), so the per-txn cap is
        # stable across calls. Grouped by the fields an activation rule matches on so the owner reads off
        # exactly what to tick. Store comes from the first line of the transaction.
        by_line, line_tids = Counter(), {}
        txns = []
        for t in unrecovered:
            lns = lines_by_tid.get(t) or []
            store = ''
            for _l in lns:
                if str(_l.get('store') or '').strip():
                    store = str(_l.get('store')).strip()
                    break
            if len(txns) < sample_cap:
                txns.append({'trans_id': t, 'store': store,
                             'trans_date': (str((lns[0].get('trans_date') if lns else '') or '')),
                             'lines': [{'department': str(_l.get('department') or '').strip(),
                                        'category': str(_l.get('category') or '').strip(),
                                        'product_desc': str(_l.get('product_desc') or '').strip()}
                                       for _l in lns]})
            for _l in lns:
                k = (store, str(_l.get('department') or '').strip(),
                     str(_l.get('category') or '').strip(), str(_l.get('product_desc') or '').strip())
                by_line[k] += 1
                line_tids.setdefault(k, set()).add(t)
        out['blank_ct_unrecovered_by_line'] = sorted(
            [{'store': k[0], 'department': k[1], 'category': k[2], 'product_desc': k[3],
              'lines': n, 'transactions': len(line_tids.get(k, set()))}
             for k, n in by_line.items()],
            key=lambda x: (-x['transactions'], -x['lines']))
        out['blank_ct_unrecovered_txns'] = txns
    return out


_STORE_STREET_SUFFIX = {
    "ave", "avenue", "st", "street", "rd", "road", "blvd", "boulevard", "ln", "lane", "dr", "drive",
    "ct", "court", "pl", "place", "way", "hwy", "highway", "pkwy", "parkway", "ter", "terrace", "cir",
    "circle", "ste", "suite", "unit", "apt", "fl", "floor", "rm", "room", "bldg", "building",
    "n", "s", "e", "w", "north", "south", "east", "west", "ne", "nw", "se", "sw",
}


def _store_lead_num(s):
    m = re.match(r"\s*(\d+)", str(s or ""))
    return m.group(1) if m else ""


def _store_street_tokens(s):
    """Non-numeric, non-suffix STREET-NAME tokens of a store string (for the leading-number merge
    guard): '957 Pennsylvania Ave' -> {'pennsylvania'}. Pure."""
    toks = [t for t in re.split(r"[^a-z0-9]+", str(s or "").lower()) if t]
    return {t for t in toks if not t.isdigit() and t not in _STORE_STREET_SUFFIX}


def _canonical_store_key_fn(client, org_id):
    """Return store_str -> canonical GROUPING key for the DISPLAY aggregation, so spelling variants of
    ONE store ('957 Pennsylvania Ave' / 'Avenue', case, whitespace) collapse to a single Sales-Report /
    Exec-MTD row, while two GENUINELY DIFFERENT stores stay split. org-scoped, config-driven (no
    hard-coded store names). NEVER raises — degrades to _cell_store_key (case/whitespace fold) on any
    error, and an org with NO store_mapping/aliases is exactly _cell_store_key (Boost byte-identical).

    Resolution precedence (self-contained on _store_maps — deliberately NOT coa's leading-number step,
    which false-merges different streets that share a house number on a PARTIALLY-mapped org — Gate-1 M1):
      0) EXPLICIT match — the store's _cell_store_key hits a store_alias / store_mapping address /
         storeops address (whitespace-insensitive: keys are _cell_store_key'd, closing the n1
         double-space case), OR the string already IS a store_code → that code's key. Explicit mappings
         are trusted verbatim (an owner alias may legitimately have no token overlap, e.g. a nickname).
      1) GUARDED leading-number — only when EXACTLY ONE mapped code carries the input's house number AND
         the input shares >=1 STREET-NAME token (suffixes/directionals dropped) with that code's
         address. "957 pennsylvania ave" ∩ "957 pennsylvania avenue" = {pennsylvania} ✓ (merge);
         "100 oak ave" vs the only-mapped "100 main st" = ∅ ✗ (stay SPLIT).
      2) otherwise _cell_store_key(store) (fold only) — never a false merge."""
    try:
        M = _store_maps(client, org_id)
    except Exception:
        M = None
    if not M:
        return _cell_store_key
    addr_to_code = M.get("addr_to_code") or {}
    so_addr_to_code = M.get("so_addr_to_code") or {}
    alias_to_code = M.get("alias_to_code") or {}
    so_codes = {str(c).upper() for c in (M.get("so_codes") or set())}
    # explicit lookup keyed on _cell_store_key (whitespace-insensitive) → store_code
    explicit = {}
    for _src in (addr_to_code, so_addr_to_code, alias_to_code):
        for _a, _c in _src.items():
            if _a and _c:
                explicit[_cell_store_key(_a)] = _c
    # leading-number index + per-code street tokens (from the mapped addresses only)
    num_to_codes, code_tokens = {}, {}
    for _a, _c in list(so_addr_to_code.items()) + list(addr_to_code.items()):
        _n = _store_lead_num(_a)
        if _n:
            num_to_codes.setdefault(_n, set()).add(_c)
        code_tokens.setdefault(_c, set()).update(_store_street_tokens(_a))

    def _key(store):
        raw_fold = _cell_store_key(store)
        try:
            # 0) explicit alias / mapped address (whitespace-insensitive)
            if raw_fold in explicit:
                return _cell_store_key(explicit[raw_fold])
            # 0c) the string already IS a store_code
            if str(store or "").strip().upper() in so_codes:
                return raw_fold
            # 1) GUARDED leading-number — unambiguous house-number + shared street-name token
            _n = _store_lead_num(store)
            _codes = num_to_codes.get(_n) if _n else None
            if _codes and len(_codes) == 1:
                _c = next(iter(_codes))
                if _store_street_tokens(store) & (code_tokens.get(_c) or set()):
                    return _cell_store_key(_c)
            return raw_fold
        except Exception:
            return raw_fold
    return _key


def _sales_cell_agg(rows, acfg, exec_cfg=None, store_key=None):
    """Aggregate raw sales lines → {(store, rep, day): cell}. `acfg` = _accessory_config(...) (the ONE
    accessory classifier). `exec_cfg` (optional _exec_metric_config result) turns ON the Executive-MTD
    extension line-metrics + the configurable Port sub-split; when None those are skipped (Sales Report /
    Targets). See the block comment above."""
    act_rules = (exec_cfg.get('activation', {}) or {}).get('rules', {}) if exec_cfg else {}
    # Per-org contract-type -> bucket override (mig 213); empty for the house -> byte-identical classifier.
    ct_map = acfg.get('contract_type_map') if acfg else None
    # Per-org bill-payment product membership (mig 214). A set of lowercased product values; NON-empty ->
    # case-insensitive EXACT match on product_desc; empty/unset -> the hard-coded Boost-token fallback below
    # (house conversion byte-identical). See _accessory_config + _BILLPAY_DEFAULT_TOKENS.
    billpay_products = acfg.get('billpay_products') if acfg else None
    # Per-org blank-contract_type activation rules (mig 224). A tid appears here ONLY when no line of it
    # classifies via contract_type — so this SUPPLEMENTS, never overrides, the ct classifier. Empty rules
    # (the house/Boost default) -> {} -> the supplement below is a no-op (BYTE-IDENTICAL).
    _act_rules = acfg.get('activation_rules') if acfg else None
    blank_bucket = _blank_ct_bucket_map(rows, ct_map, _act_rules)
    agg = {}
    for r in rows:
        # ── THE canonical skip rules — shared by all three (was three slightly different predicates).
        if str(r.get('voided') or '').strip().lower() in _VOID_TOKENS:
            continue
        if str(r.get('trans_type') or '').strip() == 'Return':
            continue
        rep = str(r.get('salesperson') or '').strip()
        if not rep or rep.lower() == 'admin':
            continue
        store = str(r.get('store') or '').strip()
        # Canonical store GROUPING key (P0 double-listing fix): `store_key` (from the caller — the shipped
        # _store_code_resolver → _cell_store_key) collapses spelling variants of ONE store ('957
        # Pennsylvania Ave' / 'Avenue', case, whitespace) into a single group so a store can't render as
        # two rows. DEFAULT None => the raw stripped string => BYTE-IDENTICAL to before. The DISPLAY name
        # stays the first-seen RAW spelling (drill-down matches the DB value normalized).
        sk = store_key(store) if store_key else store
        date = str(r.get('trans_date') or '')[:10]
        tid = str(r.get('trans_id') or '').strip()
        ct = str(r.get('contract_type') or '')
        ctl = ct.lower()
        dept = str(r.get('department') or '').strip()
        ext = safe_float(r.get('ext_price'))
        gp = safe_float(r.get('gp'))
        k = (sk, rep, date)
        a = agg.get(k)
        if not a:
            a = agg[k] = {'store': store, 'salesperson': rep, 'trans_date': date, 'login': None,
                          '_txn': set(), '_prem': set(), '_byod': set(), '_upg': set(),
                          '_port': set(), '_swap': set(), '_billpay': set(),
                          'lines': 0, 'revenue': 0.0, 'gp': 0.0, 'accessory_rev': 0.0, 'setup_fee_rev': 0.0,
                          'box_count': 0,
                          'total_phones': 0, 'bill_qty': 0, 'bill_amt': 0.0, 'activation_fee': 0.0,
                          'protect': 0}
        if a['login'] is None and r.get('user_login'):
            a['login'] = r.get('user_login')
        if tid:
            a['_txn'].add(tid)
        a['lines'] += 1
        a['revenue'] += ext
        a['gp'] += gp
        # SHARED activation classifier (money-adjacent; identical to commissions + targets), DISTINCT-txn.
        # Config-driven per-org override (mig 213) wins for a mapped label; else the hard-coded classifier.
        _cls = _resolve_ct_bucket(ct, ct_map)
        if tid and _cls == 'byod':
            a['_byod'].add(tid)
        elif tid and _cls == 'upgrade':
            a['_upg'].add(tid)
        elif tid and _cls == 'premium':
            a['_prem'].add(tid)
            # Port is a SUB-split of premium/activation (never a redefinition of it) — the token stays
            # exec_metric_config-configurable; only needed when exec_cfg is present (Exec MTD).
            if exec_cfg and _exec_act_class(ct, act_rules) == 'port':
                a['_port'].add(tid)
        elif tid and not _cls and tid in blank_bucket:
            # Blank-contract_type transaction rescued by the per-org activation_rules (mig 224). DISTINCT-
            # txn like the ct branches; the tid was proven above to have NO ct classification on any line.
            _bb = blank_bucket[tid]
            if _bb == 'byod':
                a['_byod'].add(tid)
            elif _bb == 'upgrade':
                a['_upg'].add(tid)
            elif _bb == 'premium':
                a['_prem'].add(tid)
        # Swaps — distinct-txn, contract_type contains 'swap' (independent tally; changes none of the above).
        if tid and 'swap' in ctl:
            a['_swap'].add(tid)
        # Accessory$ — the ONE shared _is_accessory classifier (all three agree; Exec MTD no longer uses
        # its own exec_metric_config['accessory'] token match for the number — see the handoff note).
        # DEVICE SET-UP FEE (mig 217) is tallied in its OWN accumulator, SEPARATE from accessory_rev, and
        # is EXCLUDED from accessory_rev so the two never double-count when the targets attainment folds
        # them together (accessory_rev + setup_fee_rev). For the house/Boost org the set-up-fee line lives
        # in a fee/'other' department (not the accessory department), so `not _setup` never removes an
        # accessory line → accessory_rev stays BYTE-IDENTICAL (Sales Report / Exec MTD / productivity
        # unchanged). Pre-217 / empty config → _is_setup_fee is False → no-op.
        _setup = _is_setup_fee(r.get('product_desc'), acfg)
        if _setup:
            a['setup_fee_rev'] += ext
        elif _is_accessory(dept, r.get('category'), r.get('product_desc'), acfg):
            a['accessory_rev'] += ext
        # Targets extension metrics. BOX departments are now CONFIG-DRIVEN (mig 218; acfg['box_departments'],
        # default = _BOX_DEPTS → house byte-identical) so boxes count correctly for non-Boost tenants across
        # every surface that shares this aggregation (Sales Report / conversion / Productivity / Review).
        if dept in (acfg.get('box_departments') or _BOX_DEPTS):
            a['box_count'] += 1
        _pl = str(r.get('product_desc') or '').lower()
        # Bill-payment membership is CONFIG-DRIVEN per org (mig 214; acfg['billpay_products']). When the org
        # has a NON-empty configured list, a line is a bill payment iff its product_desc EXACTLY matches
        # (case-insensitive) a configured value — the values are PICKED from the org's observed sales product
        # descriptions (RULE THREE), not typed substrings, so exact match is correct. When the list is
        # EMPTY/unset (or the column is missing pre-214 → _accessory_config returns an empty set), fall back
        # to the EXACT historical Boost tokens with the EXACT historical lower-cased CONTAINMENT semantics →
        # the house/Boost conversion stays byte-identical with no config set. This changes ONLY which lines
        # are counted as billpays; the conversion FORMULA (boxes ÷ billpays, in targets_engine) is unchanged.
        # DISPLAY ONLY — feeds the Daily-Targets conversion display, never a payout.
        if tid:
            if billpay_products:
                if _pl.strip() in billpay_products:
                    a['_billpay'].add(tid)
            elif any(_tok in _pl for _tok in _BILLPAY_DEFAULT_TOKENS):
                a['_billpay'].add(tid)
        # Executive-MTD extension LINE metrics — b2bsoft per-line columns (phones / bill payment /
        # activation fee / protect) the Sales Report doesn't carry, so they have NO equality requirement;
        # computed only when exec_cfg is supplied (config-driven, SAP-configurable, unchanged semantics).
        if exec_cfg:
            _d, _c = dept.lower(), str(r.get('category') or '').strip().lower()
            if _exec_line_match(exec_cfg['phones']['rules'], _d, _c, _pl):
                a['total_phones'] += 1
            if _exec_line_match(exec_cfg['bill_payment']['rules'], _d, _c, _pl):
                a['bill_qty'] += 1
                a['bill_amt'] += ext
            if _exec_line_match(exec_cfg['activation_fee']['rules'], _d, _c, _pl):
                a['activation_fee'] += ext
            if _exec_line_match(exec_cfg['protect']['rules'], _d, _c, _pl):
                a['protect'] += 1
    # "Total boxes sold" contribution from activation buckets (mig 231; owner 2026-07-24 — count the
    # customer-phone / BYOD activation as a box). box_count is otherwise a DEVICE-LINE tally; here we add
    # the DISTINCT-transaction count of each configured bucket (byod/upgrade/premium) so the metric tallies
    # to the owner's expectation across EVERY surface that reads box_count (Sales-Report box count, Daily-
    # Targets conversion + attainment, Productivity / Stack-Ranking / Review). A BYOD transaction carries NO
    # device-department line, so this never double-counts an existing box. Empty set (house/Boost default,
    # or pre-231) → no-op → BYTE-IDENTICAL. Exec MTD's "trending box" already = total activations (incl.
    # BYOD) and does not read box_count, so this ALIGNS the box-count surfaces with Exec MTD.
    _bcb = (acfg.get('box_count_buckets') if acfg else None) or set()
    if _bcb:
        for a in agg.values():
            if 'byod' in _bcb:
                a['box_count'] += len(a['_byod'])
            if 'upgrade' in _bcb:
                a['box_count'] += len(a['_upg'])
            if 'premium' in _bcb:
                a['box_count'] += len(a['_prem'])
    return agg


def _store_maps(client, org_id):
    """Build the org's store-resolution maps ONCE, shared by _store_code_resolver AND the Store-Matching
    UI's /store-resolution report — so the resolver and the audit view can NEVER disagree. Returns:
      addr_to_code    : commcalc.store_mapping  store_address(lower) -> store_code   (house canon)
      so_addr_to_code : storeops.stores         address(lower)       -> store_code   (the org's roster)
      so_codes        : {store_code upper}       — a raw string that already IS a code is preserved
      alias_to_code   : commcalc.store_aliases   alias(lower)        -> store_code   (the EXPLICIT per-org
                        mapping — the Store-Matching UI's source of truth; validated against a REAL code so a
                        stale/typo code can never hijack resolution)
      stores          : [{store_code, address, market, source}] — the org's canonical roster (store_mapping
                        UNION storeops.stores) for pick-don't-type dropdowns + smart suggestions
      resolve_store   : coa.store_resolver (raw -> canonical store_address) or None
    Org-scoped; never raises."""
    try:
        from app.modules.account import coa
        resolve_store = coa.store_resolver(client, org_id)
    except Exception:
        resolve_store = None
    try:
        sm = (client.schema('commcalc').table('store_mapping')
              .select('store_code,store_address,market').eq('org_id', org_id).execute().data) or []
    except Exception:
        sm = []
    addr_to_code, stores, seen_codes = {}, [], set()
    for m in sm:
        a = (m.get('store_address') or '').strip().lower()
        c = (m.get('store_code') or '').strip()
        if a and c:
            addr_to_code[a] = c
        if c and c.upper() not in seen_codes:
            seen_codes.add(c.upper())
            stores.append({'store_code': c, 'address': (m.get('store_address') or '').strip(),
                           'market': (m.get('market') or '').strip(), 'source': 'store_mapping'})
    # storeops.stores roster (the Daily-Targets join target). so_addr_to_code: address -> store_code;
    # so_codes: valid store_codes (upper) so a raw string that IS already a storeops code is preserved.
    so_addr_to_code, so_codes = {}, set()
    try:
        so = (client.schema('storeops').table('stores')
              .select('store_code,address,market').eq('org_id', org_id).execute().data) or []
    except Exception:
        so = []
    for s in so:
        c = (s.get('store_code') or '').strip()
        a = (s.get('address') or '').strip().lower()
        if c:
            so_codes.add(c.upper())
            if a:
                so_addr_to_code[a] = c
            if c.upper() not in seen_codes:
                seen_codes.add(c.upper())
                stores.append({'store_code': c, 'address': (s.get('address') or '').strip(),
                               'market': (s.get('market') or '').strip(), 'source': 'storeops'})
    # explicit per-org mapping — keyed on the raw POS/sales-store spelling; a code must be a REAL store
    # (store_mapping OR storeops) or it is ignored (falls through to today's behaviour).
    valid_codes = set(so_codes) | {c.upper() for c in addr_to_code.values()}
    alias_to_code = {}
    try:
        al = (client.schema('commcalc').table('store_aliases')
              .select('alias,store_code').eq('org_id', org_id).execute().data) or []
    except Exception:
        al = []
    for a in al:
        k = (a.get('alias') or '').strip().lower()
        c = (a.get('store_code') or '').strip()
        if k and c and c.upper() in valid_codes:
            alias_to_code[k] = c
    return {'addr_to_code': addr_to_code, 'so_addr_to_code': so_addr_to_code, 'so_codes': so_codes,
            'alias_to_code': alias_to_code, 'stores': stores, 'resolve_store': resolve_store}


def _store_code_resolver(client, org_id):
    """Return resolve(store_string) -> canonical store_code — the SAME mapping the Daily-Targets actuals +
    trending use so a store's sales/Exec-MTD numbers attach to the matching target row.

    Precedence (UNCHANGED order — explicit mapping → canonical → exact storeops fallback):
      0. EXPLICIT per-org mapping (commcalc.store_aliases, the Store-Matching UI) — the SOURCE OF TRUTH,
         consulted FIRST so a confirmed POS-string→store mapping wins for EVERY tenant, incl. one with no
         commcalc.store_mapping (luxelink). Without this, coa.store_resolver drops such an alias — its
         alias→address step needs a store_mapping code — so a luxelink admin's confirmed mapping was inert
         and the store could only resolve via the exact-address storeops fallback (the silent-shift risk).
         House BYTE-IDENTICAL: its seeded/confirmed aliases all carry store_mapping codes → same code today.
      1. coa.store_resolver (exact address → store_aliases→code → leading number) → commcalc.store_mapping
         address→code — UNCHANGED (house byte-identical).
      2. store_mapping MISS → the org's OWN storeops.stores roster (EXACT address / store_code match) — the
         Gate-1-flagged fallback: still runs, but now VISIBLE in the Store-Matching UI as 'exact-fallback'
         with a one-click "confirm as mapping" so the house can prove its map covers every POS string.

    Superset-only: it NEVER overrides an existing store_mapping resolution. DISPLAY-ONLY (two callers:
    _compute_feed_actuals_py + _targets_trending_by_code, both Daily Targets). An org with no store_aliases
    rows is byte-identical to before (step 0 is a no-op). Never raises; falls back to the cleaned raw string
    when nothing resolves."""
    M = _store_maps(client, org_id)
    addr_to_code, so_addr_to_code = M['addr_to_code'], M['so_addr_to_code']
    so_codes, alias_to_code, _resolve_store = M['so_codes'], M['alias_to_code'], M['resolve_store']

    def _resolve(store):
        raw = str(store or '').strip().lower()
        canon = (_resolve_store(store) if (_resolve_store and store) else None) or store
        ck = str(canon).strip().lower()
        # 0) EXPLICIT per-org mapping WINS (raw POS spelling first, then the canonicalized spelling).
        if raw and raw in alias_to_code:
            return alias_to_code[raw]
        if ck and ck in alias_to_code:
            return alias_to_code[ck]
        # 1) existing store_mapping hit — UNCHANGED (house byte-identical).
        if ck in addr_to_code:
            return addr_to_code[ck]
        # 2) store_mapping MISS → try the storeops roster: canon-as-address, raw-as-address, then
        #    canon/raw already-a-code. Only ADDS resolutions where the raw string was previously returned.
        if ck and ck in so_addr_to_code:
            return so_addr_to_code[ck]
        if raw and raw in so_addr_to_code:
            return so_addr_to_code[raw]
        if ck and str(canon).strip().upper() in so_codes:
            return str(canon).strip()
        if raw and raw.upper() in so_codes:
            return str(store).strip()
        return canon
    return _resolve


_STORE_SUITE_TOKENS = {'ste', 'suite', 'unit', 'apt', 'apartment', 'fl', 'floor', 'rm', 'room',
                       'bldg', 'building', 'no', 'num'}


def _norm_store_match(s):
    """Deterministic normalization for smart store matching (case-insensitive everywhere): case-fold, strip
    punctuation to spaces, drop suite/unit tokens (+ the number that follows) and standalone '#5', collapse
    whitespace. Pure — same input always yields the same output."""
    s = (s or '').lower()
    s = re.sub(r'#\s*\w+', ' ', s)                 # '#5', '# 12b'
    s = re.sub(r'[^a-z0-9 ]+', ' ', s)             # punctuation -> space
    toks = [t for t in s.split() if t]
    out, skip_next_num = [], False
    for t in toks:
        if t in _STORE_SUITE_TOKENS:
            skip_next_num = True
            continue
        if skip_next_num and re.fullmatch(r'\d+[a-z]?', t):
            skip_next_num = False
            continue
        skip_next_num = False
        out.append(t)
    return ' '.join(out).strip()


def _store_leading_num(s):
    m = re.match(r'\s*(\d+)', s or '')
    return m.group(1) if m else None


def _store_suggest(raw, stores, top=3):
    """Ranked candidate store matches for an observed POS store string — DETERMINISTIC, never auto-applied
    (the UI turns a confirm into an explicit mapping). `stores` = [{store_code, address, market, ...}].
    Score blends exact-normalized address match, leading street-number match, token overlap, and literal
    store-code containment. Returns up to `top` {store_code, store_address, market, confidence, score,
    reason}, sorted (score desc, then store_code asc) so ties are stable."""
    pn = _norm_store_match(raw)
    ptoks = set(pn.split())
    pnum = _store_leading_num(pn)
    praw_up = (raw or '').strip().upper()
    out = []
    for st in stores:
        code = (st.get('store_code') or '').strip()
        addr = (st.get('address') or st.get('store_address') or '').strip()
        cn = _norm_store_match(addr)
        ctoks = set(cn.split())
        reasons, score = [], 0.0
        if pn and cn and pn == cn:
            score = 1.0
            reasons.append('exact address (normalized)')
        else:
            cnum = _store_leading_num(cn)
            num_ok = bool(pnum and cnum and pnum == cnum)
            jac = (len(ptoks & ctoks) / len(ptoks | ctoks)) if (ptoks or ctoks) else 0.0
            score = 0.55 * (1.0 if num_ok else 0.0) + 0.45 * jac
            if num_ok:
                reasons.append(f'street # {pnum}')
            if ptoks & ctoks:
                reasons.append(f'{len(ptoks & ctoks)} word(s) in common')
        if code and code.upper() in praw_up:
            score = max(score, 0.9)
            reasons.append(f'contains code {code}')
        if score <= 0:
            continue
        conf = ('exact' if score >= 0.999 else 'high' if score >= 0.7 else
                'medium' if score >= 0.4 else 'low')
        out.append({'store_code': code, 'store_address': addr, 'market': st.get('market', ''),
                    'confidence': conf, 'score': round(score, 3),
                    'reason': ', '.join(reasons) or 'weak match'})
    out.sort(key=lambda x: (-x['score'], x['store_code']))
    return out[:top]


_STORE_STATUS_ORDER = {'unresolved': 0, 'exact-fallback': 1, 'store_mapping': 2, 'explicit': 3}


def _store_resolution_report(client, org_id, period=None, limit=60000):
    """The Store-Matching UI data: every OBSERVED distinct POS/sales store string in the org's sales + feed
    data, with its CURRENT resolution status — one of:
      explicit       : an explicit commcalc.store_aliases mapping resolves it (the source of truth)
      store_mapping  : resolves via commcalc.store_mapping (the house canon)
      exact-fallback : resolves ONLY via the exact storeops.stores address/code fallback (the Gate-1 concern
                       — VISIBLE here so the house can confirm-as-mapping and remove the ambiguity)
      unresolved     : nothing resolves it → needs a mapping (top smart suggestion shown)
    plus the code it resolves to and, for anything not already explicit, ranked smart suggestions. The status
    order MIRRORS _store_code_resolver step-for-step (shared _store_maps) so the audit view cannot drift from
    the resolver. Read-only; org-scoped; never raises."""
    M = _store_maps(client, org_id)
    addr_to_code, so_addr_to_code = M['addr_to_code'], M['so_addr_to_code']
    so_codes, alias_to_code, _resolve_store = M['so_codes'], M['alias_to_code'], M['resolve_store']
    stores = M['stores']
    seen = {}
    srcs = [('raw_sales', 'store'), ('daily_sales_feed', 'store')]
    for table, col in srcs:
        try:
            q = client.schema('commcalc').table(table).select(col).eq('org_id', org_id)
            if period:
                q = q.in_('period', _pvariants(period))
            rows = (q.limit(limit).execute().data) or []
        except Exception:
            continue   # table missing / no org_id → skip that source
        for r in rows:
            v = (r.get(col) or '').strip()
            if not v:
                continue
            e = seen.setdefault(v.lower(), {'raw': v, 'sources': set()})
            e['sources'].add(table)
    items, counts = [], {'explicit': 0, 'store_mapping': 0, 'exact-fallback': 0, 'unresolved': 0}
    for e in seen.values():
        raw = e['raw']
        low = raw.strip().lower()
        canon = (_resolve_store(raw) if (_resolve_store and raw) else None) or raw
        ck = str(canon).strip().lower()
        if low in alias_to_code:
            status, code = 'explicit', alias_to_code[low]
        elif ck in alias_to_code:
            status, code = 'explicit', alias_to_code[ck]
        elif ck in addr_to_code:
            status, code = 'store_mapping', addr_to_code[ck]
        elif ck and ck in so_addr_to_code:
            status, code = 'exact-fallback', so_addr_to_code[ck]
        elif low in so_addr_to_code:
            status, code = 'exact-fallback', so_addr_to_code[low]
        elif str(canon).strip().upper() in so_codes:
            status, code = 'exact-fallback', str(canon).strip()
        elif low.upper() in so_codes:
            status, code = 'exact-fallback', raw.strip()
        else:
            status, code = 'unresolved', None
        counts[status] = counts.get(status, 0) + 1
        sugg = [] if status == 'explicit' else _store_suggest(raw, stores, top=3)
        items.append({'raw': raw, 'sources': sorted(e['sources']), 'status': status,
                      'resolved_code': code, 'suggestions': sugg})
    items.sort(key=lambda x: (_STORE_STATUS_ORDER.get(x['status'], 9), x['raw'].lower()))
    return {'items': items, 'counts': counts, 'total': len(items),
            'stores': [{'store_code': s['store_code'], 'store_address': s['address'],
                        'market': s.get('market', '')} for s in stores],
            'sources_scanned': [s[0] for s in srcs]}


def _compute_feed_actuals_py(client, org_id, period, source='daily_sales_feed', rows=None):
    """The ONE processed sales source, computed in Python so the whole targets/recon system agrees.

    Mirrors the daily_sales_feed_actuals RPC BUT (a) is period-spelling agnostic (_pvariants), and
    (b) classifies contract_type by CONTAINS — anything with 'byod' is BYOD, 'upgrade' is an upgrade,
    any other non-empty Contract Type is an activation — instead of a rigid hardcoded label list. That
    is what fixes "activations/accessories show 0" when B2B's Contract Type labels drift from the exact
    strings the SQL function hardcodes (the July Action-Plan bug). Reads `source` (the daily feed),
    falling back to raw_sales — UNLESS the caller passes a pre-built `rows` set (e.g. the trans-id-deduped
    feed∪raw_sales union from _fetch_actuals), in which case those rows are aggregated as-is. Returns the
    same shape targets_engine expects."""
    cols = _ACTUALS_COLS

    if rows is None:
        def _q(table):
            return (client.schema('commcalc').table(table).select(cols)
                    .eq('org_id', org_id).in_('period', _pvariants(period)).limit(200000).execute().data) or []
        rows = _q(source)
        if not rows and source != 'raw_sales':
            try:
                rows = _q('raw_sales')
            except Exception:
                rows = []
    if not rows:
        return []
    acfg = _accessory_config(client, org_id)
    # Canonicalize the feed's store string through the SAME resolver the P&L / Store-Matching UI use
    # (exact address → store_aliases → store_code → unambiguous leading number). Without this the actuals
    # key on the RAW feed spelling (e.g. "3 Palisade Ave Yonkers") while the Daily Target keys on the
    # canonical store_code (B-3PL) → scope_achieved_mtd matches nothing → the store shows 0 activations
    # even though its sales are in the feed. Any store needing an alias/leading-number was silently 0.
    _resolve_code = _store_code_resolver(client, org_id)
    # THE shared per-(store, rep, day) pass — identical skip rules + classification + distinct-txn counting
    # as the Sales Report + Executive MTD (see _sales_cell_agg). Targets then re-keys each cell to the
    # canonical store_code (so scope_achieved_mtd matches the Daily Target's store_code) and rep.upper(),
    # merging any raw-store spellings that resolve to the same code by UNIONing the distinct-txn sets.
    cells = _sales_cell_agg(rows, acfg, store_key=_canonical_store_key_fn(client, org_id))
    agg = {}
    for (store, rep, date), a in cells.items():
        if not date:
            continue
        # `store` is now the canonical grouping key; resolve the code off the display RAW spelling.
        code = _resolve_code(a.get('store') or store)
        k = (code, rep.upper(), date)
        o = agg.get(k)
        if not o:
            o = agg[k] = {'store_code': code, 'store': store, 'rep_name': rep, 'login': a.get('login'),
                          'trans_date': date, '_prem': set(), '_byod': set(), '_upg': set(),
                          'acc_gp': 0.0, 'setup_fee': 0.0, 'box_count': 0, '_billpay': set()}
        o['_prem'] |= a['_prem']
        o['_byod'] |= a['_byod']
        o['_upg'] |= a['_upg']
        o['_billpay'] |= a['_billpay']
        # Accessory "achieved" for TARGET attainment = accessory sales revenue + device set-up fee
        # (owner directive 2026-07-17). setup_fee is ALSO carried separately (reported on its own line).
        # accessory_rev already EXCLUDES set-up-fee lines (see _sales_cell_agg) → no double-count.
        o['setup_fee'] += a['setup_fee_rev']
        o['acc_gp'] += a['accessory_rev'] + a['setup_fee_rev']
        o['box_count'] += a['box_count']
    out = []
    for o in agg.values():
        out.append({'store_code': o['store_code'], 'store': o['store'], 'rep_name': o['rep_name'],
                    'login': o['login'], 'trans_date': o['trans_date'],
                    'prem_count': len(o['_prem']), 'byod_count': len(o['_byod']),
                    'upg_count': len(o['_upg']), 'acc_gp': round(o['acc_gp'], 2),
                    'setup_fee': round(o['setup_fee'], 2),
                    'box_count': o['box_count'], 'billpay_count': len(o['_billpay'])})
    return out


def _fetch_actuals(client, org_id, period):
    """MTD 'achieved' actuals for Daily Targets — flowing from the EXACT SAME sales aggregation the Sales
    Report + Executive MTD use (owner directive 2026-07-16: "the Sales Report should flow into the Daily
    Targets"). Reads the SAME union (`_sales_rows_union`, the (day × store) cell-grain feed∪raw_sales the
    Sales Report reads) and the SAME row-level pass (`_compute_feed_actuals_py` → `_sales_cell_agg`), so
    the three surfaces can never disagree.

    Previously this used the TRANSACTION-grain union (`_sales_rows_union_txn`) — which could keep a raw_sales
    transaction the feed lacked even on a store-day the feed also sold, i.e. count sales the Sales Report's
    cell-grain view does NOT show. Repointing to the cell-grain union trades that narrow completeness edge
    for guaranteed consistency with the Sales Report (the owner's "never disagree again"): the feed still
    wins each store-day cell it holds, every other store fills from raw_sales (so luxelink's re-uploaded
    stores are still present), and in the healthy feed-only state the union is the feed verbatim → Boost
    unchanged. Display-only (targets), never commission payout."""
    rows, _umeta = _sales_rows_union(client, org_id, period, cols=_ACTUALS_COLS)
    rows = _compute_feed_actuals_py(client, org_id, period, rows=rows)
    cmap = _rep_canon_map(client, org_id)
    for r in rows:
        if r.get('rep_name'):
            r['rep_name'] = _canon(r.get('rep_name'), cmap)
    return rows


def _targets_trending_by_code(client, org_id, period, today=None):
    """Per-store-code TRENDING (projected month-end) accessory$ + activation/box count, taken DIRECTLY
    from the Executive-MTD computation (`_exec_mtd`) so the Daily-Targets / Accessory-Targets pages show
    the SAME trending numbers as Executive MTD — ONE source, both move together when the shared
    aggregation or the trend formula changes. Exec MTD keys `by_location` on the raw store string; this
    folds each row into the canonical store_code via the SAME resolver the actuals use, so a store's
    trending attaches to its Daily-Targets row (raw spellings that resolve to one code sum together).
    Display-only; never raises (a trending failure must not break the targets summary)."""
    try:
        ex = _exec_mtd(client, org_id, period, today=today)
    except Exception as e:
        print(f"WARN _targets_trending_by_code exec-mtd failed: {e}")
        return {}, {}
    resolve = _store_code_resolver(client, org_id)
    by_code = {}
    # Suspect (e), 2026-07-30: Exec MTD lists EVERY selling store; the Targets summary can only show a
    # store that resolves to a store_code in the roster/target universe. Such a store's accessory$ sat
    # in Exec MTD's total and nowhere on the Targets pages, silently — one of the ways the two
    # "different accessory numbers" arise. The resolver's LAST fallback returns the cleaned raw string
    # (never empty), so "unmapped" is not detectable here — it means "resolved to a code the roster
    # doesn't contain", which only `get_targets_summary` knows. We therefore keep the raw display
    # name(s) behind each code in `names` and let the summary compute + report the residual.
    for r in (ex.get('by_location', {}) or {}).get('rows', []) or []:
        code = str(resolve(r.get('store')) or '').strip().upper()
        if not code:
            continue
        d = by_code.setdefault(code, {'trending_acc_sales': 0.0, 'trending_box': 0,
                                      'acc_sales': 0.0, 'total_activation': 0,
                                      'setup_fee': 0.0, 'acc_plus_setup': 0.0,
                                      'trending_acc_plus_setup': 0.0, 'names': []})
        _nm = str(r.get('store') or '').strip()
        if _nm and _nm not in d['names']:
            d['names'].append(_nm)          # raw POS spelling(s) behind this code, for the recon banner
        d['trending_acc_sales'] += safe_float(r.get('trending_acc_sales'))
        d['trending_box'] += int(r.get('trending_box') or 0)
        d['acc_sales'] += safe_float(r.get('acc_sales'))
        d['total_activation'] += int(r.get('total_activation') or 0)
        # TARGET-basis twins (accessory$ + device set-up fee) — the basis the Accessory Targets page's
        # achieved/target columns use, so its Trending column projects the metric it actually tracks.
        d['setup_fee'] += safe_float(r.get('setup_fee'))
        d['acc_plus_setup'] += safe_float(r.get('acc_plus_setup'))
        d['trending_acc_plus_setup'] += safe_float(r.get('trending_acc_plus_setup'))
    for d in by_code.values():
        for _k in ('trending_acc_sales', 'acc_sales', 'setup_fee', 'acc_plus_setup',
                   'trending_acc_plus_setup'):
            d[_k] = round(d[_k], 2)
    return by_code, dict(ex.get('trending', {}) or {})


def _byod_pct_default(client, period, org_id=ORG_ID):
    try:
        r = (client.schema('commcalc').table('payout_config')
             .select('kpi_byod_target').eq('org_id', org_id).in_('period', _pvariants(period)).limit(1).execute().data) or []
        if r and r[0].get('kpi_byod_target') is not None:
            return safe_float(r[0]['kpi_byod_target'])
    except Exception:
        pass
    return 35.0


# ── ACTIVE-STORE ROSTER (owner defect 2026-08-06: "t-902 / 531 etc all t-stores have been disabled
#    but they still show in time clock, targets etc reports — check and remove") ──────────────────
# `storeops.stores.is_active` was SELECTED in several places in this module and FILTERED in NONE, so a
# store the operator disabled kept being SEEDED a fresh monthly target, kept being ROLLED FORWARD into
# next month, and kept appearing in every store picker / filter dropdown.
#
# ★ NULL-SAFE BY CONTRACT. `is_active` is a NULLABLE column whose default is true. storeops already
# codified the rule in `_inactive_ids_from` (only an EXPLICIT `is_active=false` is inactive; NULL or
# absent means ACTIVE), and every frontend picker spells it `s.is_active !== false`. A blanket
# `.eq("is_active", True)` would therefore DROP every row where the flag was never set — i.e. silently
# empty the store roster of a tenant that never touched it. We express `is_active IS NOT FALSE` in
# PYTHON rather than as a PostgREST filter for two reasons: (1) it is byte-for-byte the predicate
# storeops uses, so the two modules cannot drift apart on what "inactive" means; (2) the PostgREST
# spelling (`or=(is_active.is.null,is_active.eq.true)`) fails CLOSED — on a tenant whose table predates
# the column the request errors and the roster reads EMPTY, which on a targets page is
# indistinguishable from "you have no stores". A roster is a few dozen rows, so filtering after the
# read costs nothing.
#
# ★ HISTORY IS NOT ERASED. This helper answers "who is on the roster NOW". Every caller that renders a
# PAST period passes `keep_codes` = the stores that actually have data for that period (a saved target
# row, real achieved sales), so a store that was open in June still renders June exactly as before —
# it just carries `is_active: false` so the UI can label it "(inactive)". What stops is seeding,
# carrying forward, and offering a dead store as a pickable option.
def _store_active(s) -> bool:
    """`is_active IS NOT FALSE` for one storeops.stores row — NULL/absent means ACTIVE."""
    return (s or {}).get('is_active') is not False


_ROSTER_COLS = 'store_code,address,market,monthly_target,is_active'


def _storeops_roster(client, org_id, cols=_ROSTER_COLS, include_inactive=False, keep_codes=None):
    """The org's `storeops.stores` roster, ACTIVE ONLY by default.

    `include_inactive=True` returns everything — the module's OWN established convention, mirroring
    `GET /storeops/employees` (`include_inactive: bool = False`), not a new one.

    `keep_codes` is a set of store_codes (case-insensitive) that survive the active filter even when
    disabled: how a caller says "this store has real data in the period I am rendering, so it belongs
    in this report". That is what keeps a closed store's history intact.

    `is_active` is always requested so the predicate can be evaluated; a tenant whose table predates
    the column falls back to the caller's own column list and every row is treated as ACTIVE (exactly
    today's behaviour). Never raises — an unreadable roster returns []."""
    want = [c.strip() for c in str(cols).split(',') if c.strip()]
    sel = ','.join(want + (['is_active'] if 'is_active' not in want else []))
    try:
        rows = (client.schema('storeops').table('stores').select(sel)
                .eq('org_id', org_id).execute().data) or []
    except Exception as e:
        print(f'WARN _storeops_roster: is_active select failed, falling back ({e})')
        try:
            rows = (client.schema('storeops').table('stores').select(','.join(want))
                    .eq('org_id', org_id).execute().data) or []
        except Exception as e2:
            print(f'WARN _storeops_roster: roster unreadable ({e2})')
            return []
    if include_inactive:
        return rows
    keep = {str(c).strip().upper() for c in (keep_codes or ()) if str(c).strip()}
    return [s for s in rows
            if _store_active(s) or str(s.get('store_code') or '').strip().upper() in keep]


# ── Month-over-month target carry-forward + stretch ──────────────────────────────────────────────
# The prior month's target carries forward automatically; a store that HIT a category's target last
# month gets a 110% STRETCH on it, one that missed carries the same number forward. Evaluated per
# category (activations / upgrades / accessories). Powers the Target Settings seed preview + the
# "Roll forward from last month" action (which persists).
_MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June',
                'July', 'August', 'September', 'October', 'November', 'December']
STRETCH_FACTOR = 1.10


def _prior_period(period: str) -> str:
    """The 'Month YYYY' label one month before `period`."""
    pm = parse_period(period)
    m, y = pm['month'] - 1, pm['year']
    if m < 1:
        m, y = 12, y - 1
    return f"{_MONTH_NAMES[m - 1]} {y}"


def _carry_forward_map(client, org_id, period, stores):
    """Per store_code (UPPER): the suggested next-month target derived from the prior period —
    carry each category forward, or ×1.10 when the store achieved that category's prior target.
    basis[cat] ∈ 'stretch' | 'carry' | 'new' (no prior target to work from)."""
    prior = _prior_period(period)
    prows = (client.schema('commcalc').table('targets')
             .select('*').eq('org_id', org_id).in_('period', _pvariants(prior)).execute().data) or []
    prior_by_code = {str(r.get('store_code', '')).upper(): r for r in prows}
    byod_prior = _byod_pct_default(client, prior, org_id)
    p_actuals = _fetch_actuals(client, org_id, prior)
    out = {}
    for s in stores:
        code = str(s.get('store_code', '') or '').strip()
        if not code:
            continue
        cu = code.upper()
        ptrow = prior_by_code.get(cu)
        p_monthly = targets_engine.derive_monthly_by_cat(
            ptrow if ptrow else {'accessories_monthly': safe_float(s.get('monthly_target'))}, byod_prior)
        achieved = targets_engine.scope_achieved_mtd(p_actuals, code, None, None)  # whole prior month
        res, basis = {}, {}
        for cat, col in (('activations', 'activations_monthly'), ('upgrades', 'upgrades_monthly'),
                         ('accessories', 'accessories_monthly')):
            tgt = safe_float(p_monthly.get(cat))
            got = safe_float(achieved.get(cat))
            if tgt > 0 and got >= tgt:
                val, basis[cat] = tgt * STRETCH_FACTOR, 'stretch'
            elif tgt > 0:
                val, basis[cat] = tgt, 'carry'
            else:
                val, basis[cat] = tgt, 'new'
            res[col] = round(val) if cat != 'accessories' else round(val, 2)
        res['byod_pct'] = ptrow.get('byod_pct') if ptrow else None
        res['basis'] = basis
        out[cu] = res
    return {'prior_period': prior, 'by_code': out}


# ── TARGET-SETTING PERMISSION (owner directive 2026-08-03, the DM collective-target package) ─────
# Target Settings has ALWAYS had a permission: core's SETTING_AREAS key 'targets' ("Target Settings"),
# which the Roles UI already renders and `_can_edit_setting` already evaluates. What it did NOT have
# was an enforcement point — `PUT /targets/{period}` took no Authorization header at all, so the rule
# existed only as a nav-level `scopes: ['all']` hint on the settings page. Adding the check here
# NARROWS the write to exactly the people the existing rule already named; it widens nothing, and the
# owner's instruction for the DM drill-down was explicitly "respect the existing Target Settings
# editability rules; do not widen who may edit".
#
# DEGRADE-OPEN ON RESOLUTION, FAIL-CLOSED ON DECISION — the same posture as
# `_require_commission_plans_edit`: an unresolvable caller (RBAC off / no token / core unavailable)
# passes, so the house org and existing automation are never locked out, but an error inside the
# permission check itself propagates rather than silently allowing the write.
def _can_edit_targets(authorization: str, org_id: str):
    """(allowed, caller). Resolution failures → (True, None) per the house posture above."""
    try:
        from app.modules.core.router import _uid_from_token, _resolve_caller, _can_edit_setting
    except Exception:
        return True, None                     # core unavailable — module-wide posture (require_org only)
    try:
        uid = _uid_from_token(authorization)
        caller = _resolve_caller(sb(), uid, org_id) if uid else None
    except Exception:
        caller = None
    if caller is None:
        return True, None
    return bool(_can_edit_setting(caller, "targets")), caller


def _require_target_edit(authorization: str, org_id: str, store_code: str = ""):
    """Raise 403 unless the caller may edit Target Settings AND — when RBAC span enforcement is on —
    the store is inside their own span.

    The SPAN half is what makes the DM per-store drill-down safe: a district manager who is granted
    'targets' may set targets for the stores they manage and ONLY those. An unrestricted caller
    (scope_keyset → None: admin, or enforcement off) is unaffected, exactly as today."""
    ok, _caller = _can_edit_targets(authorization, org_id)
    if not ok:
        raise HTTPException(403, "You need the 'Target Settings' permission to set targets. "
                                 "Ask an administrator to grant it on your role.")
    code = str(store_code or "").strip()
    if not code:
        return
    try:
        from app.modules.storeops.router import scope_keyset, in_keyset
        ks = scope_keyset(authorization, org_id)
    except Exception:
        return                                # scope resolution unavailable → today's behaviour
    if ks is not None and not in_keyset(ks, code):
        raise HTTPException(403, f"'{code}' is not one of your stores — you can only set targets for "
                                 f"the stores assigned to you.")


@router.get("/targets/{period}")
def get_targets(period: str, include_inactive: bool = False,
                      authorization: str = Header(default=""), org_id: str = ORG_ID):
    """List per-store monthly target config. Stores without a row are SEEDED from the prior month —
    each category carried forward, or +10% stretched when last month's target was met (see
    _carry_forward_map). Accessories still fall back to storeops.stores.monthly_target when there's
    no prior; byod_pct from KPI config.

    DISABLED STORES (owner 2026-08-06): a store with `storeops.stores.is_active = false` is OFF the
    roster — it is never seeded a target and never offered here. It IS still returned for a period
    where it already has a SAVED target row, carrying `is_active: false` so the UI can label it
    "(inactive)": hiding a dead store from next month's planning is right, silently rewriting a month
    it was open for is not. `include_inactive=1` returns the whole roster (same opt-in shape as
    `GET /storeops/employees`)."""
    client = sb()
    pm = parse_period(period)
    rows = (client.schema('commcalc').table('targets')
            .select('*').eq('org_id', org_id).in_('period', _pvariants(period)).execute().data) or []
    by_code = {str(r.get('store_code', '')).upper(): r for r in rows}
    byod_def = _byod_pct_default(client, period, org_id)

    # keep_codes = the stores that already HAVE a saved target for this period, so a disabled store's
    # existing history renders unchanged while a disabled store with nothing saved simply drops out
    # (and is therefore never seeded below).
    stores = _storeops_roster(client, org_id, include_inactive=include_inactive,
                              keep_codes=set(by_code))
    # Only pull last month's actuals for the carry-forward when at least one store still needs seeding.
    need_seed = any((str(s.get('store_code', '') or '').strip().upper() or None) not in by_code
                    for s in stores if str(s.get('store_code', '') or '').strip())
    cf = (_carry_forward_map(client, org_id, period, stores) if need_seed
          else {'by_code': {}, 'prior_period': _prior_period(period)})
    out = []
    for s in stores:
        code = str(s.get('store_code', '') or '').strip()
        if not code:
            continue
        existing = by_code.get(code.upper())
        if existing:
            row = dict(existing)
            row['address'] = s.get('address')
            row['market'] = s.get('market')
            row['is_active'] = _store_active(s)
            row['_seeded'] = False
        else:
            cfrow = cf['by_code'].get(code.upper(), {})
            acc = cfrow.get('accessories_monthly')
            row = {
                'org_id': org_id, 'store_code': code, 'period': period,
                'period_month': pm['month'], 'period_year': pm['year'],
                'activations_monthly': cfrow.get('activations_monthly', 0),
                'upgrades_monthly': cfrow.get('upgrades_monthly', 0),
                'accessories_monthly': acc if acc is not None else safe_float(s.get('monthly_target')),
                'byod_pct': cfrow.get('byod_pct') or byod_def, 'notes': None,
                'address': s.get('address'), 'market': s.get('market'),
                'is_active': _store_active(s),
                '_seeded': True, '_seed_basis': cfrow.get('basis'), '_prior_period': cf['prior_period'],
            }
        out.append(row)
    out.sort(key=lambda r: str(r.get('address') or r.get('store_code') or ''))
    from app.modules.storeops.router import scope_keyset, in_keyset
    ks = scope_keyset(authorization, org_id)   # None = unrestricted (admin / enforcement off)
    if ks is not None:
        out = [r for r in out if in_keyset(ks, r.get('store_code'), r.get('address'))]
    return {'period': period, 'byod_pct_default': byod_def, 'targets': out}


class SaveTargetIn(LaxModel):
    store_code: Any = None
    activations_monthly: Any = None
    upgrades_monthly: Any = None
    accessories_monthly: Any = None
    byod_pct: Any = None
    notes: Any = None
    updated_by: Any = None


@router.put("/targets/{period}")
async def save_target(period: str, body: SaveTargetIn, authorization: str = Header(default=""),
                      org_id: str = ORG_ID):
    """Upsert one store's monthly target config (Target Settings save, and the DM per-store
    drill-down under My Targets).

    GATED (2026-08-03) on the EXISTING 'targets' settings area + the caller's own store span — see
    `_require_target_edit`. This endpoint previously took no Authorization header at all."""
    client = sb()
    code = str(body.store_code or '').strip()
    if not code:
        raise HTTPException(400, "store_code required")
    _require_target_edit(authorization, org_id, code)
    pm = parse_period(period)
    row = {
        'org_id': org_id, 'store_code': code, 'period': period,
        'period_month': pm['month'], 'period_year': pm['year'],
        'activations_monthly': safe_float(body.activations_monthly),
        'upgrades_monthly': safe_float(body.upgrades_monthly),
        'accessories_monthly': safe_float(body.accessories_monthly),
        # Blank field → NULL (fall back to KPI default), not 0% which would zero the BYOD target.
        'byod_pct': (safe_float(body.byod_pct)
                     if str(body.byod_pct if body.byod_pct is not None else '').strip() != ''
                     else None),
        'notes': body.notes,
        'updated_by': body.updated_by or 'web',
    }
    r = (client.schema('commcalc').table('targets')
         .upsert(row, on_conflict='org_id,store_code,period').execute())
    return r.data[0] if r.data else row


class RollForwardTargetsIn(LaxModel):
    overwrite: Any = None


@router.post("/targets/{period}/roll-forward")
def roll_forward_targets(period: str, body: Optional[RollForwardTargetsIn] = None,
                               authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Persist the month-over-month carry-forward into `period`: each store's prior-month target
    carried forward, or +10% where last month's target was met (see _carry_forward_map). By default
    only stores WITHOUT a target row for this period are written (never overwrites a hand-set target);
    pass {overwrite:true} to refresh them all. Stores with nothing to carry (all-zero) are skipped.

    GATED (2026-08-03) on the same EXISTING 'targets' settings area as the single-store save — this is
    a bulk write of the same rows and had no permission check at all. No store code is passed, so only
    the settings-area half applies; the per-store span half is enforced on the row loop below."""
    client = sb()
    _require_target_edit(authorization, org_id)
    pm = parse_period(period)
    overwrite = bool(body.overwrite) if body else False
    existing = {str(r.get('store_code', '')).upper()
                for r in ((client.schema('commcalc').table('targets')
                           .select('store_code').eq('org_id', org_id)
                           .in_('period', _pvariants(period)).execute().data) or [])}
    # WRITE PATH — no keep_codes: a disabled store must never be CREATED a new target row, for any
    # period. Reported separately in the response so the skip is visible rather than silent.
    _roster_all = _storeops_roster(client, org_id, include_inactive=True)
    stores = [s for s in _roster_all if _store_active(s)]
    inactive_skipped = len(_roster_all) - len(stores)
    cf = _carry_forward_map(client, org_id, period, stores)
    prior = cf['prior_period']
    written, skipped = [], 0
    try:
        from app.modules.storeops.router import scope_keyset as _rf_scope, in_keyset as _rf_in
        _rf_ks = _rf_scope(authorization, org_id)   # None = unrestricted (admin / enforcement off)
    except Exception:
        _rf_ks, _rf_in = None, (lambda *a, **k: True)
    for s in stores:
        code = str(s.get('store_code', '') or '').strip()
        if not code:
            continue
        cu = code.upper()
        if cu in existing and not overwrite:
            skipped += 1
            continue
        # A span-restricted caller rolls forward only their OWN stores; an unrestricted admin (ks None)
        # rolls the whole org exactly as before.
        if _rf_ks is not None and not _rf_in(_rf_ks, code):
            skipped += 1
            continue
        cfrow = cf['by_code'].get(cu, {})
        acc = cfrow.get('accessories_monthly')
        acc = acc if acc is not None else safe_float(s.get('monthly_target'))
        act = safe_float(cfrow.get('activations_monthly'))
        upg = safe_float(cfrow.get('upgrades_monthly'))
        if act <= 0 and upg <= 0 and acc <= 0:   # nothing to carry — don't create an empty row
            skipped += 1
            continue
        row = {
            'org_id': org_id, 'store_code': code, 'period': period,
            'period_month': pm['month'], 'period_year': pm['year'],
            'activations_monthly': act, 'upgrades_monthly': upg, 'accessories_monthly': acc,
            'byod_pct': cfrow.get('byod_pct'),
            'notes': f'Rolled forward from {prior}', 'updated_by': 'roll-forward',
        }
        client.schema('commcalc').table('targets').upsert(row, on_conflict='org_id,store_code,period').execute()
        written.append({'store_code': code, 'basis': cfrow.get('basis')})
    return {'period': period, 'prior_period': prior, 'written': len(written),
            'skipped': skipped, 'inactive_skipped': inactive_skipped,
            'overwrite': overwrite, 'stores': written}


# ── SHARED period normalizer for the targets / coaching / exec family ────────────────────────────
# Every endpoint below takes `{period}` straight from the platform period selector, which emits
# 'Month YYYY' (frontend/src/lib/period-context.tsx). Each of them ALSO gets called with the machine
# spelling '2026-07' by some paths, and each handled that differently: _period_bounds raised a 400
# (/targets/{period}/summary + /calendar), while calculator.parse_period silently resolved it to
# JANUARY (/exec-overview's P&L lookup -> the wrong month's numbers, no error). One normalizer at the
# entry point makes all of them accept both spellings and refuse garbage with an actionable 400
# instead of a 500 or a silently-wrong month. (Period-duality is a recurring bug class here — cf. the
# retail P&L '2026-06' vs 'June 2026' fix.)
def _period_or_400(period, what="period"):
    """The canonical 'Month YYYY' spelling for a period that may arrive in EITHER shape — 'July 2026'
    (what the platform period selector emits) or '2026-07' (what raw_sales / the daily feed / a
    machine caller use). 'Month YYYY' is the canonical direction HERE because `_period_bounds` only
    understands the month-name form and raises 400 on '2026-07'; this is the same canonical string
    `_canon_period` produces (and that calc_status / rep_commissions are keyed on).

    STRICT parse, deliberately mirroring `_pvariants` rather than leaning on
    `calculator.parse_period` — that helper silently maps anything unknown to January (so 'banana'
    became 'January 2026') and IndexErrors on an empty string, which is an unhandled 500. Anything
    that is not clearly a month-period raises a clean, actionable 400."""
    p = str(period or "").strip()
    if len(p) >= 7 and p[:4].isdigit() and p[4] == "-" and p[5:7].isdigit():
        mo, yr = int(p[5:7]), int(p[:4])
    else:
        parts = p.split()
        names = {m.lower(): i for i, m in enumerate(_calendar.month_name) if m}
        if len(parts) == 2 and parts[0].lower() in names and parts[1].isdigit():
            mo, yr = names[parts[0].lower()], int(parts[1])
        else:
            mo, yr = 0, 0
    if not (1 <= mo <= 12) or yr < 1900:
        raise HTTPException(400, f"Unrecognized {what} '{period}' - expected 'July 2026' or '2026-07'.")
    return f"{_calendar.month_name[mo]} {yr}"


@router.get("/targets/{period}/calendar")
def get_target_calendar(
    period: str, store_code: str, scope: str = "store",
    rep: str = "", today: str = "", authorization: str = Header(default=""), org_id: str = ORG_ID,
):
    """Schedule-weighted daily targets + catch-up + pace + day-by-day calendar
    for a single store (scope=store) or a single rep within it (scope=rep).

    Accepts either period spelling ('July 2026' or '2026-07'); unparseable -> clean 400."""
    client = sb()
    cperiod = _period_or_400(period)
    from app.modules.storeops.router import scope_keyset, in_keyset
    # Only a manager WITH a span (non-empty keyset) is restricted here. None = admin/unrestricted;
    # an empty set = a self-scope rep (no managed stores) viewing their OWN store from the portal —
    # must NOT be blocked. The store list a manager can reach is already span-scoped upstream.
    ks = scope_keyset(authorization, org_id)
    if ks and not in_keyset(ks, store_code):
        raise HTTPException(403, "That store is outside your assigned area.")
    start, end, today = _period_bounds(cperiod, today)
    byod_def = _byod_pct_default(client, cperiod, org_id)

    trow = (client.schema('commcalc').table('targets')
            .select('*').eq('org_id', org_id).in_('period', _pvariants(cperiod))
            .eq('store_code', store_code).limit(1).execute().data) or []
    target_row = trow[0] if trow else {}
    # Seed accessories from store monthly_target when no explicit row yet.
    if not trow:
        srow = (client.schema('storeops').table('stores')
                .select('monthly_target').eq('org_id', org_id).eq('store_code', store_code).limit(1).execute().data) or []
        if srow:
            target_row = {'accessories_monthly': safe_float(srow[0].get('monthly_target'))}
    monthly = targets_engine.derive_monthly_by_cat(target_row, byod_def)

    shifts = _fetch_shifts(client, start, end, org_id)
    actuals = _fetch_actuals(client, org_id, cperiod)
    rep_arg = rep if scope == 'rep' and rep else None

    hours_by_day = targets_engine.scope_hours_by_day(shifts, store_code, rep_arg)
    actuals_by_day = targets_engine.scope_actuals_by_day(actuals, store_code, rep_arg)
    month_end = end - _timedelta(days=1)

    # Employee target PRORATION (#10/#11): a rep's monthly target = the store monthly × the rep's
    # share of the store's scheduled hours (projected to the full month), NOT the full store target.
    # compute_scope then spreads it over the rep's days, so Σ(rep days) = store_monthly × rep_share.
    rep_share = 1.0
    if rep_arg:
        store_hours = targets_engine.scope_hours_by_day(shifts, store_code, None)
        store_eff = {**store_hours, **targets_engine.project_future_hours(store_hours, today, month_end)}
        rep_eff = {**hours_by_day, **targets_engine.project_future_hours(hours_by_day, today, month_end)}
        sh, rh = sum(store_eff.values()), sum(rep_eff.values())
        rep_share = (rh / sh) if sh > 0 else 0.0
        monthly = {c: round((v or 0) * rep_share, 2) for c, v in monthly.items()}

    result = targets_engine.compute_scope(monthly, hours_by_day, actuals_by_day, today,
                                          round_counts=True, month_end=month_end)
    result.update({
        'period': period, 'scope': scope, 'store_code': store_code,
        'rep': rep_arg, 'monthly_targets': monthly, 'rep_share': round(rep_share, 4),
        'reps': targets_engine.reps_in_scope(shifts, actuals, store_code),
    })
    # Conversion (boxes ÷ bill-payments). Always include the store rate; for a rep scope
    # also include the rep's rate + whether it's dragging the store down.
    store_conv = targets_engine.scope_conversion(actuals, store_code, None, today)
    conv = {'store': store_conv}
    if rep_arg:
        rep_conv = targets_engine.scope_conversion(actuals, store_code, rep_arg, today)
        rep_conv['below_store'] = rep_conv['rate'] < store_conv['rate']
        conv['rep'] = rep_conv
    result['conversion'] = conv
    return result


def _self_keys_from_tokens(client, org_id: str, tokens) -> set:
    """Raw store TOKENS → the UPPER keyset that identifies THOSE STORES and nothing else.

    A token is whatever the org actually recorded for the person: a pinned `app_users.store_code`,
    or a roster `storeops.employees.home_store`, which in live data is sometimes a store_code
    ('B-3PL', 'Diversey'), sometimes a street address, sometimes a POS synonym. Resolution runs
    through the SAME canonical vocabulary the span keyset is built from —
    `app.core.scope.market_index()` = storeops.stores ∪ commcalc.store_mapping ∪
    commcalc.store_aliases — so a roster spelling binds exactly like a manager's grant does. **No new
    matcher**: code → address → synonym, in that order, ONE hop each, then the shared
    `widen_codes_to_keys()` does the widening (its own proof that a code can never reach an
    out-of-span store applies unchanged here).

    A token that matches NOTHING in any vocabulary is carried through as a LITERAL key. That can only
    ever match a row whose store column is exactly that string — i.e. the store the org named — and
    can never reach a second store, so an unmapped roster value degrades to "your own store" rather
    than to "everything".

    Never raises: a vocabulary read failure leaves the literal tokens, which is the NARROW answer."""
    raw = {str(t).strip().upper() for t in (tokens or []) if str(t).strip()}
    if not raw:
        return set()
    keys, codes = set(raw), set()
    try:
        from app.core import scope as _cscope
        idx = _cscope.market_index(client, org_id)
        known = {str(s.get("store_code") or "").strip().upper()
                 for s in (idx.get("stores") or []) if str(s.get("store_code") or "").strip()}
        addr_owner, alias_owner = {}, {}
        for code, addrs in (idx.get("addr_keys") or {}).items():
            for a in (addrs or ()):
                addr_owner.setdefault(a, set()).add(code)
        for code, aliases in (idx.get("alias_keys") or {}).items():
            for a in (aliases or ()):
                alias_owner.setdefault(a, set()).add(code)
        for t in raw:
            if t in known:
                codes.add(t)
            elif t in addr_owner:
                codes |= addr_owner[t]
            elif t in alias_owner:
                codes |= alias_owner[t]
        if codes:
            keys |= _cscope.widen_codes_to_keys(client, org_id, codes)
    except Exception as e:                                          # pragma: no cover - I/O guard
        print(f"WARN _self_keys_from_tokens vocabulary resolve failed: {e}")
    return {k for k in keys if k}


def _caller_self_keyset(authorization: str, org_id: str):
    """For a SELF-scoped (rep) caller, the UPPER store keyset (store_code(s) + every address spelling
    + every POS synonym) of the rep's OWN store(s). Returns (is_self, keyset):
      • (False, None)  — NOT self-scoped (admin / unrestricted / a real manager span / RBAC off / no
                         identifiable caller). The caller keeps scope_keyset's own result.
      • (True, {keys}) — a self rep we could place in a store → restrict to THAT store.
      • (True, set())  — a self rep we could place in NO store → they see NOTHING.

    🔴 `None` NO LONGER MEANS "UNRESTRICTED" ON THE SELF PATH (fixed 2026-08-08, owner-authorised).
    ─────────────────────────────────────────────────────────────────────────────────────────────
    This function used to `return (True, None)` for a self rep with no pinned store, with the comment
    "don't lock them out". At its call site `None` is the UNRESTRICTED sentinel (`if ks is not None:`
    skips the span filter entirely), so that branch handed a single-store rep EVERY store in the
    tenant. Six live logins sat on it (4 house + 2 Luxelink). "See nothing" is the safe failure; the
    original intent — never a silent blank page — is preserved by the `setup_hint` the call site now
    raises instead ("no store assigned — ask your manager").

    A self caller can therefore NEVER be unrestricted from here: once we know the role is 'self',
    every remaining step is best-effort STORE RESOLUTION whose failure NARROWS to `set()`.

    WHERE THE STORE COMES FROM, in order:
      1. `storeops.app_users.store_code` / `.store_codes` — the login pin.
      2. `storeops.employees.home_store` for the same org_id + employee_id — the ROSTER. 5 of the 6
         live pinless reps have a perfectly good one and this function never used to read it.
      3. Nothing → `set()`.

    🚫 `app_users.market` IS DELIBERATELY IGNORED. One of the six (a Luxelink `self` login) carries
    market='Chicago' = 26 store codes; honouring it would turn a 1-store rep into a 26-store one —
    the exact over-grant this fix exists to separate out. `storeops.caller_scope` already refuses
    market widening for scope 'self'; this mirrors it.

    SCHEMA (also fixed 2026-08-08): the reads were `sb().table("app_users")` / `sb().table("stores")`,
    and commcalc's `sb()` is the DEFAULT-schema (public) client. `public.app_users` does not exist —
    PostgREST answers PGRST205 for every role, including service_role, because a schema-cache miss is
    role-independent — so the read raised and the whole function returned (False, None) on EVERY
    request. `public.stores` is a different, legacy 25-row table with no `org_id` column, so the
    address widening 400'd too. Both now go through `.schema("storeops")`, and the widening runs off
    the shared canonical index. Verified live 2026-08-08 against the real PostgREST.

    READ-ONLY, org-scoped on every read. Never raises."""
    try:
        from app.modules.storeops.router import _rbac_enabled, _role_scope
        from app.modules.core.router import _uid_from_token
    except Exception:
        return (False, None)
    # ── STEP 1 · identity. A failure here means we do not know that the caller is a rep, so we must
    # hand the decision back to scope_keyset — that is what (False, None) means and it is correct.
    try:
        if not _rbac_enabled(org_id):
            return (False, None)
        uid = _uid_from_token(authorization)
        if not uid:
            return (False, None)
        client = sb()
        rows = (client.schema("storeops").table("app_users")
                .select("role,employee_id,store_code,store_codes")
                .eq("org_id", org_id).eq("auth_id", uid).limit(1).execute().data) or []
        if not rows:
            return (False, None)
        u = rows[0]
        if _role_scope(org_id, (u.get("role") or "").strip()) != "self":
            return (False, None)
    except Exception as e:                                          # pragma: no cover - I/O guard
        print(f"WARN _caller_self_keyset identity read failed: {e}")
        return (False, None)
    # ── STEP 2 · the caller IS a self rep. From here every failure NARROWS; none can widen.
    tokens = [str(u.get("store_code"))] if str(u.get("store_code") or "").strip() else []
    tokens += [str(c) for c in (u.get("store_codes") or []) if str(c).strip()]
    if not tokens:
        eid = str(u.get("employee_id") or "").strip()
        if eid:
            try:
                erows = (client.schema("storeops").table("employees")
                         .select("home_store").eq("org_id", org_id)
                         .eq("employee_id", eid).limit(1).execute().data) or []
                hs = str((erows[0].get("home_store") if erows else "") or "").strip()
                if hs:
                    tokens.append(hs)
            except Exception as e:                                  # pragma: no cover - I/O guard
                print(f"WARN _caller_self_keyset roster home_store read failed: {e}")
    if not tokens:
        return (True, set())          # no store anywhere → sees NOTHING (never everything)
    return (True, _self_keys_from_tokens(client, org_id, tokens))


def _as_filter_list(val):
    """Normalize a repeated-query-param filter into a list of non-blank, stripped strings. Tolerates
    EVERY shape the value can arrive in:
      * None / '' / [] ................ -> []          (no filter)
      * one value ('S1') ............... -> ['S1']     (?store=S1, or an internal Python caller)
      * a repeated param (['S1','S2']) . -> ['S1','S2']
      * a fastapi.params.Query DEFAULT . -> []         (see below)

    That last case is NOT hypothetical — it is the confirmed root cause of the 2026-07-30 My-Team
    incident (masked ref 3bf51b4d, "Unhandled server error on /api/v1/commcalc/team/July 2026/
    snapshot"). An endpoint function declared `stores: Optional[List[str]] = Query(default=None)` and
    called INTERNALLY as a plain Python function receives the fastapi Query OBJECT as the default —
    which is TRUTHY and NOT iterable, so `for x in (stores or [])` raises
    `TypeError: 'Query' object is not iterable`. get_targets_summary grew its RULE FIVE filter params
    on 2026-07-17 (e36c0b2) and team_snapshot has called it without them ever since, so EVERY
    /team/{period}/snapshot request has 500'd since that date — after burning the full whole-org
    aggregation first (which is why the box also went slow). Internal callers now pass the params
    explicitly AND this normalizer refuses to raise, so the class cannot come back silently."""
    if val is None:
        return []
    if isinstance(val, str):
        val = [val]
    try:
        items = list(val)
    except TypeError:          # a Query default object, or anything else non-iterable
        return []
    return [s for s in (str(v).strip() for v in items if v is not None) if s]


@router.get("/targets/{period}/summary")
async def get_targets_summary(period: str, today: str = "", include_untargeted: bool = False,
                              include_inactive: bool = False,
                              stores: Optional[List[str]] = Query(default=None),
                              markets: Optional[List[str]] = Query(default=None),
                              reps: Optional[List[str]] = Query(default=None),
                              authorization: str = Header(default=""), org_id: str = ORG_ID):
    """All-stores overview: store-level today/pace/need/monthly/achieved per category. When RBAC
    enforcement is on, a non-admin manager only sees the stores in their org-unit span (Phase 5).
    include_untargeted=1 also returns stores that have sales/achieved but no target set (so the
    Accessory tab can track achieved accessory $ even before per-store accessory targets exist).

    RULE FIVE standardized filters (2026-07-17): optional repeated `stores` (store_code or address) /
    `markets` / `reps` query params filter the returned stores SERVER-SIDE. store/market pick which stores
    are shown (and thus the tiles + the trending sum); rep narrows the per-rep breakdown to the selected
    reps and keeps only stores where they worked/sold — the store-level target/achieved/trending stay
    WHOLE-STORE (a store target can't be split per rep). Filter OPTIONS are returned in `filters`
    (pick-don't-type over the org's real stores/markets/reps).

    TRENDING (2026-07-17): each store carries `trending_acc_sales` + `trending_box` (projected month-end)
    read DIRECTLY from Executive MTD's `_exec_mtd` (`_targets_trending_by_code`) so the Targets pages show
    the SAME trending numbers as Exec MTD — one shared aggregation + trend formula, both move together."""
    client = sb()
    cperiod = _period_or_400(period)
    start, end, today = _period_bounds(cperiod, today)
    byod_def = _byod_pct_default(client, cperiod, org_id)

    trows = (client.schema('commcalc').table('targets')
             .select('*').eq('org_id', org_id).in_('period', _pvariants(cperiod)).execute().data) or []
    tgt_by_code = {str(r.get('store_code', '')).upper(): r for r in trows}
    # A report must NEVER 500. A failure in the shift read or the sales aggregation degrades to "targets
    # render, achieved 0" instead of a blank page — the targets universe below does not depend on either.
    try:
        shifts = _fetch_shifts(client, start, end, org_id)
    except Exception as e:
        print(f"WARN targets summary shifts failed: {e}"); shifts = []
    try:
        actuals = _fetch_actuals(client, org_id, cperiod)
    except Exception as e:
        print(f"WARN targets summary actuals failed: {e}"); actuals = []
    # Whole-store projected-month-end trending, straight from Executive MTD (one source, moves together).
    trend_by_code, trend_meta = _targets_trending_by_code(client, org_id, cperiod, today=today)

    # ── ACTIVE roster (owner 2026-08-06). Read AFTER the trending pass purely so `keep_codes` can name
    #    the stores that have real activity in THIS period: a disabled store still renders any month it
    #    had a saved target or actual sales (carrying is_active:false for the "(inactive)" label), and
    #    disappears only from months where it did nothing. `include_inactive=1` = full roster.
    store_rows = _storeops_roster(client, org_id, include_inactive=include_inactive,
                                  keep_codes=set(tgt_by_code) | set(trend_by_code or {}))

    # ── UNIVERSAL store universe: storeops.stores roster UNION every targeted store_code. A tenant can have
    #    Target Settings saved for stores that are NOT in its storeops roster (or whose roster store_codes
    #    don't line up with the target codes) — sourcing the summary ONLY from storeops.stores then rendered
    #    NOTHING even though targets exist (the luxelink "not showing anything" symptom). Unioning the targeted
    #    codes guarantees a target row ALWAYS renders. For the house this is a no-op: its target codes are a
    #    subset of its storeops roster (targets are created by picking storeops stores) → roster == store_rows
    #    → byte-identical. Address/market for a target-only code are enriched from commcalc.store_mapping when
    #    present (else blank → the store_code is the label). Never raises.
    smap_by_code = {}
    try:
        for m in (client.schema('commcalc').table('store_mapping')
                  .select('store_code,store_address,market').eq('org_id', org_id).execute().data) or []:
            cu = str(m.get('store_code') or '').strip().upper()
            if cu:
                smap_by_code.setdefault(cu, {'address': str(m.get('store_address') or '').strip(),
                                             'market': str(m.get('market') or '').strip()})
    except Exception:
        smap_by_code = {}
    roster = list(store_rows)
    seen_codes = {str(s.get('store_code') or '').strip().upper()
                  for s in store_rows if str(s.get('store_code') or '').strip()}
    for cu, trow in tgt_by_code.items():
        if cu and cu not in seen_codes:
            seen_codes.add(cu)
            meta = smap_by_code.get(cu, {})
            roster.append({'store_code': str(trow.get('store_code') or cu).strip(),
                           'address': meta.get('address', ''), 'market': meta.get('market', ''),
                           'monthly_target': 0})

    # ── RULE FIVE filter OPTIONS (pick-don't-type over real data), computed from the FULL roster universe so
    #    a selection can always be changed. Store value = store_code (label = address); market = store market;
    #    rep = canonical rep name present in the period's actuals.
    store_opts = [{'value': str(s.get('store_code') or '').strip(),
                   'label': str(s.get('address') or s.get('store_code') or '').strip()}
                  for s in roster if str(s.get('store_code') or '').strip()]
    market_opts = sorted({str(s.get('market') or '').strip() for s in roster if str(s.get('market') or '').strip()})
    rep_opts = sorted({str(a.get('rep_name') or '').strip() for a in actuals if str(a.get('rep_name') or '').strip()})
    filters = {'stores': store_opts, 'markets': market_opts, 'reps': rep_opts}

    # Same selections as before for every real input (list / single value / None); routed through
    # _as_filter_list so an INTERNAL caller that omits a repeated-Query param can no longer crash the
    # endpoint with `TypeError: 'Query' object is not iterable` (ref 3bf51b4d — see _as_filter_list).
    store_sel = {x.lower() for x in _as_filter_list(stores)}
    market_sel = {x.lower() for x in _as_filter_list(markets)}
    rep_sel = {x.upper() for x in _as_filter_list(reps)}
    applied = {'stores': sorted(store_sel), 'markets': sorted(market_sel), 'reps': sorted(rep_sel)}

    out = []
    for s in roster:
        code = str(s.get('store_code', '') or '').strip()
        if not code:
            continue
        addr = str(s.get('address') or '').strip()
        mkt = str(s.get('market') or '').strip()
        # store / market filters select which stores are shown (whole-store math unchanged).
        if store_sel and code.lower() not in store_sel and addr.lower() not in store_sel:
            continue
        if market_sel and mkt.lower() not in market_sel:
            continue
        trow = tgt_by_code.get(code.upper())
        if not trow:
            trow = {'accessories_monthly': safe_float(s.get('monthly_target'))}
        monthly = targets_engine.derive_monthly_by_cat(trow, byod_def)
        if sum(monthly.values()) <= 0 and not include_untargeted:
            continue
        hours_by_day = targets_engine.scope_hours_by_day(shifts, code, None)
        actuals_by_day = targets_engine.scope_actuals_by_day(actuals, code, None)
        res = targets_engine.compute_scope(monthly, hours_by_day, actuals_by_day, today,
                                           round_counts=True, month_end=end - _timedelta(days=1))
        # Untargeted store (only reachable via include_untargeted): keep it only when it has real
        # achieved actuals — else it's just noise. Targeted stores always pass.
        if sum(monthly.values()) <= 0:
            _cats = res.get('categories', {}) or {}
            if not any(safe_float((_cats.get(c) or {}).get('achieved_mtd')) > 0 for c in _cats):
                continue
        store_conv = targets_engine.scope_conversion(actuals, code, None, today)
        # Reps who worked/sold at this store + their MTD performance, so the store
        # row breaks down into the people driving it (for corrective action).
        reps_out = []
        for rep_name in targets_engine.reps_in_scope(shifts, actuals, code):
            ach = targets_engine.scope_achieved_mtd(actuals, code, rep_name, today)
            rconv = targets_engine.scope_conversion(actuals, code, rep_name, today)
            reps_out.append({'rep': rep_name, **ach, 'conversion': rconv,
                             'below_store': rconv['rate'] < store_conv['rate']})
        # rep filter: narrow the per-rep breakdown to the selected reps + drop stores none of them touch.
        if rep_sel:
            reps_out = [r for r in reps_out if str(r['rep']).strip().upper() in rep_sel]
            if not reps_out:
                continue
        reps_out.sort(key=lambda r: -r['activations'])
        trend = trend_by_code.get(code.upper(), {})
        out.append({
            'store_code': code, 'address': s.get('address'), 'market': s.get('market'),
            'is_active': _store_active(s),
            'scheduled_hours_total': res['scheduled_hours_total'],
            'categories': res['categories'],
            'conversion': store_conv,
            'trending_acc_sales': safe_float(trend.get('trending_acc_sales')),
            # `trending_acc_sales` is Executive MTD's PURE accessory$ projection (unchanged semantics —
            # it must keep matching Exec MTD's own column). `trending_acc_target` is the projection on
            # the ACCESSORY-TARGET basis (accessory$ + device set-up fee) — the basis this row's
            # categories.accessories.achieved_mtd / monthly / need are all measured in. The Accessory
            # Targets page renders THAT one, so its Trending column projects the number in the column
            # beside it (before this it projected the pure basis, and a store whose set-up fees were
            # material could show a projected month-end BELOW its already-achieved MTD).
            'trending_acc_target': safe_float(trend.get('trending_acc_plus_setup')),
            'acc_sales_ex_setup': safe_float(trend.get('acc_sales')),
            'setup_fee_mtd_exec': safe_float(trend.get('setup_fee')),
            'trending_box': int(trend.get('trending_box') or 0),
            'reps': reps_out,
        })
    out.sort(key=lambda r: str(r.get('address') or r.get('store_code') or ''))
    # ── EXEC-MTD RECONCILIATION (2026-07-30 owner bug, suspect (e)) ──────────────────────────────
    # Executive MTD lists EVERY selling store. This page can only render a store that exists in the
    # roster/target universe above, so a selling store with no roster row, no target row and no store
    # mapping contributes accessory$ to Exec MTD's total and to NOTHING here — silently, which is one
    # of the ways the two pages "show different accessory sales". Compute the residual EXPLICITLY off
    # the SAME `_targets_trending_by_code` payload the trending columns come from, so the delta between
    # the two pages is always fully explained instead of guessed at. Computed against the UNIVERSE
    # (pre-filter, pre-RBAC) so it reports genuinely-unmapped stores only — a store hidden by the
    # active filter or by the caller's RBAC span is NOT "unmapped" and must not be reported as such.
    _universe = {str(s.get('store_code') or '').strip().upper() for s in roster
                 if str(s.get('store_code') or '').strip()}
    _un_names, _un_acc, _un_acc_setup = [], 0.0, 0.0
    for _c, _d in (trend_by_code or {}).items():
        if _c in _universe:
            continue
        _un_acc += safe_float(_d.get('acc_sales'))
        _un_acc_setup += safe_float(_d.get('acc_plus_setup'))
        for _n in (_d.get('names') or []):
            if _n not in _un_names:
                _un_names.append(_n)
    trend_meta = dict(trend_meta or {})
    trend_meta['unmapped_stores'] = sorted(_un_names)
    trend_meta['unmapped_acc_sales'] = round(_un_acc, 2)
    trend_meta['unmapped_acc_plus_setup'] = round(_un_acc_setup, 2)
    if _un_acc_setup > 0:
        setup_hint_unmapped = (
            f"{len(_un_names) or 1} store(s) sold {_un_acc_setup:,.2f} of accessory + set-up-fee $ that "
            f"Executive MTD counts but no target row can hold ({', '.join(_un_names[:5])}"
            f"{chr(8230) if len(_un_names) > 5 else ''}) - map them in Store Matching to close the gap.")
    else:
        setup_hint_unmapped = ""
    from app.modules.storeops.router import scope_keyset, in_keyset
    ks = scope_keyset(authorization, org_id)
    # A self-scoped rep gets an EMPTY keyset from scope_keyset (no manager span) → `is not None` would drop
    # every store and the rep's own targets would never show (My Targets empty). Substitute the rep's OWN
    # store(s) — login pin, else the ROSTER home store — so they see their own data.
    #
    # 🔴 A SELF CALLER IS NEVER UNRESTRICTED (2026-08-08). `_caller_self_keyset` used to return None for a
    # rep with no pinned store, and `None` is this line's UNRESTRICTED sentinel — so 6 live single-store
    # reps read EVERY store's targets. It now returns a SET (possibly empty); `or set()` re-states that
    # invariant HERE so a future edit to the helper cannot silently reopen the hole. A rep we can place in
    # no store sees zero stores and gets the explicit setup_hint below instead of a silent blank page.
    is_self, self_ks = _caller_self_keyset(authorization, org_id)
    if is_self:
        ks = self_ks if self_ks is not None else set()
    no_self_store = bool(is_self) and not ks
    if ks is not None:
        out = [s for s in out if in_keyset(ks, s.get('store_code'), s.get('address'))]
    # Config-required conditions surfaced as an EXPLICIT setup hint so the page can show a "configure X"
    # message instead of a silent blank. House (roster + matched sales) → empty hint (additive field).
    setup_hint = []
    sold_codes = {str(a.get('store_code') or '').strip().upper()
                  for a in actuals if str(a.get('store_code') or '').strip()}
    rendered_codes = {str(s.get('store_code') or '').strip().upper() for s in out}
    if no_self_store:
        # The ONLY reason this rep's page is empty is that nobody has told the system which store they
        # work at. Say so in plain English (RULE THREE/SIX voice) instead of showing a blank picker —
        # that silent blank is what the removed `(True, None)` fallback was trying to avoid, and this
        # is the safe way to avoid it. The two generic hints below would both misfire here (the rep's
        # scope is fine; the tenant's targets and store matching are fine), so they are skipped.
        setup_hint.append("No store is assigned to your login yet, so there are no targets to show. "
                          "Ask your manager to set your store on your employee record (Team → your "
                          "profile → Home store) or on your login.")
    elif not tgt_by_code and not store_rows:
        setup_hint.append("No store roster or targets for this tenant yet — add your stores (Store Admin) "
                          "and set monthly targets in Target Settings for this month.")
    elif not out and tgt_by_code:
        setup_hint.append("Targets are set but none could be shown — check that the target store codes "
                          "match your store roster / your area (RBAC) scope.")
    if not no_self_store:
        # Both of these are TENANT-CONFIG hints ("your POS store names aren't mapped"). For a rep with
        # no store of their own they are noise at best and misleading at worst — nothing is wrong with
        # the tenant's mapping, the rep just has no store — so the whole pair is skipped for them.
        if sold_codes and not (sold_codes & rendered_codes):
            setup_hint.append("Sales were found but none matched a target store — map your POS store names to "
                              "stores in Store Matching so achieved numbers attach.")
        elif setup_hint_unmapped:
            # PARTIAL mismatch — the loud "nothing matched" hint above never fires, so this was silent.
            setup_hint.append(setup_hint_unmapped)
    # ── AREA / SPAN ROLL-UP (owner 2026-08-03) ────────────────────────────────────────────────────
    # "the dm should have a collective target for all the stores assigned to them with a drill down for
    # each area assigning them per store."
    #
    # `out` is ALREADY exactly the caller's stores: the RULE FIVE filters and the RBAC span keyset have
    # both been applied above. So the collective total is a straight sum of the very rows the
    # drill-down renders — aggregate == Σ per-store BY CONSTRUCTION, and a span-restricted viewer's
    # total can only ever cover their own stores. An unrestricted admin gets the whole org's roll-up,
    # unchanged from what the store rows already said.
    #
    # PURELY ADDITIVE: `stores` / `filters` / `applied` / `trending` / `setup_hint` are untouched, so
    # every existing consumer of this endpoint is byte-identical.
    #
    # SCOPE SOURCE: `scope_keyset` — the SAME span mechanism every other reporting surface here uses.
    # mod-platform-core is splitting reporting-vs-scheduling scope in a parallel package; this surface
    # consumes whatever `scope_keyset` resolves to, so that change composes automatically with no edit
    # here.
    collective = targets_engine.aggregate_stores(out)
    can_edit_targets, _caller = _can_edit_targets(authorization, org_id)
    scope_block = {
        'restricted': ks is not None,          # False = unrestricted admin / RBAC off
        'self_scoped': bool(is_self),
        # ADDITIVE: a self rep the system cannot place in any store. Lets a page distinguish "you
        # have no store yet" from "your store has no targets" without parsing the hint text.
        'no_store_assigned': bool(no_self_store),
        'stores_in_scope': len(out),
        'is_multi_store': len(out) > 1,        # the DM/area case the collective view is for
        'can_edit_targets': bool(can_edit_targets),
        'editable_store_codes': ([s.get('store_code') for s in out] if can_edit_targets else []),
    }
    return {'period': period, 'today': today.isoformat(), 'stores': out,
            'filters': filters, 'applied': applied, 'trending': trend_meta,
            'setup_hint': setup_hint, 'collective': collective, 'scope': scope_block}


# KPI → commission tier inputs (mirrors calculator.py KPI defaults).
# Each is (key, label, payout_config column, default target %).
ACTION_KPI_DEFS = [
    ('atu', 'ATU', 'kpi_atu_target', 55),
    ('protect', 'Protect', 'kpi_protect_target', 80),
    ('boostapp', 'Carrier App', 'kpi_boostapp_target', 65),
    ('familyplan', 'Family Plan', 'kpi_familyplan_target', 45),
    ('byod', 'BYOD', 'kpi_byod_target', 35),
    ('tmr3', 'TMR3', 'kpi_tmr3_target', 70),
    ('aal', 'AAL', 'kpi_aal_target', 5),
]
_AP_CAT_LABEL = {'activations': 'Activations', 'upgrades': 'Upgrades',
                 'byod': 'BYOD', 'accessories': 'Accessories'}
_KPI_DEFAULT_CARRIER = '00000000-0000-0000-0000-000000000000'  # nil carrier_id = the org default set


def _kpi_defs(org_id=ORG_ID, carrier_id=None):
    """Per-carrier KPI metric definitions (migration 060) as (key, label, payout_config_col, default)
    tuples — SAME shape as ACTION_KPI_DEFS, so callers are unchanged. Carrier-specific rows override the
    org-default (nil-carrier) set per key; falls back to the hard-coded ACTION_KPI_DEFS if the table is
    empty or migration 060 isn't applied (so behavior is unchanged until a tenant configures their own)."""
    try:
        rows = (sb().schema('commcalc').table('carrier_kpi_metric').select('*')
                .eq('org_id', org_id).eq('is_active', True).order('sort').execute().data) or []
    except Exception:
        return ACTION_KPI_DEFS
    if not rows:
        return ACTION_KPI_DEFS
    keep = [r for r in rows if r.get('carrier_id') in (_KPI_DEFAULT_CARRIER, carrier_id)]
    by_key = {}
    for r in sorted(keep, key=lambda r: 0 if r.get('carrier_id') == carrier_id and carrier_id else 1):
        k = r.get('metric_key')
        if k and k not in by_key:
            by_key[k] = r
    ordered = sorted(by_key.values(), key=lambda r: r.get('sort') or 0)
    out = [(r['metric_key'], r.get('label') or r['metric_key'],
            r.get('payout_config_col') or f"kpi_{r['metric_key']}_target",
            safe_float(r.get('target_default'))) for r in ordered]
    return out or ACTION_KPI_DEFS


@router.get("/carrier-kpi-metrics")
def list_carrier_kpi_metrics(carrier_id: str = "", org_id: str = ORG_ID):
    """KPI metric definitions for the org (optionally a carrier). Falls back to the built-in defaults as
    rows if migration 060 isn't applied yet, so the UI always has something to show."""
    try:
        rows = (sb().schema('commcalc').table('carrier_kpi_metric').select('*')
                .eq('org_id', org_id).order('sort').execute().data) or []
    except Exception:
        return {"metrics": [], "ready": False,
                "defaults": [{"metric_key": k, "label": l, "payout_config_col": c, "target_default": d}
                             for (k, l, c, d) in ACTION_KPI_DEFS]}
    if carrier_id:
        rows = [r for r in rows if r.get('carrier_id') in (_KPI_DEFAULT_CARRIER, carrier_id)]
    return {"metrics": rows, "ready": True, "default_carrier": _KPI_DEFAULT_CARRIER}


class SaveCarrierKpiMetricIn(LaxModel):
    metric_key: str = ""
    carrier_id: Any = None
    label: Any = None
    target_default: Any = None
    payout_config_col: Any = None
    sort: Any = None
    is_active: Any = True
    source_mode: Any = None
    id: Any = None


@router.post("/carrier-kpi-metrics")
def save_carrier_kpi_metric(body: SaveCarrierKpiMetricIn, org_id: str = ORG_ID):
    """Create/edit one KPI metric definition. carrier_id omitted/blank → the org default (nil) set."""
    key = (body.metric_key or "").strip()
    if not key:
        raise HTTPException(400, "metric_key required")
    row = {"org_id": org_id, "carrier_id": body.carrier_id or _KPI_DEFAULT_CARRIER,
           "metric_key": key, "label": body.label or key,
           "target_default": safe_float(body.target_default),
           "payout_config_col": body.payout_config_col or f"kpi_{key}_target",
           "sort": int(body.sort or 0), "is_active": bool(body.is_active)}
    if "source_mode" in body.model_fields_set:   # only when the toggle is used, so metric saves still work pre-mig-853
        row["source_mode"] = body.source_mode or "manual"
    try:
        if body.id:
            r = sb().schema('commcalc').table('carrier_kpi_metric').update(row).eq('id', body.id).eq('org_id', org_id).execute()
        else:
            r = sb().schema('commcalc').table('carrier_kpi_metric').upsert(row, on_conflict='org_id,carrier_id,metric_key').execute()
        return (r.data or [{}])[0]
    except Exception as e:
        raise HTTPException(500, f"save kpi metric failed (is migration 060 applied?): {e}")


@router.delete("/carrier-kpi-metrics/{metric_id}")
def delete_carrier_kpi_metric(metric_id: str, org_id: str = ORG_ID):
    sb().schema('commcalc').table('carrier_kpi_metric').delete().eq('org_id', org_id).eq('id', metric_id).execute()
    return {"deleted": metric_id}


# ── KPI actuals (manual now / email later) — mig 853 ──────────────────────────────────────────────
def _kpi_source_mode_map(client, org_id):
    """{metric_key: 'manual'|'email'} per carrier_kpi_metric.source_mode. Empty (→ all default 'manual')
    when mig 853's source_mode column isn't applied yet."""
    try:
        rows = (client.schema('commcalc').table('carrier_kpi_metric')
                .select('metric_key,source_mode').eq('org_id', org_id).execute().data) or []
    except Exception:
        return {}
    return {r.get('metric_key'): (r.get('source_mode') or 'manual') for r in rows}


def _kpi_effective_actuals(client, org_id, period, scope='store', metric_keys=None, entities=None):
    """{(entity, metric_key): {'value', 'source'}} — the effective KPI actual per entity honoring each
    metric's source_mode: the preferred source wins, the other is a fallback so a value still shows.
    Degrades to {} when the kpi_actual table (mig 853) isn't applied yet."""
    try:
        rows = (client.schema('commcalc').table('kpi_actual').select('*')
                .eq('org_id', org_id).eq('scope', scope).in_('period', _pvariants(period))
                .limit(200000).execute().data) or []
    except Exception:
        return {}
    modes = _kpi_source_mode_map(client, org_id)
    grouped = {}
    for r in rows:
        mk = r.get('metric_key'); ent = r.get('entity')
        if metric_keys and mk not in metric_keys:
            continue
        if entities and ent not in entities:
            continue
        grouped.setdefault((ent, mk), {})[r.get('source') or 'manual'] = r.get('value')
    out = {}
    for (ent, mk), bysrc in grouped.items():
        pref = modes.get(mk, 'manual')
        alt = 'email' if pref == 'manual' else 'manual'
        if bysrc.get(pref) is not None:
            out[(ent, mk)] = {'value': bysrc[pref], 'source': pref}
        elif bysrc.get(alt) is not None:
            out[(ent, mk)] = {'value': bysrc[alt], 'source': alt + ' (fallback)'}
    return out


@router.get("/kpi-actuals")
def list_kpi_actuals(period: str, scope: str = 'store', org_id: str = ORG_ID):
    """Raw stored KPI actual rows (both sources) for the period + the per-metric source modes, so the KPI
    page can prefill the manual grid and show which source is active. Degrades cleanly pre-mig-853."""
    try:
        rows = (sb().schema('commcalc').table('kpi_actual').select('*')
                .eq('org_id', org_id).eq('scope', scope).in_('period', _pvariants(period))
                .limit(200000).execute().data) or []
        ready = True
    except Exception:
        rows, ready = [], False
    return {"period": period, "scope": scope, "ready": ready, "rows": rows,
            "source_modes": _kpi_source_mode_map(sb(), org_id)}


class SaveKpiActualsIn(LaxModel):
    period: str = ""
    scope: Any = None
    updated_by: Any = None
    entries: Any = None


@router.post("/kpi-actuals")
def save_kpi_actuals(body: SaveKpiActualsIn, org_id: str = ORG_ID):
    """Upsert MANUAL KPI values. Body {period, scope?, updated_by?, entries:[{entity, metric_key, value}]}.
    Writes source='manual' only — never touches an 'email' row, so flipping source mode loses nothing."""
    period = (body.period or "").strip()
    if not period:
        raise HTTPException(400, "period required")
    scope = body.scope or "store"
    who = body.updated_by
    rows = []
    for e in (body.entries or []):
        ent = (str(e.get("entity") or "")).strip()
        mk = (str(e.get("metric_key") or "")).strip()
        if not ent or not mk:
            continue
        val = e.get("value")
        rows.append({"org_id": org_id, "scope": scope, "entity": ent, "period": period, "metric_key": mk,
                     "value": (None if val in ("", None) else safe_float(val)), "source": "manual", "updated_by": who})
    if not rows:
        return {"saved": 0}
    try:
        r = sb().schema('commcalc').table('kpi_actual').upsert(
            rows, on_conflict='org_id,scope,entity,period,metric_key,source').execute()
        return {"saved": len(r.data or rows)}
    except Exception as ex:
        raise HTTPException(500, f"save kpi actuals failed (is migration 853 applied?): {ex}")


class ImportParamountMtdIn(LaxModel):
    period: str = ""
    html: Any = None
    dry_run: Any = None
    updated_by: Any = None


@router.post("/kpi-import/paramount")
def import_paramount_mtd(body: ImportParamountMtdIn, org_id: str = ORG_ID):
    """Parse a Paramount Wireless MTD report (HTML email body) → store zulu / tmr3 / twp per door (Door
    TSP = store_code) as source='email' KPI actuals. Body {period, html, dry_run?}. Feeds only the
    qualifier gates — component counts stay on the rep-pay basis (owner decision)."""
    from app.modules.commcalc.paramount_kpi import parse_paramount_mtd_kpis
    period = (body.period or "").strip()
    html = body.html or ""
    if not period or not str(html).strip():
        raise HTTPException(400, "period and html are required")
    parsed = parse_paramount_mtd_kpis(html)
    preview = [{"store_code": c, **m} for c, m in sorted(parsed.items())]
    entries = [(c, mk, val) for c, mets in parsed.items() for mk, val in mets.items()]
    if body.dry_run:
        return {"stores": len(parsed), "values": len(entries), "preview": preview, "saved": 0}
    rows = [{"org_id": org_id, "scope": "store", "entity": c, "period": period, "metric_key": mk,
             "value": val, "source": "email", "updated_by": body.updated_by} for (c, mk, val) in entries]
    saved = 0
    if rows:
        try:
            r = sb().schema('commcalc').table('kpi_actual').upsert(
                rows, on_conflict='org_id,scope,entity,period,metric_key,source').execute()
            saved = len(r.data or rows)
        except Exception as ex:
            raise HTTPException(500, f"paramount import failed (is migration 853 applied?): {ex}")
    return {"stores": len(parsed), "values": len(entries), "preview": preview, "saved": saved}


@router.get("/inventory-recon")
def inventory_recon(store_code: str, period: str, max_days: int = 10, org_id: str = ORG_ID):
    """IMEI/serial reconciliation for a store + period — is every device accounted for? Matches B2B
    inventory (inventory_aging_device) against B2B sales (raw_sales.serial_1) and reports: devices that
    left the shelf with no sale (shrink), sales with no matching received device, uncategorized sales,
    and a sold-within-N-days aging split. Reuses the app's own IMEI normalizer + bucket classifier."""
    from datetime import timedelta
    from app.modules.commcalc import inventory_recon as _ir
    from app.modules.commcalc import gp_report as _gp
    require_org(org_id)
    client = sb()
    resolve_code = _store_code_resolver(client, org_id)
    sc = str(store_code).strip()

    def _derived_received(r):
        rd = r.get("received_date")
        if rd:
            return str(rd)[:10]
        aod = _mi_parse_date(r.get("as_of_date"))
        dis = r.get("days_in_stock")
        if aod is not None and dis is not None:
            try:
                return (aod - timedelta(days=int(dis))).isoformat()
            except (TypeError, ValueError):
                return None
        return None

    try:
        inv_rows = (client.schema("commcalc").table("inventory_aging_device")
                    .select("imei,store,on_hand,off_hand_as_of,received_date,as_of_date,days_in_stock")
                    .eq("org_id", org_id).limit(200000).execute().data) or []
    except Exception:
        inv_rows = []
    devices = [{"imei": r.get("imei"), "on_hand": r.get("on_hand"),
                "off_hand_as_of": r.get("off_hand_as_of"), "received": _derived_received(r)}
               for r in inv_rows if resolve_code(r.get("store") or "") == sc]

    try:
        sale_rows = (client.schema("commcalc").table("raw_sales")
                     .select("serial_1,store,trans_date,product_desc,voided,trans_type")
                     .eq("org_id", org_id).in_("period", _pvariants(period)).limit(200000).execute().data) or []
    except Exception:
        sale_rows = []
    sales = [{"serial": r.get("serial_1"), "trans_date": r.get("trans_date"), "product_desc": r.get("product_desc")}
             for r in sale_rows
             if str(r.get("serial_1") or "").strip()
             and not _gp.is_voided(r.get("voided"))
             and str(r.get("trans_type") or "").strip() != "Return"
             and resolve_code(r.get("store") or "") == sc]

    result = _ir.reconcile(devices, sales, max_days=int(max_days or 10))
    return {"store_code": sc, "period": period, **result}


@router.get("/coaching/{period}")
def rep_coaching(period: str, store: Optional[List[str]] = Query(default=None),
                 market: Optional[List[str]] = Query(default=None), rep: str = "",
                 authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Per-rep COACHING view: which KPIs each rep met vs missed, and WHY they're losing money
    (commission at risk below tier 1.0 + chargebacks deducted) + flags & coaching notes. Reuses
    the KPI defs + tier/at-risk logic from the action plan; adds per-rep chargebacks + flags.
    Powers the admin/DM coaching dashboard and the employee's own coaching card (rep filter).

    `store` / `market` accept EITHER one value (?store=X — the historical shape, and what every
    existing caller sends) or a repeated list (?store=X&store=Y), so a manager's whole span can be
    pushed DOWN into this aggregation instead of being computed for the org and filtered out in Python
    afterwards (team_snapshot). Single-value behaviour is unchanged: one value = a one-element set,
    matched exactly as before (store case-insensitively against the rep's store key, market as an
    EXACT string). `rep` stays a single value."""
    require_org(org_id)
    cperiod = _period_or_400(period)
    client = sb()
    store_sel = {x.upper() for x in _as_filter_list(store)}
    market_sel = set(_as_filter_list(market))     # market compares EXACT, as it always has
    cfg_rows = (client.schema('commcalc').table('payout_config')
                .select('*').eq('org_id', org_id).in_('period', _pvariants(cperiod)).limit(1).execute().data) or []
    cfg = cfg_rows[0] if cfg_rows else {}
    # ONE read of the KPI definitions for the whole request. This used to be re-read INSIDE the
    # per-rep loop below — an N+1 (one commcalc.carrier_kpi_metric round trip per rep) on a hot page,
    # and a latent unhandled 500: _kpi_defs falls back to ACTION_KPI_DEFS when its read fails, so a
    # tenant with a CUSTOM metric key plus one transient failure mid-loop hit `kpi_targets[k]` with a
    # key that no longer existed -> KeyError out of the handler. One list, read once, can't disagree.
    kpi_defs = _kpi_defs(org_id)
    kpi_targets = {k: (safe_float(cfg.get(col)) or float(dv)) for (k, _l, col, dv) in kpi_defs}
    t100 = int(cfg.get('tier_100_min_kpis') or 7)
    comms = (client.schema('commcalc').table('rep_commissions').select('*').eq('org_id', org_id).in_('period', _pvariants(cperiod)).execute().data) or []
    cb = (client.schema('commcalc').table('chargeback_items')
          .select('epay_salesperson,amount,deduct').eq('org_id', org_id).in_('period', _pvariants(cperiod)).execute().data) or []
    ops_lines_by = _ops_chargeback_deductions(client, org_id, cperiod)
    # OPEN only (mig 287): a flag whose condition has cleared must stop counting against the rep.
    try:
        flags = (client.schema('commcalc').table('flags')
                 .select('epay_salesperson,severity,description,coaching_note')
                 .eq('org_id', org_id).in_('period', _pvariants(cperiod))
                 .eq('status', flag_persist.STATUS_OPEN).execute().data) or []
    except Exception:                              # before migration 287
        flags = (client.schema('commcalc').table('flags')
                 .select('epay_salesperson,severity,description,coaching_note').eq('org_id', org_id).in_('period', _pvariants(cperiod)).execute().data) or []
    stores = (client.schema('storeops').table('stores').select('store_code,address,market').eq('org_id', org_id).execute().data) or []
    mkt_by = {}
    for s in stores:
        for key in (s.get('store_code'), s.get('address')):
            if key:
                mkt_by[str(key).strip().upper()] = s.get('market') or ''

    cb_by, fl_by = {}, {}
    for it in cb:
        k = (it.get('epay_salesperson') or '').strip().upper()
        if not k:
            continue
        d = cb_by.setdefault(k, {'total': 0.0, 'count': 0, 'deducted': 0.0})
        amt = safe_float(it.get('amount'))
        d['count'] += 1
        d['total'] += amt
        if it.get('deduct'):
            d['deducted'] += amt
    for f in flags:
        k = (f.get('epay_salesperson') or '').strip().upper()
        if not k:
            continue
        d = fl_by.setdefault(k, {'count': 0, 'high': 0, 'notes': []})
        d['count'] += 1
        if (f.get('severity') or '').upper() == 'HIGH':
            d['high'] += 1
        note = f.get('coaching_note') or f.get('description')
        if note and note not in d['notes'] and len(d['notes']) < 3:
            d['notes'].append(note)

    reps = []
    for cr in comms:
        name = (cr.get('storeops_name') or cr.get('epay_salesperson') or '').strip()
        if not name:
            continue
        eslp = (cr.get('epay_salesperson') or '').strip()
        if rep and rep.strip().upper() not in (name.upper(), eslp.upper()):
            continue
        st = (cr.get('store') or '').strip()
        if store_sel and st.upper() not in store_sel:
            continue
        mk = mkt_by.get(st.upper(), '')
        if market_sel and mk not in market_sel:
            continue
        tier = safe_float(cr.get('tier'))
        subtotal = safe_float(cr.get('subtotal'))
        kv = cr.get('kpi_values') or {}
        kpis = [{'kpi': k, 'label': lab, 'target': kpi_targets.get(k, safe_float(_d)),
                 'actual': round(safe_float(kv.get(k)), 1),
                 'met': safe_float(kv.get(k)) >= kpi_targets.get(k, safe_float(_d))}
                for (k, lab, _c, _d) in kpi_defs]
        kpis_met = cr.get('kpis_met')
        kpis_met = sum(1 for x in kpis if x['met']) if kpis_met is None else kpis_met
        at_risk = round(subtotal * (1.0 - tier), 2) if tier < 1.0 else 0.0
        keys = {name.upper(), eslp.upper()} - {''}
        cbd = {'total': 0.0, 'count': 0, 'deducted': 0.0}
        fld = {'count': 0, 'high': 0, 'notes': []}
        for kk in keys:
            x = cb_by.get(kk)
            if x:
                cbd['total'] += x['total']; cbd['count'] += x['count']; cbd['deducted'] += x['deducted']
            y = fl_by.get(kk)
            if y:
                fld['count'] += y['count']; fld['high'] += y['high']
                for n in y['notes']:
                    if n not in fld['notes'] and len(fld['notes']) < 3:
                        fld['notes'].append(n)
        total_payout = round(safe_float(cr.get('total_payout')), 2)
        ops_amt_raw, ops_lines = _ops_cb_for_rep(ops_lines_by, keys)
        # cap at basis (total_payout - legacy chargeback_items deduction) so final never floors below 0
        ops_amt = min(ops_amt_raw, max(0.0, total_payout - cbd['deducted'])) if ops_amt_raw > 0 else ops_amt_raw
        fp = cr.get('final_payout')
        final_payout = round((safe_float(fp) if fp is not None else total_payout - cbd['deducted']) - ops_amt, 2)
        reps.append({
            'rep': name, 'store': st, 'market': mk, 'tier': tier,
            'kpis_met': kpis_met, 'total_kpis': cr.get('total_kpis') or 7,
            'subtotal': round(subtotal, 2), 'total_payout': total_payout, 'final_payout': final_payout,
            'at_risk': at_risk, 'kpis': kpis, 'short_kpis': [x['label'] for x in kpis if not x['met']],
            'need_for_full': max(0, t100 - kpis_met),
            'chargeback_total': round(cbd['total'], 2), 'chargeback_deducted': round(cbd['deducted'], 2),
            'chargeback_count': cbd['count'], 'flag_count': fld['count'], 'flag_high': fld['high'],
            'ops_chargeback_deduction': round(ops_amt, 2), 'ops_chargeback_lines': ops_lines,
            'coaching_notes': fld['notes'], 'money_on_table': round(at_risk + cbd['deducted'] + ops_amt, 2),
        })
    reps.sort(key=lambda r: -r['money_on_table'])
    from app.modules.storeops.router import scope_keyset, in_keyset
    ks = scope_keyset(authorization, org_id)
    if ks is not None:
        reps = [r for r in reps if in_keyset(ks, r.get('store'))]
    summary = {'reps': len(reps),
               'total_at_risk': round(sum(r['at_risk'] for r in reps), 2),
               'total_chargebacks': round(sum(r['chargeback_deducted'] for r in reps), 2),
               'total_ops_chargebacks': round(sum(r.get('ops_chargeback_deduction', 0) for r in reps), 2),
               'total_money_on_table': round(sum(r['money_on_table'] for r in reps), 2),
               'below_tier': sum(1 for r in reps if r['tier'] < 1.0)}
    return {"period": period, "reps": reps, "summary": summary}


def _team_totals(stores):
    """Sum the additive per-category target fields across a set of stores for the team headline."""
    cats = {}
    for s in stores:
        for cat, c in (s.get('categories') or {}).items():
            t = cats.setdefault(cat, {'unit': c.get('unit'), 'monthly': 0.0, 'achieved_mtd': 0.0,
                                      'need': 0.0, 'today_target': 0.0})
            t['monthly']      += safe_float(c.get('monthly'))
            t['achieved_mtd'] += safe_float(c.get('achieved_mtd'))
            t['need']         += safe_float(c.get('need'))
            t['today_target'] += safe_float(c.get('today_target'))
    for t in cats.values():
        for k in ('monthly', 'achieved_mtd', 'need', 'today_target'):
            t[k] = round(t[k], 2)
        t['pct'] = round(100 * t['achieved_mtd'] / t['monthly'], 1) if t['monthly'] > 0 else 0.0
    return cats


# ── TEAM-SNAPSHOT TTL MEMO (read side only) ──────────────────────────────────────────────────────
# `/team/{period}/snapshot` is the ONLY fetch gating the My-Team page's spinner, and it recomputed the
# FULL targets + coaching rollup on every single load: the sales union + `_compute_feed_actuals_py` +
# `_exec_mtd` (trending) + a nested store x rep Python pass in get_targets_summary, plus the whole
# coaching aggregation. FastAPI runs this in the shared worker, so a couple of loads in a row starved
# every other request on the box (2026-07-30 incident: public /health 21.5s, recovered after).
# Pushing the caller's span down (TIER 1, below) fixes a manager; for an OWNER whose span IS the org
# there is nothing to narrow, so the heavy pair is memoized per (org_id, canonical period, today,
# span) for _TEAM_SNAP_TTL seconds. DISPLAY-ONLY: this caches a read-side rollup of already-computed
# data — no payout number is produced, stored or altered anywhere in it.
#
# Traps this deliberately avoids (the 2026-07-25 Gate-1 rework):
#   * `get_supabase()` is a PROCESS-WIDE SINGLETON, so the key is PLAIN VALUES ONLY — never the client
#     object, which would make an entry live for the whole process lifetime.
#   * `time.monotonic()`, not wall time, so a clock adjustment can neither expire nor extend an entry.
#   * BOUNDED (_TEAM_SNAP_MAX) — cleared wholesale rather than allowed to grow without limit.
#   * Deep-copied IN and OUT, so no caller can mutate a cached payload.
#   * Staleness is bounded THREE ways: the TTL, an explicit bust when a commission recompute for that
#     org+period finishes (`_run_calculation`), and `?refresh=1` on the endpoint.
# TTL follows the platform-core `_DERIVE_TTL` precedent (core/import_health.py, 900s).
_TEAM_SNAP_TTL = 900.0
_TEAM_SNAP_MAX = 200
_TEAM_SNAP_LOCK = threading.Lock()
_team_snap_memo: dict = {}      # key -> (monotonic_expiry, [targets_summary, coaching])


def _team_snap_key(org_id, cperiod, today_key, span):
    """Cache key. Every element is a plain str/tuple (see the trap note above)."""
    return (str(org_id), str(cperiod), str(today_key), tuple(str(s) for s in (span or ())))


def _team_snap_get(key):
    """The memoized [summary, coaching] pair for `key`, or None. Returns a DEEP COPY."""
    import time as _t, copy as _cp
    with _TEAM_SNAP_LOCK:
        ent = _team_snap_memo.get(key)
        if not ent:
            return None
        if ent[0] <= _t.monotonic():
            _team_snap_memo.pop(key, None)
            return None
        return _cp.deepcopy(ent[1])


def _team_snap_put(key, value):
    import time as _t, copy as _cp
    with _TEAM_SNAP_LOCK:
        if len(_team_snap_memo) >= _TEAM_SNAP_MAX:
            _team_snap_memo.clear()
        _team_snap_memo[key] = (_t.monotonic() + _TEAM_SNAP_TTL, _cp.deepcopy(value))


def _team_snap_invalidate(org_id=None, period=None):
    """Drop memoized team-snapshot rollups. Called when a commission recompute for an org+period
    FINISHES — the coaching half reads rep_commissions, which that recompute just rewrote, so the
    next My-Team load must not serve the pre-recompute numbers for up to the TTL. Period-spelling
    tolerant (a calc can run as '2026-07' while the page asked for 'July 2026'). No args = drop
    everything (deploy / ops escape hatch). NEVER raises: it is called from the calc path."""
    try:
        with _TEAM_SNAP_LOCK:
            if org_id is None and period is None:
                _team_snap_memo.clear()
                return None
            pv = {str(p) for p in _pvariants(period)} if period is not None else None
            for k in [k for k in _team_snap_memo
                      if (org_id is None or k[0] == str(org_id)) and (pv is None or k[1] in pv)]:
                _team_snap_memo.pop(k, None)
    except Exception as e:
        print(f"WARN _team_snap_invalidate skipped ({org_id}/{period}): {e}")
    return None


@router.get("/team/{period}/snapshot")
async def team_snapshot(period: str, authorization: str = Header(default=""),
                        unit_id: str = "", today: str = "", refresh: bool = False,
                        org_id: str = ORG_ID):
    """Manager TEAM snapshot for the signed-in caller's span (or a chosen unit_id within it).
    Reuses get_targets_summary (per-store today/pace/need/achieved) + rep_coaching (per-rep
    money-at-risk/KPIs/chargebacks), filtered to the span's store_codes. Per-rep drill-down uses the
    existing GET /core/employee-dashboard. Default-scoped (no hard refusal yet — Phase 5 enforces).

    PERIOD: either spelling is accepted ('July 2026' — what the platform period selector emits — or
    '2026-07'); both resolve to the ONE canonical 'Month YYYY' this chain needs (`_period_bounds`
    rejects '2026-07'). An unparseable period is a clean 400, never a 500.

    PERFORMANCE (2026-07-30 incident, ref 3bf51b4d): the caller's span is pushed DOWN into both
    aggregations, and the heavy pair is TTL-memoized — see the `_TEAM_SNAP_TTL` note above.
    `?refresh=1` forces a fresh pass. READ-ONLY: nothing in this chain writes."""
    from app.modules.storeops.router import _caller_span_codes, _unit_store_codes, caller_scope
    cperiod = _period_or_400(period)
    if unit_id:
        codes = _unit_store_codes(org_id, unit_id)
    else:
        try:
            codes = _caller_span_codes(authorization, org_id)
        except HTTPException:
            codes = []
    # Phase 5: when enforcement is on, a non-admin can't roll up a unit outside their own span.
    allowed = caller_scope(authorization, org_id)   # None = unrestricted (admin / open mode)
    if allowed is not None:
        codes = [c for c in codes if c in allowed]
    codes_set = {c.strip().upper() for c in codes}
    if not codes_set:
        return {"period": period, "is_manager": False, "span_store_codes": [],
                "stores": [], "reps": [], "totals": {}, "money_on_table": 0.0}
    # store_code <-> address keys so coaching reps (whose 'store' may be an address) still match.
    stores_meta = sb().schema('storeops').table('stores').select('store_code,address').eq('org_id', org_id).execute().data or []
    keys = set(codes_set)
    for s in stores_meta:
        sc = str(s.get('store_code') or '').strip().upper()
        if sc in codes_set:
            ad = str(s.get('address') or '').strip().upper()
            if ad:
                keys.add(ad)
    # ── TIER 1: push the caller's span DOWN into both aggregations. `stores=` already existed on
    #    get_targets_summary and was never passed (which is also what crashed this endpoint — an
    #    unpassed repeated-Query param arrives as the truthy, non-iterable Query object; see
    #    _as_filter_list); rep_coaching's store filter now takes a list. The SAME Python span filters
    #    still run underneath, so the response is byte-identical — the pushdown only stops work that
    #    was going to be discarded. `markets`/`reps` are passed EXPLICITLY for the same crash reason.
    #    For an owner whose span is the whole org this is a no-op; TIER 2 (the memo) is their fix.
    push_stores = sorted(c for c in codes_set if c)
    # A blank span key means "reps whose store is blank" to the Python filter below but "no filter" to
    # the pushdown, so only push the coaching keys when every one of them is a real, non-blank key.
    push_keys = sorted(keys) if all(str(k).strip() for k in keys) else None
    ckey = _team_snap_key(org_id, cperiod, today or _date.today().isoformat(),
                          tuple(push_stores) + ('|',) + tuple(push_keys or ()))
    pair = None if refresh else _team_snap_get(ckey)
    if pair is None:
        summ = await get_targets_summary(cperiod, today=today, stores=push_stores or None,
                                        markets=None, reps=None, org_id=org_id)
        coach = rep_coaching(cperiod, store=push_keys, org_id=org_id)
        _team_snap_put(ckey, [summ, coach])
    else:
        summ, coach = pair[0], pair[1]
    in_span = [s for s in summ.get('stores', []) if str(s.get('store_code') or '').strip().upper() in codes_set]
    team_reps = [r for r in coach.get('reps', []) if str(r.get('store') or '').strip().upper() in keys]
    return {"period": period, "today": summ.get('today'), "is_manager": True,
            "span_store_codes": sorted(codes_set), "stores": in_span, "reps": team_reps,
            "totals": _team_totals(in_span),
            "money_on_table": round(sum(safe_float(r.get('money_on_table')) for r in team_reps), 2)}


@router.get("/exec-overview/{period}")
def exec_overview(period: str, org_id: str = ORG_ID):
    """Owner/exec single-pane: headline tiles + a store leaderboard, rolled up from the per-rep
    coaching aggregation (commissions paid / at-risk / chargebacks / flags / reps below tier).

    Accepts either period spelling. This one MATTERED silently: the P&L headline below resolves the
    period with `calculator.parse_period`, which maps '2026-07' to JANUARY — so a machine caller using
    the dashed spelling got January's P&L stapled to this month's commission tiles, with no error."""
    require_org(org_id)
    cperiod = _period_or_400(period)
    cd = rep_coaching(cperiod, org_id=org_id)
    reps = cd.get("reps", [])
    s = cd.get("summary", {})
    try:
        cbr = sb().schema('commcalc').table('chargeback_review').select('status').eq('org_id', org_id).execute().data or []
        open_cb = sum(1 for r in cbr if (r.get('status') or 'open') == 'open')
    except Exception:
        open_cb = 0
    by_store = {}
    for r in reps:
        st = r.get('store') or '—'
        d = by_store.setdefault(st, {'store': st, 'market': r.get('market') or '', 'reps': 0,
                                     'paid': 0.0, 'at_risk': 0.0, 'chargebacks': 0.0, 'flags': 0, 'on_table': 0.0})
        d['reps'] += 1
        d['paid'] += r.get('final_payout') or 0
        d['at_risk'] += r.get('at_risk') or 0
        d['chargebacks'] += r.get('chargeback_deducted') or 0
        d['flags'] += r.get('flag_count') or 0
        d['on_table'] += r.get('money_on_table') or 0
    stores = sorted(by_store.values(), key=lambda x: -x['paid'])
    for d in stores:
        for k in ('paid', 'at_risk', 'chargebacks', 'on_table'):
            d[k] = round(d[k], 2)
    # P&L headline from the Account module's consolidated statement (period stored as YYYY-MM).
    pl = {}
    try:
        pm = parse_period(cperiod)
        ym = f"{pm['year']}-{pm['month']:02d}"
        prow = (sb().schema('commcalc').table('account_statements').select('payload')
                .eq('org_id', org_id).eq('period', ym).eq('statement_type', 'pl')
                .eq('scope_key', 'consolidated').limit(1).execute().data) or []
        if prow:
            p = prow[0].get('payload') or {}
            pl = {'revenue': p.get('revenue'), 'gross_profit': p.get('gross_profit'), 'net_income': p.get('net_income')}
    except Exception:
        pass
    return {"period": period, "pl": pl,
            "tiles": {"commissions_paid": round(sum(r.get('final_payout') or 0 for r in reps), 2),
                      "commission_at_risk": s.get('total_at_risk', 0),
                      "chargebacks_deducted": s.get('total_chargebacks', 0),
                      "money_on_table": s.get('total_money_on_table', 0),
                      "reps": s.get('reps', 0), "below_tier": s.get('below_tier', 0),
                      "open_chargebacks": open_cb},
            "stores": stores}


# ════════════════════════════════════════════════════════════════════════════════════════════════
# EXECUTIVE MTD SUMMARY — the b2bsoft "Month To Date Location/Employee Sales Report", replicated from the
# org-corrected sales source so it works for EVERY tenant (luxelink + house) with NO monthly upload.
# DISPLAY-ONLY: reads sales, writes nothing, touches no pay path. Metric DEFINITIONS are CONFIG
# (exec_metric_config, mig 204) — NOT a ninth hard-coded accessory classifier (accessory-divergence note).
# ════════════════════════════════════════════════════════════════════════════════════════════════
# Defaults DERIVED from the real luxelink Total-Wireless Sales-Transaction-Details export. The ingest
# stores category = Category-column OR System-Category-column (router.py ~694), so each token list carries
# BOTH variants (System Category CellPhone/RTR Product/Accessory + Category KittedBranded/HandsetBranded/
# Other Carr. payments). Tokens are lowercase; the engine lowercases each sale line before matching.
_EXEC_METRIC_DEFAULTS = {
    'activation':     {'rules': {'byod': ['byod'], 'upgrade': ['upgrade'], 'port': ['port']}, 'basis': 'count'},
    'phones':         {'rules': {'category': ['cellphone', 'kittedbranded']}, 'basis': 'count'},
    'bill_payment':   {'rules': {'department': ['rtr'], 'category': ['rtr product', 'other carr. payments']}, 'basis': 'count'},
    'accessory':      {'rules': {'category': ['accessory', 'handsetbranded', 'accessories']}, 'basis': 'ext_price'},
    'activation_fee': {'rules': {'product_desc_contains': ['access charge']}, 'basis': 'ext_price'},
    'protect':        {'rules': {'product_desc_contains': ['protect'],
                                 'exclude_product_desc_contains': ['screen protect'],
                                 'exclude_department': ['rtr'],
                                 'exclude_category': ['rtr product', 'other carr. payments']}, 'basis': 'count'},
}
_EXEC_BUCKETS = tuple(_EXEC_METRIC_DEFAULTS.keys())


def _exec_metric_config(client, org_id):
    """Per-tenant Executive-MTD metric DEFINITIONS (exec_metric_config, mig 204), falling back to the
    DERIVED code defaults so the report works before the migration runs / for an un-seeded tenant. Returns
    {bucket: {'rules': {...}, 'basis': 'count'|'ext_price'}}. SAP-configurable: definitions are config, not
    a hard-coded classifier."""
    cfg = {k: {'rules': dict(v['rules']), 'basis': v['basis']} for k, v in _EXEC_METRIC_DEFAULTS.items()}
    try:
        rows = (client.schema('commcalc').table('exec_metric_config')
                .select('bucket,rules,basis').eq('org_id', org_id).execute().data) or []
        for r in rows:
            b = r.get('bucket')
            if b in cfg:
                cfg[b] = {'rules': r.get('rules') or {}, 'basis': r.get('basis') or cfg[b]['basis']}
    except Exception:
        pass
    return cfg


# ── PER-METRIC SOURCE OF TRUTH (mig 923) ─────────────────────────────────────────────────────────
# The default authoritative source for each metric when the tenant has no metric_source_of_truth row.
_METRIC_SOURCE_DEFAULTS = {"activations": "activation_details", "bill_payments": "sales_agg"}
# Metrics whose basis-of-truth AUTO-ACTIVATES with no config (owner 2026-08-26: "it should be automatic,
# no need to update or wire it — Activation Details becomes the basis of truth for all b2bsoft tenants").
# The consumers (Exec MTD / Sales Report) STILL fall back to the sales basis when the report has NO rows
# for the period, so a tenant that never uploaded Activation Details stays BYTE-IDENTICAL. Auto-on only
# changes anything for a tenant that actually has the report ingested — exactly the intended set.
_METRIC_AUTO_ENABLED = {"activations"}


def _metric_source(client, org_id, metric):
    """Resolve the per-metric SOURCE OF TRUTH (mig 923). Returns
    {'metric','source','enabled','reconcile_with','processor','assigned_user','tolerance','configured'}.

    No config row (every org, pre-923): a metric in _METRIC_AUTO_ENABLED (activations) defaults to its
    basis-of-truth source ENABLED — but the consumer gates on the report actually having rows, so a tenant
    without that report is byte-identical. An explicit config row always wins (a tenant can disable it).
    Never raises."""
    default = {"metric": metric, "source": _METRIC_SOURCE_DEFAULTS.get(metric, "sales_agg"),
               "enabled": (metric in _METRIC_AUTO_ENABLED), "reconcile_with": "sales_agg",
               "processor": None, "assigned_user": None, "tolerance": 0.0, "configured": False}
    try:
        rows = (client.schema("commcalc").table("metric_source_of_truth")
                .select("*").eq("org_id", org_id).eq("metric", metric).limit(1).execute().data) or []
    except Exception:
        return default
    if not rows:
        return default
    r = rows[0]
    return {"metric": metric, "source": (r.get("source") or default["source"]),
            "enabled": bool(r.get("enabled")),
            "reconcile_with": r.get("reconcile_with") or None,
            "processor": r.get("processor") or None,
            "assigned_user": r.get("assigned_user") or None,
            "tolerance": float(r.get("tolerance") or 0.0),
            "configured": True}


# Map an Activation Details bucket (New Activation / Port / BYOD / Upgrade / Tablet / Home Internet / Edge /
# Other) onto the Exec-MTD activation keys. Only Port / BYOD / Upgrade are their own columns; every other
# activation family folds into the base 'activation' column (Tablet / Home Internet / Edge / plain New all
# count as activations toward Total Activation, exactly as the b2bsoft MTD report counts them).
_AD_EXEC_KEY = {"Port": "port", "BYOD": "byod", "Upgrade": "upgrade"}


def _ad_activation_buckets(client, org_id, period, ckey_fn=None, cut=None,
                           rng_from=None, rng_to=None, no_overlap=False):
    """Aggregate the b2b Activation Details basis into per-canonical-store and per-rep activation buckets
    {'activation','port','byod','upgrade'} for the Exec-MTD source-of-truth override + reconciliation.
    Applies the SAME MTD date-cut / date-range window the sales cells use, so the two bases compare on the
    same window. Stores are keyed by the SAME canonical key Exec MTD groups by (`ckey_fn`), so an override
    lands on the matching store row. Returns (by_store, by_rep, n_rows); empty maps when Activation Details
    has no rows for the period. DISPLAY/recon only."""
    rows = _cr_resolve_activation_details(client, org_id, period, {"market_for": (lambda s: "")})
    ck = ckey_fn or (lambda s: str(s or "").strip().lower())
    by_store, by_rep, n = {}, {}, 0
    for r in rows:
        d10 = r.get("trans_date") or ""
        if cut and d10 and d10 > cut:
            continue
        if rng_from or rng_to:
            if no_overlap:
                continue
            if not d10:
                continue            # a windowed report cannot place an undated activation
            if (rng_from and d10 < rng_from) or (rng_to and d10 > rng_to):
                continue
        n += 1
        fld = _AD_EXEC_KEY.get(r.get("bucket") or "", "activation")
        st = ck(r.get("store") or "") or "—"
        rep = (r.get("salesperson") or "").strip() or "—"
        s_slot = by_store.setdefault(st, {"activation": 0, "port": 0, "byod": 0, "upgrade": 0,
                                          "_name": (r.get("store") or st)})
        r_slot = by_rep.setdefault(rep, {"activation": 0, "port": 0, "byod": 0, "upgrade": 0, "_name": rep})
        s_slot[fld] += 1
        r_slot[fld] += 1
    return by_store, by_rep, n


def _ad_cells_full(client, org_id, period, ckey_fn=None):
    """Per-(canonical-store, rep, date) Activation Details counts, split into the SAME columns b2b's Location
    Sales Report shows: {new, port, byod, tablet, home_internet, edge, upgrade}. `new` = New Activation + Other
    only (the pure New column); Tablet / Home Internet / Edge are broken out on their own so the Sales Report
    can reconcile column-by-column with the back-office (owner 2026-08-27: those were previously folded into
    `new`, inflating the Activation column). Total Activation = new+port+byod+tablet+home_internet+edge,
    excluding Upgrade. The ONE AD activation source both Exec MTD and the Sales Report read via
    _apply_activation_basis."""
    rows = _cr_resolve_activation_details(client, org_id, period, {"market_for": (lambda s: "")})
    ck = ckey_fn or (lambda s: str(s or "").strip().lower())
    cells, n = {}, 0
    _slot0 = {"new": 0, "port": 0, "byod": 0, "tablet": 0, "home_internet": 0, "edge": 0, "upgrade": 0}
    for r in rows:
        n += 1
        b = r.get("bucket") or ""
        key = (ck(r.get("store") or "") or "—", (r.get("salesperson") or "").strip() or "—",
               str(r.get("trans_date") or "")[:10])
        slot = cells.setdefault(key, {**_slot0, "_name": (r.get("store") or key[0])})
        if b == "Upgrade":
            slot["upgrade"] += 1
        elif b == "BYOD":
            slot["byod"] += 1
        elif b == "Port":
            slot["port"] += 1
        elif b == "Tablet":
            slot["tablet"] += 1
        elif b == "Home Internet":
            slot["home_internet"] += 1
        elif b == "Edge":
            slot["edge"] += 1
        else:
            slot["new"] += 1          # New Activation + Other
    return cells, n


def _blank_sales_cell(store, rep, date):
    """An empty _sales_cell_agg-shaped cell (all metrics zero) — used to ADD a store/rep/day that exists in
    Activation Details but not in the sales feed, so its activations still show (with zero sales columns)."""
    return {"store": store, "salesperson": rep, "trans_date": date, "login": None,
            "_txn": set(), "_prem": set(), "_byod": set(), "_upg": set(), "_port": set(),
            "_swap": set(), "_billpay": set(), "lines": 0, "revenue": 0.0, "gp": 0.0,
            "accessory_rev": 0.0, "setup_fee_rev": 0.0, "box_count": 0, "total_phones": 0,
            "bill_qty": 0, "bill_amt": 0.0, "activation_fee": 0.0, "protect": 0,
            "act_new": 0, "act_port": 0, "act_byod": 0, "act_upg": 0,
            "act_tablet": 0, "act_home_internet": 0, "act_edge": 0}


def _apply_activation_basis(client, org_id, period, cells, ckey_fn, restrict_stores=None):
    """THE single place that decides the activation BASIS for every display consumer (owner 2026-08-26:
    "wire once, applies everywhere — no per-surface wiring"). Sets explicit activation COUNT fields
    (act_new / act_port / act_byod / act_upg) on every shared cell; the Sales Report and Exec MTD both read
    THESE instead of re-deriving from the trans-id sets, so a basis change moves both at once.

    Defaults exactly reproduce the sales-feed counts (act_new = prem−port, etc.) → an INACTIVE basis is
    BYTE-IDENTICAL. When the tenant's basis is Activation Details (auto-on when that report has rows), the
    fields are REPLACED with the AD counts per (canonical store, rep, date): a cell present only in AD is
    ADDED (respecting `restrict_stores` — the filtered store set — when given), a sales cell absent from AD
    has its activation counts ZEROED (AD is authoritative). Mutates `cells` in place; returns src_meta
    {active, basis, ad_rows}."""
    for a in cells.values():
        a["act_new"] = len(a["_prem"]) - len(a["_port"])
        a["act_port"] = len(a["_port"])
        a["act_byod"] = len(a["_byod"])
        a["act_upg"] = len(a["_upg"])
        # The sales feed does not distinguish tablet / home-internet / edge → 0 (they stay folded inside the
        # feed's own `new` sense). An INACTIVE basis is therefore byte-identical to before this split.
        a["act_tablet"] = a["act_home_internet"] = a["act_edge"] = 0
    msrc = _metric_source(client, org_id, "activations")
    if not (msrc.get("enabled") and msrc.get("source") == "activation_details"):
        return {"active": False, "basis": "sales_agg", "ad_rows": 0}
    ad_cells, ad_n = _ad_cells_full(client, org_id, period, ckey_fn)
    if not ad_n:
        return {"active": False, "basis": "sales_agg", "ad_rows": 0}
    for a in cells.values():
        a["act_new"] = a["act_port"] = a["act_byod"] = a["act_upg"] = 0   # AD authoritative
        a["act_tablet"] = a["act_home_internet"] = a["act_edge"] = 0
    for key, ad in ad_cells.items():
        if key not in cells:
            if restrict_stores is not None and key[0] not in restrict_stores:
                continue
            cells[key] = _blank_sales_cell(ad.get("_name") or key[0], key[1], key[2])
        a = cells[key]
        # act_new stays FOLDED (new + tablet + home-internet + edge) so every existing consumer — Exec MTD's
        # act_new+act_port, the Sales Report total — is unchanged; the three sub-counts are ALSO exposed so the
        # Sales Report can show them as their own columns and display a PURE New column (act_new − the three).
        a["act_tablet"], a["act_home_internet"], a["act_edge"] = ad["tablet"], ad["home_internet"], ad["edge"]
        a["act_new"] = ad["new"] + ad["tablet"] + ad["home_internet"] + ad["edge"]
        a["act_port"], a["act_byod"], a["act_upg"] = ad["port"], ad["byod"], ad["upgrade"]
    return {"active": True, "basis": "activation_details", "ad_rows": ad_n}


def _exec_line_match(rule, dept, cat, pdesc):
    """True if a sale line matches a bucket rule (all case-insensitive; inputs already lowercased).
    category/department = exact membership in a token list; product_desc_contains = substring; exclude_*
    negate first. Match = ANY positive predicate true AND no exclusion true."""
    if rule.get('exclude_department') and dept in rule['exclude_department']:
        return False
    if rule.get('exclude_category') and cat in rule['exclude_category']:
        return False
    if rule.get('exclude_product_desc_contains') and any(t in pdesc for t in rule['exclude_product_desc_contains']):
        return False
    if rule.get('category') and cat in rule['category']:
        return True
    if rule.get('department') and dept in rule['department']:
        return True
    if rule.get('product_desc_contains') and any(t in pdesc for t in rule['product_desc_contains']):
        return True
    return False


def _exec_act_class(ct, rules):
    """Activation split (b2bsoft Location/Employee report): BYOD/Upgrade/Port by keyword-CONTAINS on the
    contract_type (config tokens), any OTHER non-blank contract_type = a plain Activation. Priority
    upgrade > byod > port > activation (so 'BYOD Port' = BYOD, 'Port with IDV' = Port). This is the ONE
    split the spreadsheet uses; it reuses the same 'non-blank contract_type = an activation' rule as
    classify_contract_type/_compute_feed_actuals_py but adds the Port refinement. None = not an activation
    line (blank contract_type — e.g. an accessory/bill-payment line)."""
    c = (ct or '').strip().lower()
    if not c:
        return None
    if any(t in c for t in (rules.get('upgrade') or [])):
        return 'upgrade'
    if any(t in c for t in (rules.get('byod') or [])):
        return 'byod'
    if any(t in c for t in (rules.get('port') or [])):
        return 'port'
    return 'activation'


def _exec_mtd(client, org_id, period, stores=None, markets=None, reps=None, today=None,
              date_from=None, date_to=None):
    """Executive Month-To-Date summary — the b2bsoft 'Month To Date Location/Employee Sales Report',
    now DERIVED FROM the EXACT SAME aggregation the Sales Report uses (owner directive 2026-07-16: "the
    Sales Report is correct — Exec MTD should take its cumulative numbers from there"). Reads the SAME
    `_sales_rows_union` (feed leads the OPEN month, raw_sales a closed one, filling the other's (day × store)
    gaps) and the SAME `_sales_cell_agg` row-level pass — canonical skip rules (voided / Returns / the
    blank-or-'admin' rep), the shared classify_contract_type + _is_accessory, DISTINCT trans_id per bucket —
    then rolls the cells up by store / employee, applies the MTD date-cut, and trends. Works for luxelink AND
    the house org with NO monthly upload. DISPLAY-ONLY (reads sales, writes nothing).

    The base activation buckets (Activation / Port / BYOD / Upgrade) + Accessory$ come from the shared
    classifier so they EQUAL the Sales Report's; exec_metric_config now only EXTENDS — the configurable Port
    sub-split + the b2bsoft per-line columns the Sales Report doesn't carry (Total Phones / Bill Payment /
    Activation Fee / Total Protect). `today` is injectable (defaults to the server date) so the MTD date-cut
    + trending are unit-testable.

    RULE FIVE standardized filters (2026-07-16): optional `stores` / `markets` / `reps` multi-selects filter
    the UNION rows SERVER-SIDE (before bucketing) so the by-location table, the by-employee table, the
    trending math AND the exports all reflect the same filtered set. Filter OPTIONS are returned in `filters`
    (pick-don't-type over the org's real data) computed from the UNFILTERED union.

    Verified formulas: Total Activation = Activation+Port+BYOD+Upgrade; Trending Box = Total Activation ×
    days_in_month ÷ complete_days_elapsed; Trending Acc. Sales likewise on Acc. Sales; Conv. = Total
    Activation ÷ Bill Payment Qty; APB = Acc. Sales ÷ Total Activation. Closed/past month trending = actual.

    TWO ACCESSORY BASES (2026-07-30, owner: "accessory sales in Executive MTD are different from the
    accessory target link"). Both come from the ONE shared `_sales_cell_agg`, which splits every line
    into `accessory_rev` and `setup_fee_rev`:
      • `acc_sales`       = PURE accessory$ — identical to the Sales Report's `accessory_rev` and to the
                            b2bsoft column this report replicates. `apb` / `trending_acc_sales` use it.
      • `acc_plus_setup`  = accessory$ + device SET-UP FEE — the basis the Accessory Targets page
                            measures achieved/target in (owner directive 2026-07-17: the set-up fee is a
                            separate PAY item, never folded into the accessory$ number, but it DOES
                            count toward the accessory TARGET).
    Neither is "the" answer; showing both, labelled, is what makes the two pages reconcile to the cent.
    `setup_fee` is the bridge between them. DISPLAY-ONLY — no payout reads any of this.

    DATE RANGE (owner directive 2026-08-11, "Executive MTD is missing the date-range filter"):
    optional `date_from` / `date_to` (YYYY-MM-DD, inclusive) narrow the report to a slice of the month
    being viewed. The range is CLAMPED to that month rather than silently spanning others — the report
    is built from ONE period's union (`_sales_rows_union(period)`), so a range reaching outside it could
    only ever return the part that is loaded, and a truncated answer that does not say it was truncated
    is the failure mode worth avoiding. `date_range.clamped` reports it when that happens, and
    `date_range.no_overlap` when the requested window misses the month entirely (every table is then
    legitimately empty rather than quietly showing the whole month).
    TRENDING follows the window: the factor stays "project to a FULL month" (× days_in_month) but the
    divisor becomes the COMPLETE days inside the selected range, so a 7-day slice projects off 7 days,
    not off the month-to-date. `trending.basis` says which of the two is in force, because the same
    column meaning two different things without saying so is how two surfaces stop reconciling.
    Rows with NO date cannot be placed in a window: they are excluded while a range is active and
    counted in `date_range.undated_excluded` (they are included, as before, when it is not)."""
    cfg = _exec_metric_config(client, org_id)
    acfg = _accessory_config(client, org_id)
    rows, meta = _sales_rows_union(client, org_id, period)

    # ── Market resolver (store_mapping; keyed by address / code / leading store-number) — inline + optional
    #    (never 500 the summary over a store_mapping read). Mirrors the sales-report resolver so the two
    #    pages agree on which market a store belongs to.
    import re as _re_em
    try:
        _sm_rows = (client.schema('commcalc').table('store_mapping')
                    .select('store_code,store_address,market').eq('org_id', org_id).execute().data) or []
    except Exception:
        _sm_rows = []

    def _lead_em(s):
        m = _re_em.match(r'\s*(\d+)', str(s or ''))
        return m.group(1) if m else ''
    _mkt_code, _mkt_addr, _mkt_num, _all_markets = {}, {}, {}, set()
    for s in _sm_rows:
        mk = (s.get('market') or '').strip()
        if not mk:
            continue
        _all_markets.add(mk)
        code = str(s.get('store_code') or '').strip()
        addr = str(s.get('store_address') or '').strip()
        if code:
            _mkt_code[code] = mk
        if addr:
            _mkt_addr[addr.lower()] = mk
        n = _lead_em(addr)
        if n:
            _mkt_num.setdefault(n, mk)

    def _market_for(store):
        st = str(store or '').strip()
        return (_mkt_addr.get(st.lower()) or _mkt_code.get(st) or _mkt_num.get(_lead_em(st)) or '')

    # ── Filter OPTIONS from the UNFILTERED union (+ storeops roster + store_mapping markets), so the
    #    pickers list every real store/market/rep present, not just what survived the current selection.
    opt_stores, opt_reps = set(), set()
    for r in rows:
        st = str(r.get('store') or '').strip()
        if st:
            opt_stores.add(st)
            mk = _market_for(st)
            if mk:
                _all_markets.add(mk)
        rp = str(r.get('salesperson') or '').strip()
        if rp and rp.lower() != 'admin':
            opt_reps.add(rp)
    try:
        # ACTIVE roster only (owner 2026-08-06) — a disabled store is no longer offered as a filter
        # option. Options harvested from the period's own sales rows above are untouched, so a store
        # that genuinely sold in the month being viewed stays selectable.
        for s in _storeops_roster(client, org_id, cols='store_code,address'):
            a = str(s.get('address') or '').strip()
            if a:
                opt_stores.add(a)
    except Exception:
        pass
    # `stores_detail` carries each store's MARKET so the RULE FIVE cascade picker (owner refinement
    # 2026-08-04: pick a market -> only that market's stores are selectable) can narrow the store list
    # client-side. Additive — the flat `stores` / `markets` lists keep their exact previous contract, so
    # nothing that already reads this response has to change. A store with no store_mapping row carries
    # market=None and lands in the picker's '(no market)' bucket rather than disappearing.
    filters = {'stores': sorted(opt_stores), 'markets': sorted(_all_markets), 'reps': sorted(opt_reps),
               'stores_detail': [{'id': st, 'label': st, 'market': (_market_for(st) or None)}
                                 for st in sorted(opt_stores)]}

    # ── Apply the selected filters to the UNION rows SERVER-SIDE (before bucketing) — case-insensitive
    #    membership; a market filter resolves each row's store to its market. Empty selection = no filter.
    # `_as_filter_list` (not `x or []`): an INTERNAL caller that omits a repeated-Query param passes the
    # fastapi Query DEFAULT OBJECT, which is truthy and NOT iterable -> `TypeError: 'Query' object is not
    # iterable` (the confirmed 3bf51b4d My-Team class). get_targets_summary was hardened for it; _exec_mtd
    # carries the identical param shape and is now also reachable with an explicit `today`, so harden it.
    stores = _as_filter_list(stores)
    markets = _as_filter_list(markets)
    reps = _as_filter_list(reps)
    store_sel = {str(s).strip().lower() for s in stores if str(s).strip()}
    rep_sel = {str(s).strip().lower() for s in reps if str(s).strip()}
    market_sel = {str(s).strip().lower() for s in markets if str(s).strip()}
    applied = {'stores': sorted(store_sel), 'markets': sorted(market_sel), 'reps': sorted(rep_sel)}
    # M2 (filter canonical-safe): the by_location rows are grouped by the CANONICAL store key, so filtering
    # by a merged store's LABEL must match every variant-spelling row of that store. Canonicalize BOTH the
    # selection and each row's store through the SAME resolver (the one _sales_cell_agg groups by below).
    _ckey_ex = _canonical_store_key_fn(client, org_id)
    store_sel_ck = {_ckey_ex(s) for s in (stores or []) if str(s).strip()}

    def _keep(r):
        st = str(r.get('store') or '').strip()
        if store_sel and _ckey_ex(st) not in store_sel_ck:
            return False
        if rep_sel and str(r.get('salesperson') or '').strip().lower() not in rep_sel:
            return False
        if market_sel and _market_for(st).strip().lower() not in market_sel:
            return False
        return True
    if store_sel or rep_sel or market_sel:
        rows = [r for r in rows if _keep(r)]

    # trending divisor: complete days elapsed (= yesterday's day-of-month) for the OPEN month; the full
    # month (factor 1) for a closed/past month. days_in_month from the calendar. `today` injectable.
    _today = today or _date.today()
    mo, yr = _month_year(period)
    dim = _calendar.monthrange(yr, mo)[1] if (1 <= mo <= 12 and yr) else 30
    open_m = _is_open_month(period)
    elapsed = max(1, _today.day - 1) if open_m else dim
    trend_factor = (dim / elapsed) if elapsed else 1.0

    # ── DATE RANGE (owner 2026-08-11) — an optional [from, to] window INSIDE the month being viewed.
    #    Parsed defensively: a malformed date is treated as "not supplied" (never 500 a report over a
    #    querystring). Either bound alone is legal — the missing one becomes the month's own bound.
    def _pdate(v):
        try:
            return _date.fromisoformat(str(v)[:10])
        except Exception:
            return None

    m_start = _date(yr, mo, 1) if (1 <= mo <= 12 and yr) else None
    m_end = _date(yr, mo, dim) if m_start else None
    rq_from, rq_to = _pdate(date_from), _pdate(date_to)
    rng_on = bool(m_start) and (rq_from is not None or rq_to is not None)
    eff_from = eff_to = None
    clamped = no_overlap = False
    if rng_on:
        eff_from = rq_from or m_start
        eff_to = rq_to or m_end
        clamped = (eff_from < m_start) or (eff_to > m_end)
        eff_from = max(eff_from, m_start)
        eff_to = min(eff_to, m_end)
        # A backwards or fully-outside window selects nothing. Say so instead of falling back to the
        # whole month — a filter that silently ignores itself is worse than an empty table.
        no_overlap = eff_from > eff_to
        # Trending divisor = COMPLETE days inside the window. For the open month "complete" still means
        # strictly before today (today is in progress), exactly as the MTD divisor does.
        last_complete = min(eff_to, _today - _timedelta(days=1)) if open_m else eff_to
        elapsed = 0 if no_overlap else max(0, (last_complete - eff_from).days + 1)
        elapsed = max(1, elapsed)
        trend_factor = (dim / elapsed) if elapsed else 1.0
    rng_from_s = eff_from.isoformat() if (rng_on and eff_from) else None
    rng_to_s = eff_to.isoformat() if (rng_on and eff_to) else None
    undated_excluded = 0
    # MTD DATE-CUT — an OPEN month is cumulative THROUGH TODAY (a line dated after today is excluded, so the
    # cumulative is a true month-to-date). Real sales are never future-dated, so this is a no-op on live
    # data; it is the ONE intentional difference from the Sales Report's whole-month total (proof case b).
    # A closed/past month has no cut (the whole month).
    cut = _today.isoformat() if open_m else None

    # THE shared per-(store, rep, day) pass — identical skip rules + classification + distinct-txn counting
    # as the Sales Report + Daily Targets (see _sales_cell_agg). Exec MTD consumes the SAME cells, applies
    # the MTD date-cut, then rolls up by store / employee. A trans_id lives in exactly one (store,rep,day)
    # cell, so SUMMING the per-cell distinct-txn counts across a store's cells == that store's distinct-txn
    # total. Activation = premium−port (Port is a sub-split of premium); Total Activation = prem+byod+upg,
    # which EQUALS the Sales Report's (activations+byod+upgrades) over the same rows.
    cells = _sales_cell_agg(rows, acfg, exec_cfg=cfg, store_key=_ckey_ex)
    # ── SOURCE OF TRUTH (mig 923): ACTIVATIONS — the SAME shared applier the Sales Report uses (wire once).
    # It sets act_new/act_port/act_byod/act_upg on every cell: from the sales feed by default (byte-identical)
    # or from Activation Details when that is the basis (auto-on with data). When a filter is active we
    # restrict AD-added cells to the filtered store set so the selection is respected; unfiltered → all AD
    # stores (incl. AD-only) appear. The MTD cut / date-range below then windows both bases identically.
    _flt_active = bool(store_sel or rep_sel or market_sel)
    _restrict = {k[0] for k in cells} if _flt_active else None
    _act_src = _apply_activation_basis(client, org_id, period, cells, _ckey_ex, restrict_stores=_restrict)
    _act_override, _ad_n = bool(_act_src.get('active')), _act_src.get('ad_rows') or 0
    _msrc_act = _metric_source(client, org_id, 'activations')

    def _blank():
        # NOTE (n3): by_store dicts also gain a '_name' key (the raw display spelling) set in the loop
        # below — a metric sentinel, NOT a bucket. Any future code iterating these dicts must skip '_name'.
        return {'activation': 0, 'port': 0, 'byod': 0, 'upgrade': 0, 'total_phones': 0,
                'tablet': 0, 'home_internet': 0, 'edge': 0,
                'bill_qty': 0, 'bill_amt': 0.0, 'acc_sales': 0.0, 'setup_fee': 0.0,
                'activation_fee': 0.0, 'protect': 0}
    by_store, by_emp = {}, {}
    for (st, rep, date), a in cells.items():
        if cut and date and date > cut:
            continue
        if rng_on:
            if no_overlap:
                continue
            if not date:
                undated_excluded += 1     # cannot be placed in a window; counted, never silently dropped
                continue
            if date < rng_from_s or date > rng_to_s:
                continue
        # Activation buckets read the SHARED basis fields (set once above), so Exec MTD and the Sales Report
        # never diverge. On the AD basis these are the Activation Details counts; else the sales-feed counts.
        # by_store is keyed on the CANONICAL store key `st` (spelling variants collapse), LABELLED with the
        # first-seen RAW display spelling.
        ds = by_store.setdefault(st or '—', _blank())
        if '_name' not in ds:
            ds['_name'] = a.get('store') or st
        for d in (ds, by_emp.setdefault(rep or '—', _blank())):
            d['activation'] += a['act_new']          # FOLDED (new + tablet + home-internet + edge)
            d['port'] += a['act_port']
            d['byod'] += a['act_byod']
            d['upgrade'] += a['act_upg']
            d['tablet'] += a['act_tablet']
            d['home_internet'] += a['act_home_internet']
            d['edge'] += a['act_edge']
            d['total_phones'] += a['total_phones']
            d['bill_qty'] += a['bill_qty']
            d['bill_amt'] += a['bill_amt']
            d['acc_sales'] += a['accessory_rev']
            # DEVICE SET-UP FEE — the SAME `setup_fee_rev` accumulator the accessory TARGET attainment
            # folds in (owner directive 2026-07-17: the set-up fee is a SEPARATE pay item, never blended
            # into the accessory$ number, but it DOES count toward the accessory target).
            d['setup_fee'] += a['setup_fee_rev']
            d['activation_fee'] += a['activation_fee']
            d['protect'] += a['protect']

    # Total Activation EXCLUDES Upgrade only on the AD basis (b2b-consistent); the sales basis is unchanged.
    _ta_excl_upgrade = bool(_act_override)

    # The tenant's set-up-fee economics, read ONCE (mig 263). Unset -> None -> the two new columns are
    # em-dashes and every pre-existing number is untouched.
    _sf_emp_pct = _sf_dealer_pct = None
    _sf_settings = {}
    try:
        from app.modules.commcalc import setup_fee_pay as _sfp_exec
        _sf_settings, _ = _sfp_exec.resolve_for_carrier(_sfp_exec.load_pay_config(client, org_id))
        _sf_emp_pct = (_sf_settings.get("employee_pct_of_collected")
                       if _sf_settings.get("include_in_commission") else None)
        _sf_dealer_pct = _sf_settings.get("dealer_share_pct")
    except Exception:
        _sf_emp_pct = _sf_dealer_pct = None

    def _row(name, label_key, d):
        # Total Activation = Activation+Port+BYOD+Upgrade on the sales basis (unchanged); on the Activation
        # Details basis it EXCLUDES Upgrade (b2b-consistent, matching /activation-counts). Upgrade is still
        # reported in its own column either way. `d['activation']` is the FOLDED count (New + Tablet + Home
        # Internet + Edge), so `ta` is unchanged; the displayed Activation column is the PURE New count and
        # Tablet / Home Internet / Edge are broken out on their own — matching b2b's Location Sales Report
        # column-for-column (owner 2026-08-27 reconciliation).
        _tab, _hi, _edge = d['tablet'], d['home_internet'], d['edge']
        _pure_new = d['activation'] - _tab - _hi - _edge
        ta = d['activation'] + d['port'] + d['byod'] + (0 if _ta_excl_upgrade else d['upgrade'])
        return {label_key: name,
                'total_activation': ta, 'activation': _pure_new, 'port': d['port'],
                'byod': d['byod'], 'tablet': _tab, 'home_internet': _hi, 'edge': _edge,
                'upgrade': d['upgrade'], 'total_phones': d['total_phones'],
                'trending_box': round(ta * trend_factor),
                'bill_payment_qty': d['bill_qty'], 'amount': round(d['bill_amt'], 2),
                'conv': round(ta / d['bill_qty'], 4) if d['bill_qty'] else 0.0,
                'acc_sales': round(d['acc_sales'], 2),
                'apb': round(d['acc_sales'] / ta, 2) if ta else 0.0,
                'trending_acc_sales': round(d['acc_sales'] * trend_factor, 2),
                # ── The accessory TARGET basis, from the SAME cells (2026-07-30 owner bug: "accessory
                #    sales in Executive MTD are different from the accessory target link"). `acc_sales`
                #    above is the PURE accessory$ (== the Sales Report's accessory_rev, == the b2bsoft
                #    column this report replicates); `acc_plus_setup` adds the device set-up fee, which
                #    is what the Accessory Targets page tracks its achieved/target against. Reporting
                #    both, labelled, is the ONLY honest way to show two legitimately different bases.
                'setup_fee': round(d['setup_fee'], 2),
                # SET-UP / ACTIVATION FEE ECONOMICS (owner 2026-08-01, mig 263). Derived from the SAME
                # `setup_fee` cell above — no second classifier, no extra pass, no per-row query. Both
                # are None until the tenant states the percentage, and a None renders as an em-dash
                # rather than a $0 that looks like a real answer.
                'setup_fee_dealer_share': (None if _sf_dealer_pct is None
                                           else round(d['setup_fee'] * _sf_dealer_pct, 2)),
                'setup_fee_employee_pay': (None if _sf_emp_pct is None
                                           else round(d['setup_fee'] * _sf_emp_pct, 2)),
                'acc_plus_setup': round(d['acc_sales'] + d['setup_fee'], 2),
                'trending_acc_plus_setup': round((d['acc_sales'] + d['setup_fee']) * trend_factor, 2),
                'activation_fee': round(d['activation_fee'], 2),
                'total_protect': d['protect']}

    def _finish(agg, label_key):
        # by_store rows carry a '_name' display label (raw spelling); by_employee rows use the rep key.
        out = [_row(d.get('_name', n), label_key, d) for n, d in agg.items()]
        out.sort(key=lambda x: -x['total_activation'])
        return out

    def _totals(rowset, label_key):
        t = {label_key: 'TOTAL'}
        for k in ('total_activation', 'activation', 'port', 'byod', 'tablet', 'home_internet', 'edge',
                  'upgrade', 'total_phones',
                  'trending_box', 'bill_payment_qty', 'amount', 'acc_sales', 'trending_acc_sales',
                  'setup_fee', 'acc_plus_setup', 'trending_acc_plus_setup',
                  'activation_fee', 'total_protect'):
            t[k] = round(sum(r.get(k, 0) for r in rowset), 2)
        # The two set-up-fee economics totals PRESERVE None. Summing an unset percentage to $0.00 would
        # print a total that looks like a real answer to a question nobody has answered.
        for k in ('setup_fee_dealer_share', 'setup_fee_employee_pay'):
            _vals = [r.get(k) for r in rowset if r.get(k) is not None]
            t[k] = round(sum(_vals), 2) if _vals else None
        t['conv'] = round(t['total_activation'] / t['bill_payment_qty'], 4) if t['bill_payment_qty'] else 0.0
        t['apb'] = round(t['acc_sales'] / t['total_activation'], 2) if t['total_activation'] else 0.0
        return t

    store_rows = _finish(by_store, 'store')
    emps = _finish(by_emp, 'employee')

    # ── Activation-classification VISIBILITY (mig 213/224) — why "Total Activation" can read LOW.
    #    Executive MTD's Total Activation counts DISTINCT transactions whose Contract Type resolves to an
    #    activation bucket (premium / byod / upgrade) via the SHARED classifier + the tenant's contract-type
    #    map. A Contract Type the map doesn't cover (e.g. a Total-carrier tenant's Home Internet / FiOS /
    #    Tablet activation labels) resolves to None and is silently EXCLUDED from the count — the exact reason
    #    the b2bsoft MTD total (which counts those) reads higher than this page. The Sales Report already
    #    surfaces this over the SAME rows and the SAME `_classification_gaps`; carrying it here too means the
    #    Exec MTD/trend surface names WHICH labels are uncounted (and by how many transactions) with a path to
    #    map them, instead of showing a lower total with no explanation. Computed over the filter-applied
    #    `rows` so a store/market/rep selection reports that scope's gaps. DISPLAY-ONLY; pure; never raises;
    #    empty everything (house/Boost, or a fully-mapped tenant) → note None → the UI banner stays hidden.
    try:
        from app.modules.commcalc import plan_pay_gate as _ppg_ex
        _exc_rules_ex, _ = _ppg_ex.load_exclusions(client, org_id)
        _is_exc_ex = (lambda _r: _ppg_ex.exclusion_hit(_r, _exc_rules_ex) is not None) if _exc_rules_ex else None
    except Exception:
        _is_exc_ex = None
    try:
        _cls_gaps_ex = _classification_gaps(rows, acfg, is_excluded=_is_exc_ex)
    except Exception:
        _cls_gaps_ex = {'note': None}

    return {'period': period, 'source': meta,
            'classification_gaps': _cls_gaps_ex,
            # SOURCE OF TRUTH (mig 923): tells the UI which basis drove Total Activation and whether Upgrade
            # is excluded from it, so the number is never silently redefined. Sales basis (the default) →
            # active:false, byte-identical response otherwise.
            'activation_source': {'source': _msrc_act.get('source'),
                                  'active': bool(_act_override),
                                  'basis': 'activation_details' if _act_override else 'sales_agg',
                                  'ad_rows': (_ad_n if _act_override else 0),
                                  'total_activation_excludes_upgrade': bool(_act_override)},
            'filters': filters, 'applied': applied,
            'date_range': {'active': rng_on, 'from': rng_from_s, 'to': rng_to_s,
                           'requested_from': (str(date_from)[:10] or None) if date_from else None,
                           'requested_to': (str(date_to)[:10] or None) if date_to else None,
                           'month_from': m_start.isoformat() if m_start else None,
                           'month_to': m_end.isoformat() if m_end else None,
                           'clamped': clamped, 'no_overlap': no_overlap,
                           'undated_excluded': undated_excluded},
            'trending': {'elapsed_days': elapsed, 'days_in_month': dim, 'factor': round(trend_factor, 6),
                         'basis': 'range' if rng_on else ('mtd' if open_m else 'month')},
            'by_location': {'rows': store_rows, 'total': _totals(store_rows, 'store')},
            'by_employee': {'rows': emps, 'total': _totals(emps, 'employee')}}


@router.get("/exec-mtd/{period}")
def exec_mtd(period: str, org_id: str = ORG_ID, today: str = "",
             date_from: str = "", date_to: str = "",
             stores: Optional[List[str]] = Query(default=None),
             markets: Optional[List[str]] = Query(default=None),
             reps: Optional[List[str]] = Query(default=None)):
    """Executive Month-To-Date summary (b2bsoft Location + Employee MTD sales) — replicated from the
    org-corrected sales source so it works for every tenant with NO monthly upload. DISPLAY-ONLY,
    org-scoped, config-driven metric definitions.

    RULE FIVE standardized filters: optional repeated `stores` / `markets` / `reps` query params filter
    the union rows SERVER-SIDE (before bucketing) so the tables, trending AND exports stay consistent.
    The response's `filters` object lists the pick-don't-type options over the org's real data.

    `today` (YYYY-MM-DD, optional) is the CALLER'S LOCAL date — the same override `/targets/{period}/
    summary` already takes (see `_period_bounds`). Without it this endpoint resolved "today" on the
    SERVER's UTC clock while the Targets pages resolved it on the browser's, so on an evening sales
    floor (after ~8pm ET, UTC has rolled over) the two surfaces used a different MTD cut and a
    different trending divisor and could not agree. Omitted/malformed -> the server date, byte-identical
    to before.

    `date_from` / `date_to` (YYYY-MM-DD, inclusive, optional) narrow the report to a slice of `period`.
    Both omitted -> the whole month-to-date, byte-identical to before. The window is clamped to the
    month and reported back in `date_range`; trending then projects from the window's own complete
    days (`trending.basis == 'range'`)."""
    require_org(org_id)
    _t = None
    if today:
        try:
            _t = _date.fromisoformat(str(today)[:10])
        except Exception:
            _t = None      # malformed override -> server date (never 500 a report over it)
    return _exec_mtd(sb(), org_id, period, stores=stores, markets=markets, reps=reps, today=_t,
                     date_from=date_from or None, date_to=date_to or None)


# ── Narrative banners (owner 2026-08-29 modernization track) ───────────────────────────────────────
# A deterministic plain-English summary rendered ABOVE a report. DELIBERATELY NOT LLM prose: every
# sentence is computed from the same numbers the table shows, so it can never contradict them, needs no
# API key, and cannot hallucinate a figure. `_narrate_delta` is the shared sentence-builder; the report
# endpoints below gather the current + prior facts and call it. Adding a banner to another report is then
# just "collect two totals dicts + a metric spec".

def _pct_change(cur, prior):
    """Signed percent change, or None when there is no prior base to compare against (a change from
    zero has no percentage). Rounds to one decimal."""
    try:
        c, p = float(cur or 0), float(prior or 0)
    except (TypeError, ValueError):
        return None
    if p == 0:
        return None
    return round((c - p) / p * 100.0, 1)


def _dir_word(delta, *, higher_is_better=True):
    """('ahead of' / 'behind' / 'level with', tone) for a signed delta, where tone is 'up'/'down'/'flat'
    keyed to whether the movement is GOOD for this metric (so the UI colours it right — a fall in
    chargebacks is good, a fall in activations is not)."""
    if delta > 0:
        return ('ahead of', 'up' if higher_is_better else 'down')
    if delta < 0:
        return ('behind', 'down' if higher_is_better else 'up')
    return ('level with', 'flat')


# Human labels for the activation buckets, used to name the driver ("…driven by ports").
_MTD_BUCKET_LABELS = {'activation': 'new activations', 'port': 'ports', 'byod': 'BYOD',
                      'upgrade': 'upgrades', 'tablet': 'tablets', 'home_internet': 'home internet',
                      'edge': 'Edge'}


def _mtd_window(period: str, through_day: int):
    """(date_from, date_to) ISO strings covering day 1 → `through_day` of `period`, with `through_day`
    clamped to the month's real length (so a 'through the 30th' comparison against February stops at the
    28th rather than spilling). Returns (from, to, clamped)."""
    pm = parse_period(period)
    y, m = pm['year'], pm['month']
    dim = _calendar.monthrange(y, m)[1] if (1 <= m <= 12 and y) else 30
    d = max(1, min(int(through_day), dim))
    return (f"{y}-{m:02d}-01", f"{y}-{m:02d}-{d:02d}", d != int(through_day))


def _mtd_narrative(client, org_id, period, today=None, stores=None, markets=None, reps=None):
    """Executive-MTD narrative: how this month-to-date compares to the SAME complete-days window of the
    prior month, plus the store leading the change and what drove it. Both windows are day 1 → yesterday
    (complete days only, so today's in-progress sales don't skew the comparison), fed to the exact same
    `_exec_mtd` aggregation the table uses. DISPLAY-ONLY; never raises — any failure yields
    `available: False` and the banner simply doesn't render."""
    try:
        _today = today or _date.today()
        prior_period = _prior_period(period)
        # OPEN month → compare month-to-date (day 1 → yesterday, complete days only) against the SAME
        # window of last month. CLOSED/past month → the fair comparison is the whole month vs last whole
        # month, so the window runs to the month's last day.
        open_m = _is_open_month(period)
        if open_m:
            through = max(1, _today.day - 1)
        else:
            _pm = parse_period(period)
            through = _calendar.monthrange(_pm['year'], _pm['month'])[1] if (1 <= _pm['month'] <= 12) else 30

        cf, ct, _ = _mtd_window(period, through)
        pf, pt, clamped = _mtd_window(prior_period, through)
        flt = dict(stores=stores, markets=markets, reps=reps)
        cur = _exec_mtd(client, org_id, period, today=_today, date_from=cf, date_to=ct, **flt)
        prior = _exec_mtd(client, org_id, prior_period, date_from=pf, date_to=pt, **flt)

        ct_tot = cur['by_location']['total']
        pt_tot = prior['by_location']['total']
        cur_ta, prior_ta = ct_tot.get('total_activation', 0), pt_tot.get('total_activation', 0)
        cur_acc, prior_acc = ct_tot.get('acc_sales', 0.0), pt_tot.get('acc_sales', 0.0)
        n_stores = len([r for r in cur['by_location']['rows'] if r.get('total_activation')])

        # No comparison possible (first month of data, or a filter that empties the prior window):
        # still give a useful non-comparative headline rather than nothing.
        if prior_ta == 0:
            if cur_ta == 0:
                return {'period': period, 'available': False}
            stores_txt = f"{n_stores} store{'s' if n_stores != 1 else ''}"
            if open_m:
                trend_val = round(cur_ta * (cur['trending'].get('factor') or 1))
                head = (f"{cur_ta:,} activations so far this month across {stores_txt}, "
                        f"trending to {trend_val:,} for the month.")
            else:
                head = f"{cur_ta:,} activations in {period} across {stores_txt}."
            return {'period': period, 'prior_period': prior_period, 'through_day': through,
                    'available': True, 'comparative': False, 'tone': 'flat', 'headline': head,
                    'bullets': ([f"Accessory sales ${cur_acc:,.0f}, ${ct_tot.get('apb', 0):,.2f} per box."] if cur_acc else []),
                    'facts': {'total_activation': cur_ta, 'acc_sales': cur_acc, 'stores': n_stores}}

        ta_delta = cur_ta - prior_ta
        ta_pct = _pct_change(cur_ta, prior_ta)
        phrase, tone = _dir_word(ta_delta)
        pct_txt = f"{abs(ta_pct):.0f}% " if ta_pct is not None else ""
        if open_m:
            headline = (f"Activations are running {pct_txt}{phrase} last month — "
                        f"{cur_ta:,} vs {prior_ta:,} through the {_ordinal(through)}.")
        else:
            headline = (f"{period} activations came in {pct_txt}{phrase} the prior month — "
                        f"{cur_ta:,} vs {prior_ta:,}.")

        bullets = []
        # Top mover store + its driving bucket, computed store-by-store on the same buckets.
        pri_by_name = {r.get('store'): r for r in prior['by_location']['rows']}
        movers = []
        for r in cur['by_location']['rows']:
            nm = r.get('store')
            d = (r.get('total_activation', 0)) - (pri_by_name.get(nm, {}).get('total_activation', 0))
            if nm:
                movers.append((d, nm, r, pri_by_name.get(nm, {})))
        movers.sort(key=lambda x: x[0])
        gain = movers[-1] if movers else None
        drop = movers[0] if movers else None
        if gain and gain[0] > 0:
            drv = _mtd_driver_bucket(gain[2], gain[3])
            bullets.append(f"{gain[1]} leads the gain (+{gain[0]:,})"
                           + (f", driven by {drv}." if drv else "."))
        if drop and drop[0] < 0 and (not gain or drop[1] != gain[1]):
            bullets.append(f"{drop[1]} is down {abs(drop[0]):,}.")
        # Accessory line.
        acc_pct = _pct_change(cur_acc, prior_acc)
        if cur_acc or prior_acc:
            acc_phrase = (f"{abs(acc_pct):.0f}% {'up' if (cur_acc - prior_acc) > 0 else 'down'} vs last month"
                          if acc_pct is not None else "no prior comparison")
            bullets.append(f"Accessory sales ${cur_acc:,.0f} ({acc_phrase}), ${ct_tot.get('apb', 0):,.2f} per box.")

        return {'period': period, 'prior_period': prior_period, 'through_day': through,
                'available': True, 'comparative': True, 'tone': tone, 'clamped': clamped,
                'headline': headline, 'bullets': bullets,
                'facts': {'total_activation': cur_ta, 'prior_total_activation': prior_ta,
                          'ta_delta': ta_delta, 'ta_pct': ta_pct,
                          'acc_sales': cur_acc, 'prior_acc_sales': prior_acc, 'acc_pct': acc_pct,
                          'stores': n_stores}}
    except Exception:
        return {'period': period, 'available': False}


def _mtd_driver_bucket(cur_row, prior_row):
    """The activation bucket that moved MOST for one store between the two windows — the 'driven by …'
    clause. Returns a human label or '' when no single bucket stands out."""
    best_lbl, best_delta = '', 0
    for k, lbl in _MTD_BUCKET_LABELS.items():
        d = (cur_row.get(k, 0) or 0) - (prior_row.get(k, 0) or 0)
        if abs(d) > abs(best_delta):
            best_delta, best_lbl = d, lbl
    return best_lbl if best_delta > 0 else ''


def _ordinal(n: int) -> str:
    """1 -> '1st', 2 -> '2nd', 22 -> '22nd' … for the 'through the Nth' phrasing."""
    n = int(n)
    if 10 <= (n % 100) <= 20:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')
    return f"{n}{suf}"


@router.get("/exec-mtd/{period}/narrative")
def exec_mtd_narrative(period: str, org_id: str = ORG_ID, today: str = "",
                       stores: Optional[List[str]] = Query(default=None),
                       markets: Optional[List[str]] = Query(default=None),
                       reps: Optional[List[str]] = Query(default=None)):
    """Plain-English summary banner for the Executive MTD report — this month-to-date vs the same
    complete-days window of last month, the store leading the change, and the accessory trend. Every
    number is computed from the SAME `_exec_mtd` aggregation the table renders, so the banner can never
    disagree with the grid. Honors the same `stores`/`markets`/`reps` filters. DISPLAY-ONLY."""
    require_org(org_id)
    _t = None
    if today:
        try:
            _t = _date.fromisoformat(str(today)[:10])
        except Exception:
            _t = None
    return _mtd_narrative(sb(), org_id, period, today=_t, stores=stores, markets=markets, reps=reps)


# Type buckets that make up b2b's "Total Activation" — everything the Activation Details report classifies
# EXCEPT an Upgrade. Verified against the b2b "Month To Date Location Sales Report" totals row
# (Activation+Port+BYOD+Tablet+HomeInternet+Edge = Total Activation; Upgrade is a separate column).
_ACT_TOTAL_BUCKETS = ("New Activation", "Port", "BYOD", "Tablet", "Home Internet", "Edge", "Other")
_ACT_BUCKET_FIELD = {"New Activation": "activation", "Port": "port", "BYOD": "byod", "Tablet": "tablet",
                     "Home Internet": "home_internet", "Edge": "edge", "Upgrade": "upgrade", "Other": "other"}


def _market_for_fn(client, org_id):
    """A `market_for(store) -> market` resolver from commcalc.store_mapping (by address / store_code /
    leading store-number), mirroring the Exec-MTD / Sales-Report market resolvers so every activation
    surface agrees on which market a store belongs to. Empty ('') when the store has no mapping — never
    raises (a store_mapping read failure just yields '' for every store)."""
    import re as _re_mf
    try:
        rows = (client.schema("commcalc").table("store_mapping")
                .select("store_code,store_address,market").eq("org_id", org_id).execute().data) or []
    except Exception:
        rows = []
    by_code, by_addr, by_num = {}, {}, {}

    def _lead(s):
        m = _re_mf.match(r"\s*(\d+)", str(s or ""))
        return m.group(1) if m else ""
    for s in rows:
        mk = (s.get("market") or "").strip()
        if not mk:
            continue
        code = str(s.get("store_code") or "").strip()
        addr = str(s.get("store_address") or "").strip()
        if code:
            by_code[code] = mk
        if addr:
            by_addr[addr.lower()] = mk
        n = _lead(addr)
        if n:
            by_num.setdefault(n, mk)

    def market_for(store):
        st = str(store or "").strip()
        return by_addr.get(st.lower()) or by_code.get(st) or by_num.get(_lead(st)) or ""
    return market_for


@router.get("/activation-counts/{period}")
def activation_counts(period: str, org_id: str = ORG_ID, as_of: str = "", include_upgrade: bool = False):
    """Store + MARKET activation COUNTS from the b2b "Activation Details" report, in the SHAPE of the b2b
    "Month To Date Location Sales Report" so the two reconcile line-for-line (owner 2026-08-26).

    One row per distinct device (deduped by Serial#; a device's insurance/Plan-Option lines share its serial
    and count once; Returns/cancelled excluded). Every store row carries its `market`, the per-type breakdown
    (activation / port / byod / tablet / home_internet / edge / upgrade), and BOTH totals so the UI can toggle
    without a re-fetch:
      • `total_activation`     = Activation+Port+BYOD+Tablet+Home Internet+Edge, EXCLUDING Upgrade (b2b's own
                                 definition — LuxeLink 687, Nova 250).
      • `total_with_upgrade`   = the above PLUS Upgrade (LuxeLink 726, Nova 261).
    `include_upgrade=true` makes the store list SORT by (and `default_total` report) the with-Upgrade total;
    the two numbers are always both present regardless. A `markets` rollup splits multi-market files (e.g.
    LuxeLink vs Nova in one export) so each market's total stands on its own.

    AS-OF CUTOFF: `as_of` (YYYY-MM-DD, or a b2b M/D/YYYY date) counts only activations dated on/before that
    day. Undated rows are always included (they cannot be placed).

    Reads the self-serve custom-import capture (raw_custom_import) — EMPTY until the Activation Details report
    is uploaded/registered as a custom import (or routed via the email import) for `period`. DISPLAY-ONLY."""
    require_org(org_id)
    client = sb()
    mfor = _market_for_fn(client, org_id)
    rows = _cr_resolve_activation_details(client, org_id, period, {"market_for": mfor})
    cutoff = _norm_report_date(as_of) if as_of else ""
    excluded_after = 0

    def _blank(label, key="store"):
        d = {key: label, "market": "", "total_activation": 0, "total_with_upgrade": 0, "upgrade": 0}
        for f in _ACT_BUCKET_FIELD.values():
            d[f] = 0
        return d

    by_store, by_market, grand = {}, {}, _blank("TOTAL")
    counted = 0
    for r in rows:
        d10 = r.get("trans_date") or ""
        if cutoff and d10 and d10 > cutoff:
            excluded_after += 1
            continue
        counted += 1
        st = (r.get("store") or "").strip() or "—"
        mk = (r.get("market") or "").strip() or "(no market)"
        bucket = r.get("bucket") or "Other"
        fld = _ACT_BUCKET_FIELD.get(bucket, "other")
        s_row = by_store.setdefault(st, _blank(st))
        s_row["market"] = (r.get("market") or "").strip()
        m_row = by_market.setdefault(mk, _blank(mk, key="market"))
        for d in (s_row, m_row, grand):
            d[fld] += 1
            d["total_with_upgrade"] += 1
            if bucket != "Upgrade":       # b2b Total Activation excludes Upgrade
                d["total_activation"] += 1
    _sort_key = (lambda x: -x["total_with_upgrade"]) if include_upgrade else (lambda x: -x["total_activation"])
    stores = sorted(by_store.values(), key=_sort_key)
    markets = sorted(by_market.values(), key=_sort_key)
    return {
        "period": period, "org_id": org_id,
        "as_of": cutoff or None, "excluded_after_cutoff": excluded_after,
        "include_upgrade": include_upgrade,
        "default_total": ("total_with_upgrade" if include_upgrade else "total_activation"),
        "counted": counted, "stores": stores, "markets": markets, "total": grand,
        "note": (None if rows else
                 "No Activation Details rows found for this period. Upload or register the b2b "
                 "'Activation Details' report as a Custom Import (Data Imports → Custom Reports), or route "
                 "it to the email import, then re-check."),
    }


@router.get("/dealer-code-map/{period}")
def dealer_code_map(period: str, org_id: str = ORG_ID):
    """The b2b Activation Details "Dealer Code" → store mapping status (owner 2026-08-26). The export
    identifies a store by a numeric Dealer Code; until that code is linked to a store record, its activations
    show as the numeric ID instead of merging onto the named store row. This lists every Dealer Code observed
    in the period's Activation Details with its device count and whether it currently resolves to a store,
    plus the org's store roster for the picker. Map an unmapped code via POST /store-aliases
    {alias: <dealer_code>, store_code: <chosen>} — the SAME explicit-alias table the resolver reads, so the
    numbers merge immediately. DISPLAY/config."""
    require_org(org_id)
    client = sb()
    dmap = _dealer_to_store_map(client, org_id)
    rows = _cr_resolve_activation_details(client, org_id, period, {"market_for": _market_for_fn(client, org_id)})
    agg = {}
    for r in rows:
        dc = (r.get("dealer_code") or "").strip()
        if not dc:
            continue
        slot = agg.setdefault(dc, {"dealer_code": dc, "activations": 0, "mapped": False, "store": None,
                                   "division": (r.get("division") or ""), "region": (r.get("region") or ""),
                                   "district": (r.get("district") or "")})
        slot["activations"] += 1        # resolver rows are already one-per-device (distinct Serial#)
        addr = dmap.get(dc.upper())
        slot["mapped"] = bool(addr)
        slot["store"] = addr or None
    codes = sorted(agg.values(), key=lambda x: (x["mapped"], -x["activations"]))
    try:
        M = _store_maps(client, org_id)
        stores = [{"store_code": s.get("store_code"), "address": (s.get("address") or s.get("store_code"))}
                  for s in (M.get("stores") or []) if s.get("store_code")]
    except Exception:
        stores = []
    return {
        "period": period, "org_id": org_id, "codes": codes, "stores": stores,
        "unmapped": sum(1 for c in codes if not c["mapped"]),
        "note": (None if codes else
                 "No Dealer Codes found in Activation Details for this period. Upload/route the b2b "
                 "'Activation Details' report, then re-check."),
    }


@router.get("/product-sales-departments/{period}")
def product_sales_departments(period: str, org_id: str = ORG_ID):
    """The DISTINCT Departments the b2b "Sales by Product" report actually contains for `period`, each flagged
    with whether it currently counts as an accessory department (owner 2026-08-26: the accessory departments
    must NOT be hard-coded — they are an OPTION pulled from this report, then saved to the org's accessory
    config once). The Sales Report → Accessory settings picker calls this to offer the observed departments as
    checkboxes instead of a free-text field, so 'Accessories' / 'C2Wireless' (or whatever a tenant's report
    calls them) come straight from the tenant's own data. Selecting them writes through the existing
    accessory-config API (put_accessory_config → accessory_config.departments), the SAME single source the
    Sales Report and this Sales-by-Product resolver both read. DISPLAY-ONLY."""
    require_org(org_id)
    client = sb()
    rows = _cr_resolve_product_sales(client, org_id, period, {"market_for": (lambda s: "")})
    try:
        acc = _accessory_config(client, org_id).get("departments") or set()
    except Exception:
        acc = set()
    seen = {}
    for r in rows:
        dept = (r.get("department") or "").strip()
        if not dept:
            continue
        d = seen.setdefault(dept, {"department": dept, "is_accessory": dept.lower() in acc,
                                   "products": 0, "ext_price": 0.0})
        d["products"] += 1
        d["ext_price"] += float(r.get("ext_price") or 0.0)
    departments = sorted(seen.values(), key=lambda x: (not x["is_accessory"], -x["ext_price"], x["department"]))
    return {
        "period": period, "org_id": org_id, "departments": departments,
        "accessory_departments": sorted([d["department"] for d in departments if d["is_accessory"]]),
        "note": (None if departments else
                 "No Sales by Product rows found for this period. Upload or route the b2b 'Sales by Product' "
                 "report (Data Imports → Custom Reports / Email Imports), then re-check."),
    }


def _sales_activation_by_store(client, org_id, period):
    """Per-canonical-store activation buckets {'activation','port','byod','upgrade','_name'} from the SHARED
    sales aggregation (_sales_cell_agg) — the SECONDARY activation source for reconciliation, computed the
    exact way Exec MTD rolls its by_location activations up (so a mismatch is real, not a method artifact).
    Whole-period (no MTD cut): the recon asks whether the month ingested the same, not a to-date slice."""
    cfg = _exec_metric_config(client, org_id)
    acfg = _accessory_config(client, org_id)
    rows, _meta = _sales_rows_union(client, org_id, period)
    ckey = _canonical_store_key_fn(client, org_id)
    cells = _sales_cell_agg(rows, acfg, exec_cfg=cfg, store_key=ckey)
    by_store = {}
    for (st, _rep, _date), a in cells.items():
        prem, port = len(a['_prem']), len(a['_port'])
        slot = by_store.setdefault(st or '—', {"activation": 0, "port": 0, "byod": 0, "upgrade": 0,
                                               "_name": (a.get('store') or st or '—')})
        slot['activation'] += prem - port
        slot['port'] += port
        slot['byod'] += len(a['_byod'])
        slot['upgrade'] += len(a['_upg'])
    return by_store


def _billpay_report_by_store(client, org_id, period, ckey_fn):
    """Per-canonical-store bill-payment {'count','amount','_name'} from the b2b "Bill Payment Transactions"
    report (the BASIS OF TRUTH) — count = txns, amount = payment (fallback total_amt). Returns (map, n_rows)."""
    rows = _cr_resolve_bill_payments(client, org_id, period, {"market_for": (lambda s: "")})
    by_store = {}
    for r in rows:
        st = (r.get("store") or "").strip() or "—"
        k = ckey_fn(st) or "—"
        slot = by_store.setdefault(k, {"count": 0, "amount": 0.0, "_name": st})
        slot["count"] += int(r.get("txns") or 1)
        slot["amount"] += float(r.get("payment") or r.get("total_amt") or 0.0)
    return by_store, len(rows)


def _billpay_sales_by_store(client, org_id, period, ckey_fn):
    """Per-canonical-store bill-payment {'count','amount','_name'} from the shared sales aggregation — the
    SECONDARY source (the Exec-MTD 'Bill Payment Qty' / '$' basis: _sales_cell_agg bill_qty / bill_amt)."""
    cfg = _exec_metric_config(client, org_id)
    acfg = _accessory_config(client, org_id)
    rows, _meta = _sales_rows_union(client, org_id, period)
    cells = _sales_cell_agg(rows, acfg, exec_cfg=cfg, store_key=ckey_fn)
    by_store = {}
    for (st, _rep, _date), a in cells.items():
        slot = by_store.setdefault(st or "—", {"count": 0, "amount": 0.0, "_name": (a.get("store") or st or "—")})
        slot["count"] += int(a.get("bill_qty") or 0)
        slot["amount"] += float(a.get("bill_amt") or 0.0)
    # Drop stores with zero bill payments so they don't dilute the recon's store set.
    return {k: v for k, v in by_store.items() if v["count"] or v["amount"]}


def _billpay_processor_name(client, org_id, msrc):
    """Which carrier PROCESSOR to reconcile bill payments against: the metric_source_of_truth.processor
    config wins ('epay'|'vidapay'); else auto-detect from commcalc.data_source (the enabled portal login's
    processor, 'total_access' → vidapay). '' when unknown → the recon runs two-way (report vs sales)."""
    p = str((msrc or {}).get("processor") or "").strip().lower()
    if p in ("epay", "vidapay"):
        return p
    try:
        rows = (client.schema("commcalc").table("data_source").select("processor,enabled")
                .eq("org_id", org_id).execute().data) or []
        for r in rows:
            if not r.get("enabled"):
                continue
            pp = str(r.get("processor") or "").strip().lower()
            if pp in ("epay",):
                return "epay"
            if pp in ("vidapay", "total_access"):
                return "vidapay"
    except Exception:
        pass
    return ""


def _billpay_processor_by_store(client, org_id, period, processor, ckey_fn):
    """Per-canonical-store bill-payment {'count','amount','_name'} from the carrier PROCESSOR feed — ePay
    (raw_epay_daily_tx via epay_ingest.per_store_day) for Boost, VidaPay (raw_ma_daily_tx, account_id →
    store_code via storeops.merchant_ids) for Total. Best-effort + defensive: any failure or an unknown
    processor returns {} so the recon degrades to report-vs-sales rather than 500-ing."""
    if processor not in ("epay", "vidapay"):
        return {}
    mo, yr = _month_year(period)
    if not (1 <= mo <= 12 and yr):
        return {}
    date_from = f"{yr}-{mo:02d}-01"
    date_to = f"{yr}-{mo:02d}-{_calendar.monthrange(yr, mo)[1]:02d}"
    by_store = {}
    try:
        if processor == "epay":
            from app.modules.commcalc import epay_ingest as _epi
            for (sc, _d), v in (_epi.per_store_day(client, org_id, date_from, date_to) or {}).items():
                k = ckey_fn(str(sc)) or str(sc) or "—"
                slot = by_store.setdefault(k, {"count": 0, "amount": 0.0, "_name": str(sc)})
                slot["count"] += int(v.get("lines") or 0)
                slot["amount"] += float(v.get("payment") or 0.0)
        else:  # vidapay
            from app.modules.storeops import merchant_ids as _mids
            amap = _mids.resolve_map(org_id, "vidapay") or {}
            q = (client.schema("commcalc").table("raw_ma_daily_tx")
                 .select("account_id,retail_cost").eq("org_id", org_id))
            rows = q.in_("period", _pvariants(period)).limit(200000).execute().data or []
            for r in rows:
                acct = str(r.get("account_id") or "").strip()
                sc = amap.get(acct) or acct or "—"
                k = ckey_fn(str(sc)) or str(sc) or "—"
                slot = by_store.setdefault(k, {"count": 0, "amount": 0.0, "_name": str(sc)})
                slot["count"] += 1
                slot["amount"] += float(r.get("retail_cost") or 0.0)
    except Exception as _pe:
        print(f"WARN bill-payment processor read failed ({processor}): {_pe}")
        return {}
    return by_store


def _billpay_cash_actual_by_store(client, org_id, period, ckey_fn):
    """Per-canonical-store ACTUAL bill-payment CASH {'amount','_name'} — the Bill Payment Transactions report
    (basis of truth) filtered to a CASH tender. This is what the drawer SHOULD hold from bill payments."""
    rows = _cr_resolve_bill_payments(client, org_id, period, {"market_for": (lambda s: "")})
    out = {}
    for r in rows:
        if "cash" not in str(r.get("tender_type") or "").lower():
            continue
        st = (r.get("store") or "").strip() or "—"
        k = ckey_fn(st) or "—"
        slot = out.setdefault(k, {"amount": 0.0, "_name": st})
        slot["amount"] += float(r.get("payment") or r.get("total_amt") or 0.0)
    return out


def _billpay_cash_declared_by_store(client, org_id, period, ckey_fn):
    """Per-canonical-store DECLARED bill-payment cash {'amount','_name'} — daily_closing.epay_on_cash (the
    portion of the rep's declared cash they attributed to ePay / bill payments), summed for the period.
    Defensive: a missing table/column yields {} so the recon degrades rather than 500-ing."""
    try:
        rows = (client.schema("commcalc").table("daily_closing")
                .select("store_code,epay_on_cash,period")
                .eq("org_id", org_id).in_("period", _pvariants(period)).limit(100000).execute().data) or []
    except Exception as _ce:
        print(f"WARN daily_closing read failed for bill-pay cash recon: {_ce}")
        return {}
    out = {}
    for r in rows:
        sc = str(r.get("store_code") or "").strip() or "—"
        k = ckey_fn(sc) or "—"
        slot = out.setdefault(k, {"amount": 0.0, "_name": sc})
        slot["amount"] += float(r.get("epay_on_cash") or 0.0)
    return out


@router.get("/metric-recon/{period}")
def metric_recon(period: str, org_id: str = ORG_ID, metric: str = "activations"):
    """RECONCILIATION for a metric (owner 2026-08-26): prove the ingest is good when the sources agree, flag +
    name a remediation when they don't.

    • `activations` — the b2b Activation Details basis (PRIMARY / basis of truth, distinct Serial#, Upgrade
      excluded) vs the shared sales aggregation, per store, on the b2b-consistent Total Activation.
    • `bill_payments` — THREE-way: the b2b Bill Payment Transactions report (PRIMARY) vs the sales aggregation
      vs the carrier PROCESSOR (ePay for Boost / VidaPay for Total, chosen from config or data_source), per
      store, on amount + count.

    `tolerance`, `reconcile_with`, `processor` and `assigned_user` come from the tenant's
    metric_source_of_truth config (mig 923); with no config the recon still runs with sensible defaults.
    Read-only."""
    require_org(org_id)
    from app.modules.commcalc import metric_recon as metric_recon_mod
    client = sb()
    ckey = _canonical_store_key_fn(client, org_id)

    if metric == "activations":
        msrc = _metric_source(client, org_id, metric)
        ad_by_store, _ad_rep, ad_n = _ad_activation_buckets(client, org_id, period, ckey_fn=ckey)
        sales_by_store = _sales_activation_by_store(client, org_id, period)
        result = metric_recon_mod.reconcile_activations(
            ad_by_store, sales_by_store,
            tolerance=msrc.get("tolerance") or 0,
            source=(msrc.get("source") if msrc.get("configured") else "activation_details"),
            reconcile_with=(msrc.get("reconcile_with") or "sales_agg"),
            assigned_user=msrc.get("assigned_user"))
        result.update({"period": period, "org_id": org_id, "metric": metric,
                       "config": {"configured": msrc.get("configured"), "enabled": msrc.get("enabled"),
                                  "source": msrc.get("source"), "processor": msrc.get("processor")},
                       "primary_rows": ad_n,
                       "note": (None if ad_n else
                                "No Activation Details rows for this period — upload or route the b2b "
                                "'Activation Details' report so the activation basis of truth is present.")})
        return result

    if metric == "bill_payments":
        msrc = _metric_source(client, org_id, metric)
        report_by_store, rep_n = _billpay_report_by_store(client, org_id, period, ckey)
        sales_by_store = _billpay_sales_by_store(client, org_id, period, ckey)
        processor = _billpay_processor_name(client, org_id, msrc)
        proc_by_store = _billpay_processor_by_store(client, org_id, period, processor, ckey)
        result = metric_recon_mod.reconcile_bill_payments(
            report_by_store, sales_by_store, proc_by_store,
            tolerance_amt=float(msrc.get("tolerance") or 0.0), tolerance_cnt=0,
            processor=processor, reconcile_with=(msrc.get("reconcile_with") or "sales_agg"),
            assigned_user=msrc.get("assigned_user"))
        # DAILY-CASH linkage (owner 2026-08-26: "wire the bill-pay reconciliation into the daily cash being
        # declared by the employees"). Reconcile ACTUAL bill-payment cash (report, tender=cash) against the
        # cash the reps DECLARED at daily closing (daily_closing.epay_on_cash), per store — over/short.
        cash_actual = _billpay_cash_actual_by_store(client, org_id, period, ckey)
        cash_declared = _billpay_cash_declared_by_store(client, org_id, period, ckey)
        daily_cash = metric_recon_mod.reconcile_billpay_cash(
            cash_actual, cash_declared,
            tolerance_amt=float(msrc.get("tolerance") or 1.0), assigned_user=msrc.get("assigned_user"))
        result.update({"period": period, "org_id": org_id, "metric": metric,
                       "config": {"configured": msrc.get("configured"), "processor": (processor or None)},
                       "primary_rows": rep_n,
                       "daily_cash": daily_cash,
                       "note": (None if rep_n else
                                "No Bill Payment Transactions rows for this period — upload or route the b2b "
                                "'Bill Payment Transactions' report so the bill-payment basis is present.")})
        return result

    raise HTTPException(400, "unknown metric (allowed: activations, bill_payments)")


@router.get("/data-lineage")
def get_data_lineage(org_id: str = ORG_ID, source_key: str = "", affected_key: str = "", kind: str = ""):
    """The system DATA-LINEAGE registry (mig 924/925) — the documented schematic of how ingested data and
    derived metrics feed each other. Each row is a dependency edge (source → affected) with entry_point, a
    code reference, a plain-English effect, kind, and auto_updated. Optional filters narrow to one source /
    affected item / kind. Returns rows + an index grouped by source so the UI can render 'if X changes, these
    update'. Empty until migration 925 (the seed) is applied. DISPLAY/documentation only."""
    require_org(org_id)
    try:
        q = sb().schema("commcalc").table("data_lineage").select("*")
        if source_key:
            q = q.eq("source_key", source_key)
        if affected_key:
            q = q.eq("affected_key", affected_key)
        if kind:
            q = q.eq("kind", kind)
        rows = q.order("source_key").order("seq").limit(5000).execute().data or []
    except Exception as e:
        return {"rows": [], "by_source": {}, "sources": [], "note": f"data_lineage unavailable (run migration 924/925): {str(e)[:160]}"}
    by_source = {}
    for r in rows:
        by_source.setdefault(r.get("source_key") or "?", []).append(r)
    return {"rows": rows, "by_source": by_source, "sources": sorted(by_source.keys()),
            "count": len(rows),
            "note": (None if rows else "data_lineage is empty — apply migration 925 (the seed) to populate the schematic.")}


# ── ONBOARDING READINESS CHECKLIST ───────────────────────────────────────────────────────────────
# One row per DATA ITEM the platform can ingest, with: how it enters, which reports/functions it powers,
# and — per tenant — whether it is actually present + wired. Derived from data_lineage (the schematic) so
# the checklist and the schematic never drift. `check` names how presence is verified for THIS tenant.
#   table      → count rows in schema.table for the org
#   custom:KEY → the raw_custom_import capture resolves for that dataset (by column signature)
#   config:X   → a per-org config is set (accessory depts / store mapping / activation basis)
_ONBOARDING_ITEMS = [
    ("sales_transactions",       "Sales Transaction Details", "table:commcalc.raw_sales|commcalc.daily_sales_feed"),
    ("activation_details_report","b2b Activation Details",     "custom:serial#,contract type"),
    ("bill_payments_report",     "b2b Bill Payment Transactions", "custom:discounts,bill pay system"),
    ("product_sales_report",     "b2b Sales by Product",       "custom:product gp,total exp comm"),
    ("store_performance_report", "b2b Store Performance",      "custom:acc ext price,bill payment qty"),
    ("processor_epay",           "ePay processor feed (Boost)", "table:commcalc.raw_epay_daily_tx"),
    ("processor_vidapay",        "VidaPay processor feed (Total)", "table:commcalc.raw_ma_daily_tx"),
    ("residual_report",          "Residual / MA commission (drives Retention Analysis)", "table:commcalc.raw_ma_commission"),
    ("mi_report",                "MI subscriber status (alt Retention basis)", "table:commcalc.raw_mi"),
    ("daily_cash",               "Employee daily cash declaration", "table:commcalc.daily_closing"),
    ("store_identity",           "Store identity / mapping",   "config:store_mapping"),
    ("accessories",              "Accessory departments",      "config:accessory"),
    ("activation_basis",         "Activation basis of truth",  "config:metric_source"),
]


def _oc_count(client, spec, org_id):
    """Presence for a 'table:' spec (one or more schema.table, pipe-separated) → total row count for org."""
    total = 0
    for st in spec.split("|"):
        try:
            schema, table = st.split(".", 1)
            r = (client.schema(schema).table(table).select("*", count="exact")
                 .eq("org_id", org_id).limit(1).execute())
            total += int(getattr(r, "count", 0) or 0)
        except Exception:
            pass
    return total


def _oc_custom_present(client, org_id, req_keys):
    """Presence for a 'custom:' spec — does raw_custom_import hold a row carrying ALL the signature keys."""
    req = [k.strip().lower() for k in req_keys.split(",") if k.strip()]
    try:
        rows = (client.schema("commcalc").table("raw_custom_import").select("data")
                .eq("org_id", org_id).limit(2000).execute().data) or []
    except Exception:
        return 0
    n = 0
    for r in rows:
        d = r.get("data") or {}
        if isinstance(d, dict):
            keys = {(k or "").strip().lower() for k in d.keys()}
            if all(k in keys for k in req):
                n += 1
    return n


def _oc_config_present(client, org_id, which):
    """Presence for a 'config:' spec — is the per-org setup done."""
    try:
        if which == "store_mapping":
            M = _store_maps(client, org_id)
            return len(M.get("stores") or [])
        if which == "accessory":
            depts = (_accessory_config(client, org_id).get("departments") or set())
            return len([d for d in depts if d and d != "ondigo"])
        if which == "metric_source":
            return 1 if _metric_source(client, org_id, "activations").get("configured") else 0
    except Exception:
        return 0
    return 0


def _onboarding_checklist(client, org_id):
    """Per-tenant readiness: for each ingestable data item — how it enters, what it powers (from the lineage
    schematic), and whether it is present/wired for THIS tenant. The systemic answer to 'this report is blank
    because nothing was mapped to feed it'."""
    # Pull the schematic once to describe what each source powers (its non-ingest consumer edges).
    try:
        edges = (client.schema("commcalc").table("data_lineage").select("*").limit(5000).execute().data) or []
    except Exception:
        edges = []
    powers = {}
    for e in edges:
        if (e.get("kind") or "") != "ingest":
            powers.setdefault(e.get("source_key") or "", []).append(
                {"affected": e.get("affected_label") or e.get("affected_key"),
                 "surface": e.get("surface"), "output": e.get("effect_english"), "kind": e.get("kind")})
    items = []
    for key, label, check in _ONBOARDING_ITEMS:
        how, present = check, 0
        if check.startswith("table:"):
            present = _oc_count(client, check[6:], org_id)
            how = "Uploaded / swept into " + check[6:].replace("|", " or ")
        elif check.startswith("custom:"):
            present = _oc_custom_present(client, org_id, check[7:])
            how = "Custom import (email/upload) → raw_custom_import"
        elif check.startswith("config:"):
            present = _oc_config_present(client, org_id, check[7:])
            how = "Configured in settings"
        items.append({
            "key": key, "label": label, "how": how,
            "present": bool(present), "count": present,
            "powers": powers.get(key, []),
            "status": ("ready" if present else "missing"),
        })
    ready = sum(1 for i in items if i["present"])
    return {"org_id": org_id, "items": items, "ready": ready, "total": len(items),
            "missing": [i["key"] for i in items if not i["present"]]}


@router.get("/onboarding-checklist")
def onboarding_checklist(org_id: str = ORG_ID):
    """Per-tenant ONBOARDING READINESS (owner 2026-08-26): every data item the platform ingests — how it
    enters, what platform function/report it powers (from the data-lineage schematic), and whether it is
    present + wired for this tenant. So a report is never silently blank 'because nothing was mapped to feed
    it' — the missing feed is named here. DISPLAY/config."""
    require_org(org_id)
    return _onboarding_checklist(sb(), org_id)


def _data_report_map(client, org_id):
    """DATA-FIRST reverse map (owner 2026-08-26: "the first check should be what data is being ingested, then
    reverse-engineer what reports/menus that data runs"). Starts from what THIS tenant actually has ingested,
    then walks the data_lineage graph forward to every report/menu (surface) each ingested source powers — and
    conversely lists the reports that are BLOCKED because their feeding data isn't ingested yet, naming what to
    provide. Reuses the presence engine (_onboarding_checklist) + the lineage graph. DISPLAY/documentation."""
    checklist = _onboarding_checklist(client, org_id)
    present = {i["key"]: bool(i["present"]) for i in checklist["items"]}
    counts = {i["key"]: i.get("count") for i in checklist["items"]}
    labels = {i["key"]: i["label"] for i in checklist["items"]}
    try:
        edges = (client.schema("commcalc").table("data_lineage").select("*").limit(5000).execute().data) or []
    except Exception:
        edges = []
    # forward adjacency + the set of ingest roots
    adj, ingest_roots, src_label = {}, set(), {}
    for e in edges:
        sk = e.get("source_key") or ""
        adj.setdefault(sk, []).append(e)
        if e.get("source_label"):
            src_label.setdefault(sk, e["source_label"])
        if (e.get("kind") or "") == "ingest":
            ingest_roots.add(sk)

    def _surfaces_from(root):
        """Every report/menu (surface) reachable downstream of an ingest root, via the lineage graph."""
        seen, stack, out = set(), [root], {}
        while stack:
            n = stack.pop()
            for e in adj.get(n, []):
                surf = (e.get("surface") or "").strip()
                if surf and (e.get("kind") or "") != "ingest":
                    out[surf] = e.get("kind") or "display"
                nxt = e.get("affected_key") or ""
                if nxt and nxt not in seen:
                    seen.add(nxt); stack.append(nxt)
        return out

    ingested, surface_feeders = [], {}
    for root in sorted(ingest_roots):
        surfs = _surfaces_from(root)
        is_present = present.get(root, False)
        ingested.append({
            "source_key": root, "source_label": src_label.get(root) or labels.get(root) or root,
            "present": is_present, "count": counts.get(root),
            "reports": sorted(surfs.keys()),
        })
        for surf in surfs:
            fed = surface_feeders.setdefault(surf, {"powered_by": [], "needs": []})
            (fed["powered_by"] if is_present else fed["needs"]).append(src_label.get(root) or root)

    reports = []
    for surf, fed in sorted(surface_feeders.items()):
        powered = bool(fed["powered_by"])
        reports.append({"report": surf, "powered": powered,
                        "powered_by": sorted(set(fed["powered_by"])),
                        "needs": sorted(set(fed["needs"])) if not powered else []})
    return {
        "org_id": org_id,
        "ingested": ingested,
        "reports": reports,
        "ingested_count": sum(1 for i in ingested if i["present"]),
        "reports_powered": sum(1 for r in reports if r["powered"]),
        "reports_total": len(reports),
        "note": (None if edges else
                 "The data-lineage schematic is empty — apply migrations 924/925 to populate the data→reports map."),
    }


@router.get("/data-readiness")
def data_readiness(org_id: str = ORG_ID):
    """DATA-FIRST readiness (owner 2026-08-26): what data is ingested for this tenant, reverse-engineered to
    the reports/menus each ingested source powers — and the reports still blocked because their feed is
    missing (with what to provide). The entry view of the Setup Wizard. DISPLAY/documentation."""
    require_org(org_id)
    return _data_report_map(sb(), org_id)


