def _require_perf_review_edit(authorization, org_id):
    """Gate performance-review / productivity CONFIG writes on their OWN permission (owner directive
    2026-07-17: "config in performance review should have a separate permission"). Uses core's
    _can_edit_setting with the 'performance_review' settings area (the per-setting pattern —
    roles.permissions.settings['performance_review']). Until that area is registered in core.SETTING_AREAS +
    the Roles UI (NEEDS CORE), _can_edit_setting DEGRADES to admin-only (scope='all' / role='admin') — a
    SAFE default that never opens config to a non-admin. RBAC off / unidentifiable caller → no active block
    (config stays require_org-gated, unchanged behaviour)."""
    try:
        from app.modules.core.router import _uid_from_token, _resolve_caller, _can_edit_setting
    except Exception:
        return
    try:
        uid = _uid_from_token(authorization)
        caller = _resolve_caller(sb(), uid, org_id) if uid else None
    except Exception:
        caller = None
    if caller is not None and not _can_edit_setting(caller, 'performance_review'):
        raise HTTPException(403, "You don't have permission to edit performance-review configuration.")


class PutProductivityConfigIn(LaxModel):
    item_key: str = ""
    label: Any = None
    source_key: Any = None
    standard_type: Any = None
    standard: Any = None
    weight: Any = None
    count_in_stack_ranker: Any = None
    count_in_review: Any = None
    enabled: Any = None
    hidden: Any = None
    sort: Any = None


@router.put("/productivity/config")
def put_productivity_config(body: PutProductivityConfigIn, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Upsert ONE registry item (add a custom item or edit/enable/disable a default). item_key required;
    source_key must be in the SOURCE CATALOG (pick-don't-type — no free-form formula). Degrades with a hint
    if mig 215 isn't applied. GATED on the 'performance_review' settings permission (B5)."""
    require_org(org_id)
    _require_perf_review_edit(authorization, org_id)
    item_key = str(body.item_key or '').strip()
    if not item_key:
        raise HTTPException(400, "item_key required")
    source_key = str(body.source_key or '').strip()
    if source_key and source_key not in _prod.SOURCE_CATALOG:
        raise HTTPException(400, f"unknown source_key (pick from the catalog): {source_key}")
    row = {'org_id': org_id, 'item_key': item_key}
    for c in ('label', 'source_key', 'standard_type'):
        if getattr(body, c) is not None:
            row[c] = str(getattr(body, c))
    if 'standard' in body.model_fields_set:
        row['standard'] = None if body.standard in (None, '') else safe_float(body.standard)
    if 'weight' in body.model_fields_set:
        row['weight'] = safe_float(body.weight)
    for b in ('count_in_stack_ranker', 'count_in_review', 'enabled', 'hidden'):
        if b in body.model_fields_set:
            row[b] = bool(getattr(body, b))
    if 'sort' in body.model_fields_set:
        row['sort'] = int(safe_float(body.sort))
    row['is_seed_default'] = item_key in {d['item_key'] for d in _prod.DEFAULT_ITEMS}
    row['updated_at'] = _datetime.now(_timezone.utc).isoformat()
    try:
        sb().schema('commcalc').table('productivity_item').upsert(row, on_conflict='org_id,item_key').execute()
        return {"ok": True, "item_key": item_key}
    except Exception as e:
        return {"ok": False, "hint": "run migration 215 (productivity_item)", "error": str(e)[:200]}


@router.delete("/productivity/config/{item_key}")
def delete_productivity_config(item_key: str, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Delete an item. A CUSTOM item is hard-deleted; a seed DEFAULT can't be removed from code, so it's
    persisted as a hidden override (restored by 'reset to defaults'). GATED on 'performance_review' (B5)."""
    require_org(org_id)
    _require_perf_review_edit(authorization, org_id)
    ik = str(item_key or '').strip()
    is_default = ik in {d['item_key'] for d in _prod.DEFAULT_ITEMS}
    try:
        if is_default:
            sb().schema('commcalc').table('productivity_item').upsert(
                {'org_id': org_id, 'item_key': ik, 'hidden': True, 'is_seed_default': True,
                 'updated_at': _datetime.now(_timezone.utc).isoformat()}, on_conflict='org_id,item_key').execute()
        else:
            sb().schema('commcalc').table('productivity_item').delete().eq('org_id', org_id).eq('item_key', ik).execute()
        return {"ok": True, "item_key": ik, "hidden": is_default}
    except Exception as e:
        return {"ok": False, "hint": "run migration 215 (productivity_item)", "error": str(e)[:200]}


@router.post("/productivity/config/reset")
def reset_productivity_config(authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Reset the registry to the code defaults (delete all org overrides). GATED on 'performance_review' (B5)."""
    require_org(org_id)
    _require_perf_review_edit(authorization, org_id)
    try:
        sb().schema('commcalc').table('productivity_item').delete().eq('org_id', org_id).execute()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "hint": "run migration 215 (productivity_item)", "error": str(e)[:200]}


@router.get("/productivity/{period}")
def get_productivity(period: str, org_id: str = ORG_ID, today: str = "",
                     stores: Optional[List[str]] = Query(default=None),
                     markets: Optional[List[str]] = Query(default=None),
                     reps: Optional[List[str]] = Query(default=None)):
    """FEATURE 1 — per-employee productivity (boxes/hr, accessory $/hr) vs the store's own baseline, grouped
    by store with rep rows. Hours = StoreOps time-clock closed punches. Zero-hours reps are surfaced (never
    divide by zero). RULE FIVE filters + RULE FOUR exports. DISPLAY-ONLY (no calc, no recompute)."""
    require_org(org_id)
    try:
        g = _prod_gather(sb(), org_id, period, stores=stores, markets=markets, reps=reps, today=today)
        res = _prod.compute_productivity(g['store_reps'], g['hours_by_key'])
        return {"period": period, "org_id": org_id, **res,
                "filters": g['filters'], "applied": g['applied'], "source_meta": g['source_meta']}
    except Exception as e:
        # A report must DEGRADE, not 500. Any unexpected cross-module condition → an empty, well-formed
        # payload the page renders as "no data" (never a crash / white screen).
        print(f"WARN productivity/{period} failed: {e}")
        return {"period": period, "org_id": org_id, "stores": [], "totals": {},
                "filters": {"stores": [], "markets": [], "reps": []}, "applied": {}, "error": str(e)[:200]}


@router.get("/productivity-insights/{period}")
def productivity_insights(period: str, store_code: str, metric: str = "acc", org_id: str = ORG_ID):
    """Productivity lens — talent-to-demand fit for ONE store. Ranks reps by output/hour (accessory $/hr
    or boxes/hr), computes what share of each rep's SCHEDULED hours falls in the store's peak-demand
    hours, and emits POSITIVE recommendations (recognize / reschedule to peak / coach). Human-in-the-loop:
    it recommends, the manager decides — never an adverse action."""
    from datetime import datetime as _dt2, timedelta as _td2
    from app.modules.commcalc import productivity_fit as _pf
    from app.modules.storeops.router import _biz_tz_for_store
    from app.modules.commcalc.staffing_heatmap import hhmm_to_hours
    require_org(org_id)
    sc = str(store_code).strip()
    client = sb()

    # 1. output/hour per rep at this store
    out_by_name = {}
    try:
        g = _prod_gather(client, org_id, period, stores=[sc])
        prod = _prod.compute_productivity(g["store_reps"], g["hours_by_key"])
        key = "acc_per_hr" if metric != "boxes" else "boxes_per_hr"
        for grp in (prod.get("stores") or []):
            if str(grp.get("store_code")) != sc:
                continue
            for r in (grp.get("reps") or []):
                out_by_name[str(r.get("rep") or "").strip().upper()] = {
                    "name": r.get("rep"), "output_per_hour": r.get(key),
                    "acc_per_hr": r.get("acc_per_hr"), "boxes_per_hr": r.get("boxes_per_hr"), "hours": r.get("hours")}
    except Exception as e:
        print(f"WARN productivity-insights gather failed: {e}")

    # period → month range
    p = str(period).strip()
    try:
        if "-" in p and p[:4].isdigit():
            yy, mm = int(p[:4]), int(p[5:7])
        else:
            d = _dt2.strptime(p, "%B %Y"); yy, mm = d.year, d.month
        from datetime import date as _d3
        d0 = _d3(yy, mm, 1); d1 = (_d3(yy + 1, 1, 1) if mm == 12 else _d3(yy, mm + 1, 1)) - _td2(days=1)
    except Exception:
        raise HTTPException(400, "period must be 'YYYY-MM' or 'Month YYYY'")

    # 2. scheduled hours-by-hour per employee (shifts carry local HH:MM)
    hours_by_emp = {}
    try:
        shifts = (get_supabase().schema("storeops").table("shifts")
                  .select("employee_name,start_time,end_time").eq("org_id", org_id).eq("store_code", sc)
                  .eq("is_deleted", False).gte("shift_date", d0.isoformat()).lte("shift_date", d1.isoformat())
                  .limit(100000).execute().data) or []
    except Exception:
        shifts = []
    for s in shifts:
        nm = str(s.get("employee_name") or "").strip().upper()
        if not nm:
            continue
        hbh = hours_by_emp.setdefault(nm, {})
        for hr in hhmm_to_hours(s.get("start_time"), s.get("end_time")):
            hbh[hr] = hbh.get(hr, 0) + 1

    # 3. demand-by-hour (trans_ts → store-local); fall back to scheduled-heads proxy when no demand yet
    tz = _biz_tz_for_store(org_id, sc)
    demand_by_hour = {}
    try:
        resolve_code = _store_code_resolver(client, org_id)
        from app.modules.commcalc import gp_report as _gp

        def _tx(table):
            return (client.schema("commcalc").table(table).select("trans_ts,store,voided")
                    .eq("org_id", org_id).in_("period", _pvariants(period))
                    .not_.is_("trans_ts", "null").limit(200000).execute().data) or []
        for r in (_tx("raw_sales") + _tx("daily_sales_feed")):
            if _gp.is_voided(r.get("voided")) or resolve_code(r.get("store") or "") != sc:
                continue
            try:
                dt = _dt2.fromisoformat(str(r.get("trans_ts")).replace("Z", "+00:00")).astimezone(tz)
            except Exception:
                continue
            demand_by_hour[dt.hour] = demand_by_hour.get(dt.hour, 0) + 1
    except Exception:
        demand_by_hour = {}
    has_demand = bool(demand_by_hour)
    if not has_demand:   # proxy: the hours the store actually staffs heaviest
        for hbh in hours_by_emp.values():
            for hr, h in hbh.items():
                demand_by_hour[hr] = demand_by_hour.get(hr, 0) + h

    peak = _pf.peak_hours(demand_by_hour)

    reps = []
    seen = set()
    for nm, info in out_by_name.items():
        seen.add(nm)
        reps.append({"name": info["name"], "output_per_hour": info["output_per_hour"],
                     "acc_per_hr": info.get("acc_per_hr"), "boxes_per_hr": info.get("boxes_per_hr"),
                     "hours_by_hour": hours_by_emp.get(nm, {})})
    for nm, hbh in hours_by_emp.items():   # scheduled but no sales → still show (output None)
        if nm not in seen:
            reps.append({"name": nm.title(), "output_per_hour": None, "acc_per_hr": None,
                         "boxes_per_hr": None, "hours_by_hour": hbh})

    res = _pf.analyze(reps, peak)
    return {"store_code": sc, "period": period, "metric": ("boxes/hr" if metric == "boxes" else "accessory $/hr"),
            "has_demand": has_demand, "peak_basis": ("transactions" if has_demand else "scheduled hours (proxy — no transaction-time data yet)"),
            "timezone": str(getattr(tz, "key", tz)), **res}


