from app.modules.commcalc import email_sweep as _email


# ═══════════════════════════════════════════════════════════════════════════════
# b2bsoft POS "standard profile" (mig 200) — one config-driven standard for any tenant whose POS is
# b2bsoft, so a new tenant's sales-ingest setup is IDENTICAL to house BY CONSTRUCTION (not hand-copied).
# The standard lives in commcalc.pos_profile (per-tenant, UI-editable — SAP-configurable rule); this code
# default mirrors the migration seed so the endpoints DEGRADE GRACEFULLY before mig 200 is applied.
# ═══════════════════════════════════════════════════════════════════════════════
_B2BSOFT_POS_DEFAULT = {
    "pos_key": "b2bsoft",
    "label": "B2B Soft (standard)",
    "imap_defaults": {"imap_port": 993, "use_ssl": True, "mailbox": "INBOX", "since_days": 14},
    "filename_rules": [
        {"pattern": "*Sales*Transaction*Details*", "upload_type": "daily_sales",
         "note": "daily B2B sales export — use the full-column \"for Metrics pro\" report (Ext Price + GP)"},
        {"pattern": "*Inventory*Aging*", "upload_type": "inventory_aging",
         "note": "b2bsoft inventory aging → Balance-Sheet inventory value"},
        {"pattern": "*X-Report*", "upload_type": "x_report",
         "note": "POS X-report tender summary → daily-closing cash/credit recon"},
    ],
    "schedule_defaults": {"frequency": "hourly", "hour": 7},
    "report_defs": [
        {"report_key": "sales", "label": "Sales Transactions",
         "source_name": "Sales Transaction Details (78-col)", "target_table": "raw_sales",
         "upload_endpoint": "commcalc/upload/sales", "period_mode": "current", "auto": True, "sort_order": 10},
        {"report_key": "inventory", "label": "Inventory Aging", "source_name": "Inventory Aging",
         "target_table": "inventory_value", "upload_endpoint": None, "period_mode": "snapshot",
         "auto": False, "sort_order": 20},
    ],
}


def _pos_profile(client, org_id, pos_key="b2bsoft"):
    """This tenant's editable POS standard profile, else the code default (so it works before mig 200).
    Org-scoped read — never reaches into another tenant's row."""
    try:
        rows = (client.schema("commcalc").table("pos_profile").select("*")
                .eq("org_id", org_id).eq("pos_key", pos_key).limit(1).execute().data) or []
        if rows:
            r = rows[0]
            # Fill any blank column from the code default so a partially-edited row still applies cleanly.
            for k in ("imap_defaults", "schedule_defaults"):
                if not r.get(k):
                    r[k] = _B2BSOFT_POS_DEFAULT[k]
            if not r.get("filename_rules"):
                r["filename_rules"] = _B2BSOFT_POS_DEFAULT["filename_rules"]
            if not r.get("report_defs"):
                r["report_defs"] = _B2BSOFT_POS_DEFAULT["report_defs"]
            return r
    except Exception:
        pass
    return {"org_id": org_id, **_B2BSOFT_POS_DEFAULT}


def _mailbox_cross_org(client, username, exclude_org):
    """Every OTHER tenant that has a mailbox configured at the same address `username`. This is the
    misfile detector: the Luxelink mailbox was filed under the HOUSE org and would have ingested Total
    sales into Boost. Case-insensitive; uses the service client (crosses orgs on purpose — a safety
    check), and returns only org_id/account/label/enabled (no creds), never another tenant's data."""
    u = (username or "").strip()
    if not u:
        return []
    try:
        rows = (client.schema("commcalc").table("email_sweep_config")
                .select("org_id,account,label,enabled,username").ilike("username", u).execute().data) or []
    except Exception:
        return []
    out = []
    for r in rows:
        if str(r.get("org_id") or "") == str(exclude_org or ""):
            continue
        if (r.get("username") or "").strip().lower() != u.lower():
            continue
        out.append({"org_id": r.get("org_id"), "account": r.get("account"),
                    "label": r.get("label"), "enabled": bool(r.get("enabled"))})
    return out


def _email_cfg(client, org_id, account='default'):
    """One mailbox config for (org, account). Tolerant of pre-075 schema (no 'account' column) so the
    single-mailbox setup keeps working before the migration is applied."""
    try:
        rows = (client.schema('commcalc').table('email_sweep_config').select('*')
                .eq('org_id', org_id).eq('account', account).limit(1).execute().data) or []
    except Exception:
        rows = (client.schema('commcalc').table('email_sweep_config').select('*')
                .eq('org_id', org_id).limit(1).execute().data) or []
    return rows[0] if rows else None


def _email_accounts(client, org_id):
    """Every mailbox configured for a tenant (multi-mailbox, mig 075). Pre-075 this returns the single
    row. Each row is a distinct inbox with its own creds + patterns + schedule."""
    try:
        rows = (client.schema('commcalc').table('email_sweep_config').select('*')
                .eq('org_id', org_id).order('account').execute().data) or []
    except Exception:
        rows = (client.schema('commcalc').table('email_sweep_config').select('*')
                .eq('org_id', org_id).limit(1).execute().data) or []
    return rows


def _email_status_update(client, org_id, account, upd):
    """Patch one mailbox's status columns, scoped to its account. Falls back to org-only pre-075
    (no 'account' column) so the single-mailbox setup still updates. Best-effort."""
    try:
        client.schema('commcalc').table('email_sweep_config').update(upd) \
            .eq('org_id', org_id).eq('account', account).execute()
    except Exception:
        try:
            client.schema('commcalc').table('email_sweep_config').update(upd).eq('org_id', org_id).execute()
        except Exception:
            pass


def _auto_custom_report_patterns(client, org_id):
    """Auto-derived filename patterns for every registered CUSTOM report (report_definitions), so a report
    added for email ingestion is matched WITHOUT the tenant hand-crafting a glob (owner 2026-08-26: adding a
    custom report should make it ingest automatically — "email has the data but the system did not get them"
    was exactly a new report with no filename rule). Pattern = the label's words joined by '*'
    (e.g. 'Activation Details' → '*activation*details*'); the report_key slug is also accepted. Used as a
    FALLBACK appended AFTER the explicit patterns (first-match wins in match_upload_type), so nothing that
    already matched changes. Never raises."""
    import re as _re_ap
    out, seen = [], set()
    try:
        defs = (client.schema("commcalc").table("report_definitions")
                .select("report_key,label,target_table,upload_endpoint").eq("org_id", org_id).execute().data) or []
    except Exception:
        return out
    for d in defs:
        if not (d.get("upload_endpoint") == "custom" or d.get("target_table") == CUSTOM_IMPORT_TABLE):
            continue
        rk = (d.get("report_key") or "").strip()
        if not rk:
            continue
        for raw in ((d.get("label") or rk), rk):
            words = [w for w in _re_ap.split(r"[^a-z0-9]+", str(raw).lower()) if w]
            if not words:
                continue
            pat = "*" + "*".join(words) + "*"
            if pat not in seen:
                seen.add(pat)
                out.append({"pattern": pat, "upload_type": rk, "auto": True})
    return out


# Built-in FALLBACK filename patterns for the three core feeds the freshness banner tracks (daily sales,
# activation details, bill payment). Appended AFTER the tenant's explicit rules AND the custom-report auto
# patterns, so an explicit rule always wins — these only catch a report the tenant never wrote a rule for,
# in particular one RENAMED at the source. b2b recreating "Sales Transaction Details" as
# "My Sales Transaction Details Legacy New" stops matching a narrow old glob and would otherwise freeze the
# Sales feed silently; a broad-but-specific glob on the report's distinctive words keeps it importing.
# `daily_sales` has NO custom auto-pattern (it is a built-in upload type, not a custom report), so this is
# the one that actually closes the current gap; the other two are belt-and-braces for a tenant whose
# activation/bill report is not registered as a custom sheet. `auto: True` marks them derived.
_BUILTIN_FEED_FALLBACK_PATTERNS = [
    {"pattern": "*sales*transaction*details*", "upload_type": "daily_sales", "auto": True},
    {"pattern": "*activation*details*", "upload_type": "activation_details", "auto": True},
    {"pattern": "*bill*payment*transaction*", "upload_type": "bill_payment_transactions", "auto": True},
]


async def _run_email_sweep(org_id, account='default'):
    """Connect to ONE tenant mailbox (org, account), download every NEW attachment matching a configured
    pattern, route each through the existing upload pipeline, and record what was processed (dedup by
    account+message_id+name)."""
    from starlette.datastructures import UploadFile as _UF
    client = sb()
    cfg = _email_cfg(client, org_id, account)
    account = (cfg or {}).get('account') or account
    if not cfg or not (cfg.get('imap_host') or '').strip():
        return {"ok": False, "error": "Email/IMAP not configured", "account": account}
    # AUTO-MATCH new custom reports: append derived patterns for every registered custom sheet AFTER the
    # explicit rules (explicit wins first), so a report the tenant just added ingests without a hand-written
    # glob. This closes the "attachment is in the inbox but never imports because no rule matched it" gap.
    _auto_pats = _auto_custom_report_patterns(client, org_id)
    # Explicit tenant rules first, then per-custom-report auto patterns, then the built-in core-feed
    # fallbacks (sales / activation / bill). First match wins, so nothing that already matched changes;
    # the fallbacks only rescue a renamed/unruled report that would otherwise be dropped.
    cfg = {**cfg, 'patterns': (cfg.get('patterns') or []) + (_auto_pats or []) + _BUILTIN_FEED_FALLBACK_PATTERNS}
    # An empty rules list matches NOTHING — fail loudly instead of a silent "0/0 ingested" while
    # reports sit in the inbox (bit the Total/luxelink mailbox setup 2026-07-02).
    if not any((p.get('pattern') or '').strip() for p in (cfg.get('patterns') or []) if isinstance(p, dict)):
        _email_status_update(client, org_id, account,
            {'last_run_at': _datetime.now(_timezone.utc).isoformat(),
             'last_status': "no filename rules configured — add patterns, nothing can match"})
        return {"ok": False, "account": account,
                "error": "This mailbox has no filename rules — add a rule (e.g. *Sales*Transaction*Details* → daily sales) and Save."}
    seen = client.schema('commcalc').table('email_processed').select('message_id,filename,rows_saved,status').eq('org_id', org_id).limit(100000).execute().data or []
    # DEDUP CONTRACT (see _sweep_ingest_outcome): a message is done when it ACTUALLY ingested (status ok +
    # rows saved) OR its outcome was TERMINAL-zero — 'empty' (read fine, carried nothing ingestable) /
    # 'ignored' (no importer for that report). Everything else — an error, a price-guard refusal, unmapped
    # tender labels, a parse miss — auto-retries on the next sweep, so a file that failed once is never
    # skipped forever AND a file nothing can be done about stops being re-pulled every hour.
    already = {(r.get('message_id'), r.get('filename')) for r in seen
               if (r.get('status') == 'ok' and (r.get('rows_saved') or 0) > 0)
               or r.get('status') in SWEEP_TERMINAL_ZERO_STATUSES}
    # Messages we are about to RE-attempt after a previous non-terminal outcome — reported so an operator
    # can see a file is being retried rather than silently looping.
    _prior_nonterminal = {(r.get('message_id'), r.get('filename')) for r in seen
                          if (r.get('message_id'), r.get('filename')) not in already}
    try:
        # to_thread (2026-08-04 outage fix): fetch_new_attachments is SYNCHRONOUS imaplib network I/O
        # (connect + search + full RFC822 downloads). Awaited inline it blocks the event loop for the
        # whole mailbox session — with a wedged mail host that meant the entire backend froze at the
        # top of every hour. The 30s socket timeout in email_sweep._connect caps the hang; this keeps
        # even the capped hang off the loop.
        import asyncio as _asyncio
        _unrouted = []   # data-file attachments that matched NO rule (a renamed/unruled report) — surfaced below
        files = await _asyncio.to_thread(_email.fetch_new_attachments, cfg, already, _unrouted)
    except Exception as e:
        em = str(e)
        # An AUTH rejection is routinely misread as "the password was erased" — it never is (nothing in
        # this module clears a stored password). Mail hosts (e.g. Bluehost/cPHulk) temporarily block
        # frequent logins, so say exactly that instead of a bare failure the UI turns into
        # "re-enter your password".
        if any(s in em.upper() for s in ("AUTHENTICATIONFAILED", "INVALID CREDENTIALS", "LOGIN FAILED")):
            em = (f"login rejected: {em} — the saved password is UNCHANGED. Mail hosts sometimes "
                  "temporarily block frequent logins; the next scheduled run usually recovers. "
                  "Re-enter the password only if Test connection also fails.")
        else:
            em = f"connect error: {em}"
        _email_status_update(client, org_id, account,
            {'last_run_at': _datetime.now(_timezone.utc).isoformat(), 'last_status': em})
        return {"ok": False, "error": em, "account": account}
    results = []
    shrinks = []   # row-count guardrail hits (a truncated/partial export) → alert after the loop
    journal_failures, journal_first_error, retried = 0, None, 0
    just_ok_mids = set()   # message-ids ingested ok THIS run — the mailbox cleaner deletes these when enabled
    for f in files:
        name, size, ut, mid = f['name'], f['size'], f.get('upload_type'), f.get('message_id')
        period = "" if ut in ("daily_sales", "ma_commission", "ma_daily_tx", "ma_fulfillment") else _ftp_current_period()
        status, detail, rows_saved, shrink, skipped_flag, terminal = "ok", None, 0, [], None, True
        if (mid, name) in _prior_nonterminal:
            retried += 1
        try:
            uf = _UF(io.BytesIO(f['bytes']), filename=name)
            # org_id passed as a KEYWORD (was the 5th positional, which landed in `close_date` while org_id
            # silently defaulted to the house org — a latent multi-tenant misroute that would send a tenant
            # mailbox's swept sales into Boost the moment that mailbox is filed under its own org; inert
            # today because sweeps run as the house org). trace_source tags the mig-202 upload_trace.
            res = await upload_file(ut, uf, period, force=False, org_id=org_id, trace_source='email_sweep')
            # ONE honest reading of the result (_sweep_ingest_outcome), shared with the FTP sweep. It
            # replaces the per-marker if/elif ladder that used to live here: every branch that ladder
            # handled keeps its EXACT status + detail wording (price-guard full/partial refusal,
            # Inventory-Aging 0-store parse, device-only ingest incl. reading the real `devices` count,
            # the X-Report zero reasons and its two partial-save caveats), and the outcomes the ladder
            # had no branch for — a file that read fine but mapped 0 rows, a custom sheet with no data
            # rows, a KNOWN_IGNORED_TYPES attachment — stop being recorded as a green 'ok · 0 rows'.
            _o = _sweep_ingest_outcome(res, upload_type=ut)
            status, detail = _o['status'], _o['detail']
            rows_saved, shrink, skipped_flag, terminal = (_o['rows_saved'], _o['shrink'],
                                                          _o['skipped'], _o['terminal'])
        except HTTPException as he:
            # An error is NEVER terminal — the dedup above must let it retry next sweep.
            status, detail, terminal = "error", str(he.detail)[:300], False
        except Exception as e:
            status, detail, terminal = "error", str(e)[:300], False
        try:
            client.schema('commcalc').table('email_processed').upsert(
                {'org_id': org_id, 'account': account, 'message_id': mid, 'filename': name, 'file_size': size,
                 'upload_type': ut, 'rows_saved': rows_saved, 'status': status, 'detail': detail,
                 'processed_at': _datetime.now(_timezone.utc).isoformat()},
                on_conflict='org_id,account,message_id,filename').execute()
        except Exception as _je:
            # WAS `except Exception: pass`. A LOST journal row is not cosmetic: this message is then
            # re-fetched and re-INGESTED on every sweep (the hourly-duplicate class). Count it, keep the
            # first real error, and report it on the sweep's status line — never swallow it.
            journal_failures += 1
            if journal_first_error is None:
                journal_first_error = str(_je)[:300]
            print(f'WARN email_processed upsert failed for {name}: {_je}')
        for s in shrink:
            shrinks.append({'file': name, 'upload_type': ut, **s})
        results.append({"file": name, "upload_type": ut, "status": status, "rows_saved": rows_saved,
                        "detail": detail, "shrink": shrink, "skipped": skipped_flag,
                        "terminal": terminal})
        if status == 'ok' and (rows_saved or 0) > 0 and mid:
            just_ok_mids.add(mid)
    ok = sum(1 for r in results if r['status'] == 'ok')
    # A truncated/partial emailed export (far fewer rows than the day/period it replaced) would silently
    # corrupt reports — alert the connector recipients (same scope as connector-health) so it's caught.
    # Shared with the FTP sweep now (which raised no alert at all before).
    await _sweep_shrink_alert(client, org_id, shrinks, source_line=f"Mailbox: {account}")
    status_msg = (f"{ok}/{len(results)} attachments ingested" if results
                  else "no new attachments to import — matched files already imported OK, or none match your rules (use Test connection)")
    status_msg += _sweep_status_suffix(results, journal_failures=journal_failures,
                                       journal_first_error=journal_first_error, retried=retried,
                                       shrinks=shrinks)
    # MAILBOX CLEANER (owner 2026-08-28: "clean the email so we don't overload it"). When this mailbox is set
    # to delete-after-ingest, remove the report emails whose data is ALREADY captured. Runs on THIS sweep's
    # own authenticated connection — no separate login, no shared password — and deletes ONLY messages
    # recorded ok+rows (this run + prior), never a non-report or un-ingested email. Off the event loop
    # (blocking imaplib), best-effort: a cleanup failure can never affect the ingest that just succeeded.
    if str(cfg.get('cleanup_mode') or 'off').strip().lower() == 'delete':
        _ok_mids = set(just_ok_mids) | {r.get('message_id') for r in seen
                                        if r.get('status') == 'ok' and (r.get('rows_saved') or 0) > 0}
        try:
            import asyncio as _asyncio_cl
            _cl = await _asyncio_cl.to_thread(_email.cleanup_ingested, cfg, _ok_mids)
            if (_cl or {}).get('deleted'):
                status_msg += f" · cleaned {_cl['deleted']} ingested email(s) from the mailbox"
        except Exception as _ce:
            print(f"WARN mailbox cleanup failed for {account}: {_ce}")
    # UNROUTED REPORTS (owner 2026-08-29). Data-file attachments that arrived but matched NO import rule —
    # the "the email HAS the data but the system didn't import it" failure, usually a report renamed at the
    # source. Persist the list for the freshness banner (guarded — no-ops until the column exists; writing []
    # clears it once the report gets a rule) and escalate a once-a-day-deduped alert, so a silent feed freeze
    # becomes a visible, self-explaining prompt to add a rule. Best-effort: never affects the ingest above.
    _unr_names, _seen_un = [], set()
    for _u in (_unrouted or []):
        _n = (_u.get('name') or '').strip()
        if _n and _n.lower() not in _seen_un:
            _seen_un.add(_n.lower()); _unr_names.append(_n)
    if _table_has_column(client, 'email_sweep_config', 'last_unrouted'):
        try:
            import json as _json_un
            _email_status_update(client, org_id, account, {'last_unrouted': _json_un.dumps(_unr_names[:25])})
        except Exception as _ue:
            print(f"WARN persist unrouted failed for {account}: {_ue}")
    if _unr_names:
        try:
            from app.modules.closing.router import _send_alert
            _subj = f"⚠️ {len(_unr_names)} report(s) arrived that no import rule matched"
            _preview = "\n".join(f"  • {n}" for n in _unr_names[:12])
            _txt = (f"MetricsPro found report attachment(s) in the '{account}' mailbox that were delivered but "
                    f"matched NO filename import rule, so their data was NOT imported. A feed can silently go "
                    f"stale this way — usually because a report was renamed at the source:\n\n{_preview}\n\n"
                    f"What to do: open Data Imports → Email Imports and add or widen a rule so the filename "
                    f"matches (e.g. *Sales*Transaction*Details* → daily sales). The next sweep imports it.")
            _ref = f"unrouted:{org_id}:{account}:{_date.today().isoformat()}"   # once per mailbox per day
            await _send_alert(client, org_id, "connector", _subj, _txt, _ref)
        except Exception as _ae:
            print(f"WARN unrouted alert failed for {account}: {_ae}")
    _email_status_update(client, org_id, account,
        {'last_run_at': _datetime.now(_timezone.utc).isoformat(), 'last_status': status_msg})
    # Auto-derive the monthly commission basis (raw_sales) from the feed — best-effort + guarded,
    # never breaks the sweep. DEFAULT ON when the registry has no 'sales' row: new tenants never had
    # the row the house has, so their raw_sales silently stayed empty and plan-mode pay was $0
    # (luxelink, 2026-07-14). An explicit auto=false row still opts a tenant out.
    try:
        # EVERY non-'error' outcome fires this trigger, which is EXACTLY the pre-change firing set and
        # deliberately so: before the honest-status work, every daily_sales result that did not raise was
        # recorded 'ok' or 'skipped', so `!= 'error'` reproduces it byte-for-byte now that 'empty' and
        # 'ignored' exist as distinct statuses. Nothing about which periods promote or recompute moves —
        # the promote reads the (unchanged) feed, so it is a no-op on unchanged data either way.
        if (any(r.get('upload_type') == 'daily_sales' and r.get('status') != 'error' for r in results)
                and _registry_auto_map(client, org_id).get('sales', True)):
            _pr = _promote_feed_to_raw_sales(client, org_id, _ftp_current_period())
            # MONTH-BOUNDARY GRACE (2026-08-01). The feed keeps FINALIZING the old month after midnight
            # (luxelink's July feed grew 283→313→317 across the 00:09–04:05 runs of August 1) while this
            # line, which asks the wall clock, had already moved on to the new month — leaving 45 July
            # transactions in the feed and out of the paid basis. Re-derive the prior month too while the
            # tenant's window is open. Deliberately AFTER the current-month promote and deliberately
            # OUTSIDE the recompute block below: a grace re-derive NEVER triggers a recompute — money
            # moves attended, so the owner runs Calculate for the closed month. Best-effort: a failure
            # here can no more break the sweep than the current-month promote can.
            for _gp, _g, _gret in _sales_derive_plan(client, org_id)[1:]:
                try:
                    _promote_feed_to_raw_sales(client, org_id, _gp, grace=_g, retain=_gret)
                except Exception as _ge:
                    print(f"WARN month-boundary grace re-derive of {_gp} failed: {_ge}")
            # Plan-mode tenants have no other automatic recompute (the DLAR auto-recalc is Boost-only),
            # so a promotion that actually wrote rows recalculates the period — sales flow to pay every
            # sweep with nobody pressing Run Calculation. Best-effort; the zero-wipe guard protects the
            # snapshot, and Boost orgs are excluded (their recompute cadence stays the daily DLAR sweep).
            try:
                if (_pr or {}).get('written'):
                    _carriers = (client.schema('commcalc').table('carrier').select('*')
                                 .eq('org_id', org_id).execute().data) or []
                    if _resolve_carrier_mode(_carriers) != 'boost':
                        # _run_calculation is a plain `def` now (it has zero awaits and takes minutes).
                        # _run_email_sweep IS a real coroutine, so calling it inline would block the one
                        # event loop for the whole recompute — exactly the freeze this package removes.
                        # run_in_threadpool is what Starlette itself does with a sync BackgroundTask.
                        from starlette.concurrency import run_in_threadpool as _in_pool
                        await _in_pool(_run_calculation, _ftp_current_period(), org_id)
            except Exception as e2:
                print(f"WARN auto-recalc after promote failed: {e2}")
    except Exception as e:
        print(f"WARN auto-promote feed->raw_sales failed: {e}")
    return {"ok": True, "account": account, "ingested": ok, "files": results,
            "retried": retried, "journal_failures": journal_failures,
            "journal_first_error": journal_first_error}


async def _run_email_sweep_all(org_id):
    """Run EVERY configured mailbox for a tenant (used by run-now with no account). Returns a per-account
    roll-up. Runs each account even if others fail."""
    accounts = [a.get('account') or 'default' for a in _email_accounts(sb(), org_id)] or ['default']
    out = []
    for acct in accounts:
        try:
            out.append(await _run_email_sweep(org_id, acct))
        except Exception as e:
            out.append({"ok": False, "account": acct, "error": str(e)})
    return {"ok": True, "accounts": len(out), "runs": out,
            "ingested": sum((r.get('ingested') or 0) for r in out)}


def _sales_derive_plan(client, org_id, now=None, base_retain=0.85):
    """Which period(s) the AUTOMATIC derivation must cover for THIS tenant right now, as
    [(period, grace, retain), ...]. Entry 0 is always the current month with grace=False and the normal
    guard — i.e. exactly what ran before the month-boundary fix. Any further entry is the PRIOR month,
    re-derived because the B2B feed keeps finalizing it for a few days past midnight (see
    sales_derive.py for the incident this exists for).

    Per-tenant by construction: the window comes from that org's own
    commission_org_config.sales_derive_grace (RULE ONE + RULE TWO). A tenant with the window switched
    off — or migration 266 unapplied on a tenant that never had a row — gets [(current, False, 0.85)],
    which is today's behaviour with nothing added."""
    return sales_derive.plan(now or _datetime.now(), sales_derive.load(client, org_id), base_retain)


def _promote_feed_to_raw_sales(client, org_id, period, dry_run=False, force=False, retain=0.85,
                               grace=False):
    """Derive the authoritative monthly raw_sales for `period` from the accumulated daily B2B email
    feed (daily_sales_feed), so the monthly Sales file no longer has to be uploaded by hand.

    MERGE, not blind replace: the rebuilt raw_sales = every feed transaction for the month PLUS any
    transaction that exists in the current raw_sales but NOT in the feed — so a transaction is NEVER
    dropped (the feed can lag the monthly file by a handful of transactions during the transition).
    daily_sales_feed and raw_sales share an identical column shape (same parser), so feed rows copy
    straight across; the period label is normalized to the monthly 'Month YYYY' form.

    Guarded: if the merged result would shrink the existing raw_sales line count below `retain` of its
    current size, the write is SKIPPED (a half-delivered feed can't wipe a good month) unless force.
    dry_run returns the would-be delta WITHOUT writing — the safe way to validate before committing.

    ANTI-DUPLICATION (2026-07-16, luxelink July 2026 incident — feed-less days compounding ~2x→16x per
    run): (1) the paginated `_all()` read now `.order('id')` so unordered OFFSET pages can't re-read rows;
    (2) the carried-over `monthly_only` rows (existing raw_sales rows the feed lacks — the feed-less days)
    are content-deduped before persisting (`summary['dupes_dropped']`), which also SELF-HEALS pre-existing
    bloat on the next run — NOTE this collapses two genuinely-identical line items on one real ticket to
    one (accepted; the authoritative monthly re-upload restores exact per-line truth); (3) an in-process
    per-(org_id, period) mutex serializes the hourly email-sweep promotion against the scheduled
    _promote_all_due — a second concurrent run for the same org+period SKIPS ('promotion already running')
    rather than interleaving a delete/insert into a double-count. dry_run is read-only → not mutex-gated.

    MONTH-BOUNDARY GRACE (2026-08-01, luxelink July→August): `grace=True` marks a re-derive of a period
    that is NO LONGER the current month — the sweep re-runs the PRIOR month for a few days after
    rollover because the B2B feed keeps finalizing it past midnight (see sales_derive.py). It changes
    exactly two things and NOTHING else: (a) every upload_trace row it writes is labelled
    `sales_derive.GRACE_NOTE` so the trace stays self-explanatory, and (b) a period whose feed is EMPTY
    is SKIPPED OUTRIGHT instead of being rebuilt from its own monthly-only rows — a closed month is
    never rewritten (nor content-deduped) on the strength of a feed that has nothing to say about it.
    With grace=False every line below behaves exactly as it did before this parameter existed."""
    pv = _pvariants(period)
    canon = next((v for v in pv if v[:1].isalpha()), period)  # 'June 2026' form for raw_sales
    # DEFECT 3 mutex — real (writing) runs only; dry_run is read-only so it must never block/skip a real
    # run. Non-blocking acquire: a concurrent real run for the same org+period skips with a trace note.
    _lock = None if dry_run else _promo_lock_for(org_id, canon)
    if _lock is not None and not _lock.acquire(blocking=False):
        note = "promotion already running for this org+period — skipped (concurrent run)"
        _tnote = f"{sales_derive.GRACE_NOTE} — {note}" if grace else note
        _write_upload_trace(org_id, source="promotion", filename=None, upload_type="sales",
                            period=canon, result={"saved": 0, "skipped": note, "note": _tnote})
        return {"period": canon, "dry_run": dry_run, "skipped": note, "grace": grace}
    try:
        return _promote_feed_impl(client, org_id, pv, canon, dry_run, force, retain, grace)
    finally:
        if _lock is not None:
            _lock.release()


def _promote_feed_impl(client, org_id, pv, canon, dry_run, force, retain, grace=False):
    """Core feed→raw_sales merge, mutex-guarded by `_promote_feed_to_raw_sales` (which precomputes
    pv/canon). See that wrapper's docstring for the full contract — including what `grace` does."""

    def _all(table):
        out, start = [], 0
        while True:
            rows = (client.schema('commcalc').table(table).select('*')
                    .eq('org_id', org_id).in_('period', pv)
                    .order('id').range(start, start + 999).execute().data) or []
            out.extend(rows)
            if len(rows) < 1000:
                return out
            start += 1000

    feed = _all('daily_sales_feed')
    existing = _all('raw_sales')
    feed_trans = {r.get('trans_id') for r in feed if r.get('trans_id')}
    raw_cols = set(existing[0].keys()) if existing else None
    DROP = {'id', 'created_at'}
    if raw_cols is None and feed:
        # First promotion for this org: raw_sales has no row to learn its columns from, and the feed
        # carries feed-only columns raw_sales lacks — inserting them 500s the whole promotion (hit by
        # luxelink 2026-07-14; the house org never hit it because its raw_sales was never empty).
        # Probe each feed column against raw_sales once; unknown columns are dropped. org_id/period
        # are re-stamped explicitly below, so they survive even if a probe hiccups.
        raw_cols = set()
        for c in feed[0].keys():
            if c in DROP:
                continue
            try:
                client.schema('commcalc').table('raw_sales').select(c).limit(1).execute()
                raw_cols.add(c)
            except Exception:
                continue

    new_rows = []
    for r in feed:
        row = {k: v for k, v in r.items() if k not in DROP and (raw_cols is None or k in raw_cols)}
        row['org_id'] = org_id
        row['period'] = canon
        new_rows.append(row)
    # DEFECT 2 — the feed-less-day rows (in raw_sales but NOT the feed) are carried over VERBATIM, so any
    # read-skew / previously-persisted duplicate compounds run-over-run (the feed-covered days don't,
    # because they're rebuilt from the feed each run). Content-dedupe them (signature drops id + created_at)
    # keeping the FIRST occurrence — this also self-heals existing bloat on the next run.
    monthly_only = [r for r in existing if r.get('trans_id') not in feed_trans]
    monthly_only, dupes_dropped = _dedupe_rows(monthly_only, drop_keys=('id', 'created_at'))
    for r in monthly_only:
        new_rows.append({k: v for k, v in r.items() if k != 'id'})

    def _amt(rows):
        return round(sum((safe_float(x.get('ext_price')) or 0) for x in rows), 2)
    summary = {
        "period": canon, "dry_run": dry_run, "grace": grace,
        "feed_lines": len(feed), "feed_trans": len(feed_trans),
        "existing_lines": len(existing), "existing_trans": len({r.get('trans_id') for r in existing}),
        "monthly_only_trans": len({r.get('trans_id') for r in monthly_only}),
        "dupes_dropped": dupes_dropped,
        "result_lines": len(new_rows), "result_trans": len({r.get('trans_id') for r in new_rows}),
        "existing_amount": _amt(existing), "result_amount": _amt(new_rows),
    }
    def _trace_promo(saved, skipped=None, error=None, note=None):
        # mig 202: trace the promotion (feed→raw_sales) like any other ingest. dry_run previews aren't
        # traced (no write). Best-effort — never affects the promotion. `note` surfaces the dedupe heal
        # (dupes_dropped) so the self-healing is observable in the trace even on a clean success.
        if dry_run:
            return
        # grace runs SAY SO on the trace (dispatch item 6). grace=False ⇒ `note or skipped`, which is
        # byte-for-byte what this wrote before.
        _tnote = note or skipped
        if grace:
            _tnote = f"{sales_derive.GRACE_NOTE} — {_tnote}" if _tnote else sales_derive.GRACE_NOTE
        _write_upload_trace(org_id, source="promotion", filename=None, upload_type="sales",
                            period=canon,
                            result={"saved": saved, "skipped": skipped, "note": _tnote,
                                    "_trace": {"rows_in": summary.get("feed_lines"),
                                               "target_table": "raw_sales",
                                               "periods": {canon: summary.get("result_lines", 0)},
                                               "date_counts": {}}},
                            error=error)

    # ★ MONEY-CRITICAL GUARD (grace runs only). The normal path treats "feed empty but raw_sales full"
    # as a rewrite of the existing month from its own monthly-only rows — harmless for the OPEN month it
    # was written for (it self-heals duplicates), but on a CLOSED month it would delete-then-reinsert a
    # basis somebody is about to be PAID from, silently collapsing genuinely-identical line items on the
    # way through (_dedupe_rows). A grace re-derive with nothing in the feed has, by definition, nothing
    # to add — so it touches nothing at all. Each period is judged INDEPENDENTLY: an empty July feed can
    # never wipe or churn July, and says nothing about August.
    if grace and not feed:
        summary["skipped"] = ("grace re-derive: no daily-feed rows for this period — raw_sales left "
                              "exactly as it is (a closed month is never rebuilt from an empty feed)")
        _trace_promo(0, skipped=summary["skipped"])
        return summary
    if not new_rows:
        summary["skipped"] = "no feed or monthly rows for this period"
        _trace_promo(0, skipped=summary["skipped"])
        return summary
    if existing and not force and len(new_rows) < retain * len(existing):
        summary["skipped"] = (f"guard: result {len(new_rows)} lines < {int(retain * 100)}% of existing "
                              f"{len(existing)} — feed looks incomplete (use force to override)")
        _trace_promo(0, skipped=summary["skipped"])
        return summary
    if dry_run:
        return summary

    # CROSS-TENANT INGEST GUARD (migration 280). The promotion is the path that made the 2026-07-14
    # Diversey mis-file PERMANENT — `monthly_only` carries over any raw_sales row the feed lacks, so
    # six foreign lines were re-inserted hourly for three weeks. Screening here is what stops that
    # from being invisible. 'warn' (the default) writes every row exactly as before.
    try:
        _g = _isg.screen(client, org_id, new_rows, 'raw_sales', source='promotion',
                         upload_type='sales', period=canon)
        if _g.get('flags'):
            _isg.record(client, org_id, _g)
            summary['guard'] = {'mode': _g['mode'], 'unknown_stores': _g['unknown_stores'],
                                'rows_flagged': _g['rows_flagged'],
                                'rows_withheld': _g['rows_withheld']}
        new_rows = _g.get('kept', new_rows)
    except Exception as _ge:
        print(f'WARN promotion ingest guard skipped: {_ge}')

    try:
        client.schema('commcalc').table('raw_sales').delete().eq('org_id', org_id).in_('period', pv).execute()
        for i in range(0, len(new_rows), 500):
            client.schema('commcalc').table('raw_sales').insert(new_rows[i:i + 500]).execute()
    except Exception as e:
        _trace_promo(0, error=str(e))
        raise
    summary["written"] = len(new_rows)
    _heal_note = (f"healed {dupes_dropped} duplicate monthly-only line(s) via content-dedupe"
                  if dupes_dropped else None)
    _trace_promo(len(new_rows), note=_heal_note)
    return summary


@router.post("/sales/promote-feed")
def promote_feed(period: str, org_id: str = ORG_ID, dry_run: bool = True, force: bool = False):
    """Build the monthly commission basis (raw_sales) for a period from the daily B2B email feed.
    dry_run=true (default) PREVIEWS the delta without writing — pass dry_run=false to commit, then
    recompute the period. Idempotent + guarded; merges so no transaction is ever dropped."""
    require_org(org_id)
    return _promote_feed_to_raw_sales(sb(), org_id, period, dry_run=dry_run, force=force)


@router.get("/sales/derive-config")
def get_sales_derive_config(org_id: str = ORG_ID):
    """This tenant's MONTH-BOUNDARY GRACE WINDOW: for how many days after rollover the automatic
    feed→raw_sales derivation keeps re-deriving the month that just closed.

    WHY IT EXISTS: the hourly derivation asks the wall clock for its period, so from 00:00 on the 1st it
    only ever derived the NEW month — while the B2B daily feed carried on finalizing the OLD one for
    hours (luxelink, 2026-08-01: 45 July transactions delivered to the feed after midnight, never
    promoted into the July basis, invisible to every July report and unpaid in a July recompute).

    Read-only. Returns the EFFECTIVE config, the code default it falls back to, and what the next
    automatic run will cover for this tenant right now."""
    require_org(org_id)
    client = sb()
    cfg = sales_derive.load(client, org_id)
    now = _datetime.now()
    return {
        "org_id": org_id,
        "config": cfg,
        "default": dict(sales_derive.DEFAULT),
        "max_days": sales_derive.MAX_GRACE_DAYS,
        "today": now.strftime("%Y-%m-%d"),
        "window_open": sales_derive.window_open(now, cfg),
        "current_period": _ftp_current_period(),
        "prior_period": sales_derive.prior_period_label(now),
        "next_run_periods": [p for p, _g, _r in _sales_derive_plan(client, org_id, now=now)],
        "grace_note": sales_derive.GRACE_NOTE,
    }


class PutSalesDeriveConfigIn(LaxModel):
    enabled: Any = None
    days: Any = None
    retain: Any = None


@router.put("/sales/derive-config")
def put_sales_derive_config(body: PutSalesDeriveConfigIn, org_id: str = ORG_ID, authorization: str = Header(default="")):
    """Save the tenant's month-boundary grace window (migration 266). Import-channel setting, so it is
    gated on the SAME 'import_health' settings area as the mailbox/portal editors — not the commission
    pay gate, because this changes WHEN sales are derived and never what anyone is paid.

    Body: {enabled: bool, days: int (0..15), retain: float|null}. days=0 (or enabled=false) restores the
    pre-fix behaviour for this tenant exactly: current month only, forever. `retain` is the shrink guard
    for GRACE runs only — set 1.0 if this tenant hand-uploads authoritative monthly files and a closed
    month must never come back with fewer lines than it had."""
    require_org(org_id)
    _require_import_admin(authorization, org_id)
    cfg = sales_derive.resolve({
        "enabled": body.enabled if "enabled" in body.model_fields_set else True,
        "days": body.days if "days" in body.model_fields_set else sales_derive.DEFAULT["days"],
        "retain": body.retain,
    })
    row = {"org_id": org_id, sales_derive.CONFIG_COLUMN: cfg,
           "updated_at": _datetime.now(_timezone.utc).isoformat()}
    try:
        sb().schema("commcalc").table("commission_org_config").upsert(row, on_conflict="org_id").execute()
    except Exception as e:
        raise HTTPException(500, f"could not save the derive window (is migration 266 applied?): {e}")
    return get_sales_derive_config(org_id=org_id)


@router.get("/sales/derive-status")
def get_sales_derive_status(org_id: str = ORG_ID, period: str = ""):
    """Is the monthly basis for `period` actually in step with the daily feed? Count-only and read-only.

    `missing_in_monthly` is the month-boundary defect's own number: transactions the feed delivered that
    raw_sales never received. > 0 on a CLOSED month means that month's reports are short and a recompute
    of it would underpay — re-derive it (POST /commcalc/sales/promote-feed) BEFORE calculating.

    Default period = the month that just closed, which is the one the boundary puts at risk."""
    require_org(org_id)
    client = sb()
    now = _datetime.now()
    p = (period or "").strip() or sales_derive.prior_period_label(now)
    gap = sales_recon.derive_gap(p, org_id=org_id, client=client)
    cfg = sales_derive.load(client, org_id)
    closed = _canon_period(p) != _canon_period(_ftp_current_period())
    return {**gap, "is_closed_month": closed,
            "grace_window_open": sales_derive.window_open(now, cfg),
            "grace_config": cfg,
            "auto_derive_enabled": bool(_registry_auto_map(client, org_id).get("sales", True)),
            "action": ("re-derive this period from the daily feed, then re-calculate it"
                       if gap.get("missing_in_monthly") else None)}


def _promote_all_due(client, period=None):
    """ORG-AGNOSTIC, self-healing feed→raw_sales promotion. For the OPEN month (default) it reconciles
    EVERY tenant that has daily_sales_feed rows — so a tenant whose email sweep hasn't ingested a NEW
    attachment recently still gets its raw_sales backfilled from the accumulated feed. This is the
    org-level fix for "the daily feed is ingesting but the Daily Sales reports show nothing": the promotion
    was previously invoked ONLY as a side-effect of the email sweep processing a fresh attachment
    (_run_email_sweep ~line 9126); when no new file arrives, the ~10 raw_sales-only display consumers
    (gp_report / sales_analyzer / top-sellers / discrepancy phantom / accessory-flags / fraud scan + the
    finance P&L and retail closing _b2b_day) show empty for a tenant with a healthy feed (luxelink July 2026).

    MONEY-SAFE by construction: promotion MERGES + dedups by trans_id (a trans_id present in BOTH tables is
    counted ONCE — feed wins, monthly-only kept once) and is guarded by the existing retain guard; it runs
    on the OPEN month only, which the commission calculator (_fetch_sales_unified) reads from the FEED
    regardless — so Boost/house pay is byte-identical and no pay is recomputed here (the sweep path + manual
    /calculate own recompute). Per-org opt-out via report_definitions.auto for report_key='sales' (the same
    gate the in-sweep promote uses).

    MONTH-BOUNDARY GRACE (2026-08-01): when NO period is requested, each tenant ALSO gets the month that
    just closed re-derived while its own grace window is open (commission_org_config.sales_derive_grace;
    see sales_derive.py). Still no recompute — the closed month's pay stays a human's decision. Passing an
    explicit `period` means EXACTLY that period, grace off, so the pg_cron/manual targeted call is
    unchanged."""
    explicit = bool(period)            # an explicitly-requested period means EXACTLY that period
    period = period or _ftp_current_period()
    pv = _pvariants(period)
    _now = _datetime.now()

    # 1) every tenant with feed rows for a period — fast RPC (mig 204), else a bounded distinct scan so
    #    the job still self-heals before the migration runs.
    def _feed_orgs(periods):
        try:
            rows = client.schema('commcalc').rpc('sales_feed_orgs_for_period',
                                                 {'p_periods': periods}).execute().data or []
            return [r['org_id'] for r in rows if r.get('org_id')], None
        except Exception:
            pass
        try:
            seen, start = set(), 0
            while True:
                batch = (client.schema('commcalc').table('daily_sales_feed').select('org_id')
                         .in_('period', periods).range(start, start + 4999).execute().data) or []
                for r in batch:
                    if r.get('org_id'):
                        seen.add(r['org_id'])
                if len(batch) < 5000:
                    break
                start += 5000
            return list(seen), None
        except Exception as e:
            return [], f"could not enumerate feed orgs: {e}"

    orgs, err = _feed_orgs(pv)
    if err:
        return {"ok": False, "error": err, "period": period}

    # MONTH-BOUNDARY GRACE (2026-08-01): a tenant whose OLD month is still finalizing may legitimately
    # have NO rows in the new month yet, so it would not appear in `orgs` at all. Enumerate the prior
    # period separately — never merged into `orgs`, so an org found ONLY here gets its closed month
    # re-derived and its current month left alone (exactly as today). Skipped entirely when a period was
    # requested explicitly, and short-circuited for the back half of every month (enumeration_needed).
    prior = sales_derive.prior_period_label(_now)
    grace_orgs = []
    if not explicit and sales_derive.enumeration_needed(_now):
        grace_orgs, _gerr = _feed_orgs(_pvariants(prior))
        if _gerr:
            grace_orgs = []                 # never fail the whole sweep over the grace enumeration

    cur_set = set(orgs)
    out = []
    for oid in list(orgs) + [o for o in grace_orgs if o not in cur_set]:
        try:
            if not _registry_auto_map(client, oid).get('sales', True):
                out.append({"org_id": oid, "skipped": "sales auto=false"})
                continue
            if oid in cur_set:
                pr = _promote_feed_to_raw_sales(client, oid, period)
                out.append({"org_id": oid, "written": (pr or {}).get('written', 0),
                            "result_lines": (pr or {}).get('result_lines'),
                            "skipped": (pr or {}).get('skipped')})
            if not explicit:
                for _gp, _g, _gret in _sales_derive_plan(client, oid, now=_now)[1:]:
                    gr = _promote_feed_to_raw_sales(client, oid, _gp, grace=_g, retain=_gret)
                    out.append({"org_id": oid, "period": _gp, "grace": True,
                                "written": (gr or {}).get('written', 0),
                                "result_lines": (gr or {}).get('result_lines'),
                                "skipped": (gr or {}).get('skipped')})
        except Exception as e:
            out.append({"org_id": oid, "error": str(e)[:200]})
    # DAILY COMMISSION ACCRUAL (mig 267) rides the SAME scheduled sweep, deliberately at the TAIL:
    # this is the moment the day's sales are actually complete for every tenant (the feed has just been
    # derived into raw_sales), which is exactly when "what has this rep earned today" becomes a number
    # worth writing down. No new cron infrastructure — see payout_accrual.run_all_due.
    # It re-accrues yesterday + today per tenant (per-tenant auto_run.days_back), is IDEMPOTENT, writes
    # ONLY commcalc.daily_commission_accrual, and can never raise into the promotion it rides on: an
    # accrual failure must not be able to stop sales from being derived.
    accrual = None
    if not explicit:
        try:
            accrual = payout_accrual.run_all_due(client)
        except Exception as e:
            accrual = {"ok": False, "error": str(e)[:200]}
    return {"ok": True, "period": period, "orgs": len(orgs),
            "grace_period": None if explicit else prior,
            "grace_orgs": sum(1 for r in out if r.get('grace')),
            "written_orgs": sum(1 for r in out if r.get('written')), "detail": out,
            "accrual": accrual}


@router.post("/sales/promote-due")
def sales_promote_due(x_notify_secret: str = Header(default=""), period: str = None):
    """pg_cron entrypoint — org-agnostic, self-healing feed→raw_sales promotion for the OPEN month across
    EVERY tenant (see _promote_all_due). Reuses NOTIFY_RUN_SECRET (no new env var). DISPLAY-safe: OPEN
    month only, promotion dedups by trans_id, no pay recompute — a run can never change Boost numbers or
    double-count. Schedule hourly (offset from the email-sweep cron) so raw_sales never lags the feed for
    any tenant. With no `period` it also re-derives the JUST-CLOSED month inside each tenant's
    month-boundary grace window (sales_derive.py) — still with no recompute anywhere."""
    if not verify_notify_secret(x_notify_secret):
        raise HTTPException(403, "forbidden")
    return _promote_all_due(sb(), period)


def _strip_pw(cfg):
    cfg = dict(cfg)
    cfg['has_password'] = bool(cfg.pop('password', None))
    return cfg


@router.get("/email-sweep/accounts")
def list_email_accounts(org_id: str = ORG_ID):
    """Every mailbox configured for this tenant (passwords stripped). Multi-mailbox = one row per
    report source (e.g. B2B feed + Total Wireless). [] if none configured yet."""
