@router.get("/financing/targets/{period}")
def get_financing_targets(period: str, include_inactive: bool = False,
                                authorization: str = Header(default=""),
                                org_id: str = ORG_ID):
    """The assignable per-store financing targets for a period, over the org's own store roster (so the
    Target Settings grid can render a Financing column next to the existing ones). Span-scoped for a
    restricted caller, exactly like the main targets list."""
    require_org(org_id)
    client = sb()
    rows = []
    ready = True
    try:
        rows = (client.schema('commcalc').table(_finreg.TARGET_TABLE).select('*')
                .eq('org_id', org_id).in_('period', _pvariants(period)).limit(20000).execute().data) or []
    except Exception:
        rows, ready = [], False
    by_code = {}
    per_vendor = {}
    for r in rows:
        code = str(r.get('store_code') or '').strip()
        vk = str(r.get('vendor_key') or '').strip().lower()
        if not code:
            continue
        if vk:
            per_vendor.setdefault(code.upper(), []).append(
                {"vendor_key": vk, "target_units": safe_float(r.get('target_units')),
                 "target_amount": r.get('target_amount')})
        else:
            by_code[code.upper()] = r
    # ACTIVE roster (owner 2026-08-06): a disabled store is not offered a new financing target, but one
    # that already has a saved row for the period keeps rendering it. include_inactive=1 = full roster.
    stores = _storeops_roster(client, org_id, cols='store_code,address,market,is_active',
                              include_inactive=include_inactive,
                              keep_codes=set(by_code) | set(per_vendor))
    out = []
    for s in stores:
        code = str(s.get('store_code') or '').strip()
        if not code:
            continue
        cur = by_code.get(code.upper())
        out.append({'store_code': code, 'address': s.get('address'), 'market': s.get('market'),
                    'is_active': _store_active(s),
                    'target_units': safe_float((cur or {}).get('target_units')),
                    'target_amount': (cur or {}).get('target_amount'),
                    'notes': (cur or {}).get('notes'),
                    'vendor_targets': per_vendor.get(code.upper(), []),
                    '_saved': cur is not None})
    out.sort(key=lambda r: str(r.get('address') or r.get('store_code') or ''))
    try:
        from app.modules.storeops.router import scope_keyset, in_keyset
        ks = scope_keyset(authorization, org_id)
        if ks is not None:
            out = [r for r in out if in_keyset(ks, r.get('store_code'), r.get('address'))]
    except Exception:
        pass
    vendors, _vr = _finreg.load_vendors(client, org_id)
    return {'period': period, 'ready': ready, 'targets': out,
            'vendors': [{'vendor_key': v['vendor_key'], 'label': v['label']} for v in vendors],
            'note': (None if ready else
                     'Migration 272 has not been run — financing targets cannot be saved yet.')}


class SaveFinancingTargetIn(LaxModel):
    store_code: Any = None
    vendor_key: Any = None
    target_amount: Any = None
    target_units: Any = None
    notes: Any = None
    updated_by: Any = None


@router.put("/financing/targets/{period}")
async def save_financing_target(period: str, body: SaveFinancingTargetIn, authorization: str = Header(default=""),
                                org_id: str = ORG_ID):
    """Set ONE store's monthly financing target (optionally per vendor). Gated on the SAME 'targets'
    settings area + store span as the existing Target Settings save.

    A target is not a payout: it changes what the Financing report calls attainment, and — only if the
    owner has configured attainment tiers — which tier a store reaches. It is deliberately a separate
    table from commcalc.targets so this cannot break the existing target save."""
    require_org(org_id)
    client = sb()
    code = str(body.store_code or '').strip()
    if not code:
        raise HTTPException(400, "store_code required")
    _require_target_edit(authorization, org_id, code)
    vk = str(body.vendor_key or '').strip().lower()
    amt = body.target_amount
    row = {'org_id': org_id, 'period': period, 'store_code': code,
           'vendor_key': (vk or None),
           'target_units': safe_float(body.target_units),
           'target_amount': (safe_float(amt) if str(amt if amt is not None else '').strip() != '' else None),
           'notes': body.notes,
           'updated_by': body.updated_by or 'web',
           'updated_at': datetime.now(timezone.utc).isoformat()}
    try:
        r = (client.schema('commcalc').table(_finreg.TARGET_TABLE)
             .upsert(row, on_conflict='org_id,period,store_code,vendor_key').execute())
    except Exception:
        # Upsert on a partial/expression unique index can be rejected by PostgREST; fall back to an
        # explicit delete-then-insert for this exact key so a target save never silently fails.
        try:
            q = (client.schema('commcalc').table(_finreg.TARGET_TABLE).delete()
                 .eq('org_id', org_id).eq('period', period).eq('store_code', code))
            q = q.is_('vendor_key', 'null') if not vk else q.eq('vendor_key', vk)
            q.execute()
            r = client.schema('commcalc').table(_finreg.TARGET_TABLE).insert(row).execute()
        except Exception as ex2:
            raise HTTPException(500, f"could not save the financing target "
                                     f"(is migration 272 applied?): {ex2}")
    return (r.data[0] if getattr(r, 'data', None) else row)


@router.get("/financing/{period}")
def financing_report(period: str, org_id: str = ORG_ID):
    """THE FINANCING REPORT — financed units and financed dollars by vendor x store x rep for a period,
    with per-store target attainment and MTD pace.

    Read-only. Sales come from the canonical DISPLAY union of raw_sales and daily_sales_feed (so a tenant
    on the hourly feed sees the open month and a promoted month is never masked by a stale feed), and
    units are collapsed to DEVICES with the same gate the payout uses."""
    require_org(org_id)
    client = sb()
    rows, meta = _sales_rows_union(client, org_id, period, cols=_FIN_SALES_COLS)
    vendors = _finreg.resolve_vendors(client, org_id)
    targets = _fintier.load_targets(client, org_id, _pvariants(period))
    store_index = _fintier.load_store_index(client, org_id)
    resolve_market, all_markets = _store_market_resolver(client, org_id)
    gate, ucfg = _fin_gate()
    acc_fn = None
    try:
        acc_fn = gate.accessory_predicate(client, org_id) if gate is not None else None
    except Exception:
        acc_fn = None
    md, de = _finrep.month_bounds(period)
    out = _finrep.build(rows, vendors, targets, store_index, resolve_market, period,
                        gate=gate, unit_cfg=ucfg, is_accessory=acc_fn,
                        month_days=md, days_elapsed=de)
    out["markets"] = all_markets
    out["source"] = {"rows_read": len(rows), "primary": (meta or {}).get("primary"),
                     "meta": meta}
    # A vendor running on an INHERITED DEFAULT (the built-in ACIMA tender fallback) is deliberately NOT
    # counted as configured: it has a matcher, but nobody chose it, and on the house export the real
    # tender string is not the fallback. Counting it would turn "nobody mapped this" into a green light.
    out["configured_vendors"] = sum(1 for v in vendors if v.get("detection_status") == "configured")
    out["vendors_running_on_defaults"] = sum(
        1 for v in vendors if v.get("detection_status") == "inherited_default")
    out["ready"] = True
    return out


# ═══ ATU (AUTOPAY) OPPORTUNITY ══════════════════════════════════════════════════════════════════════
# Owner directive 2026-08-12: card-paying customers vs those on ATU, and the % of revenue forgone by
# not converting them. The four assumptions (customer saving, Boost rate, Total rate, Total recharge
# base) are TENANT CONFIG, never constants — the owner stated plainly that they change. All math lives
# in commcalc/atu_opportunity.py (pure, harness_atu_opportunity.py 43/43, reproduces the measured July
# figures exactly: 617 card customers / 315 on ATU / 51.1% / $24,766 open recharge).
_ATU_DEFAULTS = {"saving_per_month": 9.0, "boost_rate_pct": 5.0, "total_rate_pct": 8.5,
                 "total_recharge_base": 0.0}


def _atu_cfg(client, org_id):
    """This tenant's assumptions. Degrades to the owner's stated defaults when mig 295 has not run, so
    the page renders rather than 500-ing on a tenant that is one migration behind."""
    try:
        rows = (client.schema("commcalc").table("atu_config").select("*")
                .eq("org_id", org_id).limit(1).execute().data) or []
    except Exception:
        return dict(_ATU_DEFAULTS), False
    if not rows:
        return dict(_ATU_DEFAULTS), True
    r = rows[0]
    out = {}
    for k, dv in _ATU_DEFAULTS.items():
        try:
            out[k] = float(r.get(k)) if r.get(k) is not None else dv
        except (TypeError, ValueError):
            out[k] = dv
    return out, True


@router.get("/atu-config")
def atu_config_get(org_id: str = ORG_ID):
    """The tenant's ATU assumptions (RULE: config, not constants)."""
    require_org(org_id)
    cfg, present = _atu_cfg(sb(), org_id)
    return {"org_id": org_id, "config": cfg, "table_present": present, "defaults": _ATU_DEFAULTS}


class AtuConfigSetIn(LaxModel):
    saving_per_month: Any = None
    boost_rate_pct: Any = None
    total_rate_pct: Any = None
    total_recharge_base: Any = None


@router.post("/atu-config")
def atu_config_set(body: AtuConfigSetIn, org_id: str = ORG_ID):
    """Save the assumptions. org_id is STAMPED (RULE ONE). Values are clamped to >= 0 — a negative rate
    would silently flip the sign of the whole report."""
    require_org(org_id)
    payload = {"org_id": org_id}
    for k in _ATU_DEFAULTS:
        if k in body.model_fields_set:
            try:
                payload[k] = max(0.0, float(getattr(body, k)))
            except (TypeError, ValueError):
                continue
    payload["updated_at"] = _datetime.now(_timezone.utc).isoformat()
    try:
        sb().schema("commcalc").table("atu_config").upsert(payload, on_conflict="org_id").execute()
    except Exception as e:
        raise HTTPException(400, f"Could not save ATU settings — run migration 295_atu_opportunity_config.sql first. [{e}]")
    cfg, _ = _atu_cfg(sb(), org_id)
    return {"ok": True, "config": cfg}


@router.get("/atu-opportunity")
def atu_opportunity_report(period: str = "", start: str = "", end: str = "",
                           stores: str = "", markets: str = "",
                           authorization: str = Header(default=""), org_id: str = ORG_ID):
    """ATU opportunity for a period, optionally narrowed to a date range / stores / markets (RULE FIVE).

    Reads the TRANSACTION-grain sales union, because enrolment is a department-less $0 `Autopay` LINE and
    can only be seen by reducing across every line of a transaction — filtering rows before that returns
    a confident 0% attach for every store. Span-scoped like every other report: a store-scoped user never
    sees an out-of-scope store."""
    require_org(org_id)
    client = sb()
    if not period:
        n = _datetime.now(_timezone.utc)
        period = f"{n.year}-{n.month:02d}"
    cfg, table_present = _atu_cfg(client, org_id)
    rows, _meta = _sales_rows_union_txn(
        client, org_id, period,
        cols="trans_id,trans_date,store,tender_type,product_desc,ext_price,mdn,contract_type,voided")
    rows = [r for r in rows if str(r.get("voided") or "").strip().lower() not in ("true", "yes", "y", "1")]

    s0, s1 = (start or "").strip()[:10], (end or "").strip()[:10]
    if s0 or s1:
        def _in(r):
            d = str(r.get("trans_date") or "")[:10]
            return (not s0 or d >= s0) and (not s1 or d <= s1)
        rows = [r for r in rows if _in(r)]

    resolve_market, all_markets = _store_market_resolver(client, org_id)
    sel_stores = [s for s in (stores or "").split(",") if s.strip()]
    sel_markets = [s for s in (markets or "").split(",") if s.strip()]
    if sel_stores:
        keep = set(sel_stores)
        rows = [r for r in rows if str(r.get("store") or "") in keep]
    if sel_markets:
        keep = set(sel_markets)
        rows = [r for r in rows if resolve_market(r.get("store")) in keep]

    try:
        from app.modules.storeops.router import scope_keyset, in_keyset
        ks = scope_keyset(authorization, org_id)
        if ks is not None:
            rows = [r for r in rows if in_keyset(ks, r.get("store"))]
    except Exception:
        pass

    txs = _atu.fold_transactions(rows)
    summary = _atu.summarize(txs, cfg["saving_per_month"], cfg["boost_rate_pct"],
                             cfg["total_rate_pct"], cfg["total_recharge_base"])
    stores_out = _atu.by_store(txs, cfg["boost_rate_pct"])
    for s in stores_out:
        s["market"] = resolve_market(s["store"])
    store_opts = sorted({str(r.get("store") or "") for r in rows if r.get("store")})
    return {
        "org_id": org_id, "period": period, "start": s0 or None, "end": s1 or None,
        "config": cfg, "table_present": table_present,
        "summary": summary, "stores": stores_out,
        "transactions": len(txs),
        "filter_options": {"stores": store_opts, "markets": sorted(all_markets)},
        "applied_filters": {"stores": sel_stores, "markets": sel_markets},
        # Stated on the page, not buried: enrolment is observed at ACTIVATION only, so a customer who
        # enrols later via the carrier app is invisible here and the open position is an UPPER BOUND.
        "caveats": [
            "Enrolment is observed at activation in the POS feed. A customer who enrols later through "
            "the carrier app does not appear here, so the open position is an upper bound.",
            "Customer counts use the mobile number (autopay attaches per line); the recharge base is "
            "per transaction. The two denominators differ by design.",
            "Total/VidaPay recharges do not reach the POS export, so the Total side uses the recharge "
            "base entered in Settings.",
        ],
    }


# ══════════════════════════════════════════════════════════════════════════════════════════════════
# MANAGEMENT INCENTIVE (migration 852) — per-manager, store-aggregated incentive plans. CRUD for the
# plan definition, a compute endpoint that feeds the pure engine (management_incentive.py), and the
# payout ledger (draft → approved → paid). Every read degrades to empty when mig 852 hasn't run, so a
# pre-migration tenant never 500s. Actual production/metric resolution (accessory $, VHI/FIOS, Edge,
# cash-deposit, inventory aging, KPI pull) lands in a follow-up; today the caller supplies actuals +
# qualifier values (manual/entry or a later resolver), and the engine does the money math.
# ══════════════════════════════════════════════════════════════════════════════════════════════════
_MI_CHILD_TABLES = ("management_incentive_component", "management_incentive_bonus",
                    "management_incentive_qualifier", "management_incentive_assignment")


def _mi_load_plans(client, org_id, plan_id=None, active_only=False):
    """Load management-incentive plans with their children nested, shaped for the engine + the builder
    UI. Best-effort: an un-run migration 852 (tables absent) returns []."""
    try:
        q = (client.schema("commcalc").table("management_incentive_plan").select("*").eq("org_id", org_id))
        if plan_id:
            q = q.eq("id", plan_id)
        if active_only:
            q = q.eq("is_active", True)
        plans = q.execute().data or []
    except Exception:
        return []
    if not plans:
        return []
    ids = [p["id"] for p in plans]
    kids = {t: {} for t in _MI_CHILD_TABLES}
    for t in _MI_CHILD_TABLES:
        try:
            rows = (client.schema("commcalc").table(t).select("*")
                    .eq("org_id", org_id).in_("plan_id", ids).execute().data) or []
        except Exception:
            rows = []
        for r in rows:
            kids[t].setdefault(r.get("plan_id"), []).append(r)
    for p in plans:
        p["components"] = sorted(kids["management_incentive_component"].get(p["id"], []), key=lambda x: x.get("sort", 0))
        p["bonuses"] = sorted(kids["management_incentive_bonus"].get(p["id"], []), key=lambda x: x.get("sort", 0))
        p["qualifiers"] = sorted(kids["management_incentive_qualifier"].get(p["id"], []), key=lambda x: x.get("sort", 0))
        p["assignments"] = kids["management_incentive_assignment"].get(p["id"], [])
    return plans


@router.get("/management-incentive/plans")
def mi_list_plans(org_id: str = ORG_ID):
    """Every management-incentive plan for the tenant, children nested. Empty pre-migration-852."""
    require_org(org_id)
    return {"plans": _mi_load_plans(sb(), org_id)}


class MiSavePlanIn(LaxModel):
    id: Any = None
    name: str = ""
    level: Any = None
    carrier_id: Any = None
    period_type: Any = None
    consolidated_bonus_amount: Any = 300
    is_active: Any = True
    is_default: Any = False
    notes: Any = None
    actor: Any = _Field(default=None, alias="_actor")
    components: Any = None
    bonuses: Any = None
    qualifiers: Any = None
    assignments: Any = None


@router.post("/management-incentive/plans")
def mi_save_plan(body: MiSavePlanIn, org_id: str = ORG_ID):
    """Upsert a plan and REPLACE its children (components / bonuses / qualifiers / assignments) —
    delete-then-insert, the same shape as save_commission_plan. `assignments` is how an employee/role/
    level is attached to the plan (scope precedence employee>role>store>market>default). Editing a plan
    stamps updated_by so the platform seeder never clobbers it again."""
    require_org(org_id)
    name = (body.name or "").strip()
    if not name:
        raise HTTPException(400, "name required")
    client = sb()
    header = {
        "org_id": org_id, "name": name,
        "level": (body.level or None),
        "carrier_id": body.carrier_id or None,
        "period_type": (body.period_type or "monthly"),
        "consolidated_bonus_amount": safe_float(body.consolidated_bonus_amount),
        "is_active": bool(body.is_active),
        "is_default": bool(body.is_default),
        "notes": body.notes or None,
        "updated_by": (body.actor or "admin"),
    }
    try:
        if body.id:
            client.schema("commcalc").table("management_incentive_plan").update(header) \
                  .eq("id", body.id).eq("org_id", org_id).execute()
            plan_id = body.id
        else:
            r = client.schema("commcalc").table("management_incentive_plan") \
                      .upsert(header, on_conflict="org_id,name").execute()
            plan_id = (r.data or [{}])[0].get("id")
            if not plan_id:
                got = (client.schema("commcalc").table("management_incentive_plan").select("id")
                       .eq("org_id", org_id).eq("name", name).limit(1).execute().data) or []
                plan_id = got[0]["id"] if got else None
        if not plan_id:
            raise HTTPException(500, "could not resolve plan id after save")

        def _kids(key, table, fields):
            client.schema("commcalc").table(table).delete().eq("org_id", org_id).eq("plan_id", plan_id).execute()
            rows = getattr(body, key) or []
            clean = []
            for i, raw in enumerate(rows):
                row = {k: raw.get(k) for k in fields if k in raw}
                row["org_id"], row["plan_id"] = org_id, plan_id
                row.setdefault("sort", i)
                clean.append(row)
            if clean:
                client.schema("commcalc").table(table).insert(clean).execute()

        _kids("components", "management_incentive_component",
              ("label", "kind", "rate", "metric_source", "target_per_store", "store_count", "cap_at_target", "sort"))
        _kids("bonuses", "management_incentive_bonus",
              ("label", "kind", "amount", "gated_by", "config", "sort"))
        _kids("qualifiers", "management_incentive_qualifier",
              ("metric_key", "label", "source", "op", "threshold", "unit", "config", "applies_to", "sort"))
        _kids("assignments", "management_incentive_assignment",
              ("scope", "scope_value", "priority"))
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"save failed (has migration 852 run?): {e}")
    plans = _mi_load_plans(client, org_id, plan_id=plan_id)
    return {"ok": True, "plan": (plans[0] if plans else {"id": plan_id})}


@router.delete("/management-incentive/plans/{plan_id}")
def mi_delete_plan(plan_id: str, org_id: str = ORG_ID):
    """Delete a plan (children cascade via the FK). A seeded default can be deleted; the seeder will
    re-create it on the next sync unless a tenant keeps its own edited copy."""
    require_org(org_id)
    try:
        sb().schema("commcalc").table("management_incentive_plan").delete() \
            .eq("id", plan_id).eq("org_id", org_id).execute()
    except Exception as e:
        raise HTTPException(500, f"delete failed: {e}")
    return {"ok": True}


class MiComputeIn(LaxModel):
    plan_id: Any = None
    employee_id: Any = None
    employee_name: Any = None
    role: Any = None
    store: Any = None
    market: Any = None
    store_keys: Any = None
    store_codes: Any = None
    manager_store_count: Any = None
    actuals: Any = None
    qualifier_values: Any = None
    derived: Any = None
    overrides: Any = None
    period: Any = None
    save: Any = None


@router.post("/management-incentive/compute")
def mi_compute(body: MiComputeIn, org_id: str = ORG_ID):
    """Compute a manager's incentive for a period and (optionally) save it as a draft payout.

    Body: {plan_id?, employee_id, employee_name?, role?, store?, market?, store_keys?, period,
           store_codes?, manager_store_count?, actuals{}, qualifier_values{}, derived{}, overrides{},
           save?(bool)}. When plan_id is omitted the plan is RESOLVED for the manager exactly like the
           employee commission plan (employee>role>store>market>default). Returns the full breakdown;
           when save=true it upserts commcalc.management_incentive_payout as a draft (never auto-paid)."""
    require_org(org_id)
    from app.modules.commcalc import management_incentive as _mi
    client = sb()
    plans = _mi_load_plans(client, org_id, plan_id=body.plan_id, active_only=not body.plan_id)
    if body.plan_id:
        plan = plans[0] if plans else None
    else:
        plan = _mi.resolve_plan(
            plans, employee_name=body.employee_name, role=body.role,
            store=body.store, market=body.market, store_keys=body.store_keys)
    if not plan:
        raise HTTPException(404, "no management-incentive plan resolves for this manager")

    store_codes = body.store_codes or []
    store_count = body.manager_store_count
    if store_count is None:
        store_count = len(store_codes)
    result = _mi.compute_payout(
        plan,
        actuals=body.actuals or {},
        qualifier_values=body.qualifier_values or {},
        manager_store_count=store_count,
        derived=body.derived or {},
        overrides=body.overrides or {})

    period = (body.period or "").strip()
    saved = None
    if body.save and period and body.employee_id:
        row = {
            "org_id": org_id, "plan_id": plan.get("id"),
            "employee_id": str(body.employee_id), "employee_name": body.employee_name,
            "period": period, "store_codes": store_codes, "breakdown": result,
            "component_total": result["component_total"], "bonus_total": result["bonus_total"],
            "total": result["total"], "qualified": result["consolidated_qualified"],
            "status": "draft", "updated_at": datetime.now(timezone.utc).isoformat(),
        }
        try:
            up = client.schema("commcalc").table("management_incentive_payout").upsert(
                row, on_conflict="org_id,plan_id,employee_id,period").execute()
            saved = True
            _intimate_mi_payout(org_id, (up.data or [{}])[0], store_codes)
        except Exception as e:
            saved = f"not saved: {e}"
    return {"ok": True, "plan_id": plan.get("id"), "plan_name": plan.get("name"),
            "breakdown": result, "saved": saved}


@router.get("/management-incentive/payouts")
def mi_list_payouts(period: str = "", employee_id: str = "", status: str = "", org_id: str = ORG_ID):
    """Computed management-incentive payouts for the tenant (the statement + accrual source). Filters:
    period 'YYYY-MM', employee_id, status. Newest first. Empty pre-migration-852."""
    require_org(org_id)
    try:
        q = sb().schema("commcalc").table("management_incentive_payout").select("*").eq("org_id", org_id)
        if period:
            q = q.eq("period", period)
        if employee_id:
            q = q.eq("employee_id", employee_id)
        if status:
            q = q.eq("status", status)
        rows = q.order("period", desc=True).limit(1000).execute().data or []
    except Exception:
        rows = []
    return {"payouts": rows}


class MiPayoutDecisionIn(LaxModel):
    decision: str = ""
    who: Any = None
    who_name: Any = None
    note: Any = None


def _intimate_mi_payout(org_id, payout, store_codes=None):
    """Intimation-only bridge to the unified approvals inbox for a management-incentive payout.

    The payout ledger is multi-state (draft -> approved -> paid) and its decision has THREE actions
    (approve / deny / pay), where 'deny' reopens to draft rather than terminally rejecting — it is NOT a
    single binary approve/deny, and 'pay' moves commission money. So it has NO acting on_decide (the
    adapter blocks inbox decisions); the decision stays on the incentive board and we only MIRROR the
    payout into the inbox as an intimation. Best-effort; never raises."""
    try:
        pid = payout.get("id")
        if not pid or (payout.get("status") or "draft") != "draft":
            return
        from app.modules.approvals import engine as _approvals
        total = payout.get("total")
        store = next((s for s in (store_codes or payout.get("store_codes") or []) if s), None)
        _approvals.create_request(
            org_id, type="management_incentive", source_table="management_incentive_payout",
            source_id=pid,
            title=f"Management incentive ${float(total or 0):,.2f} — {payout.get('employee_name') or payout.get('employee_id')} ({payout.get('period')})",
            summary="Computed manager-incentive payout awaiting approval on the incentive board.",
            payload={"total": total, "period": payout.get("period"),
                     "employee_id": payout.get("employee_id")},
            store_code=store, priority="normal", notify=False)
    except Exception:
        pass


@router.post("/management-incentive/payouts/{payout_id}/decision")
def mi_payout_decision(payout_id: str, body: MiPayoutDecisionIn, org_id: str = ORG_ID):
    """Approve / deny / mark-paid a computed payout — the ledger transition (draft → approved → paid).
    Body: {decision:'approve'|'deny'|'pay', note?, who?, who_name?}. Denying keeps the row for the audit
    trail but zeroes nothing here — payroll readers act on status. Nothing is paid until 'pay'."""
    require_org(org_id)
    decision = (body.decision or "").strip().lower()
    status = {"approve": "approved", "deny": "draft", "pay": "paid"}.get(decision)
    if status is None:
        raise HTTPException(400, "decision must be 'approve', 'deny', or 'pay'")
    _iso = datetime.now(timezone.utc).isoformat()
    upd = {"status": status, "decided_by": body.who, "decided_by_name": body.who_name,
           "decided_at": _iso, "updated_at": _iso}
    if body.note is not None:
        upd["override_note"] = body.note
    try:
        r = (sb().schema("commcalc").table("management_incentive_payout").update(upd)
             .eq("id", payout_id).eq("org_id", org_id).execute())
        if not (r.data or []):
            raise HTTPException(404, "payout not found")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"decision failed: {e}")
    # Intimation-only mirror: reflect approve/deny into the inbox request (pay is a later money step the
    # board owns). Never affects the ledger decision above.
    if decision in ("approve", "deny"):
        try:
            from app.modules.approvals import engine as _approvals
            _approvals.sync_source_decision(org_id, type="management_incentive",
                                            source_table="management_incentive_payout",
                                            source_id=payout_id, decision=decision,
                                            actor=body.who, note=body.note)
        except Exception:
            pass
    return {"ok": True, "status": status}


# ── AUTO-PULL the numbers (migration 852 follow-up) ───────────────────────────────────────────────
# Resolve a manager's actuals + qualification metrics for a period, aggregated across the stores they
# manage, REUSING the app's own math so the numbers match every other surface. Best-effort per metric:
# a metric with no data source (or a failed read) is left UNRESOLVED and stays a manual-entry field —
# it is never silently guessed. Returns pre-fill values the Compute tab drops in for the manager to
# review before saving. Nothing here computes pay.
def _mi_word_in(text, word):
    """True when `word` appears as a whole token in `text` (case-insensitive) — the same word-match the
    activation/category classifiers use, so 'edge' doesn't match 'ledger' and 'vhi' doesn't match 'vhic'."""
    toks = set()
    cur = ""
    for ch in str(text or "").lower():
        if ch.isalnum():
            cur += ch
        else:
            if cur:
                toks.add(cur)
            cur = ""
    if cur:
        toks.add(cur)
    return word in toks


def _mi_classify_sales_row(category, contract_type, product_desc):
    """Word-match a sales row to a Management-Incentive component metric. Returns 'edge' | 'twp' |
    'vhi_fios' | None. NOTE: the app has no pre-assembled per-store count for these — this defines each
    by the same tokens the activation/category classifiers recognize (see _AUTO_ACT_CATEGORY_KEYS and
    installment_category rules). TWP = Total Wireless Protect insurance attach (owner: "TW" = protect).
    Kept pure for the harness."""
    fields = (category, contract_type, product_desc)
    if any(_mi_word_in(f, "edge") for f in fields):
        return "edge"
    if any(_mi_word_in(f, "twp") or _mi_word_in(f, "protect") for f in fields):
        return "twp"
    if any(_mi_word_in(product_desc, w) for w in ("vhi",)) or any(_mi_word_in(f, "fios") for f in fields):
        return "vhi_fios"
    # 'home internet' is a two-token phrase → check the raw substring on category/product_desc.
    if any("home internet" in str(f or "").lower() for f in (category, product_desc)):
        return "vhi_fios"
    return None


def _mi_parse_date(s):
    from datetime import date as _d
    if not s:
        return None
    s = str(s)[:10]
    try:
        return _d(int(s[:4]), int(s[5:7]), int(s[8:10]))
    except (ValueError, IndexError):
        return None


def _mi_ever_over_days(received_date, days_in_stock, as_of_date, off_hand_as_of, m_start, m_end, max_days):
    """Did this device EVER exceed max_days in stock DURING [m_start, m_end]? Returns True/False, or None
    when the age is unknowable. This answers the period-correct question the shipped gate did not: not "is
    it over N right now" but "did it peak over N at any point in the period." `received` falls back to
    (as_of_date − days_in_stock) when received_date is NULL — the luxelink aging export carries age, not a
    received date, and device_history uses the same fallback ladder. PURE / unit-tested."""
    from datetime import timedelta
    ms = _mi_parse_date(m_start); me = _mi_parse_date(m_end)
    rec = _mi_parse_date(received_date)
    if rec is None:
        aod = _mi_parse_date(as_of_date)
        try:
            dis = int(days_in_stock)
        except (TypeError, ValueError):
            dis = None
        if aod is not None and dis is not None:
            rec = aod - timedelta(days=dis)
    if rec is None or ms is None or me is None:
        return None
    off = _mi_parse_date(off_hand_as_of)
    in_stock = rec <= me and (off is None or off >= ms)     # on the shelf at some point in the period
    shelf_end = min(off, me) if off is not None else me     # last day it could have aged within the period
    peak = (shelf_end - rec).days
    return bool(in_stock and peak > int(max_days))


def _mi_period_dates(period):
    """'YYYY-MM' → (first_day, last_day) ISO date strings for that month."""
    from datetime import date as _d
    y, m = int(str(period)[:4]), int(str(period)[5:7])
    first = _d(y, m, 1)
    nxt = _d(y + 1, 1, 1) if m == 12 else _d(y, m + 1, 1)
    last = _d.fromordinal(nxt.toordinal() - 1)
    return first.isoformat(), last.isoformat()


def _mi_resolve_numbers(client, org_id, period, employee_id, plan):
    """Assemble {store_codes, manager_store_count, actuals, qualifier_values, derived, resolved,
    unresolved, notes}. Every read is guarded — a failure leaves that key unresolved (manual)."""
    out = {"store_codes": [], "manager_store_count": 0, "actuals": {}, "qualifier_values": {},
           "derived": {}, "resolved": [], "unresolved": [], "notes": {}}

    # 1. Manager → store set (org tree, the SAME span RBAC uses).
    store_codes = []
    try:
        rows = (get_supabase().schema("storeops")
                .rpc("org_span_for_manager", {"p_org_id": org_id, "p_employee_id": str(employee_id)})
                .execute().data) or []
        store_codes = sorted({(r.get("store_code") or "").strip() for r in rows if (r.get("store_code") or "").strip()})
    except Exception:
        store_codes = []
    out["store_codes"] = store_codes
    out["manager_store_count"] = len(store_codes)
    if not store_codes:
        out["notes"]["store_codes"] = "No stores resolved from the org tree for this manager (org units / managers configured?)."
    scodes = set(store_codes)

    which_sources = {(c.get("metric_source") or "") for c in (plan.get("components") or [])}
    which_quals = {(q.get("metric_key") or "") for q in (plan.get("qualifiers") or [])}

    # 2. Accessory $ — the app's own accessory 'achieved' (ext_price + set-up fee), summed over stores.
    if "accessory_gp" in which_sources:
        try:
            feed = _compute_feed_actuals_py(client, org_id, period) or []
            acc = round(sum(_f_num(a.get("acc_gp")) for a in feed if (a.get("store_code") or "") in scodes), 2)
            out["actuals"]["accessory_gp"] = acc
            out["resolved"].append("accessory_gp")
            out["notes"]["accessory_gp"] = "Accessory sales + device set-up fee (the app's accessory 'achieved'), summed over the manager's stores."
        except Exception:
            out["unresolved"].append("accessory_gp")

    # 3/4. Edge + VHI/FIOS counts — counted over the EXACT SAME transactions rep commission is paid on,
    # so the DM's roll-up shares one basis of truth with rep pay. We apply calc_rep_commissions' own row
    # filters (gp_report.is_voided, trans_type != 'Return', salesperson != 'admin') and its source
    # precedence (raw_sales → daily_sales_feed), then tag edge / VHI-FIOS by product tokens. NOTE: rep pay
    # has no distinct edge/VHI line today — both fold into 'premium activations' — so this counts the same
    # sales universe reps are paid on and labels the two product kinds within it.
    if any(k in which_sources for k in ("edge_count", "vhi_fios_count", "twp_count")):
        try:
            from app.modules.commcalc import gp_report as _gp
            resolve_code = _store_code_resolver(client, org_id)
            def _raw(table):
                return (client.schema("commcalc").table(table).select(_ACTUALS_COLS)
                        .eq("org_id", org_id).in_("period", _pvariants(period)).limit(200000).execute().data) or []
            rows = _raw("raw_sales") or _raw("daily_sales_feed")   # rep-pay source precedence
            edge_ids, vhi_ids, twp_ids = set(), set(), set()
            for r in rows:
                if _gp.is_voided(r.get("voided")):
                    continue
                if str(r.get("trans_type") or "").strip() == "Return":
                    continue
                if str(r.get("salesperson") or "").strip().lower() == "admin":
                    continue
                code = resolve_code(r.get("store") or "")
                if code not in scodes:
                    continue
                kind = _mi_classify_sales_row(r.get("category"), r.get("contract_type"), r.get("product_desc"))
                tid = r.get("trans_id")
                if kind == "edge":
                    edge_ids.add(tid)
                elif kind == "twp":
                    twp_ids.add(tid)
                elif kind == "vhi_fios":
                    vhi_ids.add(tid)
            _basis = " transactions from the same sales rep commission is paid on (voids / Returns / admin excluded, raw_sales→feed)."
            if "edge_count" in which_sources:
                out["actuals"]["edge_count"] = len(edge_ids)
                out["resolved"].append("edge_count")
                out["notes"]["edge_count"] = "Edge" + _basis + " Reps fold Edge into premium activations today."
            if "vhi_fios_count" in which_sources:
                out["actuals"]["vhi_fios_count"] = len(vhi_ids)
                out["resolved"].append("vhi_fios_count")
                out["notes"]["vhi_fios_count"] = "VHI / FIOS / home-internet" + _basis + " Reps fold these into premium activations today."
            if "twp_count" in which_sources:
                out["actuals"]["twp_count"] = len(twp_ids)
                out["resolved"].append("twp_count")
                out["notes"]["twp_count"] = "Total Wireless Protect (TWP) insurance attachments" + _basis
        except Exception:
            for k in ("edge_count", "vhi_fios_count", "twp_count"):
                if k in which_sources:
                    out["unresolved"].append(k)

    # 5. tmr3 (3MR) — store-level DLAR, averaged over the manager's stores.
    if "tmr3" in which_quals:
        try:
            mo = int(str(period)[5:7]); yr = int(str(period)[:4])
            q = (client.schema("commcalc").table("raw_dlar_store").select("store_code,tmr3,period_month,period_year,period")
                 .eq("org_id", org_id).in_("store_code", list(scodes) or [""]))
            dl = q.execute().data or []
            vals = [_f_num(r.get("tmr3")) for r in dl
                    if (str(r.get("period_month")) == str(mo) and str(r.get("period_year")) == str(yr))
                    or (str(period) in _pvariants(str(r.get("period") or "")))]
            vals = [v for v in vals if v is not None]
            if vals:
                out["qualifier_values"]["tmr3"] = round(sum(vals) / len(vals), 2)
                out["resolved"].append("tmr3")
                out["notes"]["tmr3"] = "3-month retention (raw_dlar_store), averaged over the manager's stores."
            else:
                out["unresolved"].append("tmr3")
        except Exception:
            out["unresolved"].append("tmr3")

    # 6. Cash deposit — leftover (collected − deposited) over the store set + period (proxy for the gate).
    if "cash_deposit" in which_quals:
        try:
            from app.modules.closing import deposit_recon as _dr
            d0, d1 = _mi_period_dates(period)
            closing = _dr.closing_cash_raw_by_store_day(client, org_id, d0, d1, list(scodes))
            deps = _dr.bank_deposits_by_store_day(client, org_id, d0, d1, list(scodes))
            collected = round(sum(v.get("t_cash", 0.0) for v in closing.values()), 2)
            deposited = round(sum(_f_num(r.get("amount")) for r in deps), 2)
            out["qualifier_values"]["cash_deposit"] = round(collected - deposited, 2)
            out["resolved"].append("cash_deposit")
            out["notes"]["cash_deposit"] = f"Cash left undeposited = collected ${collected} − deposited ${deposited}, over the period. Gate wants ≤ threshold."
        except Exception:
            out["unresolved"].append("cash_deposit")

    # inventory_aging derived gate — did ANY device EVER exceed max_days in stock DURING the period, across
    # the store set? (period-correct: not "over N right now" but "peaked over N at any point in the month").
    # max_days is per-org configurable (management_incentive_bonus.config.max_days — Luxelink 10 / Cellfonz 45).
    inv_bonus = any((b.get("gated_by") or "") == "inventory_aging" for b in (plan.get("bonuses") or []))
    if inv_bonus:
        try:
            max_days = 10
            for b in (plan.get("bonuses") or []):
                if (b.get("gated_by") or "") == "inventory_aging":
                    max_days = int((b.get("config") or {}).get("max_days", 10) or 10)
                    break
            d0, d1 = _mi_period_dates(period)
            resolve_code = _store_code_resolver(client, org_id)
            rows = (client.schema("commcalc").table("inventory_aging_device")
                    .select("store,received_date,days_in_stock,as_of_date,off_hand_as_of")
                    .eq("org_id", org_id).limit(200000).execute().data) or []
            hit = False; checked = 0; unknown = 0
            for r in rows:
                if resolve_code(r.get("store") or "") not in scodes:
                    continue
                ever = _mi_ever_over_days(r.get("received_date"), r.get("days_in_stock"),
                                          r.get("as_of_date"), r.get("off_hand_as_of"), d0, d1, max_days)
                if ever is None:
                    unknown += 1
                    continue
                checked += 1
                if ever:
                    hit = True
                    break
            if checked == 0:
                # No evaluable age data → fail closed to manual review rather than silently granting.
                out["unresolved"].append("inventory_aging")
                out["notes"]["inventory_aging"] = f"No evaluable inventory-age data for these stores in the period ({unknown} device row(s) missing age) — enter manually."
            else:
                out["derived"]["inventory_aging"] = not hit    # qualifies when NO device ever aged past max_days
                note = (f"A device exceeded {max_days} days in stock during the period → gate not met."
                        if hit else f"No device exceeded {max_days} days in stock during the period, across the manager's stores.")
                if unknown:
                    note += f" ⚠ {unknown} device(s) had no age data and were skipped — review."
                out["resolved"].append("inventory_aging")
                out["notes"]["inventory_aging"] = note
        except Exception:
            out["unresolved"].append("inventory_aging")

    # zulu / twp / address_checks — read STORED KPI actuals (manual now, email later), honoring each
    # metric's source_mode, averaged across the manager's stores (same grain as tmr3). Unresolved only
    # when there's genuinely no stored value yet.
    # tmr3 included so an imported Paramount 3MR backfills when raw_dlar_store had none (it's skipped here
    # if the DLAR block above already resolved it).
    kpi_pending = [k for k in which_quals if k in ("zulu", "twp", "address_checks", "tmr3") and k not in out["resolved"]]
    if kpi_pending:
        try:
            eff = _kpi_effective_actuals(client, org_id, period, scope="store",
                                         metric_keys=set(kpi_pending), entities=scodes)
        except Exception:
            eff = {}
        for k in kpi_pending:
            vals = [v["value"] for (ent, mk), v in eff.items() if mk == k and v.get("value") is not None]
            if vals:
                out["qualifier_values"][k] = round(sum(vals) / len(vals), 2)
                srcs = sorted({str(v["source"]).split()[0] for (ent, mk), v in eff.items() if mk == k})
                out["resolved"].append(k)
                out["notes"][k] = f"Stored KPI actual ({'/'.join(srcs) or 'manual'}), averaged across the manager's stores."
            else:
                out["unresolved"].append(k)
                out["notes"][k] = "No stored KPI value yet — enter on the KPI page (manual mode) or via email import once wired."
    return out


def _f_num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0


class MiResolveIn(LaxModel):
    employee_id: Any = None
    period: Any = None
    plan_id: Any = None


@router.post("/management-incentive/resolve")
def mi_resolve(body: MiResolveIn, org_id: str = ORG_ID):
    """Auto-pull a manager's numbers for a period, aggregated over the stores they manage — reusing the
    app's own accessory/DLAR/deposit/inventory math. Body: {plan_id, employee_id, period}. Returns
    pre-fill {store_codes, manager_store_count, actuals, qualifier_values, derived, resolved[],
    unresolved[], notes{}} for the Compute tab; the manager reviews before saving. Never computes pay."""
    require_org(org_id)
    employee_id = str(body.employee_id or "").strip()
    period = str(body.period or "").strip()
    if not employee_id or not period:
        raise HTTPException(400, "employee_id and period are required")
    client = sb()
    plans = _mi_load_plans(client, org_id, plan_id=body.plan_id)
    plan = plans[0] if plans else None
    if not plan:
        raise HTTPException(404, "plan not found")
    return {"ok": True, **_mi_resolve_numbers(client, org_id, period, employee_id, plan)}


# ── ePay (Boost) Daily Transaction Detail ingest + recon (owner directive 2026-08-20, migration 903) ──
# Boost's owner-portal report. MA/VidaPay (Total) is the sibling with its own report (raw_ma_daily_tx);
# same logic per carrier. Each line resolves to OUR store via the merchant-ID registry (processor 'epay').
from app.modules.commcalc import epay_ingest as _epay  # noqa: E402


def _epay_require_manager(authorization, org_id):
    from app.modules.storeops.router import _require_manager
    _require_manager(authorization, org_id)


@router.post("/epay/upload")
async def epay_upload(file: UploadFile = File(...), authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Upload a Boost ePay 'Daily Transaction Detail' export (xlsx/csv). Parses, resolves each terminal to
    a store via the merchant registry, and stores the lines idempotently. Returns rows saved + any
    terminals that still need a store mapping (with a suggested store from the UserName)."""
    _epay_require_manager(authorization, org_id)
    contents = await file.read()
    fname = (getattr(file, "filename", "") or "").lower()
    try:
        if fname.endswith((".csv", ".txt")):
            df = None
            for enc in ("utf-8-sig", "cp1252", "latin-1"):
                try:
                    df = pd.read_csv(io.BytesIO(contents), dtype=str, encoding=enc); break
                except UnicodeDecodeError:
                    continue
        else:
            df = pd.read_excel(io.BytesIO(contents), dtype=str)
    except Exception as e:
        raise HTTPException(400, f"Could not read file ({fname or 'upload'}): {e}")
    if df is None:
        raise HTTPException(400, "Could not read the file — save it as .xlsx or .csv and retry.")
    df = df.fillna("")
    cols = set(str(c).strip() for c in df.columns)
    if "TransactionID" not in cols or "TerminalID" not in cols:
        raise HTTPException(400, "This doesn't look like the ePay Daily Transaction Detail report "
                                 "(missing TransactionID / TerminalID columns).")
    batch = (fname or "epay") + ":" + str(len(contents))
    res = _epay.ingest(org_id, df.to_dict("records"), source_batch=batch, client=get_supabase())
    return {"ok": True, **res}


@router.get("/epay/unmapped")
def epay_unmapped(org_id: str = ORG_ID):
    """Terminals with ingested rows but no resolved store — the confirm queue, each with a UserName-based
    suggestion so an admin maps it in one click."""
    return {"unmapped": _epay.unmapped_terminals(get_supabase(), org_id), "processor": "epay"}


@router.post("/epay/map-terminal")
def epay_map_terminal(body: dict, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Confirm a terminal -> store mapping. Writes the store's ePay merchant id in the registry AND
    backfills the already-ingested rows so past days reconcile. Body: {terminal_id, store_code}."""
    _epay_require_manager(authorization, org_id)
    from app.modules.storeops import merchant_ids as _mids
    terminal_id = str(body.get("terminal_id") or "").strip()
    store_code = str(body.get("store_code") or "").strip()
    if not (terminal_id and store_code):
        raise HTTPException(400, "terminal_id and store_code are required")
    _mids.upsert(org_id, store_code, _epay.PROCESSOR, merchant_id=terminal_id)
    backfilled = _epay.backfill_store_codes(get_supabase(), org_id, terminal_id, store_code)
    return {"ok": True, "terminal_id": terminal_id, "store_code": store_code, "rows_backfilled": backfilled}


@router.get("/epay/recon")
def epay_recon(date_from: str = "", date_to: str = "", org_id: str = ORG_ID):
    """Per-store-day portal PAYMENT + FEE from the ingested ePay rows (the portal side of the recon).
    date_from/date_to = 'YYYY-MM-DD' (date_to defaults to date_from)."""
    if not date_from:
        raise HTTPException(400, "date_from (YYYY-MM-DD) is required")
    m = _epay.per_store_day(get_supabase(), org_id, date_from, date_to or date_from)
    rows = [{"store_code": sc, "close_date": d, **vals} for (sc, d), vals in sorted(m.items())]
    return {"rows": rows,
            "totals": {"payment": round(sum(r["payment"] for r in rows), 2),
                       "fee": round(sum(r["fee"] for r in rows), 2),
                       "store_days": len(rows)}}


@router.get("/epay/fee-recon")
def epay_fee_recon(date_from: str = "", date_to: str = "", tolerance: float = 1.0,
                   authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Fee reconciliation: the Boost 'ePay service charge' our system captured (raw_sales) vs the fee the
    owner's portal shows (Daily Transaction Detail), per store-day. Biggest discrepancies first — these
    are what the hourly sweep escalates to DM+. Scoped to the caller's store span."""
    if not date_from:
        raise HTTPException(400, "date_from (YYYY-MM-DD) is required")
    from app.modules.commcalc import epay_fee_recon as _fr
    from app.modules.storeops.router import scope_keyset, in_keyset
    ks = scope_keyset(authorization, org_id)
    out = _fr.fee_recon(get_supabase(), org_id, date_from, date_to or date_from, tolerance=tolerance)
    if ks is not None:
        out["rows"] = [r for r in out["rows"] if in_keyset(ks, r.get("store_code"))]
        out["totals"] = {
            "system_fee": round(sum(r["system_fee"] for r in out["rows"]), 2),
            "portal_fee": round(sum(r["portal_fee"] for r in out["rows"]), 2),
            "var": round(sum(r["var"] for r in out["rows"]), 2),
            "flagged": sum(1 for r in out["rows"] if r["flag"]), "store_days": len(out["rows"])}
    return out


# ══════════════════════════════════════════════════════════════════════════════════════════════════
# ePay DISCREPANCY ALERTS (epic P4). An HOURLY sweep that recomputes TODAY's ePay reconciliation per
# tenant and emails District Managers AND above the same day when a store's fee or payment recon is off
# beyond the tenant's tolerance. Mirrors the accountability morning lateness plumbing EXACTLY
# (storeops.router `_run_lateness_alerts` / run-due / alert-config): per-tenant enable + tolerance on
# storeops.tenants (migration 905, default OFF), dedup via storeops.alert_log (scope 'epay_discrepancy'),
# recipient hierarchy via storeops.router `_managers_above_dm`, email via notify.channels.email_resend.
# The pure email PLANNER lives in commcalc.epay_alerts. Config lives in storeops.* (NOT commcalc), so
# these helpers use a storeops-schema client for tenants + alert_log; the recon recompute passes the
# default client (epay_fee_recon / closing resolve their own commcalc schema).
# ══════════════════════════════════════════════════════════════════════════════════════════════════
def _epay_portal_pull(client, org_id):
    """Config-gated Boost portal AUTO-PULL HOOK (P4). Runs at the TOP of the hourly run-due flow, BEFORE
    the recompute, so a freshly pulled Daily Transaction Detail reconciles the same tick. Gated by
    EPAY_PORTAL_SOURCE (env; 'email' / 'api' / 'none', default 'none'):

      • 'none' (the common case today) → a documented NO-OP. The owner hasn't chosen an access path yet.
      • 'email' → poll the report inbox for the DTD attachment (TODO, not yet wired).
      • 'api'   → pull via the Boost owner-portal API (TODO, not yet wired).

    NEVER raises and NEVER hardcodes a credential or portal URL. Returns a small status dict for the log."""
    source = (_os.environ.get("EPAY_PORTAL_SOURCE", "") or "none").strip().lower()
    if source in ("", "none"):
        return {"source": "none", "pulled": 0,
                "note": "auto-pull disabled — owner has not configured a portal source"}
    try:
        if source == "email":
            # TODO(owner): poll the configured report mailbox (mirror commcalc.email_sweep / ftp_sweep) for
            # the Boost "Daily Transaction Detail" attachment, then hand its rows to
            # epay_ingest.ingest(org_id, records, ...). Requires the mailbox + a routing rule to be
            # provisioned first. No-op until then.
            return {"source": "email", "pulled": 0, "note": "TODO: email-inbox poll not yet wired"}
        if source == "api":
            # Portal case: drive the headless-Chromium ePay Owner Portal sweep for the Daily
            # Transaction Detail ONLY, reusing the backend-only epay_sweep_config credentials (never
            # hardcoded). The sweep downloads the DTD and routes it through epay_ingest (parse +
            # payment/fee split + terminal→store resolution + idempotent upsert), so the same tick's
            # recompute reconciles the freshest portal data. No-op (never raises) when credentials are
            # missing.
            cfg = _epay_cfg(client, org_id)
            if not cfg or not cfg.get("portal_user") or not cfg.get("portal_pass"):
                return {"source": "api", "pulled": 0,
                        "note": "no epay_sweep_config credentials — auto-pull skipped"}
            rcfg = _registry_report_cfg(client, org_id)
            # sync Playwright cannot run inside this coroutine's event loop — run the sweep in a
            # worker thread (which has no running loop), exactly like /epay/sweep/discover-reports.
            import concurrent.futures as _cf

            def _run_dtd_sweep():
                return epay_sweep.run_epay_sweep(
                    client, org_id, cfg.get("portal_url"), cfg["portal_user"], cfg["portal_pass"],
                    reports=["epay_daily_tx"], report_cfg=rcfg)

            with _cf.ThreadPoolExecutor(max_workers=1) as _ex:
                res = _ex.submit(_run_dtd_sweep).result() or {}
            pulled = sum(int((r or {}).get("rows") or 0) for r in (res.get("reports") or []))
            out = {"source": "api", "pulled": pulled}
            if res.get("errors"):
                out["errors"] = res["errors"]
            return out
    except Exception:
        return {"source": source, "pulled": 0, "error": "auto-pull failed (swallowed)"}
    return {"source": source, "pulled": 0, "note": "unknown EPAY_PORTAL_SOURCE; treated as no-op"}


def _epay_recompute_flags(client, org_id, day, tolerance):
    """Recompute ONE day's ePay reconciliation for a tenant and return the FLAGGED store-days. Reuses the
    existing recon math — no duplication:
      • FEE     → commcalc.epay_fee_recon.fee_recon (system raw_sales 'ePay service charge' vs portal DTD).
      • PAYMENT → the P2 recon embedded in closing._closing_summary_for_date's money_recon['epay']
                  (declared ePay at closing vs the portal DTD payment, epay_ingest.per_store_day).
    Returns [{store_code, close_date, kind ('fee'|'payment'), system, portal, variance}] for
    |variance| > tolerance. NEVER raises (a missing table / un-run migration degrades to fewer flags)."""
    flags = []
    # FEE side — system (raw_sales) vs portal (DTD), per store-day.
    try:
        from app.modules.commcalc import epay_fee_recon as _fr
        fr = _fr.fee_recon(client, org_id, day, day, tolerance=tolerance)
        for r in (fr.get("rows") or []):
            if r.get("flag"):
                flags.append({"store_code": r.get("store_code"), "close_date": r.get("close_date") or day,
                              "kind": "fee", "system": r.get("system_fee"), "portal": r.get("portal_fee"),
                              "variance": r.get("var")})
    except Exception:
        pass
    # PAYMENT side — declared ePay vs portal DTD payment (P2 logic, embedded in the DM-Verify summary).
    try:
        from app.modules.closing.router import _closing_summary_for_date
        cards = _closing_summary_for_date(client, org_id, day, None, None, None, tolerance, False)
        for c in (cards or []):
            ep = ((c.get("money_recon") or {}) or {}).get("epay") or {}
            if ep.get("flag") and not ep.get("portal_pending"):
                flags.append({"store_code": c.get("store_code"), "close_date": c.get("close_date") or day,
                              "kind": "payment", "system": ep.get("declared"), "portal": ep.get("portal"),
                              "variance": ep.get("var")})
    except Exception:
        pass
    return flags


def _epay_mark_run(so_client, org_id, today, detail):
    """Bookkeeping on storeops.tenants (epay_alert_last_run / _last_detail). Best-effort, never raises."""
    try:
        so_client.table("tenants").update(
            {"epay_alert_last_run": datetime.now(timezone.utc).isoformat(),
             "epay_alert_last_detail": f"{today}: {detail}"}).eq("org_id", org_id).execute()
    except Exception:
        pass


async def _run_epay_discrepancy_alerts(org_id_filter=None, respect_enabled=True, dry_run=False):
    """The hourly ePay discrepancy sweep. Iterates tenants; skips unless `epay_alerts_enabled`; for TODAY
    (tenant-local via storeops _biz_tz_for) runs the config-gated portal auto-pull hook, recomputes the
    ePay reconciliation (fee + payment), flags store-days over `epay_alert_tolerance`, resolves DM+above
    per flagged store, plans one digest per manager, and sends them deduped via storeops.alert_log
    (scope 'epay_discrepancy', ref_key incorporating tenant+store+date+kind so a discrepancy escalates
    once/day). Marks the run on the tenant row. NEVER raises."""
    from app.modules.storeops.router import (_managers_above_dm, _biz_tz_for,
                                              _lateness_already_sent, _lateness_record_sent)
    from app.modules.commcalc import epay_alerts as _ea
    from app.modules.notify.channels import email_resend
    root = get_supabase()
    so = root.schema("storeops")   # storeops.tenants + storeops.alert_log
    try:
        tenants = so.table("tenants").select("*").execute().data or []
    except Exception:
        tenants = []
    if org_id_filter:
        tenants = [t for t in tenants if str(t.get("org_id")) == str(org_id_filter)]
    email_ok = email_resend.is_configured()
    results = []
    for t in tenants:
        oid = t.get("org_id")
        if respect_enabled and not bool(t.get("epay_alerts_enabled")):
            continue
        try:
            tol = float(t.get("epay_alert_tolerance") or 1.0)
        except (TypeError, ValueError):
            tol = 1.0
        now_local = datetime.now(timezone.utc).astimezone(_biz_tz_for(oid))
        today = now_local.date().isoformat()
        # Portal auto-pull HOOK — config-gated; a NO-OP unless EPAY_PORTAL_SOURCE is set. Never raises.
        _epay_portal_pull(root, oid)
        flags = _epay_recompute_flags(root, oid, today, tol)
        if not flags:
            if not dry_run:
                _epay_mark_run(so, oid, today, "no discrepancies")
            results.append({"org_id": oid, "sent": 0, "skipped": 0, "flagged": 0})
            continue
        stores = {f["store_code"] for f in flags if f.get("store_code")}
        hierarchy = {s: _managers_above_dm(oid, s) for s in stores}
        plan = _ea.plan_emails(flags, hierarchy, today)
        sent = skipped = 0
        planned = []
        for dg in plan["digests"]:
            # Dedup per (store, date, kind) for THIS recipient — keep only items not already sent today,
            # so a discrepancy escalates once/day and a NEW gap found later the same day still sends.
            new_items = [it for it in dg["items"]
                         if not _lateness_already_sent(so, oid, "epay_discrepancy", it["ref_key"])]
            if not new_items:
                skipped += 1
                planned.append({"to": dg["to"], "subject": dg["subject"], "already_sent": True})
                continue
            built = _ea.build_digest(dg["to_name"], new_items)
            planned.append({"to": dg["to"], "subject": built["subject"], "already_sent": False,
                            "items": [f"{i['store_code']} {i['close_date']} {i['kind']}" for i in new_items]})
            if dry_run:
                continue
            if email_ok:
                try:
                    await email_resend.send_email(to=dg["to"], subject=built["subject"], html=built["html"])
                    for it in new_items:
                        _lateness_record_sent(so, oid, "epay_discrepancy", it["ref_key"], dg["to"])
                    sent += 1
                except Exception:
                    pass
        if not dry_run:
            _epay_mark_run(so, oid, today,
                           f"sent {sent}, skipped {skipped}, {len(flags)} flagged store-day(s)")
        results.append({"org_id": oid, "sent": sent, "skipped": skipped, "flagged": len(flags),
                        "email_configured": email_ok, "planned": planned if dry_run else None})
    return {"ran": len(results), "dry_run": dry_run, "results": results}


@router.post("/epay/alerts/run-due")
async def epay_alerts_run_due(x_notify_secret: str = Header(default="")):
    """Secret-gated HOURLY pg_cron entrypoint (P4). Recomputes TODAY's ePay reconciliation for every
    enabled tenant and emails DM+above a digest of any store-day off beyond the tenant's tolerance,
    deduped via storeops.alert_log so a given discrepancy escalates once per day. Mirrors the
    accountability lateness run-due. See migration 905 for the cron registration."""
    if not verify_notify_secret(x_notify_secret):
        raise HTTPException(403, "forbidden")
    return await _run_epay_discrepancy_alerts(respect_enabled=True, dry_run=False)


@router.post("/epay/alerts/run-now")
async def epay_alerts_run_now(send: bool = False, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Manager/admin manual trigger for THIS tenant, bypassing the enable gate. Defaults to a DRY RUN
    (returns exactly who WOULD be emailed and which store-days, sending nothing) — pass ?send=true to
    actually send. Dedup is always honored, so a real send won't duplicate the hourly run."""
    from app.modules.storeops.router import _require_manager
    mgr = _require_manager(authorization, org_id)
    org_id = mgr.get("org_id") or org_id
    return await _run_epay_discrepancy_alerts(org_id_filter=org_id, respect_enabled=False, dry_run=(not send))


@router.get("/epay/alert-config")
def get_epay_alert_config(authorization: str = Header(default=""), org_id: str = ORG_ID):
    """ePay discrepancy-alert config for the tenant (enabled + dollar tolerance), plus last-run
    bookkeeping. Any manager may view; the PUT is manager/admin only. Config lives on storeops.tenants
    (migration 905)."""
    so = get_supabase().schema("storeops")
    try:
        rows = (so.table("tenants").select(
            "epay_alerts_enabled,epay_alert_tolerance,epay_alert_last_run,epay_alert_last_detail")
            .eq("org_id", org_id).limit(1).execute().data) or []
        r = rows[0] if rows else {}
        return {"enabled": bool(r.get("epay_alerts_enabled")),
                "tolerance": float(r.get("epay_alert_tolerance") or 1.0),
                "last_run": r.get("epay_alert_last_run"), "last_detail": r.get("epay_alert_last_detail"),
                "available": True}
    except Exception:
        return {"enabled": False, "tolerance": 1.0, "last_run": None, "last_detail": None, "available": False}


class EpayAlertConfigIn(LaxModel):
    enabled: Any = None
    tolerance: Any = None


@router.put("/epay/alert-config")
def put_epay_alert_config(body: EpayAlertConfigIn, authorization: str = Header(default=""), org_id: str = ORG_ID):
    """Manager/admin only. Turn the hourly ePay discrepancy alerts on/off and set the dollar tolerance
    (a store-day is flagged when |fee variance| or |payment variance| exceeds it; default 1.00)."""
    from app.modules.storeops.router import _require_manager
    mgr = _require_manager(authorization, org_id)
    org_id = mgr.get("org_id") or org_id
    upd = {}
    sent = body.model_fields_set
    if "enabled" in sent:
        upd["epay_alerts_enabled"] = bool(body.enabled)
    if "tolerance" in sent:
        try:
            tv = round(float(body.tolerance), 2)
        except (TypeError, ValueError):
            raise HTTPException(400, "tolerance must be a number (dollars), e.g. 1.00")
        if tv < 0:
            raise HTTPException(400, "tolerance must be >= 0")
        upd["epay_alert_tolerance"] = tv
    if not upd:
        raise HTTPException(400, "Nothing to update — send `enabled` and/or `tolerance`.")
    try:
        get_supabase().schema("storeops").table("tenants").update(upd).eq("org_id", org_id).execute()
    except Exception:
        raise HTTPException(400, "Couldn't save — is migration 905 applied?")
    return get_epay_alert_config(authorization=authorization, org_id=org_id)
